{
  "timeline": [
    {
      "headline": "Birth of Louis-François Cartier",
      "text": "Louis-François Cartier, the founder of Cartier, was born in 1819.",
      "date": "1819"
    },
    {
      "headline": "Founding of Cartier",
      "text": "In 1847, Louis-François Cartier took over the workshop of his master, Adolphe Picard, and founded Cartier in Paris.",
      "date": "1847"
    },
    {
      "headline": "Expansion under Alfred Cartier",
      "text": "In 1874, Alfred Cartier, the son of Louis-François Cartier, took over the business and began expanding its reach.",
      "date": "1874"
    },
    {
      "headline": "Opening of the Rue de la Paix Boutique",
      "text": "In 1899, Cartier opened a boutique at 13 Rue de la Paix, Paris, which became the center of the company's operations.",
      "date": "1899"
    },
    {
      "headline": "Introduction of the Santos Watch",
      "text": "In 1904, Cartier created the Santos wristwatch for aviator Alberto Santos-Dumont, marking one of the first wristwatches designed for men.",
      "date": "1904"
    },
    {
      "headline": "Death of Louis-François Cartier",
      "text": "Louis-François Cartier passed away in 1904.",
      "date": "1904"
    },
    {
      "headline": "Cartier's International Expansion",
      "text": "In the early 20th century, Cartier expanded internationally with the opening of stores in London (1909) and New York City (1917).",
      "date": "1917"
    },
    {
      "headline": "Cartier's Trinity Ring",
      "text": "In 1924, Cartier introduced the Trinity ring, a design featuring three interlocking bands of gold.",
      "date": "1924"
    },
    {
      "headline": "Cartier's Ownership Change",
      "text": "In 1964, the Cartier family sold the business, ending its control over the company.",
      "date": "1964"
    },
    {
      "headline": "Acquisition by Richemont Group",
      "text": "In 1988, Cartier became a part of the Swiss Richemont Group, a global luxury goods conglomerate.",
      "date": "1988"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Darko Miličić",
      "text": "Darko Miličić was born on June 20, 1985, in Novi Sad, SR Serbia, SFR Yugoslavia.",
      "date": "1985-06-20"
    },
    {
      "headline": "NBA Draft",
      "text": "Darko Miličić was selected by the Detroit Pistons as the second overall pick in the 2003 NBA Draft.",
      "date": "2003"
    },
    {
      "headline": "NBA Debut",
      "text": "Darko Miličić made his NBA debut with the Detroit Pistons during the 2003-2004 NBA season.",
      "date": "2003"
    },
    {
      "headline": "NBA Championship",
      "text": "Darko Miličić became the youngest player to win an NBA championship when the Detroit Pistons won the title in June 2004.",
      "date": "2004-06"
    },
    {
      "headline": "Trade to Orlando Magic",
      "text": "Darko Miličić was traded to the Orlando Magic in February 2006.",
      "date": "2006-02"
    },
    {
      "headline": "Signing with Memphis Grizzlies",
      "text": "Darko Miličić signed with the Memphis Grizzlies in July 2007.",
      "date": "2007-07"
    },
    {
      "headline": "Trade to New York Knicks",
      "text": "Darko Miličić was traded to the New York Knicks in June 2009.",
      "date": "2009-06"
    },
    {
      "headline": "Trade to Minnesota Timberwolves",
      "text": "Darko Miličić was traded to the Minnesota Timberwolves in February 2010.",
      "date": "2010-02"
    },
    {
      "headline": "Signing with Boston Celtics",
      "text": "Darko Miličić signed with the Boston Celtics in September 2012.",
      "date": "2012-09"
    },
    {
      "headline": "Retirement from NBA",
      "text": "Darko Miličić retired from the NBA in 2013.",
      "date": "2013"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Ramanuja",
      "text": "Ramanuja was born in 1017 in Sriperumbudur, Tamil Nadu, India.",
      "date": "1017"
    },
    {
      "headline": "Initiation into Sannyasa",
      "text": "Ramanuja was initiated into the monastic order of Sannyasa by his guru, Yadava Prakasha, around 1037.",
      "date": "1037"
    },
    {
      "headline": "Conflict with Yadava Prakasha",
      "text": "Ramanuja had philosophical disagreements with his teacher Yadava Prakasha, leading to his departure from the guru's tutelage.",
      "date": "1037"
    },
    {
      "headline": "Becomes Head of Srirangam Matha",
      "text": "Ramanuja became the head of the Srirangam Matha, a prominent Vaishnavism monastery, around 1050.",
      "date": "1050"
    },
    {
      "headline": "Composition of Sri Bhashya",
      "text": "Ramanuja composed the Sri Bhashya, a commentary on the Brahma Sutras, around 1100.",
      "date": "1100"
    },
    {
      "headline": "Composition of Gita Bhashya",
      "text": "Ramanuja wrote the Gita Bhashya, a commentary on the Bhagavad Gita, around 1100.",
      "date": "1100"
    },
    {
      "headline": "Social Reforms and Temple Administration",
      "text": "Ramanuja implemented significant social reforms and restructured temple administration, promoting inclusivity and devotion.",
      "date": "1100"
    },
    {
      "headline": "Death of Ramanuja",
      "text": "Ramanuja passed away in 1137 in Srirangam, Tamil Nadu, India.",
      "date": "1137"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "First Broadcast of The Young Ones",
      "text": "The Young Ones, a British sitcom, was first broadcast on BBC2. The show focused on the lives of four dissimilar students and their landlord's family, featuring anarchic, offbeat, and surreal humour. The first series aired in 1982.",
      "date": "1982"
    },
    {
      "headline": "Second Series of The Young Ones",
      "text": "The second series of The Young Ones was broadcast on BBC2 in 1984. The show continued to feature slapstick gags, visual humour, surreal jokes, and musical numbers from various performers.",
      "date": "1984"
    }
  ]
}

