{
  "timeline": [
    {
      "headline": "Maxie Long sets 440 yards world record",
      "text": "In 1900, Maxie Long set a world record for the 440 yards with a time of 47.8 seconds. This performance was later recognized by the International Amateur Athletics Federation (IAAF) as a world record for the 400 meters.",
      "date": "1900"
    },
    {
      "headline": "Charles Reidpath sets 400 meters world record",
      "text": "On July 12, 1912, Charles Reidpath set a world record in the 400 meters with a time of 48.2 seconds at the Stockholm Olympics. This was the first officially recognized world record for the 400 meters by the IAAF.",
      "date": "1912-07-12"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Charles Mingus",
      "text": "Charles Mingus Jr. was born on April 22, 1922, in Nogales, Arizona, USA.",
      "date": "1922-04-22"
    },
    {
      "headline": "Release of Pithecanthropus Erectus",
      "text": "In 1956, Charles Mingus released the album 'Pithecanthropus Erectus', which is considered a landmark in the development of modern jazz.",
      "date": "1956"
    },
    {
      "headline": "Release of Mingus Ah Um",
      "text": "In 1959, Mingus released 'Mingus Ah Um', an album that is regarded as one of his masterpieces and a classic in the jazz genre.",
      "date": "1959"
    },
    {
      "headline": "Release of The Black Saint and the Sinner Lady",
      "text": "In 1963, Mingus released 'The Black Saint and the Sinner Lady', a highly acclaimed album noted for its orchestral complexity and emotional depth.",
      "date": "1963"
    },
    {
      "headline": "Diagnosed with Amyotrophic Lateral Sclerosis",
      "text": "In 1977, Charles Mingus was diagnosed with amyotrophic lateral sclerosis (ALS), a progressive neurodegenerative disease.",
      "date": "1977"
    },
    {
      "headline": "Death of Charles Mingus",
      "text": "Charles Mingus passed away on January 5, 1979, in Cuernavaca, Mexico, at the age of 56.",
      "date": "1979-01-05"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "87th Academy Awards Ceremony",
      "text": "The 87th Academy Awards ceremony, presented by the Academy of Motion Picture Arts and Sciences (AMPAS), honored the best films of 2014 and took place on February 22, 2015, at the Dolby Theatre in Hollywood, Los Angeles. The ceremony began at 5:30 p.m. PST / 8:30 p.m. EST.",
      "date": "2015-02-22"
    },
    {
      "headline": "Television Broadcast",
      "text": "The ceremony was televised in the United States by ABC. It was produced by Neil Meron and Craig Zadan and directed by Hamish Hamilton.",
      "date": "2015-02-22"
    },
    {
      "headline": "Neil Patrick Harris Hosts",
      "text": "Actor Neil Patrick Harris hosted the 87th Academy Awards ceremony for the first time.",
      "date": "2015-02-22"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Ascension of Jesus",
      "text": "According to Acts 1:9-11, Jesus ascended to heaven in the presence of his apostles after giving them instructions to spread his teachings.",
      "date": "0030"
    },
    {
      "headline": "Pentecost",
      "text": "Acts 2 describes the event of Pentecost, when the Holy Spirit descended upon the apostles, enabling them to speak in different languages and marking the beginning of their public ministry.",
      "date": "0030"
    },
    {
      "headline": "Peter's Sermon",
      "text": "In Acts 2:14-41, Peter delivers a sermon to the crowd in Jerusalem, resulting in the conversion and baptism of about 3,000 people.",
      "date": "0030"
    },
    {
      "headline": "Healing of the Lame Beggar",
      "text": "Acts 3 recounts Peter and John healing a lame beggar at the temple gate called Beautiful, which leads to Peter preaching to the amazed onlookers.",
      "date": "0030"
    },
    {
      "headline": "Stephen's Martyrdom",
      "text": "Acts 7 describes the stoning of Stephen, the first Christian martyr, after he delivers a speech to the Sanhedrin accusing them of resisting the Holy Spirit.",
      "date": "0034"
    },
    {
      "headline": "Conversion of Saul",
      "text": "Acts 9 details the conversion of Saul of Tarsus, a persecutor of Christians, who experiences a vision of Jesus on the road to Damascus and becomes the apostle Paul.",
      "date": "0035"
    },
    {
      "headline": "Peter's Vision and Cornelius' Conversion",
      "text": "In Acts 10, Peter has a vision that leads him to preach to the Gentile Cornelius, marking the first significant outreach to non-Jews.",
      "date": "0039"
    },
    {
      "headline": "Council of Jerusalem",
      "text": "Acts 15 describes the Council of Jerusalem, where the apostles and elders decide that Gentile converts to Christianity do not need to follow all Jewish laws.",
      "date": "0049"
    },
    {
      "headline": "Paul's Missionary Journeys",
      "text": "Throughout Acts, Paul undertakes several missionary journeys across the Roman Empire, spreading Christianity and establishing churches.",
      "date": "0046-0057"
    },
    {
      "headline": "Paul's Arrest and Journey to Rome",
      "text": "Acts 21-28 narrates Paul's arrest in Jerusalem, his trials, and his journey to Rome, where he continues to preach while under house arrest.",
      "date": "0058-0060"
    }
  ]
}

