{
  "timeline": [
    {
      "headline": "Birth of Hwang Min-hyun",
      "text": "Hwang Min-hyun was born on August 9, 1995, in Busan, South Korea.",
      "date": "1995-08-09"
    },
    {
      "headline": "Debut with NU'EST",
      "text": "Hwang Min-hyun debuted as a member of the South Korean boy band NU'EST in March 2012.",
      "date": "2012-03"
    },
    {
      "headline": "Participation in Produce 101 Season 2",
      "text": "In 2017, Hwang Min-hyun participated in the second season of Produce 101, a reality competition show, and finished in ninth place.",
      "date": "2017"
    },
    {
      "headline": "Debut with Wanna One",
      "text": "After finishing ninth in Produce 101 Season 2, Hwang Min-hyun became a member of the project boy group Wanna One, which debuted in August 2017.",
      "date": "2017-08"
    },
    {
      "headline": "Wanna One's Disbandment",
      "text": "Wanna One officially disbanded on December 31, 2018, following the end of their contract.",
      "date": "2018-12-31"
    },
    {
      "headline": "Return to NU'EST",
      "text": "Following the disbandment of Wanna One, Hwang Min-hyun returned to NU'EST in 2019.",
      "date": "2019"
    },
    {
      "headline": "NU'EST's Disbandment",
      "text": "NU'EST disbanded in 2022 after ten years together as a group.",
      "date": "2022"
    },
    {
      "headline": "Solo Career",
      "text": "After NU'EST's disbandment, Hwang Min-hyun continued his career as a solo artist and actor under Pledis Entertainment.",
      "date": "2022"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Ross McCall",
      "text": "Ross McCall was born on January 13, 1976, in Port Glasgow, Scotland.",
