    },
    {
      "headline": "Role in 'White Collar'",
      "text": "From 2010 to 2014, Ross McCall starred as Matthew Keller in the television series 'White Collar'.",
      "date": "2010"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Daniel Inouye",
      "text": "Daniel Ken Inouye was born on September 7, 1924, in Honolulu, Hawaii.",
      "date": "1924-09-07"
    },
    {
      "headline": "Enlistment in the U.S. Army",
      "text": "Inouye enlisted in the U.S. Army in 1943, joining the 442nd Regimental Combat Team, a unit composed primarily of Japanese Americans.",
      "date": "1943"
    },
    {
      "headline": "Injury in World War II",
      "text": "On April 21, 1945, Inouye was severely wounded in action in Italy, leading to the amputation of his right arm.",
      "date": "1945-04-21"
    },
    {
      "headline": "Awarded the Medal of Honor",
      "text": "Inouye was awarded the Medal of Honor for his actions during World War II, though the award was not presented until June 21, 2000.",
      "date": "2000-06-21"
    },
    {
      "headline": "Graduation from University of Hawaii",
      "text": "Inouye graduated from the University of Hawaii in 1950 with a degree in political science.",
      "date": "1950"
    },
    {
      "headline": "Graduation from George Washington University Law School",
      "text": "Inouye earned his law degree from George Washington University Law School in 1953.",
      "date": "1953"
    },
    {
      "headline": "Election to Hawaii Territorial House of Representatives",
      "text": "Inouye was elected to the Hawaii Territorial House of Representatives in 1954.",
      "date": "1954"
    },
    {
      "headline": "Election to Hawaii Territorial Senate",
      "text": "Inouye was elected to the Hawaii Territorial Senate in 1958.",
      "date": "1958"
    },
    {
      "headline": "First U.S. Representative for Hawaii",
      "text": "In 1959, following Hawaii's statehood, Inouye was elected as the first U.S. Representative for the State of Hawaii.",
      "date": "1959"
    },
    {
      "headline": "Election to U.S. Senate",
      "text": "Inouye was elected to the United States Senate in 1962, beginning his long tenure in the Senate.",
      "date": "1962"
    },
    {
      "headline": "Chairman of the Senate Intelligence Committee",
      "text": "Inouye served as the Chairman of the Senate Intelligence Committee from 1976 to 1979.",
      "date": "1976"
    },
    {
      "headline": "Chairman of the Senate Indian Affairs Committee",
      "text": "Inouye served as the Chairman of the Senate Indian Affairs Committee from 1987 to 1995.",
      "date": "1987"
    },
    {
      "headline": "Chairman of the Senate Commerce Committee",
      "text": "Inouye served as the Chairman of the Senate Commerce Committee from 2007 to 2009.",
      "date": "2007"
    },
    {
      "headline": "Chairman of the Senate Appropriations Committee",
      "text": "Inouye served as the Chairman of the Senate Appropriations Committee from 2009 until his death in 2012.",
      "date": "2009"
    },
    {
      "headline": "President pro tempore of the U.S. Senate",
      "text": "Inouye served as the President pro tempore of the United States Senate from 2010 until his death in 2012.",
      "date": "2010"
    },
    {
      "headline": "Death of Daniel Inouye",
      "text": "Daniel Inouye passed away on December 17, 2012, in Bethesda, Maryland.",
      "date": "2012-12-17"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Richard Hawley",
      "text": "Richard Willis Hawley was born on January 17, 1967, in Sheffield, England.",
      "date": "1967-01-17"
    },
    {
      "headline": "Formation of Treebound Story",
      "text": "In the 1980s, Richard Hawley formed his first band, Treebound Story, which marked the beginning of his music career.",
      "date": "1980"
    },
    {
      "headline": "Success with Longpigs",
      "text": "Richard Hawley found success in the 1990s as a member of the Britpop band Longpigs.",
      "date": "1990"
    },
    {
      "headline": "Touring with Pulp",
      "text": "Hawley played with the band Pulp, led by his friend Jarvis Cocker, as a touring musician for a short time.",
      "date": "1998"
    },
    {
      "headline": "Solo Career Launch",
      "text": "Richard Hawley launched his solo career and has since released eight studio albums.",
      "date": "2001"
    },
    {
      "headline": "First Mercury Prize Nomination",
      "text": "Hawley was nominated for the Mercury Prize for the first time for his solo work.",
      "date": "2006"
    },
    {
      "headline": "Second Mercury Prize Nomination",
      "text": "He received his second Mercury Prize nomination, further establishing his reputation as a solo artist.",
      "date": "2012"
    },
    {
      "headline": "Brit Award Nomination",
      "text": "Richard Hawley was nominated for a Brit Award, recognizing his contributions to music.",
      "date": "2013"
    },
    {
      "headline": "Collaborations with Various Artists",
      "text": "Throughout his career, Hawley has collaborated with artists such as Lisa Marie Presley, Shakespears Sister, Arctic Monkeys, Manic Street Preachers, Elbow, Duane Eddy, and Paul Weller.",
      "date": "2010"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Ginni Thomas",
      "text": "Virginia 'Ginni' Thomas was born on February 23, 1957, in Omaha, Nebraska.",
      "date": "1957-02-23"
    },
    {
      "headline": "Marriage to Clarence Thomas",
      "text": "In 1987, Ginni Thomas married Clarence Thomas, who would later become an associate justice of the Supreme Court of the United States.",
      "date": "1987"
    },
    {
      "headline": "Clarence Thomas Appointed to Supreme Court",
      "text": "In 1991, Clarence Thomas was appointed as an associate justice of the Supreme Court of the United States, making Ginni Thomas the spouse of a Supreme Court justice.",
      "date": "1991"
    },
    {
      "headline": "Founding of Liberty Central",
      "text": "In 2009, Ginni Thomas founded Liberty Central, a conservative political advocacy nonprofit organization.",
      "date": "2009"
    },
    {
      "headline": "Controversy Over Political Activism",
      "text": "Throughout the 2010s and into the 2020s, Ginni Thomas became a controversial figure due to her conservative activism and commentary, which is unusual for the spouse of a Supreme Court justice.",
      "date": "2010"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Creation of the Office",
      "text": "The office of the Governor-General of India was created in 1773 with the title of Governor-General of the Presidency of Fort William.",
      "date": "1773"
    },
    {
      "headline": "First Governor-General",
      "text": "Warren Hastings became the first Governor-General of the Presidency of Fort William in 1773.",
      "date": "1773"
    },
    {
      "headline": "Regulating Act of 1773",
      "text": "The Regulating Act of 1773 established the office of the Governor-General and marked the beginning of British control over Indian affairs.",
      "date": "1773"
    },
    {
      "headline": "Expansion of Authority",
      "text": "In 1833, the Charter Act granted the Governor-General complete authority over all of British territory in the Indian subcontinent, and the official came to be known as the Governor-General of India.",
      "date": "1833"
    },
    {
      "headline": "First Governor-General of India",
      "text": "William Bentinck became the first Governor-General of India in 1833 under the new title.",
      "date": "1833"
    },
    {
      "headline": "End of East India Company Rule",
      "text": "Following the Indian Rebellion of 1857, the British Crown assumed direct control over India, ending the rule of the East India Company in 1858.",
      "date": "1858"
    },
    {
      "headline": "Viceroy of India",
      "text": "The title of Viceroy was added to the Governor-General in 1858, making the official the representative of the British monarch in India.",
      "date": "1858"
    },
    {
      "headline": "Indian Independence",
      "text": "India gained independence from British rule on August 15, 1947, and the role of the Governor-General became the representative of the monarch of India.",
      "date": "1947-08-15"
    },
    {
      "headline": "Last Governor-General",
      "text": "Chakravarti Rajagopalachari became the last Governor-General of India, serving from 1948 until the office was abolished in 1950.",
      "date": "1948"
    },
    {
      "headline": "Abolition of the Office",
      "text": "The office of the Governor-General of India was abolished on January 26, 1950, when India became a republic.",
      "date": "1950-01-26"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Saparmurat Niyazov",
      "text": "Saparmurat Niyazov was born on February 19, 1940, in Gypjak, Turkmen SSR, Soviet Union.",
      "date": "1940-02-19"
    },
    {
      "headline": "First Secretary of the Communist Party of Turkmenistan",
      "text": "In 1985, Saparmurat Niyazov became the First Secretary of the Communist Party of Turkmenistan, marking the beginning of his leadership in the region.",
      "date": "1985"
    },
    {
      "headline": "Support for the 1991 Soviet coup attempt",
      "text": "In August 1991, Niyazov supported the Soviet coup attempt against Mikhail Gorbachev, which ultimately failed.",
      "date": "1991-08"
    },
    {
      "headline": "Turkmenistan's Independence and Presidency",
      "text": "Following the dissolution of the Soviet Union, Turkmenistan declared independence in October 1991. Niyazov became the President of Turkmenistan, a position he held until his death.",
      "date": "1991-10"
    },
    {
      "headline": "Presidential Election and Title of Türkmenbaşy",
      "text": "In June 1992, Niyazov was elected as the President of Turkmenistan. He later adopted the title 'Türkmenbaşy', meaning 'Leader of the Turkmen'.",
      "date": "1992-06"
    },
    {
      "headline": "Lifetime Presidency",
      "text": "In 1999, the People's Council of Turkmenistan declared Niyazov President for Life, solidifying his control over the country.",
      "date": "1999"
    },
    {
      "headline": "Death of Saparmurat Niyazov",
      "text": "Saparmurat Niyazov died on December 21, 2006, in Ashgabat, Turkmenistan, ending his 21-year rule over the country.",
      "date": "2006-12-21"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Martin D. Ginsburg",
      "text": "Martin David Ginsburg was born on June 10, 1932, in Brooklyn, New York.",
      "date": "1932-06-10"
    },
    {
      "headline": "Marriage to Ruth Bader",
