{
  "timeline": [
    {
      "headline": "Roman Conquest",
      "text": "The Low Countries were conquered by the Romans in the 1st century BCE, becoming part of the Roman Empire.",
      "date": "-0057"
    },
    {
      "headline": "Frankish Rule",
      "text": "After the fall of the Roman Empire, the Low Countries became part of the Frankish Empire in the 5th century.",
      "date": "0500"
    },
    {
      "headline": "Treaty of Verdun",
      "text": "The Treaty of Verdun in 843 divided the Carolingian Empire, with the Low Countries becoming part of Middle Francia.",
      "date": "0843"
    },
    {
      "headline": "Rise of the County of Flanders",
      "text": "In the 9th and 10th centuries, the County of Flanders emerged as a powerful feudal state in the Low Countries.",
      "date": "0900"
    },
    {
      "headline": "Burgundian Netherlands",
      "text": "In the 15th century, the Low Countries were united under the rule of the Dukes of Burgundy.",
      "date": "1433"
    },
    {
      "headline": "Habsburg Netherlands",
      "text": "The Low Countries came under the control of the Habsburg dynasty in 1482, following the marriage of Mary of Burgundy to Maximilian I.",
      "date": "1482"
    },
    {
      "headline": "Eighty Years' War",
      "text": "The Eighty Years' War (1568–1648) was a revolt of the Seventeen Provinces against the Spanish Empire, leading to the independence of the Dutch Republic.",
      "date": "1568"
    },
    {
      "headline": "Treaty of Westphalia",
      "text": "The Treaty of Westphalia in 1648 ended the Eighty Years' War and recognized the independence of the Dutch Republic.",
      "date": "1648"
    },
    {
      "headline": "French Revolutionary Wars",
      "text": "The Low Countries were invaded by France during the French Revolutionary Wars, leading to the establishment of the Batavian Republic in 1795.",
      "date": "1795"
    },
    {
      "headline": "United Kingdom of the Netherlands",
      "text": "After the defeat of Napoleon, the Congress of Vienna in 1815 created the United Kingdom of the Netherlands, uniting the northern and southern Low Countries.",
      "date": "1815"
    },
    {
      "headline": "Belgian Revolution",
      "text": "The Belgian Revolution in 1830 led to the independence of Belgium from the United Kingdom of the Netherlands.",
      "date": "1830"
    },
    {
      "headline": "Formation of Benelux",
      "text": "The Benelux Union was formed in 1944 as a customs union between Belgium, the Netherlands, and Luxembourg.",
      "date": "1944"
    }
  ]
}

