{
  "timeline": [
    {
      "headline": "Publication of the Manifesto of Futurism",
      "text": "On February 20, 1909, Filippo Tommaso Marinetti published the Manifesto of Futurism in the French newspaper Le Figaro. This manifesto outlined the principles of Futurism, emphasizing speed, technology, and modernity.",
      "date": "1909-02-20"
    },
    {
      "headline": "Futurist Painting Manifesto",
      "text": "In 1910, the Futurist Painting Manifesto was published by artists including Umberto Boccioni, Carlo Carrà, and Luigi Russolo. This manifesto applied Futurist principles to the visual arts.",
      "date": "1910"
    },
    {
      "headline": "Unique Forms of Continuity in Space",
      "text": "In 1913, Umberto Boccioni created the sculpture Unique Forms of Continuity in Space, which became one of the most iconic works of Futurist art.",
      "date": "1913"
    },
    {
      "headline": "The Art of Noises",
      "text": "In 1913, Luigi Russolo published The Art of Noises, a manifesto that introduced the concept of noise music, which was a significant contribution to the Futurist movement.",
      "date": "1913"
    },
    {
      "headline": "Abstract Speed + Sound",
      "text": "Between 1913 and 1914, Giacomo Balla created the painting Abstract Speed + Sound, which exemplified the Futurist fascination with movement and technology.",
      "date": "1913"
    },
    {
      "headline": "Futurism and World War I",
      "text": "During World War I, many Futurists, including Marinetti and Boccioni, supported the war as a means of cultural renewal. Boccioni died in 1916 during the war.",
      "date": "1914"
    },
    {
      "headline": "Decline of Futurism",
      "text": "After World War I, the Futurist movement began to decline as many of its key figures either died or moved on to other artistic pursuits. The movement's association with Fascism also contributed to its decline.",
      "date": "1920"
    }
  ]
}

