      "date": "-03000"
    },
    {
      "headline": "Theophoric Names Indicating Popularity",
      "text": "A large number of theophoric names, both masculine and feminine, attest to Dagon's popularity as a deity in ancient times.",
      "date": "-03000"
    },
    {
      "headline": "Worship of Dagon in Mesopotamia",
      "text": "Dagon was also worshiped further east, in Mesopotamia, where many rulers regarded him as the god capable of granting them kingship over the western areas.",
      "date": "-03000"
    }
  ]
}

