    {
      "headline": "Foundation of Nineveh",
      "text": "Nineveh, the ancient Assyrian city, was founded on the eastern bank of the Tigris River. It became one of the largest cities in the world during the Neo-Assyrian Empire.",
      "date": "-0700"
    },
    {
      "headline": "Fall of Nineveh",
      "text": "In 612 BCE, Nineveh was sacked by a coalition of Babylonians, Medes, and Scythians, marking the end of the Neo-Assyrian Empire.",
      "date": "-0612"
    },
    {
      "headline": "Mosul under the Umayyad Caliphate",
      "text": "Mosul became an important city under the Umayyad Caliphate in the 7th century CE, serving as a key trade and administrative center.",
      "date": "0661"
    },
    {
      "headline": "Mosul under the Abbasid Caliphate",
      "text": "In the 8th century, Mosul continued to thrive under the Abbasid Caliphate, becoming a center of learning and culture.",
      "date": "0750"
    },
    {
      "headline": "Seljuk Rule",
      "text": "In the 11th century, Mosul came under the control of the Seljuk Empire, further enhancing its strategic importance.",
      "date": "1055"
    },
    {
      "headline": "Zengid Dynasty",
      "text": "In the 12th century, Mosul became the capital of the Zengid dynasty, known for its architectural and cultural developments.",
      "date": "1127"
    },
    {
      "headline": "Mongol Invasion",
      "text": "In 1261, Mosul was captured by the Mongols, leading to significant destruction and a decline in its prosperity.",
      "date": "1261"
    },
    {
      "headline": "Ottoman Empire Control",
      "text": "Mosul became part of the Ottoman Empire in 1535, remaining under Ottoman control until the end of World War I.",
      "date": "1535"
    },
    {
      "headline": "British Mandate",
      "text": "After World War I, Mosul was placed under British mandate as part of the newly formed state of Iraq.",
      "date": "1920"
    },
    {
      "headline": "Mosul in Modern Iraq",
      "text": "Mosul became a significant city in modern Iraq, known for its diverse population and cultural heritage.",
      "date": "1932"
    },
    {
      "headline": "ISIS Occupation",
      "text": "In June 2014, Mosul was captured by ISIS, leading to severe destruction and humanitarian crises.",
      "date": "2014-06"
    },
    {
      "headline": "Liberation of Mosul",
      "text": "In July 2017, Iraqi forces, with international support, liberated Mosul from ISIS control after a prolonged battle.",
      "date": "2017-07"
    }
  ]
}

{
  "timeline": [
