}

{
  "timeline": [
    {
      "headline": "Proposal of Dunbar's Number",
      "text": "In the 1990s, British anthropologist Robin Dunbar proposed the concept of Dunbar's number, suggesting a cognitive limit to the number of people with whom one can maintain stable social relationships. This number is approximately 150.",
      "date": "1990"
    },
    {
      "headline": "Correlation Between Brain Size and Social Group Size",
      "text": "Robin Dunbar found a correlation between primate brain size and average social group size. By using the average human brain size and extrapolating from the results of primates, he proposed that humans can comfortably maintain 150 stable relationships.",
      "date": "1990"
    },
    {
      "headline": "Publication of Dunbar's Research",
      "text": "Robin Dunbar's research on the correlation between brain size and social group size, which led to the proposal of Dunbar's number, was published in the 1990s.",
      "date": "1990"
    }
  ]
}

