{
  "timeline": [
    {
      "headline": "Sand River Convention",
      "text": "On 1852-01-17, the Sand River Convention was signed, recognizing the independence of the South African Republic, also known as the Transvaal Republic, from British control.",
      "date": "1852-01-17"
    },
    {
      "headline": "Establishment of the South African Republic",
      "text": "In 1852, following the Sand River Convention, the South African Republic was officially established as an independent Boer republic in Southern Africa.",
      "date": "1852"
    },
    {
      "headline": "First Boer War",
      "text": "The First Boer War took place from 1880 to 1881, where the South African Republic fought against British forces to regain its independence after British annexation in 1877.",
      "date": "1880"
    },
    {
      "headline": "Pretoria Convention",
      "text": "On 1881-08-03, the Pretoria Convention was signed, ending the First Boer War and restoring self-government to the South African Republic under British suzerainty.",
      "date": "1881-08-03"
    },
    {
      "headline": "London Convention",
      "text": "In 1884, the London Convention was signed, which modified the Pretoria Convention and further recognized the independence of the South African Republic, although under British suzerainty.",
      "date": "1884"
    },
    {
      "headline": "Discovery of Gold",
      "text": "In 1886, gold was discovered on the Witwatersrand, leading to an influx of foreigners and significant economic growth in the South African Republic.",
      "date": "1886"
    },
    {
      "headline": "Jameson Raid",
      "text": "The Jameson Raid occurred from 1895-12-29 to 1896-01-02, when British forces attempted to incite an uprising in the South African Republic, but were defeated.",
      "date": "1895-12-29"
    },
    {
      "headline": "Second Boer War",
      "text": "The Second Boer War took place from 1899 to 1902, where the South African Republic and the Orange Free State fought against the British Empire.",
      "date": "1899"
    },
    {
      "headline": "Treaty of Vereeniging",
      "text": "On 1902-05-31, the Treaty of Vereeniging was signed, ending the Second Boer War and resulting in the annexation of the South African Republic into the British Empire.",
      "date": "1902-05-31"
    }
  ]
}

