    {
      "headline": "Mention by Tacitus",
      "text": "Around 100 AD, the Roman historian Tacitus mentioned a people known as the Angles (Anglii) living beyond the Lombards and Semnones, near the River Elbe.",
      "date": "0100"
    },
    {
      "headline": "Migration to Great Britain",
      "text": "In the 5th century, the Angles, along with the Saxons and Jutes, began migrating from their homeland in what is now northern Germany and southern Denmark to Great Britain. This migration marked the beginning of the Anglo-Saxon period in British history.",
      "date": "0400"
    },
    {
      "headline": "Establishment of Anglo-Saxon Kingdoms",
      "text": "By the 6th century, the Angles had established several kingdoms in what is now England, including Mercia, Northumbria, and East Anglia. These kingdoms were part of the Heptarchy, a collective name for the seven kingdoms of Anglo-Saxon England.",
      "date": "0500"
    },
    {
      "headline": "Formation of England",
      "text": "The name 'England' is derived from the Angles. Over time, the various Anglo-Saxon kingdoms unified, and the term 'England' came to be used for the entire region.",
      "date": "0800"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Formation of the Sons of Liberty",
      "text": "The Sons of Liberty was formed in the summer of 1765 in response to the Stamp Act imposed by the British government. The group was established to advance the rights of the colonists and to fight against taxation without representation.",
      "date": "1765"
    },
    {
      "headline": "Stamp Act Congress",
      "text": "In October 1765, the Sons of Liberty played a significant role in organizing the Stamp Act Congress in New York City, where representatives from several colonies gathered to devise a unified protest against the Stamp Act.",
      "date": "1765-10"
    },
    {
      "headline": "Stamp Act Riots",
      "text": "Throughout late 1765, the Sons of Liberty organized and participated in riots and protests against the Stamp Act, including the destruction of the home of Andrew Oliver, the Massachusetts stamp distributor, on August 14, 1765.",
      "date": "1765-08-14"
    },
    {
      "headline": "Repeal of the Stamp Act",
      "text": "On March 18, 1766, the British Parliament repealed the Stamp Act, largely due to the widespread protests and economic boycotts organized by the Sons of Liberty and other colonial groups.",
      "date": "1766-03-18"
    },
    {
      "headline": "Boston Tea Party",
      "text": "On December 16, 1773, members of the Sons of Liberty, disguised as Mohawk Indians, boarded British ships in Boston Harbor and dumped 342 chests of tea into the water in protest of the Tea Act.",
      "date": "1773-12-16"
    },
    {
      "headline": "Intolerable Acts",
      "text": "In response to the Boston Tea Party, the British government enacted the Intolerable Acts in 1774, which further galvanized the Sons of Liberty and other colonial groups to resist British rule.",
      "date": "1774"
    },
    {
      "headline": "Role in the American Revolution",
      "text": "Throughout the American Revolution, the Sons of Liberty continued to play a crucial role in organizing resistance against British rule, including mobilizing colonial militias and spreading revolutionary ideas.",
      "date": "1775-1783"
    }
  ]
}

