  "timeline": [
    {
      "headline": "First March - Bloody Sunday",
      "text": "On March 7, 1965, around 600 civil rights marchers headed east out of Selma on U.S. Route 80. They got only as far as the Edmund Pettus Bridge, six blocks away, where state and local lawmen attacked them with billy clubs and tear gas and drove them back into Selma. This day became known as 'Bloody Sunday'.",
      "date": "1965-03-07"
    },
    {
      "headline": "Second March - Turnaround Tuesday",
      "text": "On March 9, 1965, Martin Luther King Jr. led a symbolic march to the bridge. The marchers were again confronted by a wall of state troopers. King led the marchers in prayer and then turned them around, avoiding another confrontation. This event became known as 'Turnaround Tuesday'.",
      "date": "1965-03-09"
    },
    {
      "headline": "Third March - Successful March to Montgomery",
      "text": "On March 21, 1965, under the protection of federal forces, approximately 3,200 marchers set out from Selma to Montgomery. They marched an average of 12 miles a day and slept in fields. By the time they reached the capitol on March 25, their numbers had swelled to 25,000.",
      "date": "1965-03-21"
    },
    {
      "headline": "Arrival in Montgomery",
      "text": "On March 25, 1965, the marchers arrived in Montgomery. Martin Luther King Jr. delivered a speech on the steps of the state capitol, calling for voting rights for African Americans.",
      "date": "1965-03-25"
    },
    {
      "headline": "Passage of the Voting Rights Act",
      "text": "On August 6, 1965, the Voting Rights Act was signed into law by President Lyndon B. Johnson. This landmark legislation prohibited racial discrimination in voting, largely as a result of the Selma to Montgomery marches.",
      "date": "1965-08-06"
    }
  ]
}

