  "timeline": [
    {
      "headline": "First Mention of Cluj-Napoca",
      "text": "The first mention of Cluj-Napoca, then known as Napoca, dates back to the Roman period. The city was established as a municipium in 124 AD.",
      "date": "0124"
    },
    {
      "headline": "Elevation to Colony",
      "text": "In 197 AD, Napoca was elevated to the status of a colonia, which was the highest rank of Roman city.",
      "date": "0197"
    },
    {
      "headline": "Medieval Development",
      "text": "By the 12th century, Cluj had developed into a significant medieval town, known as Klausenburg in German and Kolozsvár in Hungarian.",
      "date": "1100"
    },
    {
      "headline": "Part of the Kingdom of Hungary",
      "text": "In 1316, Cluj was granted city status by Charles I of Hungary, marking its importance within the Kingdom of Hungary.",
      "date": "1316"
    },
    {
      "headline": "Capital of the Grand Principality of Transylvania",
      "text": "During the 16th century, Cluj became the capital of the Grand Principality of Transylvania, a status it held for several decades.",
      "date": "1500"
    },
    {
      "headline": "Austro-Hungarian Compromise",
      "text": "Following the Austro-Hungarian Compromise of 1867, Cluj became part of the Austro-Hungarian Empire, losing its status as the capital of Transylvania.",
      "date": "1867"
    },
    {
      "headline": "Union with Romania",
      "text": "In 1918, after World War I, Cluj became part of Romania following the union of Transylvania with Romania.",
      "date": "1918"
    },
    {
      "headline": "Second Vienna Award",
      "text": "In 1940, the Second Vienna Award resulted in Northern Transylvania, including Cluj, being ceded to Hungary.",
      "date": "1940"
    },
    {
      "headline": "Return to Romania",
      "text": "After World War II, in 1945, Cluj was returned to Romania as part of the post-war settlement.",
      "date": "1945"
    },
    {
      "headline": "Modern Development",
      "text": "In the late 20th and early 21st centuries, Cluj-Napoca developed into a major cultural, academic, and economic center in Romania.",
      "date": "2000"
    }
  ]
}

