{
  "timeline": [
    {
      "headline": "Origin of Kathak",
      "text": "Kathak originated in ancient northern India with the traveling bards known as Kathakars, who communicated stories from the Hindu epics through dance, songs, and music. The term 'Kathak' is derived from the Sanskrit word 'katha' meaning 'story'.",
      "date": "-0500"
    },
    {
      "headline": "Development during the Bhakti Movement",
      "text": "During the Bhakti movement, which began around the 15th century, Kathak was influenced by devotional themes and became a means of expressing devotion to Hindu deities.",
      "date": "1400"
    },
    {
      "headline": "Mughal Influence on Kathak",
      "text": "In the 16th and 17th centuries, Kathak was influenced by Persian and Mughal cultures, incorporating elements of court dance and music, and evolving into a more sophisticated form.",
      "date": "1600"
    },
    {
      "headline": "Kathak in the Courts of Nawabs",
      "text": "By the 18th century, Kathak had become a prominent form of entertainment in the courts of Nawabs, particularly in Lucknow and Jaipur, leading to the development of distinct styles or gharanas.",
      "date": "1700"
    },
    {
      "headline": "British Colonial Period",
      "text": "During the British colonial period in the 19th century, Kathak faced decline due to the suppression of Indian cultural practices. However, it survived through the patronage of princely states and revival efforts.",
      "date": "1800"
    },
    {
      "headline": "Revival of Kathak",
      "text": "In the early 20th century, Kathak experienced a revival as part of the Indian cultural renaissance, with efforts to preserve and promote it as a classical dance form.",
      "date": "1900"
    },
    {
      "headline": "Post-Independence Recognition",
      "text": "After India's independence in 1947, Kathak gained recognition as one of the major classical dance forms of India, with institutions established for its teaching and promotion.",
      "date": "1947"
    }
  ]
}

