      "headline": "Hundred Years' War",
      "text": "The Hundred Years' War between France and England began in 1337 and lasted until 1453, significantly impacting the French monarchy and territory.",
      "date": "1337"
    },
    {
      "headline": "Joan of Arc's Campaign",
      "text": "In 1429, Joan of Arc led a successful campaign to lift the siege of Orléans, turning the tide in favor of the French during the Hundred Years' War.",
      "date": "1429"
    },
    {
      "headline": "End of the Hundred Years' War",
      "text": "The Hundred Years' War ended in 1453 with the French victory at the Battle of Castillon, solidifying French control over its territory.",
      "date": "1453"
    },
    {
      "headline": "French Wars of Religion",
      "text": "The French Wars of Religion were a series of conflicts from 1562 to 1598 between Catholics and Huguenots (Protestants) in France.",
      "date": "1562"
    },
    {
      "headline": "Edict of Nantes",
      "text": "In 1598, King Henry IV issued the Edict of Nantes, granting religious freedom to Protestants and ending the French Wars of Religion.",
      "date": "1598"
    },
    {
      "headline": "Reign of Louis XIV",
      "text": "Louis XIV, known as the Sun King, reigned from 1643 to 1715 and established absolute monarchy in France.",
      "date": "1643"
    },
    {
      "headline": "French Revolution",
      "text": "The French Revolution began in 1789, leading to the overthrow of the monarchy and the establishment of the French Republic.",
      "date": "1789"
    },
    {
      "headline": "Napoleon Bonaparte's Rule",
      "text": "Napoleon Bonaparte rose to power, becoming Emperor of the French in 1804 and leading France through a series of military campaigns across Europe.",
      "date": "1804"
    },
    {
      "headline": "Fall of Napoleon",
      "text": "Napoleon was defeated at the Battle of Waterloo in 1815, leading to his abdication and the restoration of the monarchy in France.",
      "date": "1815"
    },
    {
      "headline": "Establishment of the Third Republic",
      "text": "The Third Republic was established in France in 1870 following the collapse of the Second Empire.",
      "date": "1870"
    },
    {
      "headline": "World War I",
      "text": "France was a major participant in World War I from 1914 to 1918, suffering significant casualties and devastation.",
      "date": "1914"
