  "timeline": [
    {
      "headline": "Birth of Édouard Manet",
      "text": "Édouard Manet was born on January 23, 1832, in Paris, France.",
      "date": "1832-01-23"
    },
    {
      "headline": "Manet's Early Art Education",
      "text": "In 1848, Manet went to Rio de Janeiro as a cadet on a training vessel, but upon returning to France, he decided to pursue a career in art.",
      "date": "1848"
    },
    {
      "headline": "Studying under Thomas Couture",
      "text": "From 1850 to 1856, Manet studied under the academic painter Thomas Couture, where he learned the basics of painting.",
      "date": "1850"
    },
    {
      "headline": "First Major Work: The Absinthe Drinker",
      "text": "In 1859, Manet completed 'The Absinthe Drinker', one of his first major works, which was rejected by the Paris Salon.",
      "date": "1859"
    },
    {
      "headline": "Exhibition of The Spanish Singer",
      "text": "In 1861, Manet's painting 'The Spanish Singer' was accepted by the Paris Salon, earning him his first success.",
      "date": "1861"
    },
    {
      "headline": "Creation of Luncheon on the Grass",
      "text": "In 1863, Manet painted 'Le Déjeuner sur l'herbe' (Luncheon on the Grass), which caused a scandal at the Salon des Refusés.",
      "date": "1863"
    },
    {
      "headline": "Olympia's Controversy",
      "text": "In 1865, Manet exhibited 'Olympia' at the Paris Salon, which caused a public scandal due to its bold subject matter.",
      "date": "1865"
    },
    {
      "headline": "Manet's Influence on Impressionism",
      "text": "In the late 1860s and early 1870s, Manet became associated with the Impressionists, influencing artists like Claude Monet and Edgar Degas.",
      "date": "1870"
    },
    {
      "headline": "The Execution of Emperor Maximilian",
      "text": "In 1868, Manet completed 'The Execution of Emperor Maximilian', a politically charged painting reflecting contemporary events.",
      "date": "1868"
    },
    {
      "headline": "Exhibition at the Salon",
      "text": "In 1874, Manet exhibited 'The Railway' at the Paris Salon, showcasing his continued evolution as an artist.",
      "date": "1874"
    },
    {
      "headline": "Manet's Declining Health",
      "text": "In the late 1870s, Manet's health began to decline due to syphilis, affecting his ability to work.",
      "date": "1879"
    },
    {
      "headline": "Awarded the Legion of Honour",
      "text": "In 1881, Manet was awarded the Legion of Honour, recognizing his contributions to French art.",
      "date": "1881"
    },
    {
      "headline": "Death of Édouard Manet",
      "text": "Édouard Manet died on April 30, 1883, in Paris, France, after suffering from complications related to syphilis.",
      "date": "1883-04-30"
    }
  ]
}

