    {
      "headline": "Formation of Meteor Crater",
      "text": "Meteor Crater was formed approximately 50,000 years ago during the Pleistocene epoch when a nickel-iron meteorite about 160 feet (50 meters) in diameter struck the Earth.",
      "date": "-48000"
    },
    {
      "headline": "Discovery by European Americans",
      "text": "In the late 19th century, European Americans discovered the crater. It was initially thought to be a volcanic crater.",
      "date": "1800"
    },
    {
      "headline": "Daniel Barringer's Investigation",
      "text": "In 1903, mining engineer Daniel Barringer became convinced that the crater was the result of a meteorite impact and secured mining rights to the land.",
      "date": "1903"
    },
    {
      "headline": "Barringer's Drilling Efforts",
      "text": "Between 1903 and 1905, Daniel Barringer conducted drilling operations in an attempt to find the meteorite, but he was unsuccessful.",
      "date": "1905"
    },
    {
      "headline": "Scientific Acceptance of Impact Origin",
      "text": "In the 1960s, scientific consensus was reached that Meteor Crater was indeed formed by a meteorite impact, confirming Barringer's hypothesis.",
      "date": "1960"
    },
    {
      "headline": "National Natural Landmark Designation",
      "text": "In 1967, Meteor Crater was designated as a National Natural Landmark due to its significance as a well-preserved meteorite impact site.",
      "date": "1967"
    }
  ]
}

