{
  "timeline": [
    {
      "headline": "Emergence of Progressivism",
      "text": "Progressivism began to emerge in the United States as a political movement in response to modernization, including the growth of large corporations, pollution, and political corruption. This movement started gaining traction at the end of the 19th century.",
      "date": "1890"
    },
    {
      "headline": "Progressive Era",
      "text": "The Progressive Era is generally considered to have spanned from the 1890s to the 1920s. During this time, progressivism reached its height, influencing American politics significantly.",
      "date": "1890-1920"
    },
    {
      "headline": "Theodore Roosevelt's Presidency",
      "text": "Theodore Roosevelt, who served as the 26th President of the United States from 1901 to 1909, was a key figure in the Progressive Movement. His policies, known as the Square Deal, focused on conservation of natural resources, control of corporations, and consumer protection.",
      "date": "1901-1909"
    },
    {
      "headline": "Establishment of the Federal Reserve System",
      "text": "In 1913, the Federal Reserve System was established as part of the progressive reforms to provide the country with a safer, more flexible, and more stable monetary and financial system.",
      "date": "1913"
    },
    {
      "headline": "Ratification of the 16th Amendment",
      "text": "The 16th Amendment to the United States Constitution, allowing Congress to levy an income tax, was ratified on February 3, 1913. This was a significant progressive reform aimed at addressing economic inequality.",
      "date": "1913-02-03"
    },
    {
      "headline": "Ratification of the 17th Amendment",
      "text": "The 17th Amendment, which established the direct election of United States Senators by popular vote, was ratified on April 8, 1913. This was another key reform of the Progressive Era aimed at reducing corruption.",
      "date": "1913-04-08"
    },
    {
      "headline": "Women's Suffrage Movement",
      "text": "The women's suffrage movement, a significant part of the Progressive Era, culminated in the ratification of the 19th Amendment on August 18, 1920, granting women the right to vote.",
      "date": "1920-08-18"
    },
    {
      "headline": "New Deal Era",
      "text": "The New Deal, implemented by President Franklin D. Roosevelt in response to the Great Depression, was influenced by progressive ideas and marked a continuation of progressive policies in the 1930s.",
      "date": "1933-1939"
    },
    {
      "headline": "Great Society Programs",
      "text": "In the 1960s, President Lyndon B. Johnson's Great Society programs, which aimed to eliminate poverty and racial injustice, were influenced by progressive ideals.",
      "date": "1964-1965"
    },
    {
      "headline": "Modern Progressivism",
      "text": "Into the 21st century, progressivism continues to advocate for policies that are generally considered social democratic and part of the American Left, addressing issues such as healthcare, education, and environmental protection.",
      "date": "2000"
    }
  ]
}

