      "headline": "Battle of Stalingrad",
      "text": "The Battle of Stalingrad, one of the deadliest battles in history, began on August 23, 1942, and ended with the surrender of the German 6th Army on February 2, 1943.",
      "date": "1942-08-23"
    },
    {
      "headline": "D-Day and the Normandy Invasion",
      "text": "On June 6, 1944, Allied forces launched the Normandy Invasion, also known as D-Day, which marked the beginning of the end for the German Army in Western Europe.",
      "date": "1944-06-06"
    },
    {
      "headline": "German Surrender",
      "text": "On May 7, 1945, the German Army surrendered unconditionally to the Allied forces, effectively ending World War II in Europe.",
      "date": "1945-05-07"
    },
    {
      "headline": "Formal Dissolution of the German Army",
      "text": "The German Army was formally dissolved in August 1946, following the end of World War II and the occupation of Germany by Allied forces.",
      "date": "1946-08"
    }
  ]
}

