{
  "timeline": [
    {
      "headline": "Birth of Xenophon",
      "text": "Xenophon was born around 430 BCE in Athens, Greece.",
      "date": "-0430"
    },
    {
      "headline": "Participation in the Expedition of Cyrus the Younger",
      "text": "In 401 BCE, Xenophon joined the expedition of Cyrus the Younger against the Persian king Artaxerxes II. This marked the beginning of his military career.",
      "date": "-0401"
    },
    {
      "headline": "Elected Leader of the Ten Thousand",
      "text": "In 401 BCE, after the death of Cyrus the Younger and the capture of Greek generals, Xenophon was elected as one of the leaders of the Ten Thousand, the Greek mercenaries who had to retreat from Persia.",
      "date": "-0401"
    },
    {
      "headline": "Retreat of the Ten Thousand",
      "text": "Xenophon led the Ten Thousand on a successful retreat from Persia to the Black Sea, a journey that lasted until 399 BCE. This retreat was later documented in his work 'Anabasis'.",
      "date": "-0399"
    },
    {
      "headline": "Settlement in Scillus",
      "text": "After returning to Greece, Xenophon settled in Scillus, near Olympia, around 394 BCE, where he lived for several years.",
      "date": "-0394"
    },
    {
      "headline": "Writing of 'Anabasis'",
      "text": "During his time in Scillus, Xenophon wrote 'Anabasis', a detailed account of the expedition with Cyrus and the retreat of the Ten Thousand.",
      "date": "-0380"
    },
    {
      "headline": "Writing of 'Hellenica'",
      "text": "Xenophon wrote 'Hellenica', a history of Greece that picks up where Thucydides left off, covering the final years of the Peloponnesian War and its aftermath.",
      "date": "-0359"
    },
    {
      "headline": "Death of Xenophon",
      "text": "Xenophon died around 354 BCE, possibly in Corinth, Greece.",
      "date": "-0354"
    }
  ]
}

