{
  "timeline": [
    {
      "headline": "Invention of the Wheel",
      "text": "The wheel was invented in the late Neolithic period, around 3500 BCE, in Mesopotamia. It was initially used for pottery making and later adapted for transportation.",
      "date": "-3500"
    },
    {
      "headline": "Invention of Writing",
      "text": "Writing was invented around 3200 BCE in Mesopotamia. The earliest form of writing was cuneiform, used for record-keeping and communication.",
      "date": "-3200"
    },
    {
      "headline": "Invention of the Plow",
      "text": "The plow was invented around 3000 BCE in Mesopotamia. It revolutionized agriculture by increasing efficiency in farming.",
      "date": "-3000"
    },
    {
      "headline": "Invention of the Sailboat",
      "text": "The sailboat was invented around 3000 BCE in Mesopotamia. It allowed for more efficient transportation and trade across bodies of water.",
      "date": "-3000"
    },
    {
      "headline": "Invention of the Alphabet",
      "text": "The first alphabet was developed around 1800 BCE by the Phoenicians. It was a significant advancement in written communication.",
      "date": "-1800"
    },
    {
      "headline": "Invention of Iron Smelting",
      "text": "Iron smelting was developed around 1200 BCE, marking the beginning of the Iron Age. It allowed for stronger tools and weapons.",
      "date": "-1200"
    },
    {
      "headline": "Invention of the Water Mill",
      "text": "The water mill was invented around 3rd century BCE. It was used for grinding grain and later adapted for other industrial uses.",
      "date": "-0300"
    },
    {
      "headline": "Invention of Paper",
      "text": "Paper was invented in China around 105 CE by Cai Lun. It became a crucial medium for writing and documentation.",
      "date": "0105"
    },
    {
      "headline": "Invention of Gunpowder",
      "text": "Gunpowder was invented in China during the 9th century. It was initially used for fireworks and later for military purposes.",
      "date": "0800"
    },
    {
      "headline": "Invention of the Printing Press",
      "text": "The printing press was invented by Johannes Gutenberg around 1440. It revolutionized the production of books and the dissemination of knowledge.",
      "date": "1440"
    },
    {
      "headline": "Invention of the Steam Engine",
      "text": "The steam engine was developed in the late 17th century, with significant improvements by James Watt in the 1760s. It played a key role in the Industrial Revolution.",
      "date": "1760"
    },
    {
      "headline": "Invention of the Telegraph",
      "text": "The telegraph was invented in the 1830s by Samuel Morse and others. It enabled long-distance communication using coded signals.",
      "date": "1830"
    },
    {
      "headline": "Invention of the Telephone",
      "text": "The telephone was invented by Alexander Graham Bell in 1876. It allowed for voice communication over long distances.",
      "date": "1876"
    },
    {
      "headline": "Invention of the Light Bulb",
      "text": "The light bulb was invented by Thomas Edison in 1879. It provided a practical and long-lasting source of artificial light.",
      "date": "1879"
    },
    {
      "headline": "Invention of the Airplane",
      "text": "The Wright brothers, Orville and Wilbur, invented the first successful airplane in 1903. It marked the beginning of powered flight.",
      "date": "1903"
    },
    {
      "headline": "Invention of the Internet",
      "text": "The internet was developed in the late 20th century, with significant contributions from various researchers. It revolutionized global communication and information sharing.",
      "date": "1980"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Formation of the Moon",
      "text": "The Moon, including its far side, formed approximately 4.5 billion years ago from the debris left over after a giant impact between Earth and a Mars-sized body.",
      "date": "-4500000000"
    },
    {
      "headline": "Synchronous Rotation Established",
      "text": "The Moon's synchronous rotation, which causes the same side to always face Earth, was established early in its history, billions of years ago.",
      "date": "-4500000000"
    },
    {
      "headline": "Formation of the South Pole–Aitken Basin",
      "text": "The South Pole–Aitken basin, one of the largest craters in the Solar System, formed on the far side of the Moon over 4 billion years ago.",
      "date": "-4000000000"
    },
    {
      "headline": "First Images of the Far Side",
      "text": "On October 7, 1959, the Soviet spacecraft Luna 3 took the first photographs of the far side of the Moon, revealing its rugged terrain.",
      "date": "1959-10-07"
    },
    {
      "headline": "First Human Observation",
      "text": "During the Apollo 8 mission in December 1968, astronauts became the first humans to see the far side of the Moon with their own eyes.",
      "date": "1968-12"
    },
    {
      "headline": "Chang'e 4 Landing",
      "text": "On January 3, 2019, China's Chang'e 4 mission became the first spacecraft to successfully land on the far side of the Moon.",
      "date": "2019-01-03"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Initial Announcement of Dreadnought-class Submarine",
      "text": "In 2006, the UK government announced plans to replace the Vanguard-class submarines with a new class of ballistic missile submarines to maintain the continuous at-sea deterrent (CASD).",
      "date": "2006"
