    {
      "headline": "Establishment of the Kingdom of Naples",
      "text": "The Kingdom of Naples was established in 1282 following the War of the Sicilian Vespers (1282–1302), when the island of Sicily revolted and was conquered by the Crown of Aragon, becoming a separate kingdom. This left the Neapolitan mainland under the possession of Charles of Anjou.",
      "date": "1282"
    },
    {
      "headline": "Death of Joanna I",
      "text": "In the late 14th century, two competing lines of the Angevin family competed for the Kingdom of Naples. This conflict resulted in the death of Joanna I by Charles III of Naples.",
      "date": "1382"
    },
    {
      "headline": "Joanna II adopts Alfonso V of Aragon as heir",
      "text": "Joanna II, daughter of Charles III, adopted King Alfonso V of Aragon as her heir, setting the stage for the eventual unification of Naples with the Aragonese dominions.",
      "date": "1421"
    },
    {
      "headline": "Unification with Aragon",
      "text": "In 1442, King Alfonso V of Aragon united Naples into his Aragonese dominions, effectively bringing the Kingdom of Naples under Aragonese control.",
      "date": "1442"
    },
    {
      "headline": "End of the Kingdom of Naples",
      "text": "The Kingdom of Naples ceased to exist as a separate entity in 1816 when it was merged with the Kingdom of Sicily to form the Kingdom of the Two Sicilies.",
      "date": "1816"
    }
  ]
}

