{
  "timeline": [
    {
      "headline": "Establishment of the Warsaw Ghetto",
      "text": "The Warsaw Ghetto was established by the German authorities in October 1940, confining over 400,000 Jews in an area of 3.4 square kilometers.",
      "date": "1940-10"
    },
    {
      "headline": "First Deportations from the Warsaw Ghetto",
      "text": "In July 1942, the Nazis began the mass deportation of Jews from the Warsaw Ghetto to the Treblinka extermination camp. By September 1942, about 300,000 Jews had been deported.",
      "date": "1942-07"
    },
    {
      "headline": "Formation of the Jewish Combat Organization (ŻOB)",
      "text": "In October 1942, the Jewish Combat Organization (Żydowska Organizacja Bojowa, ŻOB) was formed to resist further deportations and fight against the Nazis.",
      "date": "1942-10"
    },
    {
      "headline": "First Armed Resistance",
      "text": "On January 18, 1943, the ŻOB and other Jewish fighters launched an armed resistance against the Nazis during a deportation, marking the first significant act of armed resistance in the ghetto.",
      "date": "1943-01-18"
    },
    {
      "headline": "Start of the Warsaw Ghetto Uprising",
      "text": "The Warsaw Ghetto Uprising began on April 19, 1943, when Nazi forces entered the ghetto to begin the final deportation of its remaining inhabitants. Jewish fighters launched a full-scale revolt.",
      "date": "1943-04-19"
    },
    {
      "headline": "End of the Warsaw Ghetto Uprising",
      "text": "The uprising ended on May 16, 1943, after the Nazis systematically destroyed the ghetto, including the Great Synagogue of Warsaw, and killed or captured the remaining fighters.",
      "date": "1943-05-16"
    },
    {
      "headline": "Aftermath and Legacy",
      "text": "The Warsaw Ghetto Uprising became a symbol of Jewish resistance against the Nazis. It inspired other uprisings and remains a significant event in Holocaust history.",
      "date": "1943"
    }
  ]
}

