{
  "timeline": [
    {
      "headline": "Earliest Known Examples of Linear B",
      "text": "The earliest known examples of Linear B date to around 1450 BC. This script was used for writing in Mycenaean Greek, the earliest attested form of the Greek language.",
      "date": "-1450"
    },
    {
      "headline": "Adaptation from Linear A",
      "text": "Linear B was adapted from the earlier Linear A script, which was used for writing the Minoan language. Linear A remains undeciphered.",
      "date": "-1450"
    },
    {
      "headline": "Usage in Mycenaean Civilization",
      "text": "Linear B was primarily used in the palace archives of Mycenaean centers such as Knossos, Kydonia, Pylos, Thebes, and Mycenae.",
      "date": "-1450"
    },
    {
      "headline": "Disappearance of Linear B",
      "text": "Linear B disappeared with the fall of the Mycenaean civilization during the Late Bronze Age collapse, around 1200 BC.",
      "date": "-1200"
    },
    {
      "headline": "Greek Dark Ages",
      "text": "Following the disappearance of Linear B, the succeeding period known as the Greek Dark Ages shows no evidence of the use of writing.",
      "date": "-1200"
    }
  ]
}

