{
  "timeline": [
    {
      "headline": "Formation of the Union Army",
      "text": "The Union Army was formed in 1861 at the start of the American Civil War, following the secession of Southern states and the formation of the Confederate States of America.",
      "date": "1861"
    },
    {
      "headline": "First Battle of Bull Run",
      "text": "On July 21, 1861, the Union Army suffered a defeat at the First Battle of Bull Run, the first major battle of the Civil War, near Manassas, Virginia.",
      "date": "1861-07-21"
    },
    {
      "headline": "Battle of Antietam",
      "text": "On September 17, 1862, the Union Army fought the Confederate Army at the Battle of Antietam in Maryland, resulting in the bloodiest single-day battle in American history.",
      "date": "1862-09-17"
    },
    {
      "headline": "Emancipation Proclamation",
      "text": "On January 1, 1863, President Abraham Lincoln issued the Emancipation Proclamation, which declared the freedom of all slaves in Confederate-held territory, altering the Union Army's war aims.",
      "date": "1863-01-01"
    },
    {
      "headline": "Battle of Gettysburg",
      "text": "From July 1 to July 3, 1863, the Union Army achieved a significant victory at the Battle of Gettysburg in Pennsylvania, marking a turning point in the Civil War.",
      "date": "1863-07-01"
    },
    {
      "headline": "Siege of Vicksburg",
      "text": "On July 4, 1863, the Union Army, under General Ulysses S. Grant, captured Vicksburg, Mississippi, gaining control of the Mississippi River and splitting the Confederacy.",
      "date": "1863-07-04"
    },
    {
      "headline": "Grant appointed General-in-Chief",
      "text": "On March 9, 1864, Ulysses S. Grant was appointed General-in-Chief of all Union armies, leading to a more coordinated military strategy.",
      "date": "1864-03-09"
    },
    {
      "headline": "Sherman's March to the Sea",
      "text": "From November 15 to December 21, 1864, Union General William Tecumseh Sherman led a destructive campaign from Atlanta to Savannah, Georgia, known as Sherman's March to the Sea.",
      "date": "1864-11-15"
    },
    {
      "headline": "Surrender at Appomattox Court House",
      "text": "On April 9, 1865, Confederate General Robert E. Lee surrendered to Union General Ulysses S. Grant at Appomattox Court House in Virginia, effectively ending the Civil War.",
      "date": "1865-04-09"
    },
    {
      "headline": "Disbandment of the Union Army",
      "text": "Following the end of the Civil War, the Union Army was gradually disbanded, with most soldiers mustered out by 1866.",
      "date": "1866"
    }
  ]
}

