{
  "timeline": [
    {
      "headline": "Commissioning of the Necklace",
      "text": "In 1772, King Louis XV of France commissioned a diamond necklace for his mistress, Madame du Barry. The necklace was designed by the jewelers Boehmer and Bassenge.",
      "date": "1772"
    },
    {
      "headline": "Death of King Louis XV",
      "text": "King Louis XV died in 1774 before the necklace was completed, leaving the jewelers with a costly piece that no one had purchased.",
      "date": "1774"
    },
    {
      "headline": "Attempt to Sell the Necklace to Marie Antoinette",
      "text": "In 1778, the jewelers attempted to sell the necklace to Queen Marie Antoinette, but she declined, citing the expense.",
      "date": "1778"
    },
    {
      "headline": "Involvement of Jeanne de la Motte",
      "text": "In 1784, Jeanne de la Motte, a con artist, convinced Cardinal de Rohan that she was in favor with Queen Marie Antoinette and could help him win her favor by purchasing the necklace on her behalf.",
      "date": "1784"
    },
    {
      "headline": "Purchase of the Necklace",
      "text": "In August 1784, Cardinal de Rohan agreed to purchase the necklace, believing he was acting on behalf of the Queen. He received a letter, supposedly from Marie Antoinette, authorizing the purchase.",
      "date": "1784-08"
    },
    {
      "headline": "Discovery of the Fraud",
      "text": "In 1785, the fraud was discovered when the jewelers demanded payment from the Queen, who denied any knowledge of the transaction.",
      "date": "1785"
    },
    {
      "headline": "Trial and Public Scandal",
      "text": "The affair went to trial in 1786, causing a public scandal that tarnished the reputation of the monarchy. Jeanne de la Motte was found guilty and sentenced to whipping, branding, and imprisonment.",
      "date": "1786"
    },
    {
      "headline": "Impact on the French Monarchy",
      "text": "The Affair of the Diamond Necklace contributed to the public's negative perception of the monarchy, particularly Marie Antoinette, and is considered one of the events leading up to the French Revolution.",
      "date": "1786"
    }
  ]
}

