{
  "timeline": [
    {
      "headline": "Origin of the Term 'Steganography'",
      "text": "The term 'steganography' originates from the Greek words 'steganós', meaning 'covered or concealed', and '-graphia', meaning 'writing'.",
      "date": "-0500"
    },
    {
      "headline": "Earliest Known Use of Steganography",
      "text": "The earliest known use of steganography dates back to around 440 BCE when Herodotus documented the use of hidden messages in wax tablets.",
      "date": "-0440"
    },
    {
      "headline": "Steganography in Ancient Greece",
      "text": "In ancient Greece, messages were hidden under wax on writing tablets or tattooed on the shaved heads of slaves, which were then covered by hair regrowth.",
      "date": "-0500"
    },
    {
      "headline": "Steganography in the Middle Ages",
      "text": "During the Middle Ages, steganography was used in various forms, such as writing messages on the inside of hard-boiled eggs using vinegar-based ink.",
      "date": "1200"
    },
    {
      "headline": "Johannes Trithemius' 'Steganographia'",
      "text": "In 1499, Johannes Trithemius wrote 'Steganographia', a book on cryptography and steganography, which was published posthumously in 1606.",
      "date": "1499"
    },
    {
      "headline": "Steganography in World War II",
      "text": "During World War II, steganography was used to send covert messages, such as microdots, which were tiny photographs that could be hidden in letters.",
      "date": "1940"
    },
    {
      "headline": "Digital Steganography Emergence",
      "text": "With the advent of computers, digital steganography emerged, allowing for the concealment of information within digital files such as images, audio, and video.",
      "date": "1980"
    },
    {
      "headline": "Development of Steganographic Software",
      "text": "In the late 1990s, software tools for digital steganography became more widely available, enabling users to hide data within digital media files.",
      "date": "1995"
    },
    {
      "headline": "Steganography in Modern Cybersecurity",
      "text": "In the 21st century, steganography is used in cybersecurity for both legitimate purposes, such as watermarking, and malicious activities, such as data exfiltration.",
      "date": "2000"
    }
  ]
}

