    },
    {
      "headline": "Arrival of Vasco da Gama",
      "text": "On May 20, 1498, Portuguese explorer Vasco da Gama landed in Kozhikode, marking the first European sea voyage to India.",
      "date": "1498-05-20"
    },
    {
      "headline": "Portuguese Establishment",
      "text": "In 1511, the Portuguese established a trading post in Kozhikode, which led to conflicts with local rulers.",
      "date": "1511"
    },
    {
      "headline": "Dutch Influence",
      "text": "In the 17th century, the Dutch East India Company established a presence in Kozhikode, competing with the Portuguese for control of the spice trade.",
      "date": "1600"
    },
    {
      "headline": "British Control",
      "text": "In 1792, following the Third Anglo-Mysore War, Kozhikode came under British control as part of the Malabar District.",
      "date": "1792"
    },
    {
      "headline": "Independence and Integration into India",
      "text": "After India's independence in 1947, Kozhikode became part of the state of Kerala in 1956.",
      "date": "1956"
    },
