{
  "timeline": [
    {
      "headline": "Birth of M. Visvesvaraya",
      "text": "Mokshagundam Visvesvaraya was born on September 15, 1861, in Muddenahalli, Kingdom of Mysore, British India.",
      "date": "1861-09-15"
    },
    {
      "headline": "Graduation from College",
      "text": "In 1881, Visvesvaraya graduated from the Central College, Bangalore, and later attended the College of Engineering, Pune, where he earned a degree in civil engineering.",
      "date": "1881"
    },
    {
      "headline": "Joining Public Works Department",
      "text": "In 1884, Visvesvaraya joined the Public Works Department of Bombay as an Assistant Engineer.",
      "date": "1884"
    },
    {
      "headline": "Flood Protection System in Hyderabad",
      "text": "In 1909, Visvesvaraya designed a flood protection system for the city of Hyderabad, which had been devastated by floods.",
      "date": "1909"
    },
    {
      "headline": "Dewan of Mysore",
      "text": "In 1912, Visvesvaraya was appointed as the Dewan of Mysore, a position he held until 1918. During his tenure, he implemented several industrial and educational reforms.",
      "date": "1912"
    },
    {
      "headline": "Retirement from Dewanship",
      "text": "Visvesvaraya retired from his position as Dewan of Mysore in 1918, after six years of service.",
      "date": "1918"
    },
    {
      "headline": "Knight Commander of the Order of the Indian Empire",
      "text": "In 1915, Visvesvaraya was knighted as a Knight Commander of the Order of the Indian Empire (KCIE) by King George V for his contributions to public good.",
      "date": "1915"
    },
    {
      "headline": "Bharat Ratna Award",
      "text": "In 1955, Visvesvaraya was awarded the Bharat Ratna, India's highest civilian honor, in recognition of his outstanding contributions to engineering and public service.",
      "date": "1955"
    },
    {
      "headline": "Death of M. Visvesvaraya",
      "text": "M. Visvesvaraya passed away on April 14, 1962, in Bangalore, India, at the age of 100.",
      "date": "1962-04-14"
    }
  ]
}

