    {
      "headline": "Introduction of the Swedish Krona",
      "text": "The Swedish krona was introduced as the official currency of Sweden, replacing the riksdaler. The krona was introduced as part of the Scandinavian Monetary Union, which was established in 1873.",
      "date": "1873"
    },
    {
      "headline": "Scandinavian Monetary Union Dissolution",
      "text": "The Scandinavian Monetary Union, which included Sweden, Denmark, and Norway, was dissolved in 1914 due to the outbreak of World War I. Despite the dissolution, Sweden continued to use the krona.",
      "date": "1914"
    },
    {
      "headline": "Decimalization of the Krona",
      "text": "The Swedish krona was decimalized, meaning it was divided into 100 öre. This decimalization was part of the original introduction of the currency in 1873.",
      "date": "1873"
    },
    {
      "headline": "Sweden Joins the European Union",
      "text": "Sweden joined the European Union on January 1, 1995. Despite being a member, Sweden has not adopted the euro and continues to use the krona as its currency.",
      "date": "1995-01-01"
    },
    {
      "headline": "Referendum on Euro Adoption",
      "text": "In 2003, Sweden held a referendum to decide whether to adopt the euro as its currency. The majority voted against adopting the euro, and Sweden retained the krona.",
      "date": "2003"
    },
    {
      "headline": "Swedish Krona in Global Trade",
      "text": "As of April 2016, the Swedish krona was the ninth-most traded currency in the world by value, highlighting its significance in global financial markets.",
      "date": "2016-04"
    }
  ]
}

