  "timeline": [
    {
      "headline": "Birth of Jacques-Louis David",
      "text": "Jacques-Louis David was born on August 30, 1748, in Paris, France.",
      "date": "1748-08-30"
    },
    {
      "headline": "Wins the Prix de Rome",
      "text": "In 1774, Jacques-Louis David won the prestigious Prix de Rome, a French scholarship for arts students, which allowed him to study in Rome.",
      "date": "1774"
    },
    {
      "headline": "Studies in Rome",
      "text": "From 1775 to 1780, David studied in Rome, where he was influenced by the classical art and architecture of the city.",
      "date": "1775"
    },
    {
      "headline": "Returns to Paris",
      "text": "David returned to Paris in 1780 after completing his studies in Rome.",
      "date": "1780"
    },
    {
      "headline": "Exhibits 'The Oath of the Horatii'",
      "text": "In 1785, David exhibited 'The Oath of the Horatii' at the Paris Salon, which became a defining work of Neoclassical art.",
      "date": "1785"
    },
    {
      "headline": "Paints 'The Death of Socrates'",
      "text": "In 1787, David completed 'The Death of Socrates', another significant Neoclassical painting.",
      "date": "1787"
    },
    {
      "headline": "Paints 'The Lictors Bring to Brutus the Bodies of His Sons'",
      "text": "In 1789, David painted 'The Lictors Bring to Brutus the Bodies of His Sons', reflecting the political climate of the time.",
      "date": "1789"
    },
    {
      "headline": "Becomes a supporter of the French Revolution",
      "text": "David became an active supporter of the French Revolution in the late 1780s and early 1790s, aligning himself with the Jacobins.",
      "date": "1790"
    },
    {
      "headline": "Paints 'The Death of Marat'",
      "text": "In 1793, David painted 'The Death of Marat', a famous revolutionary propaganda piece.",
      "date": "1793"
    },
    {
      "headline": "Imprisonment",
      "text": "David was imprisoned in 1794 following the fall of Robespierre and the Jacobins.",
      "date": "1794"
    },
    {
      "headline": "Release from Prison",
      "text": "David was released from prison in 1795 after the political climate changed.",
      "date": "1795"
    },
    {
      "headline": "Appointed court painter to Napoleon",
      "text": "In 1804, David was appointed as the court painter to Napoleon Bonaparte.",
      "date": "1804"
    },
    {
      "headline": "Paints 'The Coronation of Napoleon'",
      "text": "In 1807, David completed 'The Coronation of Napoleon', one of his most famous works.",
      "date": "1807"
    },
    {
      "headline": "Exile to Brussels",
      "text": "Following the fall of Napoleon, David went into exile in Brussels in 1816.",
      "date": "1816"
    },
    {
      "headline": "Death of Jacques-Louis David",
      "text": "Jacques-Louis David died on December 29, 1825, in Brussels, Belgium.",
      "date": "1825-12-29"
    }
  ]
}

