      "headline": "Foundation of Pisa",
      "text": "Pisa was founded as an Etruscan settlement, likely around the 6th century BCE.",
      "date": "-0600"
    },
    {
      "headline": "Roman Era",
      "text": "Pisa became a Roman colony in 180 BCE, serving as a naval base for the Romans.",
      "date": "-0180"
    },
    {
      "headline": "Pisa as a Maritime Republic",
      "text": "In the 11th century, Pisa emerged as one of the four major maritime republics of Italy, alongside Venice, Genoa, and Amalfi.",
      "date": "1000"
    },
    {
      "headline": "Battle of Meloria",
      "text": "On August 6, 1284, Pisa suffered a major defeat against Genoa in the Battle of Meloria, which marked the decline of Pisa's maritime power.",
      "date": "1284-08-06"
    },
    {
      "headline": "Annexation by Florence",
      "text": "In 1406, Pisa was conquered by Florence, ending its independence as a maritime republic.",
      "date": "1406"
    },
    {
      "headline": "Construction of the Leaning Tower",
      "text": "The construction of the Leaning Tower of Pisa began in 1173 and was completed in 1372, taking nearly 200 years due to interruptions.",
      "date": "1173"
    },
    {
      "headline": "Pisa University Founded",
      "text": "The University of Pisa was officially founded in 1343, becoming one of the oldest universities in Italy.",
      "date": "1343"
    },
    {
      "headline": "Pisa under Medici Rule",
      "text": "In 1509, Pisa was incorporated into the Grand Duchy of Tuscany under the Medici family.",
      "date": "1509"
    },
    {
      "headline": "Pisa during World War II",
      "text": "During World War II, Pisa suffered significant damage from Allied bombing raids in 1944.",
      "date": "1944"
    },
    {
      "headline": "Restoration of the Leaning Tower",
      "text": "In 1990, the Leaning Tower of Pisa was closed to the public for restoration and stabilization efforts, reopening in 2001.",
      "date": "1990"
    }
  ]
}

