{
  "timeline": [
    {
      "headline": "First Recorded Use of 'Peleset'",
      "text": "The earliest recorded use of a name similar to 'Palestine' is 'Peleset,' which appears in Egyptian texts from the 12th century BCE. These texts refer to a group of people associated with the Sea Peoples.",
      "date": "-1200"
    },
    {
      "headline": "Herodotus Mentions 'Palestine'",
      "text": "In the 5th century BCE, the Greek historian Herodotus refers to the region as 'Palaistine' in his writings, marking one of the earliest known uses of the name in Greek literature.",
      "date": "-0485"
    },
    {
      "headline": "Roman Province of 'Syria Palaestina'",
      "text": "In 135 CE, following the Bar Kokhba revolt, the Roman Emperor Hadrian renamed the province of Judea to 'Syria Palaestina' in an attempt to minimize Jewish identification with the land of Israel.",
      "date": "0135"
    },
    {
      "headline": "Byzantine Period Use",
      "text": "During the Byzantine period, the name 'Palaestina' continued to be used, with the region being divided into three administrative units: Palaestina Prima, Palaestina Secunda, and Palaestina Tertia.",
      "date": "0400"
    },
    {
      "headline": "Islamic Conquest and Use of 'Filastin'",
      "text": "After the Islamic conquest in the 7th century, the name 'Filastin' was used in Arabic to refer to the region, as documented in early Islamic administrative records.",
      "date": "0636"
    },
    {
      "headline": "Crusader Period References",
      "text": "During the Crusader period, the name 'Palestine' was used in various European languages to refer to the region, often in the context of the Crusades and the Latin Kingdom of Jerusalem.",
      "date": "1099"
    },
    {
      "headline": "Ottoman Empire Use",
      "text": "Under the Ottoman Empire, which ruled the region from 1517 to 1917, the name 'Palestine' was used in Western languages, although the Ottomans did not use it as an official administrative name.",
      "date": "1517"
    },
    {
      "headline": "British Mandate for Palestine",
      "text": "Following World War I, the League of Nations granted Britain the mandate to govern the region, officially naming it the 'British Mandate for Palestine' in 1920.",
      "date": "1920"
    }
  ]
}

