    {
      "headline": "Gallipoli Campaign Begins",
      "text": "On 25 April 1915, the Australian and New Zealand Army Corps (ANZAC) landed at Gallipoli, marking the beginning of the Gallipoli Campaign during World War I.",
      "date": "1915-04-25"
    },
    {
      "headline": "First Anzac Day Commemoration",
      "text": "The first Anzac Day was observed on 25 April 1916. The day was marked by a variety of ceremonies and services in Australia, New Zealand, and London.",
      "date": "1916-04-25"
    },
    {
      "headline": "Anzac Day Becomes a Public Holiday",
      "text": "By the 1920s, Anzac Day had become established as a public holiday in Australia and New Zealand, with various commemorative events held annually.",
      "date": "1920"
    },
    {
      "headline": "Anzac Day Act Passed in New Zealand",
      "text": "In 1921, the New Zealand government passed the Anzac Day Act, making 25 April a public holiday.",
      "date": "1921"
    },
    {
      "headline": "Two-Minute Silence Introduced",
      "text": "In 1927, a two-minute silence was introduced as part of the Anzac Day services in Australia, a tradition that continues to this day.",
      "date": "1927"
    },
    {
      "headline": "Anzac Day Act Passed in Australia",
      "text": "In 1927, the Australian government passed legislation to formalize Anzac Day as a national day of commemoration.",
      "date": "1927"
    },
    {
      "headline": "Anzac Day During World War II",
      "text": "During World War II, Anzac Day commemorations continued, although they were sometimes scaled back due to wartime restrictions.",
      "date": "1939-1945"
    },
    {
      "headline": "Anzac Day Becomes More Inclusive",
      "text": "In the latter half of the 20th century, Anzac Day began to commemorate not only those who served in World War I but also those who served in subsequent conflicts.",
      "date": "1950s"
    },
    {
      "headline": "Dawn Service Tradition",
      "text": "The tradition of holding a dawn service on Anzac Day became more widespread in the 1970s, reflecting the time of the original Gallipoli landings.",
      "date": "1970s"
    },
    {
      "headline": "Anzac Day Centenary",
      "text": "In 2015, the centenary of the Gallipoli landings was commemorated with large-scale events in Australia, New Zealand, and Turkey.",
      "date": "2015-04-25"
    }
  ]
}

