    {
      "headline": "Planning of Dieppe Raid",
      "text": "The planning for the Dieppe Raid, also known as Operation Jubilee, began in early 1942. The objective was to test the feasibility of a large-scale amphibious assault on a fortified coast and gather intelligence.",
      "date": "1942"
    },
    {
      "headline": "Dieppe Raid Commences",
      "text": "On August 19, 1942, the Dieppe Raid was launched. Over 6,050 infantry, predominantly Canadian, supported by a regiment of tanks, were put ashore from a naval force operating under the protection of Royal Air Force (RAF) fighters.",
      "date": "1942-08-19"
    },
    {
      "headline": "Outcome of the Dieppe Raid",
      "text": "The Dieppe Raid ended in disaster for the Allies. Of the 6,050 troops involved, 3,623 were killed, wounded, or captured. The raid provided valuable lessons for future amphibious operations, despite its failure.",
      "date": "1942-08-19"
    },
    {
      "headline": "Impact on Future Operations",
      "text": "The lessons learned from the Dieppe Raid influenced the planning and execution of future Allied amphibious operations, including the successful D-Day landings in Normandy in 1944.",
      "date": "1944"
    }
  ]
}

