{
  "timeline": [
    {
      "headline": "Construction of the Palais de la Cité",
      "text": "The Palais de la Cité, which included the Conciergerie, was constructed as a royal palace for the French kings. The exact date of construction is not clear, but it was a prominent royal residence by the 10th century.",
      "date": "1000"
    },
    {
      "headline": "Transformation into a Prison",
      "text": "In the 14th century, the Conciergerie was transformed from a royal palace into a prison. This marked the beginning of its use as a detention facility.",
      "date": "1300"
    },
    {
      "headline": "French Revolution and Use as a Revolutionary Tribunal",
      "text": "During the French Revolution, from 1793 to 1794, the Conciergerie became a principal detention center for prisoners awaiting trial by the Revolutionary Tribunal. It housed 2,780 prisoners, including notable figures like Marie Antoinette.",
      "date": "1793"
    },
    {
      "headline": "Execution of Marie Antoinette",
      "text": "On October 16, 1793, Marie Antoinette was executed by guillotine after being imprisoned and tried at the Conciergerie.",
      "date": "1793-10-16"
    },
    {
      "headline": "End of the Revolutionary Tribunal",
      "text": "The Revolutionary Tribunal was abolished in 1795, ending the Conciergerie's role as a center for revolutionary justice.",
      "date": "1795"
    },
    {
      "headline": "Conciergerie Becomes a National Monument",
      "text": "In the 19th century, the Conciergerie was designated as a national monument, preserving its historical significance and opening it to the public as a museum.",
      "date": "1800"
    }
  ]
}

