{
  "timeline": [
    {
      "headline": "Start of the Miners' Strike",
      "text": "The 1984–1985 United Kingdom miners' strike began on 6 March 1984. It was initiated by the National Union of Mineworkers (NUM) led by Arthur Scargill in response to the National Coal Board's announcement of pit closures.",
      "date": "1984-03-06"
    },
    {
      "headline": "Battle of Orgreave",
      "text": "On 18 June 1984, one of the most violent confrontations of the strike occurred at the Orgreave coking plant in South Yorkshire. Thousands of police and pickets clashed in what became known as the Battle of Orgreave.",
      "date": "1984-06-18"
    },
    {
      "headline": "NUM's National Ballot Controversy",
      "text": "Throughout the strike, there was controversy over the lack of a national ballot among NUM members. Arthur Scargill's decision not to hold a ballot was a point of contention and weakened support for the strike.",
      "date": "1984"
    },
    {
      "headline": "Government's Response",
      "text": "Prime Minister Margaret Thatcher's government took a firm stance against the strike, emphasizing the need to reduce the power of trade unions and maintain economic stability.",
      "date": "1984"
    },
    {
      "headline": "End of the Miners' Strike",
      "text": "The strike officially ended on 3 March 1985, after nearly a year of industrial action. The miners returned to work without having achieved their aims, marking a significant defeat for the NUM.",
      "date": "1985-03-03"
    }
  ]
}

