    },
    {
      "headline": "Acquisition of Vueling",
      "text": "In April 2013, IAG acquired a controlling stake in the Spanish low-cost airline Vueling. This acquisition was part of IAG's strategy to expand its low-cost operations in Europe.",
      "date": "2013-04"
    },
    {
      "headline": "Acquisition of Aer Lingus",
      "text": "In August 2015, IAG completed the acquisition of Aer Lingus, the flag carrier airline of Ireland. This acquisition further expanded IAG's network and strengthened its position in the transatlantic market.",
      "date": "2015-08"
    },
    {
      "headline": "Launch of LEVEL",
      "text": "In March 2017, IAG launched LEVEL, a new low-cost long-haul airline brand. LEVEL was created to operate flights from various European cities to destinations in the Americas.",
      "date": "2017-03"
    },
    {
      "headline": "Acquisition of Air Europa",
      "text": "In November 2019, IAG announced the acquisition of Air Europa, a Spanish airline, for €1 billion. The acquisition aimed to transform Madrid into a major European hub.",
      "date": "2019-11"
    }
  ]
}

