{
  "timeline": [
    {
      "headline": "Rise of Aten Worship",
      "text": "The worship of Aten began to rise in prominence during the reign of Pharaoh Amenhotep III, who ruled from approximately 1386 to 1349 BCE. Aten was initially one of many deities worshipped in ancient Egypt.",
      "date": "-1386"
    },
    {
      "headline": "Akhenaten's Reign Begins",
      "text": "Akhenaten, originally named Amenhotep IV, ascended to the throne of Egypt and began his reign around 1353 BCE. He is known for establishing Atenism as the state religion.",
      "date": "-1353"
    },
    {
      "headline": "Establishment of Atenism",
      "text": "Around 1346 BCE, Akhenaten declared Aten as the sole god, effectively establishing Atenism and marking a significant shift from traditional Egyptian polytheism.",
      "date": "-1346"
    },
    {
      "headline": "Construction of Akhetaten",
      "text": "Akhenaten founded a new capital city dedicated to Aten, named Akhetaten (modern-day Amarna), around 1346 BCE. This city became the center of Aten worship.",
      "date": "-1346"
    },
    {
      "headline": "Height of Aten Worship",
      "text": "During the Amarna Period, Atenism reached its peak as the dominant religious practice in Egypt, with Akhenaten promoting Aten as the supreme deity.",
      "date": "-1340"
    },
    {
      "headline": "End of Akhenaten's Reign",
      "text": "Akhenaten's reign ended around 1336 BCE, leading to the decline of Atenism as traditional religious practices were gradually restored.",
      "date": "-1336"
    },
    {
      "headline": "Restoration of Traditional Religion",
      "text": "After Akhenaten's death, his successors, including Tutankhamun, began restoring the traditional polytheistic religion, diminishing the prominence of Aten.",
      "date": "-1332"
    }
  ]
}

