{
  "timeline": [
    {
      "headline": "Murder of Megan Kanka",
      "text": "On July 29, 1994, seven-year-old Megan Kanka was raped and murdered by a neighbor who was a convicted sex offender. This tragic event led to public outcry and the eventual creation of Megan's Law.",
      "date": "1994-07-29"
    },
    {
      "headline": "Introduction of Megan's Law in New Jersey",
      "text": "In response to Megan Kanka's murder, New Jersey passed the first state-level Megan's Law in October 1994, requiring sex offender registration and community notification.",
      "date": "1994-10"
    },
    {
      "headline": "Federal Megan's Law Enacted",
      "text": "On May 17, 1996, President Bill Clinton signed the federal Megan's Law, which amended the Jacob Wetterling Act to require states to establish a community notification system for registered sex offenders.",
      "date": "1996-05-17"
    },
    {
      "headline": "Implementation of State-Level Megan's Laws",
      "text": "Following the enactment of the federal Megan's Law, all U.S. states implemented their own versions of Megan's Law, which included both sex offender registration and community notification requirements.",
      "date": "1996"
    },
    {
      "headline": "International Megan's Law",
      "text": "In 2016, the International Megan's Law to Prevent Child Exploitation and Other Sexual Crimes Through Advanced Notification of Traveling Sex Offenders was signed into law, aiming to prevent sex offenders from exploiting children abroad.",
      "date": "2016"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Morrill Act of 1862",
      "text": "The first Morrill Act was signed into law by President Abraham Lincoln on July 2, 1862. This act provided each state with 30,000 acres of federal land for each member in their Congressional delegation. The land was to be sold to fund public colleges that focused on agriculture and the mechanical arts.",
      "date": "1862-07-02"
    },
    {
      "headline": "First Land-Grant University Established",
      "text": "The first land-grant university, Kansas State University, was established on February 16, 1863, under the provisions of the Morrill Act of 1862.",
      "date": "1863-02-16"
    },
    {
      "headline": "Morrill Act of 1890",
      "text": "The second Morrill Act was enacted on August 30, 1890. This act aimed to extend the benefits of the land-grant system to African Americans by providing additional funding to states that established separate land-grant institutions for black students.",
      "date": "1890-08-30"
    },
    {
      "headline": "Establishment of 1890 Land-Grant Universities",
      "text": "Following the Morrill Act of 1890, 19 historically black colleges and universities (HBCUs) were designated as land-grant institutions.",
      "date": "1890"
    },
    {
      "headline": "Equity in Educational Land-Grant Status Act of 1994",
      "text": "The Equity in Educational Land-Grant Status Act of 1994 was passed, granting land-grant status to 35 Native American tribal colleges and universities.",
      "date": "1994"
    },
    {
      "headline": "Expansion to 106 Land-Grant Institutions",
      "text": "As of the implementation of the 1994 Act, there are a total of 106 land-grant institutions: 57 under the 1862 Act, 19 under the 1890 Act, and 35 under the 1994 Act.",
      "date": "1994"
    }
  ]
}

