    {
      "headline": "Birth of Donatello",
      "text": "Donatello was born in Florence, Italy, in 1386. He was born as Donato di Niccolò di Betto Bardi.",
      "date": "1386"
    },
    {
      "headline": "Apprenticeship and Early Work",
      "text": "In his early years, Donatello apprenticed with Lorenzo Ghiberti, a renowned sculptor of the time, where he learned the basics of sculpture and metalwork.",
      "date": "1400"
    },
    {
      "headline": "Collaboration with Brunelleschi",
      "text": "Around 1404, Donatello collaborated with Filippo Brunelleschi on a trip to Rome, where they studied classical art and architecture.",
      "date": "1404"
    },
    {
      "headline": "Commission for St. George",
      "text": "In 1416, Donatello completed the statue of St. George for the Orsanmichele church in Florence, showcasing his mastery of human anatomy and expression.",
      "date": "1416"
    },
    {
      "headline": "Creation of the Bronze David",
      "text": "Between 1430 and 1440, Donatello created the bronze statue of David, which was the first freestanding nude male sculpture since antiquity. It was commissioned by the Medici family.",
      "date": "1430"
    },
    {
      "headline": "Work in Padua",
      "text": "In 1443, Donatello moved to Padua, where he created the equestrian statue of Gattamelata, a pioneering work in Renaissance sculpture.",
      "date": "1443"
    },
    {
      "headline": "Return to Florence",
      "text": "Donatello returned to Florence in 1453, where he continued to work on various commissions, including the pulpits for the San Lorenzo Basilica.",
      "date": "1453"
    },
    {
      "headline": "Death of Donatello",
      "text": "Donatello died on December 13, 1466, in Florence, Italy. He left behind a legacy as one of the most influential sculptors of the Renaissance.",
      "date": "1466-12-13"
    }
  ]
}

