{
  "timeline": [
    {
      "headline": "Founding of the British East India Company",
      "text": "The British East India Company (EIC) was founded on December 31, 1600, by a royal charter granted by Queen Elizabeth I.",
      "date": "1600-12-31"
    },
    {
      "headline": "First Trading Post Established in India",
      "text": "In 1612, the East India Company established its first trading post in India at Surat, marking the beginning of its presence in the Indian subcontinent.",
      "date": "1612"
    },
    {
      "headline": "Battle of Plassey",
      "text": "On June 23, 1757, the East India Company, led by Robert Clive, defeated the Nawab of Bengal and his French allies at the Battle of Plassey, marking the start of British political control in India.",
      "date": "1757-06-23"
    },
    {
      "headline": "Battle of Buxar",
      "text": "The Battle of Buxar was fought on October 22, 1764, where the East India Company defeated the combined forces of the Mughal Emperor, the Nawab of Oudh, and the Nawab of Bengal, consolidating its control over Bengal.",
      "date": "1764-10-22"
    },
    {
      "headline": "Regulating Act of 1773",
      "text": "The Regulating Act of 1773 was passed by the British Parliament to address the mismanagement of the East India Company and to bring its rule in India under the control of the British government.",
      "date": "1773"
    },
    {
      "headline": "Pitt's India Act",
      "text": "In 1784, Pitt's India Act was enacted, establishing a dual system of control by the British government and the East India Company over India.",
      "date": "1784"
    },
    {
      "headline": "Charter Act of 1813",
      "text": "The Charter Act of 1813 ended the trade monopoly of the East India Company in India, except for trade in tea and trade with China.",
      "date": "1813"
    },
    {
      "headline": "Charter Act of 1833",
      "text": "The Charter Act of 1833 was passed, making the Governor-General of Bengal the Governor-General of India, centralizing administration.",
      "date": "1833"
    },
    {
      "headline": "Indian Rebellion of 1857",
      "text": "The Indian Rebellion of 1857, also known as the Sepoy Mutiny, began on May 10, 1857, as a major, but ultimately unsuccessful, uprising against the East India Company's rule.",
      "date": "1857-05-10"
    },
    {
      "headline": "Government of India Act 1858",
      "text": "Following the suppression of the Indian Rebellion of 1857, the Government of India Act 1858 was enacted, transferring the administration of India from the East India Company to the British Crown.",
      "date": "1858"
    },
    {
      "headline": "End of Company Rule in India",
      "text": "In 1858, the British Crown took over the administration of India from the East India Company, marking the end of Company rule and the beginning of the British Raj.",
      "date": "1858"
    }
  ]
}

