  "timeline": [
    {
      "headline": "Beginning of the February Revolution",
      "text": "The French Revolution of 1848 began in February 1848, marked by widespread civil unrest and protests against the July Monarchy.",
      "date": "1848-02"
    },
    {
      "headline": "Protests in Paris",
      "text": "On February 22, 1848, protests erupted in Paris as citizens demanded electoral reform and the resignation of Prime Minister François Guizot.",
      "date": "1848-02-22"
    },
    {
      "headline": "Guizot's Resignation",
      "text": "On February 23, 1848, Prime Minister François Guizot resigned in response to the escalating protests.",
      "date": "1848-02-23"
    },
    {
      "headline": "Shooting of Protesters",
      "text": "On the night of February 23, 1848, soldiers fired on protesters in Paris, killing 52 people, which intensified the revolutionary fervor.",
      "date": "1848-02-23"
    },
    {
      "headline": "Abdication of King Louis-Philippe",
      "text": "On February 24, 1848, King Louis-Philippe abdicated the throne in favor of his grandson, but the move failed to quell the revolution.",
      "date": "1848-02-24"
    },
    {
      "headline": "Proclamation of the Second Republic",
      "text": "On February 26, 1848, the French Second Republic was proclaimed, marking the end of the July Monarchy and the establishment of a provisional government.",
      "date": "1848-02-26"
    },
    {
      "headline": "Establishment of National Workshops",
      "text": "In March 1848, the provisional government established National Workshops to provide employment for the unemployed.",
      "date": "1848-03"
    },
    {
      "headline": "June Days Uprising",
      "text": "From June 23 to June 26, 1848, the June Days Uprising occurred as workers protested against the closure of the National Workshops, leading to violent clashes with the military.",
      "date": "1848-06-23"
    },
    {
      "headline": "Election of Louis-Napoleon Bonaparte",
      "text": "On December 10, 1848, Louis-Napoleon Bonaparte was elected President of the French Second Republic, marking a significant political shift.",
      "date": "1848-12-10"
    }
  ]
}

