    {
      "headline": "Expulsion from France",
      "text": "In 1306, King Philip IV of France expelled the Jews from his kingdom, seizing their property.",
      "date": "1306"
    },
    {
      "headline": "Expulsion from Spain",
      "text": "In 1492, the Alhambra Decree ordered the expulsion of practicing Jews from the Kingdoms of Castile and Aragon, leading to the Spanish Jewish exodus.",
      "date": "1492"
