      "headline": "Introduction of the Chalmers Award",
      "text": "Prior to the BBWAA MVP award, the Chalmers Award was given from 1911 to 1914 to the most valuable player in each league.",
      "date": "1911"
    },
    {
      "headline": "Discontinuation of the Chalmers Award",
      "text": "The Chalmers Award was discontinued after the 1914 season, leading to a gap in MVP awards until the BBWAA began their MVP award in 1931.",
      "date": "1914"
    },
    {
      "headline": "First Unanimous MVP Winner",
      "text": "In 1935, Hank Greenberg of the Detroit Tigers became the first player to win the MVP award unanimously.",
      "date": "1935"
    },
    {
      "headline": "First African American MVP Winner",
      "text": "Jackie Robinson became the first African American player to win the MVP award in 1949, playing for the Brooklyn Dodgers.",
      "date": "1949"
    },
    {
      "headline": "First Cy Young and MVP Winner",
      "text": "In 1956, Don Newcombe of the Brooklyn Dodgers became the first player to win both the Cy Young Award and the MVP award in the same year.",
      "date": "1956"
