{
  "timeline": [
    {
      "headline": "Invention of the MOSFET",
      "text": "The metal–oxide–semiconductor field-effect transistor (MOSFET) was invented by Mohamed Atalla and Dawon Kahng at Bell Labs in 1959. This invention laid the groundwork for CMOS technology.",
      "date": "1959"
    },
    {
      "headline": "Development of CMOS Technology",
      "text": "CMOS technology was developed by Frank Wanlass at Fairchild Semiconductor in 1963. He discovered that complementary MOS transistors could be used to create low-power logic circuits.",
      "date": "1963"
    },
    {
      "headline": "First CMOS Integrated Circuit",
      "text": "The first CMOS integrated circuit was developed in 1968 by Albert Medwin at RCA. This marked the beginning of CMOS technology being used in commercial products.",
      "date": "1968"
    },
    {
      "headline": "Introduction of CMOS in Microprocessors",
      "text": "In the 1970s, CMOS technology began to be used in microprocessors, offering advantages in power consumption and heat generation compared to other technologies.",
      "date": "1970"
    },
    {
      "headline": "CMOS Becomes Dominant in IC Fabrication",
      "text": "By the 1980s, CMOS technology became the dominant process for fabricating integrated circuits due to its low power consumption and high noise immunity.",
      "date": "1980"
    },
    {
      "headline": "Advancements in CMOS Scaling",
      "text": "Throughout the 1990s and 2000s, advancements in CMOS scaling allowed for increased transistor density and performance, leading to the development of more powerful and efficient electronic devices.",
      "date": "1990"
    },
    {
      "headline": "CMOS in Modern Electronics",
      "text": "Today, CMOS technology is used in a wide range of electronic devices, including smartphones, computers, and digital cameras, due to its efficiency and scalability.",
      "date": "2023"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Origins of Kendo",
      "text": "Kendo originated from the traditional Japanese swordsmanship (kenjutsu) practiced by samurai warriors. It evolved over centuries as a method of training and discipline.",
      "date": "-1185"
    },
    {
      "headline": "Development of Shinai and Bōgu",
      "text": "During the Edo period (1603-1868), the shinai (bamboo sword) and bōgu (protective armor) were developed to allow for safer practice of sword techniques.",
      "date": "1603"
    },
    {
      "headline": "Establishment of Modern Kendo",
      "text": "In the late 19th century, kendo began to take its modern form, incorporating elements of traditional kenjutsu with new training methods.",
      "date": "1868"
    },
    {
      "headline": "Kendo in the Meiji Period",
      "text": "During the Meiji period (1868-1912), kendo was promoted as a way to preserve traditional Japanese martial arts and was included in school curriculums.",
      "date": "1868"
    },
    {
      "headline": "Formation of Dai Nippon Butoku Kai",
      "text": "In 1895, the Dai Nippon Butoku Kai was established to promote martial arts, including kendo, throughout Japan.",
      "date": "1895"
    },
