{
  "timeline": [
    {
      "headline": "Birth of Bhima",
      "text": "Bhima was born to Kunti and King Pandu through the blessings of Vayu, the wind god, which bestowed upon him superhuman strength from birth.",
      "date": "-0319"
    },
    {
      "headline": "Bhima's Childhood and Education",
      "text": "Bhima, along with his brothers, was educated in the arts of warfare and statecraft under the guidance of their teacher, Drona.",
      "date": "-0305"
    },
    {
      "headline": "Bhima's Marriage to Hidimbi",
      "text": "During their exile in the forest, Bhima married Hidimbi, a rakshasi, and they had a son named Ghatotkacha.",
      "date": "-0300"
    },
    {
      "headline": "Marriage to Draupadi",
      "text": "Bhima, along with his brothers, married Draupadi, the princess of Panchala, after winning her hand in a swayamvara.",
      "date": "-0295"
    },
    {
      "headline": "Exile of the Pandavas",
      "text": "After losing a game of dice to the Kauravas, Bhima and his brothers were exiled to the forest for 13 years.",
      "date": "-0290"
    },
    {
      "headline": "Return from Exile",
      "text": "The Pandavas returned from exile and demanded their rightful share of the kingdom, leading to tensions with the Kauravas.",
      "date": "-0277"
    },
    {
      "headline": "Kurukshetra War",
      "text": "Bhima played a crucial role in the Kurukshetra War, which lasted for 18 days. He fulfilled his vow by killing all hundred Kaurava brothers, including Duryodhana.",
      "date": "-0275"
    },
    {
      "headline": "Bhima's Later Life",
      "text": "After the war, Bhima helped Yudhishthira in ruling the kingdom. He remained a key figure in the administration and defense of the realm.",
      "date": "-0270"
    },
    {
      "headline": "Bhima's Death",
      "text": "Bhima, along with his brothers, renounced the world and embarked on a journey to the Himalayas, where he eventually died.",
      "date": "-0260"
    }
  ]
}

