    },
    {
      "headline": "Assassination of Dong Zhuo",
      "text": "In 192, Lü Bu turned against Dong Zhuo and assassinated him after being instigated by Wang Yun and Shisun Rui. This act temporarily shifted the power dynamics within the Han central government.",
      "date": "0192"
    },
    {
      "headline": "Defeat and Flight",
      "text": "Following the assassination of Dong Zhuo, Lü Bu was defeated and driven away by Dong Zhuo's followers, including Li Jue and Guo Si.",
      "date": "0192"
    },
    {
      "headline": "Service under Yuan Shu",
      "text": "After fleeing, Lü Bu briefly served under the warlord Yuan Shu but later left due to disagreements.",
      "date": "0194"
    },
    {
      "headline": "Capture of Xiapi",
      "text": "In 196, Lü Bu seized control of Xiapi, a strategic city, and established his base there, further consolidating his power.",
      "date": "0196"
    },
    {
      "headline": "Defeat at the Battle of Xiapi",
      "text": "In 198, Lü Bu was defeated by the combined forces of Cao Cao and Liu Bei at the Battle of Xiapi. He was captured and executed by Cao Cao shortly thereafter.",
      "date": "0198"
    },
    {
      "headline": "Death of Lü Bu",
      "text": "Lü Bu was executed by hanging on Cao Cao's orders in 199, marking the end of his tumultuous career as a warlord.",
