{
  "timeline": [
    {
      "headline": "Birth of Birsa Munda",
      "text": "Birsa Munda was born on November 15, 1875, in Ulihatu, Bengal Presidency, British India.",
      "date": "1875-11-15"
    },
    {
      "headline": "Education and Early Life",
      "text": "In the early 1880s, Birsa Munda attended a German Mission school where he was influenced by Christianity and Western education.",
      "date": "1880"
    },
    {
      "headline": "Conversion to Christianity",
      "text": "In the late 1880s, Birsa Munda converted to Christianity, taking the name Birsa David, which allowed him to attend the missionary school.",
      "date": "1886"
    },
    {
      "headline": "Return to Traditional Beliefs",
      "text": "By the early 1890s, Birsa Munda renounced Christianity and returned to his traditional tribal beliefs, becoming a leader and spiritual figure among the Munda people.",
      "date": "1890"
    },
    {
      "headline": "Beginning of the Munda Rebellion",
      "text": "In 1895, Birsa Munda began to preach the need for the Munda people to reclaim their land and rights from the British and landlords, marking the start of the Munda Rebellion.",
      "date": "1895"
    },
    {
      "headline": "Arrest and Imprisonment",
      "text": "In 1895, Birsa Munda was arrested by the British authorities for his role in the rebellion and was imprisoned for two years.",
      "date": "1895"
    },
    {
      "headline": "Release from Prison",
      "text": "Birsa Munda was released from prison in 1897, after serving two years for his involvement in the rebellion.",
      "date": "1897"
    },
    {
      "headline": "Intensification of the Munda Rebellion",
      "text": "In 1899, Birsa Munda intensified his efforts against the British and landlords, leading to widespread uprisings in the Munda region.",
      "date": "1899"
    },
    {
      "headline": "Death of Birsa Munda",
      "text": "Birsa Munda died on June 9, 1900, in Ranchi Jail under mysterious circumstances, marking the end of his leadership in the Munda Rebellion.",
      "date": "1900-06-09"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Founding of Bombardier Inc.",
      "text": "Bombardier Inc. was founded in 1942 by Joseph-Armand Bombardier in Valcourt, Quebec, Canada. The company was initially established to market his invention of the snowmobile.",
      "date": "1942"
    },
    {
      "headline": "Introduction of the B7 Snowmobile",
      "text": "In 1942, Bombardier introduced the B7 snowmobile, which was one of the first commercial snowmobiles and laid the foundation for the company's future success.",
      "date": "1942"
    },
    {
      "headline": "Expansion into Rail Transportation",
      "text": "In the 1970s, Bombardier expanded into the rail transportation industry, marking a significant diversification from its original snowmobile business.",
      "date": "1970"
    },
    {
      "headline": "Acquisition of Canadair",
      "text": "In 1986, Bombardier acquired Canadair, a Canadian aircraft manufacturer, which marked the company's entry into the aerospace industry.",
      "date": "1986"
    },
    {
      "headline": "Acquisition of Learjet",
      "text": "In 1990, Bombardier acquired Learjet, an American manufacturer of business jets, further expanding its aerospace division.",
      "date": "1990"
    },
    {
      "headline": "Acquisition of de Havilland Canada",
      "text": "In 1992, Bombardier acquired de Havilland Canada from Boeing, adding to its portfolio of regional aircraft.",
      "date": "1992"
    },
    {
      "headline": "Introduction of the CRJ Series",
      "text": "In 1992, Bombardier launched the CRJ series of regional jets, which became one of the most successful regional jet programs in the world.",
      "date": "1992"
    },
    {
      "headline": "Introduction of the Global Express",
      "text": "In 1996, Bombardier introduced the Global Express, a long-range business jet that became a flagship product for the company.",
      "date": "1996"
    },
    {
      "headline": "Launch of the CSeries Program",
      "text": "In 2008, Bombardier launched the CSeries program, aimed at producing a new family of narrow-body, medium-range jetliners.",
      "date": "2008"
    },
    {
      "headline": "Sale of the CSeries to Airbus",
      "text": "In 2018, Bombardier sold a majority stake in the CSeries program to Airbus, which rebranded it as the Airbus A220.",
      "date": "2018"
    },
