{
  "timeline": [
    {
      "headline": "First Murder",
      "text": "In late January or early February 1828, the first victim, an old pensioner named Donald, died of natural causes in Hare's lodging house. Burke and Hare sold the body to Dr. Robert Knox for dissection.",
      "date": "1828-01"
    },
    {
      "headline": "Second Murder",
      "text": "In February 1828, Burke and Hare murdered Abigail Simpson, a salt seller, and sold her body to Dr. Knox.",
      "date": "1828-02"
    },
    {
      "headline": "Third Murder",
      "text": "In March 1828, Burke and Hare murdered an Englishman named Joseph, a miller, and sold his body to Dr. Knox.",
      "date": "1828-03"
    },
    {
      "headline": "Fourth Murder",
      "text": "In April 1828, Burke and Hare murdered Mary Paterson, a young woman, and sold her body to Dr. Knox.",
      "date": "1828-04"
    },
    {
      "headline": "Fifth Murder",
      "text": "In May 1828, Burke and Hare murdered Effie, a cinder gatherer, and sold her body to Dr. Knox.",
      "date": "1828-05"
    },
    {
      "headline": "Sixth Murder",
      "text": "In June 1828, Burke and Hare murdered an old woman named Mrs. Haldane and sold her body to Dr. Knox.",
      "date": "1828-06"
    },
    {
      "headline": "Seventh Murder",
      "text": "In July 1828, Burke and Hare murdered Mrs. Haldane's daughter and sold her body to Dr. Knox.",
      "date": "1828-07"
    },
    {
      "headline": "Eighth Murder",
      "text": "In August 1828, Burke and Hare murdered a woman named Ann McDougal and sold her body to Dr. Knox.",
      "date": "1828-08"
    },
    {
      "headline": "Ninth Murder",
      "text": "In September 1828, Burke and Hare murdered a washerwoman named Mrs. Ostler and sold her body to Dr. Knox.",
      "date": "1828-09"
    },
    {
      "headline": "Tenth Murder",
      "text": "In October 1828, Burke and Hare murdered a beggar woman named Ann McTaggart and sold her body to Dr. Knox.",
      "date": "1828-10"
    },
    {
      "headline": "Eleventh Murder",
      "text": "In October 1828, Burke and Hare murdered a woman named Mary Docherty and sold her body to Dr. Knox.",
      "date": "1828-10"
    },
    {
      "headline": "Arrest of Burke and Hare",
      "text": "On November 2, 1828, Burke and Hare were arrested after the body of Mary Docherty was discovered.",
