    },
    {
      "headline": "Release of 'Bohemian Rhapsody'",
      "text": "In 1975, Queen released the album 'A Night at the Opera', which included the groundbreaking single 'Bohemian Rhapsody'. The song became one of the band's most popular and enduring hits.",
      "date": "1975"
    },
    {
      "headline": "Live Aid Performance",
      "text": "On July 13, 1985, Queen performed at the Live Aid concert at Wembley Stadium, London. Their performance is widely regarded as one of the greatest live performances in the history of rock music.",
      "date": "1985-07-13"
    },
    {
      "headline": "Diagnosis with HIV",
      "text": "In 1987, Freddie Mercury was diagnosed with HIV, although he kept his illness private for several years.",
      "date": "1987"
    },
    {
      "headline": "Final Public Appearance",
      "text": "Freddie Mercury made his final public appearance on February 18, 1990, at the BRIT Awards, where Queen received the Brit Award for Outstanding Contribution to Music.",
      "date": "1990-02-18"
    },
    {
      "headline": "Public Announcement of Illness",
      "text": "On November 23, 1991, Freddie Mercury released a public statement confirming that he had AIDS.",
      "date": "1991-11-23"
    },
    {
      "headline": "Death of Freddie Mercury",
      "text": "Freddie Mercury died on November 24, 1991, at the age of 45, due to bronchial pneumonia resulting from AIDS.",
