{
  "timeline": [
    {
      "headline": "Whiskey Tax Enacted",
      "text": "In 1791, the United States federal government imposed the first tax on a domestic product, known as the 'whiskey tax'. This tax was intended to generate revenue to pay the war debt incurred during the Revolutionary War.",
      "date": "1791"
    },
    {
      "headline": "Resistance Begins",
      "text": "Farmers on the western frontier, particularly in Pennsylvania, began to resist the whiskey tax in 1791. They were accustomed to distilling their surplus grain into whiskey and saw the tax as unfair.",
      "date": "1791"
    },
    {
      "headline": "Escalation of Protests",
      "text": "By 1794, protests against the whiskey tax had escalated into violent confrontations. The resistance was particularly strong in Western Pennsylvania.",
      "date": "1794"
    },
    {
      "headline": "Washington's Response",
      "text": "In August 1794, President George Washington responded to the rebellion by calling up a militia force of about 13,000 men to suppress the insurgents.",
      "date": "1794-08"
    },
    {
      "headline": "Rebellion Suppressed",
      "text": "By October 1794, the federal militia had successfully suppressed the Whiskey Rebellion, demonstrating the power of the new federal government to enforce its laws.",
      "date": "1794-10"
    },
    {
      "headline": "Aftermath and Impact",
      "text": "The suppression of the Whiskey Rebellion in 1794 had a lasting impact on the United States, establishing federal authority and setting a precedent for federal response to civil unrest.",
      "date": "1794"
    }
  ]
}

