    {
      "headline": "Kingdom of Aragon Established",
      "text": "In 1035, the Kingdom of Aragon was established when Ramiro I, the illegitimate son of Sancho III of Navarre, became the first king of Aragon.",
      "date": "1035"
    },
    {
      "headline": "Union with the County of Barcelona",
      "text": "In 1137, the Kingdom of Aragon was united with the County of Barcelona through the marriage of Petronila of Aragon and Ramon Berenguer IV, Count of Barcelona, forming the Crown of Aragon.",
      "date": "1137"
    },
