    {
      "headline": "Union of the Crowns of Aragon and Castile",
      "text": "In 1469, the marriage of Ferdinand II of Aragon and Isabella I of Castile led to the dynastic union of the Crown of Aragon and the Crown of Castile.",
      "date": "1469"
    },
    {
      "headline": "War of the Spanish Succession",
      "text": "The War of the Spanish Succession (1701-1714) resulted in the Nueva Planta decrees, which abolished the Crown of Aragon's institutions and integrated its territories into a centralized Spanish state.",
      "date": "1701"
    },
    {
      "headline": "Statute of Autonomy of Aragon",
      "text": "On August 10, 1982, the Statute of Autonomy of Aragon was approved, granting Aragon autonomy within Spain.",
      "date": "1982-08-10"
    },
    {
      "headline": "Revised Statute of Autonomy",
      "text": "In 2007, a revised Statute of Autonomy was enacted, recognizing Aragon as a historic nationality within Spain.",
      "date": "2007"
    }
  ]
}

