    {
      "headline": "Development of Waqf System",
      "text": "The waqf system developed as a means for Muslims to donate assets for religious or charitable purposes, with no intention of reclaiming them. This system allowed for the provision of social services and the preservation of cultural and historical sites.",
      "date": "0800"
    },
    {
      "headline": "Role of Waqif and Mutawalli",
      "text": "In the waqf system, the donor is known as a waqif, and they appoint a mutawalli, or trustee, to manage the property. The mutawalli is responsible for overseeing the waqf and may receive a share of the revenues it generates.",
      "date": "0800"
    },
    {
      "headline": "Legal Framework of Waqf",
      "text": "The waqf system is based on several hadiths and Islamic legal principles, which provide the framework for its operation and governance.",
      "date": "0800"
    },
    {
      "headline": "Impact of Waqf on Islamic Society",
      "text": "Waqf has played a significant role in Islamic society by funding mosques, schools, hospitals, and other public services, contributing to the welfare and development of communities.",
      "date": "0800"
    }
  ]
}

