  "timeline": [
    {
      "headline": "Founding of id Software",
      "text": "id Software was founded on February 1, 1991, by John Carmack, John Romero, Tom Hall, and Adrian Carmack, who were all members of the computer company Softdisk.",
      "date": "1991-02-01"
    },
    {
      "headline": "Release of Commander Keen",
      "text": "In December 1990, before the official founding of id Software, the team released Commander Keen in Invasion of the Vorticons, which was a major success and established the company.",
      "date": "1990-12"
    },
    {
      "headline": "Release of Wolfenstein 3D",
      "text": "In May 1992, id Software released Wolfenstein 3D, which is often credited with popularizing the first-person shooter genre.",
      "date": "1992-05"
    },
    {
      "headline": "Release of Doom",
      "text": "On December 10, 1993, id Software released Doom, a landmark title in the video game industry that further established the first-person shooter genre.",
      "date": "1993-12-10"
    },
    {
      "headline": "Release of Quake",
      "text": "In June 1996, id Software released Quake, which introduced true 3D graphics and online multiplayer gaming.",
      "date": "1996-06"
    },
    {
      "headline": "Departure of John Romero",
      "text": "In August 1996, John Romero left id Software to form his own company, Ion Storm.",
      "date": "1996-08"
    },
    {
      "headline": "Release of Quake II",
      "text": "In December 1997, id Software released Quake II, which was a commercial success and continued to build on the Quake franchise.",
      "date": "1997-12"
    },
    {
      "headline": "Release of Doom 3",
      "text": "On August 3, 2004, id Software released Doom 3, a reboot of the original Doom series with advanced graphics and a horror-focused atmosphere.",
      "date": "2004-08-03"
    },
    {
      "headline": "Acquisition by ZeniMax Media",
      "text": "In June 2009, id Software was acquired by ZeniMax Media, the parent company of Bethesda Softworks.",
      "date": "2009-06"
    },
    {
      "headline": "Release of Rage",
      "text": "On October 4, 2011, id Software released Rage, a first-person shooter set in a post-apocalyptic world.",
      "date": "2011-10-04"
    },
    {
      "headline": "Release of Doom (2016)",
      "text": "On May 13, 2016, id Software released a reboot of the Doom series, simply titled Doom, which was praised for its fast-paced gameplay and graphics.",
      "date": "2016-05-13"
    },
    {
      "headline": "Release of Doom Eternal",
      "text": "On March 20, 2020, id Software released Doom Eternal, a sequel to the 2016 Doom game, which received critical acclaim for its design and gameplay.",
      "date": "2020-03-20"
    }
  ]
}

