    {
      "headline": "Announcement of the Truman Doctrine",
      "text": "President Harry S. Truman announced the Truman Doctrine to Congress on March 12, 1947. The doctrine pledged American support for democracies against authoritarian threats, specifically aiming to counter the growth of the Soviet bloc during the Cold War.",
      "date": "1947-03-12"
    },
    {
      "headline": "Further Development of the Truman Doctrine",
      "text": "On July 4, 1948, President Truman further developed the Truman Doctrine by pledging to oppose communist rebellions in Greece and Soviet demands from Turkey. This marked a significant expansion of the doctrine's scope.",
      "date": "1948-07-04"
    },
    {
      "headline": "Formation of NATO",
      "text": "The Truman Doctrine led to the formation of the North Atlantic Treaty Organization (NATO) in 1949. NATO was established as a collective defense alliance to counter Soviet influence and aggression.",
      "date": "1949"
    },
    {
      "headline": "Start of the Cold War",
      "text": "Historians often use President Truman's speech to Congress on March 12, 1947, as the date marking the start of the Cold War, due to its significant impact on U.S. foreign policy and international relations.",
      "date": "1947-03-12"
    }
  ]
}

