{
  "timeline": [
    {
      "headline": "Emergence of Pop Art",
      "text": "Pop art emerged in the mid- to late-1950s in the United Kingdom and the United States. It challenged traditional fine art by incorporating imagery from popular and mass culture.",
      "date": "1950"
    },
    {
      "headline": "Independent Group Formation",
      "text": "In 1952, the Independent Group was formed in London. It is considered a precursor to the pop art movement, as it explored the relationship between popular culture and art.",
      "date": "1952"
    },
    {
      "headline": "First Use of the Term 'Pop Art'",
      "text": "The term 'pop art' was first used by British art critic Lawrence Alloway in the late 1950s to describe a new form of art that used imagery from popular culture.",
      "date": "1958"
    },
    {
      "headline": "Andy Warhol's Campbell's Soup Cans",
      "text": "In 1962, American artist Andy Warhol exhibited his famous 'Campbell's Soup Cans' series, which became an iconic representation of pop art.",
      "date": "1962"
    },
    {
      "headline": "Roy Lichtenstein's Comic Strip Paintings",
      "text": "Roy Lichtenstein gained fame in the early 1960s for his paintings based on comic strips, such as 'Whaam!' (1963), which became emblematic of the pop art movement.",
      "date": "1963"
    },
    {
      "headline": "The First International Exhibition of Pop Art",
      "text": "In 1964, the 'New Realists' exhibition at the Sidney Janis Gallery in New York City was one of the first international exhibitions to showcase pop art.",
      "date": "1964"
    },
    {
      "headline": "Pop Art's Influence on Fashion",
      "text": "In the mid-1960s, pop art began to influence fashion, with designers like Yves Saint Laurent incorporating pop art elements into their collections.",
      "date": "1965"
    },
    {
      "headline": "Decline of Pop Art",
      "text": "By the late 1960s, pop art began to decline as a dominant art movement, giving way to other movements such as minimalism and conceptual art.",
      "date": "1969"
    }
  ]
}

