{
  "timeline": [
    {
      "headline": "Start of the Nine Years' War",
      "text": "The Nine Years' War began in 1688 when France, under King Louis XIV, invaded the Rhineland, prompting the formation of the Grand Alliance by England, the Dutch Republic, and the Holy Roman Empire.",
      "date": "1688"
    },
    {
      "headline": "Battle of Walcourt",
      "text": "On August 25, 1689, the Battle of Walcourt took place, where the forces of the Grand Alliance, led by the Duke of Marlborough, defeated the French army.",
      "date": "1689-08-25"
    },
    {
      "headline": "Williamite War in Ireland",
      "text": "The Williamite War in Ireland, a related conflict, began in 1689 and lasted until 1691, as part of the broader Nine Years' War.",
      "date": "1689"
    },
    {
      "headline": "King William's War",
      "text": "King William's War, the North American theater of the Nine Years' War, began in 1689 and involved battles between English and French colonies.",
      "date": "1689"
    },
    {
      "headline": "Battle of Fleurus",
      "text": "On July 1, 1690, the Battle of Fleurus occurred, where the French army, commanded by Marshal Luxembourg, defeated the forces of the Grand Alliance.",
      "date": "1690-07-01"
    },
    {
      "headline": "Battle of Beachy Head",
      "text": "On July 10, 1690, the French fleet defeated the Anglo-Dutch fleet at the Battle of Beachy Head, gaining temporary control of the English Channel.",
      "date": "1690-07-10"
    },
    {
      "headline": "Battle of Steenkerque",
      "text": "On August 3, 1692, the Battle of Steenkerque took place, resulting in a French victory over the forces of the Grand Alliance.",
      "date": "1692-08-03"
    },
    {
      "headline": "Battle of Landen",
      "text": "On July 29, 1693, the Battle of Landen was fought, where the French army, led by Marshal Luxembourg, defeated the Grand Alliance forces.",
      "date": "1693-07-29"
    },
    {
      "headline": "Battle of Marsaglia",
      "text": "On October 4, 1693, the Battle of Marsaglia occurred, with the French army achieving a decisive victory over the forces of the Grand Alliance.",
      "date": "1693-10-04"
    },
    {
      "headline": "Treaty of Ryswick",
      "text": "The Nine Years' War ended with the signing of the Treaty of Ryswick on September 20, 1697, which restored the territorial status quo and recognized William III as the legitimate king of England.",
      "date": "1697-09-20"
    }
  ]
}

