{
  "timeline": [
    {
      "headline": "Foundation of the Kingdom of Sussex",
      "text": "The Kingdom of Sussex was established by Ælle, who is considered the first king. The foundation is traditionally dated to 477 AD.",
      "date": "0477"
    },
    {
      "headline": "Battle of Mercredesburne",
      "text": "In 485, Ælle fought against the Britons at the Battle of Mercredesburne, further consolidating his power in the region.",
      "date": "0485"
    },
    {
      "headline": "Ælle's Victory at Pevensey",
      "text": "In 491, Ælle and his son Cissa captured the fortress of Pevensey, marking a significant expansion of their territory.",
      "date": "0491"
    },
    {
      "headline": "Conversion to Christianity",
      "text": "In the late 7th century, Sussex was the last of the Anglo-Saxon kingdoms to convert to Christianity, with the efforts of Saint Wilfrid around 681.",
      "date": "0681"
    },
    {
      "headline": "Annexation by Wessex",
      "text": "In 825, Sussex was annexed by the Kingdom of Wessex under King Egbert, losing its status as an independent kingdom.",
      "date": "0825"
    },
    {
      "headline": "Norman Conquest",
      "text": "In 1066, Sussex was a key location during the Norman Conquest, with the Battle of Hastings occurring near the town of Battle.",
      "date": "1066"
    },
    {
      "headline": "Creation of the County of Sussex",
      "text": "Following the Norman Conquest, Sussex was established as a county, with its boundaries largely reflecting those of the former kingdom.",
      "date": "1066"
    },
    {
      "headline": "Division into East and West Sussex",
      "text": "In 1889, Sussex was divided into two administrative counties, East Sussex and West Sussex, under the Local Government Act 1888.",
      "date": "1889"
    },
    {
      "headline": "Establishment of Ceremonial Counties",
      "text": "In 1974, the Local Government Act 1972 came into effect, formally establishing East Sussex and West Sussex as separate ceremonial counties.",
      "date": "1974"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Development of Chivalry",
      "text": "Chivalry, or the chivalric code, began to develop in Europe between 1170 and 1220. It was an informal and varying code of conduct associated with the medieval Christian institution of knighthood.",
      "date": "1170"
    },
    {
      "headline": "Popularization in Medieval Literature",
      "text": "The ideals of chivalry were popularized in medieval literature, particularly through the literary cycles known as the Matter of France and the Matter of Britain.",
      "date": "1130"
    },
    {
      "headline": "Matter of France",
      "text": "The Matter of France relates to the legendary companions of Charlemagne and his men-at-arms, the paladins, and contributed to the chivalric ideals.",
      "date": "1170"
    },
    {
      "headline": "Matter of Britain",
      "text": "The Matter of Britain, informed by Geoffrey of Monmouth's 'Historia Regum Britanniae' written in the 1130s, popularized the legend of King Arthur and his knights of the Round Table, further embedding chivalric ideals.",
      "date": "1130"
    }
  ]
}

{
