{
  "timeline": [
    {
      "headline": "Construction of Cutty Sark",
      "text": "Cutty Sark was built on the River Leven, Dumbarton, Scotland in 1869 for the Jock Willis Shipping Line. She was one of the last tea clippers to be built.",
      "date": "1869"
    },
    {
      "headline": "Launch of Cutty Sark",
      "text": "Cutty Sark was launched on November 22, 1869. She was designed to be one of the fastest ships of her time.",
      "date": "1869-11-22"
    },
    {
      "headline": "First Voyage",
      "text": "Cutty Sark embarked on her maiden voyage on February 16, 1870, sailing from London to Shanghai.",
      "date": "1870-02-16"
    },
    {
      "headline": "Transition to Wool Trade",
      "text": "In 1883, Cutty Sark began transporting wool from Australia to England, a trade she dominated for several years due to her speed.",
      "date": "1883"
    },
    {
      "headline": "Sold to Portuguese Company",
      "text": "In 1895, Cutty Sark was sold to the Portuguese company Ferreira and renamed Ferreira.",
      "date": "1895"
    },
    {
      "headline": "Renamed Maria do Amparo",
      "text": "In 1922, Cutty Sark was renamed Maria do Amparo after being sold again within Portugal.",
      "date": "1922"
    },
    {
      "headline": "Return to British Ownership",
      "text": "Cutty Sark was purchased by Captain Wilfred Dowman in 1922, who restored her and returned her to British ownership.",
      "date": "1922"
    },
    {
      "headline": "Preservation as a Museum Ship",
      "text": "In 1954, Cutty Sark was moved to a custom-built dry dock in Greenwich, London, to be preserved as a museum ship.",
      "date": "1954"
    },
    {
      "headline": "Fire Damage",
      "text": "On May 21, 2007, Cutty Sark was severely damaged by a fire while undergoing conservation work.",
      "date": "2007-05-21"
    },
    {
      "headline": "Reopening after Restoration",
      "text": "After extensive restoration, Cutty Sark was reopened to the public on April 25, 2012.",
      "date": "2012-04-25"
    }
  ]
}

