      "headline": "Birth of Charles-Maurice de Talleyrand-Périgord",
      "text": "Charles-Maurice de Talleyrand-Périgord was born on February 2, 1754, in Paris, France.",
      "date": "1754-02-02"
    },
    {
      "headline": "Agent-General of the Clergy",
      "text": "In 1780, Talleyrand was appointed as the Agent-General of the Clergy, a position that involved managing the financial affairs of the French Catholic Church.",
      "date": "1780"
    },
    {
      "headline": "Bishop of Autun",
      "text": "In 1789, just before the outbreak of the French Revolution, Talleyrand became the Bishop of Autun.",
      "date": "1789"
    },
    {
      "headline": "Role in the French Revolution",
      "text": "During the French Revolution, Talleyrand played a significant role, including supporting the Civil Constitution of the Clergy in 1790.",
      "date": "1790"
    },
    {
      "headline": "Foreign Minister under the Directory",
      "text": "Talleyrand served as the Foreign Minister of France from 1797 to 1799 under the Directory.",
      "date": "1797"
    },
    {
      "headline": "Foreign Minister under Napoleon",
      "text": "He was appointed Foreign Minister again by Napoleon Bonaparte, serving from 1799 to 1807.",
      "date": "1799"
    },
    {
      "headline": "Prince of Benevento",
      "text": "In 1806, Talleyrand was made the Prince of Benevento by Napoleon.",
      "date": "1806"
    },
    {
      "headline": "Resignation as Foreign Minister",
      "text": "Talleyrand resigned as Foreign Minister in 1807, although he continued to be involved in politics.",
      "date": "1807"
    },
    {
      "headline": "Congress of Vienna",
      "text": "Talleyrand played a crucial role at the Congress of Vienna in 1814-1815, representing France and helping to shape the post-Napoleonic order in Europe.",
      "date": "1814"
    },
    {
      "headline": "Prime Minister of France",
      "text": "He briefly served as the Prime Minister of France from July 9, 1815, to September 26, 1815.",
      "date": "1815-07-09"
    },
    {
      "headline": "Ambassador to the United Kingdom",
      "text": "Talleyrand served as the French ambassador to the United Kingdom from 1830 to 1834.",
      "date": "1830"
    },
    {
      "headline": "Death of Charles-Maurice de Talleyrand-Périgord",
      "text": "Charles-Maurice de Talleyrand-Périgord died on May 17, 1838, in Paris, France.",
      "date": "1838-05-17"
    }
  ]
}

