    },
    {
      "headline": "Galileo Galilei's telescopic discoveries",
      "text": "In 1610, Galileo Galilei used a telescope to make significant astronomical discoveries, including the moons of Jupiter and the phases of Venus, supporting the heliocentric model.",
      "date": "1610"
