{
  "timeline": [
    {
      "headline": "First Recorded Use of Naval Mines",
      "text": "The first recorded use of naval mines was by the Chinese during the Ming dynasty. These early mines were made of bamboo and filled with gunpowder. They were used to defend against Japanese pirates in the 14th century.",
      "date": "1300"
    },
    {
      "headline": "Development of the Modern Naval Mine",
      "text": "The modern naval mine began to take shape in the 19th century with the development of contact mines. These mines were designed to explode upon contact with a ship.",
      "date": "1800"
    },
    {
      "headline": "Use of Naval Mines in the Crimean War",
      "text": "Naval mines were used extensively during the Crimean War (1853-1856) by the Russians to defend against British and French naval forces.",
      "date": "1853"
    },
    {
      "headline": "Naval Mines in the American Civil War",
      "text": "During the American Civil War (1861-1865), both the Union and Confederate forces used naval mines, known as torpedoes at the time, to protect harbors and rivers.",
      "date": "1861"
    },
    {
      "headline": "World War I and Naval Mines",
      "text": "Naval mines were used extensively during World War I (1914-1918). The North Sea Mine Barrage was one of the largest minefields laid during the war, intended to restrict the movement of German U-boats.",
      "date": "1914"
    },
    {
      "headline": "World War II and Advanced Naval Mines",
      "text": "In World War II (1939-1945), naval mines saw significant technological advancements, including the development of magnetic and acoustic mines. These mines played a crucial role in naval warfare.",
      "date": "1939"
    },
    {
      "headline": "Post-World War II Developments",
      "text": "After World War II, naval mines continued to evolve with advancements in technology, including the development of influence mines that could be triggered by the magnetic, acoustic, or pressure signatures of ships.",
      "date": "1945"
    },
    {
      "headline": "Naval Mines in the Korean War",
      "text": "During the Korean War (1950-1953), naval mines were used by North Korean forces to protect their harbors and coastal areas.",
      "date": "1950"
    },
    {
      "headline": "Modern Use of Naval Mines",
      "text": "In recent decades, naval mines have been used in various conflicts, including the Iran-Iraq War (1980-1988) and the Gulf War (1990-1991), demonstrating their continued strategic importance.",
      "date": "1980"
    }
  ]
}

