{
  "timeline": [
    {
      "headline": "Founding of Fluxus",
      "text": "Fluxus was founded in the early 1960s by George Maciunas, a Lithuanian-American artist. The movement began as a loose, international network of artists, composers, and designers.",
      "date": "1960"
    },
    {
      "headline": "First Fluxus Festival",
      "text": "The first Fluxus Festival took place in Wiesbaden, Germany, in September 1962. This event marked the official launch of the Fluxus movement.",
      "date": "1962-09"
    },
    {
      "headline": "Fluxus Manifesto",
      "text": "George Maciunas published the Fluxus Manifesto in 1963, outlining the goals and philosophy of the movement, emphasizing simplicity, anti-commercialism, and the blending of different artistic disciplines.",
      "date": "1963"
    },
    {
      "headline": "Intermedia Concept Introduced",
      "text": "In 1965, Fluxus artist Dick Higgins introduced the concept of 'intermedia,' which described the blending of different artistic media, a hallmark of Fluxus activities.",
      "date": "1965"
    },
    {
      "headline": "Development of Video Art",
      "text": "Fluxus artists Nam June Paik and Wolf Vostell pioneered video art in the mid-1960s, using television sets and video technology as artistic mediums.",
      "date": "1965"
    },
    {
      "headline": "Fluxus in New York",
      "text": "Throughout the 1960s, Fluxus activities expanded in New York, with artists like Yoko Ono, George Brecht, and La Monte Young contributing to the movement's growth.",
      "date": "1960s"
    },
    {
      "headline": "Fluxus and Conceptual Art",
      "text": "Henry Flynt, an artist associated with Fluxus, developed the concept of conceptual art in the 1960s, focusing on the idea over the physical art object.",
      "date": "1960s"
    },
    {
      "headline": "Fluxus in the 1970s",
      "text": "The movement continued to evolve in the 1970s, with Fluxus artists participating in performances, exhibitions, and publications worldwide.",
      "date": "1970s"
    },
    {
      "headline": "Legacy of Fluxus",
      "text": "Fluxus left a lasting impact on contemporary art, influencing movements such as performance art, installation art, and digital art.",
      "date": "1980s and beyond"
    }
  ]
}

