{
  "timeline": [
    {
      "headline": "Discovery of the Strong Force",
      "text": "The concept of the strong force was first introduced in the early 20th century to explain the binding of protons and neutrons in the atomic nucleus. This was necessary to account for the stability of atomic nuclei despite the repulsive electromagnetic force between protons.",
      "date": "1930"
    },
    {
      "headline": "Yukawa's Meson Theory",
      "text": "In 1935, Hideki Yukawa proposed the existence of a particle, later known as the pion, as the carrier of the strong force between nucleons. This was the first theoretical model to describe the strong interaction.",
      "date": "1935"
    },
    {
      "headline": "Discovery of Pions",
      "text": "In 1947, pions were discovered in cosmic ray experiments, providing experimental evidence for Yukawa's theory and the existence of the strong force.",
      "date": "1947"
    },
    {
      "headline": "Development of Quantum Chromodynamics (QCD)",
      "text": "In the 1970s, Quantum Chromodynamics (QCD) was developed as the theory of the strong interaction. QCD describes the interactions between quarks and gluons, the fundamental particles that make up protons, neutrons, and other hadrons.",
      "date": "1970"
    },
    {
      "headline": "Asymptotic Freedom",
      "text": "In 1973, the concept of asymptotic freedom was discovered by David Gross, Frank Wilczek, and David Politzer. This property of QCD explains why quarks behave as free particles at high energies.",
      "date": "1973"
    },
    {
      "headline": "Nobel Prize in Physics for QCD",
      "text": "In 2004, David Gross, Frank Wilczek, and David Politzer were awarded the Nobel Prize in Physics for their discovery of asymptotic freedom in the theory of the strong interaction.",
      "date": "2004"
    }
  ]
}

