{
  "timeline": [
    {
      "headline": "Hippocrates' Contribution to Mental Health",
      "text": "Hippocrates, often considered the 'Father of Medicine', proposed that mental disorders were caused by imbalances in bodily fluids, known as humors, around 400 BCE.",
      "date": "-0400"
    },
    {
      "headline": "Establishment of the First Psychiatric Hospital",
      "text": "The first psychiatric hospital, Bethlem Royal Hospital, was established in London in 1247, marking a significant development in the institutional care of mental health patients.",
      "date": "1247"
    },
    {
      "headline": "Philippe Pinel's Reforms",
      "text": "In 1793, Philippe Pinel, a French physician, introduced humane treatment reforms in psychiatric hospitals, advocating for the unchaining of patients and the use of moral therapy.",
      "date": "1793"
    },
    {
      "headline": "Founding of the American Psychiatric Association",
      "text": "The American Psychiatric Association was founded in 1844, originally as the Association of Medical Superintendents of American Institutions for the Insane.",
      "date": "1844"
    },
    {
      "headline": "Sigmund Freud's Psychoanalysis",
      "text": "Sigmund Freud developed the theory of psychoanalysis in the late 19th and early 20th centuries, introducing concepts such as the unconscious mind and defense mechanisms.",
      "date": "1890"
    },
    {
      "headline": "Introduction of Electroconvulsive Therapy (ECT)",
      "text": "Electroconvulsive therapy was first used in 1938 by Italian neurologist Ugo Cerletti, becoming a significant treatment for severe mental disorders.",
      "date": "1938"
    },
    {
      "headline": "Development of Antipsychotic Medications",
      "text": "The first antipsychotic medication, chlorpromazine, was developed in 1952, revolutionizing the treatment of schizophrenia and other psychotic disorders.",
      "date": "1952"
    },
    {
      "headline": "Publication of DSM-III",
      "text": "The third edition of the Diagnostic and Statistical Manual of Mental Disorders (DSM-III) was published in 1980, introducing a more systematic and standardized approach to diagnosing mental disorders.",
      "date": "1980"
    },
    {
      "headline": "Introduction of SSRIs",
      "text": "Selective serotonin reuptake inhibitors (SSRIs), a class of antidepressants, were introduced in the late 1980s, offering a new treatment option for depression and anxiety disorders.",
      "date": "1987"
    }
  ]
}

