    },
    {
      "headline": "Brown v. Board of Education",
      "text": "In 1954, the ACLU filed an amicus brief in the landmark Supreme Court case Brown v. Board of Education, which declared racial segregation in public schools unconstitutional.",
      "date": "1954"
    },
    {
      "headline": "Defending Free Speech in Skokie",
      "text": "In 1977, the ACLU defended the right of a neo-Nazi group to march in Skokie, Illinois, a community with a large Jewish population, emphasizing the importance of free speech.",
      "date": "1977"
    },
    {
      "headline": "Roe v. Wade",
      "text": "The ACLU played a significant role in the 1973 Supreme Court case Roe v. Wade, which recognized a woman's constitutional right to have an abortion.",
      "date": "1973"
    },
    {
      "headline": "ACLU and the Patriot Act",
      "text": "Following the September 11 attacks in 2001, the ACLU actively opposed the USA PATRIOT Act, arguing that it infringed on civil liberties.",
      "date": "2001"
    },
