    {
      "headline": "Potsdam Edict of Tolerance",
      "text": "In 1685, the Edict of Potsdam was issued by Frederick William, inviting Huguenots to settle in the city, boosting its population and economy.",
      "date": "1685"
    },
    {
      "headline": "Potsdam Becomes a Royal Residence",
      "text": "In 1701, Potsdam became a royal residence under Frederick I of Prussia, leading to significant architectural and cultural development.",
      "date": "1701"
    },
    {
      "headline": "Sanssouci Palace Construction",
      "text": "The construction of Sanssouci Palace, the summer residence of Frederick the Great, began in 1745.",
      "date": "1745"
    },
    {
      "headline": "Potsdam Conference",
      "text": "The Potsdam Conference was held from July 17 to August 2, 1945, where Allied leaders met to discuss post-World War II arrangements.",
      "date": "1945-07-17"
    },
    {
      "headline": "Potsdam Becomes Part of East Germany",
      "text": "After World War II, Potsdam became part of East Germany in 1949.",
      "date": "1949"
