    {
      "headline": "Early Opposition to Nazism",
      "text": "From the early 1930s, various groups and individuals began to oppose the rise of the Nazi regime in Germany. This included political parties like the Social Democrats and Communists, as well as religious groups and intellectuals.",
      "date": "1930"
    },
    {
      "headline": "The White Rose Movement",
      "text": "In 1942, the White Rose, a non-violent resistance group led by students including Hans and Sophie Scholl, began distributing leaflets calling for active opposition to the Nazi regime.",
      "date": "1942"
    },
    {
      "headline": "The July 20 Plot",
      "text": "On July 20, 1944, a group of German military officers, led by Claus von Stauffenberg, attempted to assassinate Adolf Hitler and overthrow the Nazi government. The plot failed, leading to severe reprisals.",
      "date": "1944-07-20"
    },
    {
      "headline": "The Kreisau Circle",
      "text": "The Kreisau Circle was a group of intellectuals and professionals who met between 1940 and 1944 to discuss plans for a post-Nazi Germany. They were eventually discovered and many members were executed.",
      "date": "1940"
    },
    {
      "headline": "Operation Valkyrie",
      "text": "Operation Valkyrie was a plan developed by German military officers to take control of the government in the event of Hitler's assassination. It was activated during the July 20 Plot but ultimately failed.",
      "date": "1944"
    },
    {
      "headline": "The Red Orchestra",
      "text": "The Red Orchestra was a network of anti-Nazi resistance groups in Germany and occupied Europe. They were involved in espionage and disseminating anti-Nazi propaganda. Many members were arrested and executed in 1942-1943.",
      "date": "1942"
    },
    {
      "headline": "The Rosenstrasse Protest",
      "text": "In February 1943, non-Jewish wives of Jewish men protested in Berlin against the arrest of their husbands. The protest led to the release of the men, marking a rare successful public protest against Nazi policies.",
      "date": "1943-02"
    },
    {
      "headline": "The Edelweiss Pirates",
      "text": "The Edelweiss Pirates were a loosely organized group of youths who resisted the Nazi regime through acts of defiance and sabotage. They were active throughout the 1930s and 1940s.",
      "date": "1930"
    },
    {
      "headline": "The Confessing Church",
      "text": "The Confessing Church was a movement within the German Protestant Church that opposed the Nazi regime's attempts to control the churches. It was founded in 1934 and continued its resistance throughout the Nazi era.",
      "date": "1934"
    }
  ]
}

