    {
      "headline": "United Nations Security Council Resolution 1973",
      "text": "On 17 March 2011, the United Nations Security Council adopted Resolution 1973 with ten votes in favor and five abstentions. The resolution called for an immediate ceasefire in Libya, an end to attacks against civilians, and imposed a no-fly zone over the country.",
      "date": "2011-03-17"
    },
    {
      "headline": "Start of NATO-led Military Intervention",
      "text": "On 19 March 2011, a multi-state NATO-led coalition began a military intervention in Libya. The intervention aimed to enforce the UN Security Council Resolution 1973, which included implementing a no-fly zone and protecting civilians from attacks by the Libyan government forces.",
      "date": "2011-03-19"
    },
    {
      "headline": "Operation Odyssey Dawn",
      "text": "The United States launched Operation Odyssey Dawn on 19 March 2011, as part of the international military intervention in Libya. The operation involved air and missile strikes against Libyan government forces to enforce the no-fly zone and protect civilians.",
      "date": "2011-03-19"
    },
    {
      "headline": "NATO Assumes Command",
      "text": "On 31 March 2011, NATO officially took command of military operations in Libya from the coalition forces. The operation was named Operation Unified Protector, focusing on enforcing the arms embargo, maintaining the no-fly zone, and protecting civilians.",
      "date": "2011-03-31"
    },
    {
      "headline": "End of NATO Operations",
      "text": "NATO ended its military operations in Libya on 31 October 2011, following the death of Muammar Gaddafi and the fall of his regime. The intervention was deemed successful in achieving its objectives of protecting civilians and enforcing the no-fly zone.",
      "date": "2011-10-31"
    }
  ]
}

