{
  "timeline": [
    {
      "headline": "Discovery of Redshift",
      "text": "In 1848, the concept of redshift was first proposed by the French physicist Hippolyte Fizeau. He suggested that the observed change in the wavelength of light from a star could be due to the Doppler effect, which is the change in frequency or wavelength of a wave in relation to an observer moving relative to the wave source.",
      "date": "1848"
    },
    {
      "headline": "Vesto Slipher's Observations",
      "text": "In 1912, American astronomer Vesto Slipher made the first measurements of the redshift of galaxies. He observed that the spectral lines of light from galaxies were shifted towards the red end of the spectrum, indicating that they were moving away from Earth.",
      "date": "1912"
    },
    {
      "headline": "Hubble's Law",
      "text": "In 1929, Edwin Hubble formulated Hubble's Law, which states that the redshift of galaxies is proportional to their distance from Earth. This discovery provided the first observational evidence for the expansion of the universe.",
      "date": "1929"
    },
    {
      "headline": "Cosmological Redshift",
      "text": "The concept of cosmological redshift was developed as a result of the expanding universe model. It describes the redshift of light from distant galaxies as a result of the expansion of space itself, rather than the motion of galaxies through space.",
      "date": "1929"
    },
    {
      "headline": "Gravitational Redshift",
      "text": "Gravitational redshift was predicted by Albert Einstein in 1916 as part of his general theory of relativity. It describes the process by which light or other electromagnetic radiation from a source is increased in wavelength, or redshifted, when moving away from a gravitational field.",
      "date": "1916"
    }
  ]
}

