{
  "timeline": [
    {
      "headline": "Founding of the Kataeb Party",
      "text": "The Kataeb Party, also known as the Phalangist Party, was founded by Pierre Gemayel in 1936 as a right-wing Christian political party in Lebanon.",
      "date": "1936"
    },
    {
      "headline": "Lebanese Civil War",
      "text": "The Kataeb Party and its paramilitary wings played a major role in the Lebanese Civil War, which lasted from 1975 to 1990, opposing Palestinian insurgency in South Lebanon and collaborating with Israel.",
      "date": "1975"
    },
    {
      "headline": "Black Saturday Massacre",
      "text": "On December 6, 1975, Phalangist militiamen were responsible for the Black Saturday massacre, one of the worst massacres committed during the Lebanese Civil War.",
      "date": "1975-12-06"
    },
    {
      "headline": "Tel al-Zaatar Massacre",
      "text": "In 1976, the Kataeb Party's militia was involved in the Tel al-Zaatar massacre, which resulted in the deaths of many Palestinian refugees.",
      "date": "1976"
    },
    {
      "headline": "Karantina Massacre",
      "text": "In January 1976, Phalangist forces committed the Karantina massacre, targeting a predominantly Muslim slum in Beirut.",
      "date": "1976-01"
    },
    {
      "headline": "Ehden Massacre",
      "text": "The Ehden massacre occurred on June 13, 1978, when Phalangist forces attacked the town of Ehden, resulting in the deaths of many civilians.",
      "date": "1978-06-13"
    },
    {
      "headline": "Bachir Gemayel Elected President",
      "text": "In 1982, Bachir Gemayel, the leader of the Kataeb Party's militia and Pierre Gemayel's youngest son, was elected President of Lebanon.",
      "date": "1982"
    },
    {
      "headline": "Assassination of Bachir Gemayel",
      "text": "Bachir Gemayel was assassinated on September 14, 1982, before he could take office as President of Lebanon.",
      "date": "1982-09-14"
    },
    {
      "headline": "Sabra and Shatilla Massacre",
      "text": "In September 1982, Phalangist militiamen committed the Sabra and Shatilla massacre with support from the Israeli Defense Forces (IDF).",
      "date": "1982-09"
    },
    {
      "headline": "Amine Gemayel Presidency",
      "text": "Following the assassination of his brother Bachir, Amine Gemayel became President of Lebanon and led the Kataeb Party through much of the Lebanese Civil War.",
      "date": "1982"
    },
    {
      "headline": "Decline and Re-emergence",
      "text": "The Kataeb Party experienced a decline in the late 1980s and 1990s but slowly re-emerged in the early 2000s.",
      "date": "2000"
    },
    {
      "headline": "Current Status",
      "text": "As of the early 2020s, the Kataeb Party is part of the Lebanese opposition and holds 4 out of the 128 seats in the Lebanese Parliament.",
      "date": "2020"
    }
  ]
}

