{
  "timeline": [
    {
      "headline": "Bombay Bombings",
      "text": "On 12 March 1993, a series of 12 bomb explosions took place in Bombay, Maharashtra, India. The attacks resulted in 257 fatalities and 1,400 injuries.",
      "date": "1993-03-12"
    },
    {
      "headline": "Coordination by Dawood Ibrahim",
      "text": "The bombings were coordinated by Dawood Ibrahim, leader of the Mumbai-based international organized crime syndicate D-Company. Ibrahim was believed to have ordered and helped organize the bombings through his subordinate Tiger Memon.",
      "date": "1993-03-12"
    },
    {
      "headline": "Aftermath and Investigation",
      "text": "Following the bombings, investigations were launched which revealed the involvement of the D-Company and its leader Dawood Ibrahim. The attacks were seen as retaliation for the Babri Masjid demolition.",
      "date": "1993"
    },
    {
      "headline": "Arrests and Trials",
      "text": "In the years following the bombings, several arrests were made, and trials were conducted. Many individuals were convicted for their roles in the attacks.",
      "date": "1993-2007"
    },
    {
      "headline": "Convictions and Sentencing",
      "text": "In 2006, 100 of the 129 accused were found guilty under the Terrorist and Disruptive Activities (Prevention) Act (TADA). The sentencing included death penalties and life imprisonments.",
      "date": "2006"
    },
    {
      "headline": "Yakub Memon Execution",
      "text": "Yakub Memon, one of the main conspirators, was executed on 30 July 2015 after being convicted for his involvement in the bombings.",
      "date": "2015-07-30"
    }
  ]
}

