{
  "timeline": [
    {
      "headline": "Opening of the Council of Trent",
      "text": "The Council of Trent officially opened on December 13, 1545, in the city of Trent, which is now located in northern Italy. It was convened by Pope Paul III in response to the Protestant Reformation.",
      "date": "1545-12-13"
    },
    {
      "headline": "First Period of the Council",
      "text": "The first period of the Council of Trent lasted from 1545 to 1547. During this time, the council addressed issues such as the authority of the Scriptures and the role of tradition.",
      "date": "1545"
    },
    {
      "headline": "Transfer to Bologna",
      "text": "In 1547, the council was temporarily transferred to Bologna due to an outbreak of the plague in Trent. This move was controversial and led to a temporary suspension of the council.",
      "date": "1547"
    },
    {
      "headline": "Second Period of the Council",
      "text": "The second period of the Council of Trent took place from 1551 to 1552. It was reconvened by Pope Julius III and focused on the sacraments and the Eucharist.",
      "date": "1551"
    },
    {
      "headline": "Suspension of the Council",
      "text": "The council was suspended again in 1552 due to political and military tensions in Europe, including the Schmalkaldic War.",
      "date": "1552"
    },
    {
      "headline": "Third Period of the Council",
      "text": "The third and final period of the Council of Trent occurred from 1562 to 1563. It was reconvened by Pope Pius IV and addressed issues such as the reform of the clergy and the establishment of seminaries.",
      "date": "1562"
    },
    {
      "headline": "Conclusion of the Council of Trent",
      "text": "The Council of Trent concluded on December 4, 1563. It resulted in significant reforms within the Catholic Church and played a key role in the Counter-Reformation.",
      "date": "1563-12-04"
    }
  ]
}

