{
  "timeline": [
    {
      "headline": "Origins of Lean Manufacturing",
      "text": "Lean manufacturing has its roots in the Toyota Production System (TPS), developed by Taiichi Ohno and Eiji Toyoda between the 1940s and 1970s. The system aimed to improve efficiency by eliminating waste and optimizing production processes.",
      "date": "1940"
    },
    {
      "headline": "Introduction of Just-In-Time (JIT) Production",
      "text": "The concept of Just-In-Time (JIT) production, a key component of lean manufacturing, was introduced by Toyota in the 1950s. JIT focuses on reducing inventory and producing only what is needed, when it is needed.",
      "date": "1950"
    },
    {
      "headline": "Development of the Toyota Production System",
      "text": "By the 1970s, the Toyota Production System was fully developed, incorporating principles such as JIT, jidoka (automation with a human touch), and continuous improvement (kaizen).",
      "date": "1970"
    },
    {
      "headline": "Lean Manufacturing Gains Attention in the West",
      "text": "In the late 1980s, Western companies began to take notice of the efficiency and success of the Toyota Production System. This led to the adoption of lean manufacturing principles in various industries outside of Japan.",
      "date": "1980"
    },
    {
      "headline": "Publication of 'The Machine That Changed the World'",
      "text": "In 1990, the book 'The Machine That Changed the World' by James P. Womack, Daniel T. Jones, and Daniel Roos was published. It introduced the term 'lean manufacturing' and detailed the benefits of the Toyota Production System.",
      "date": "1990"
    },
    {
      "headline": "Lean Manufacturing Becomes a Global Standard",
      "text": "Throughout the 1990s and 2000s, lean manufacturing principles were adopted globally across various industries, becoming a standard for efficient production and management practices.",
      "date": "1990"
    }
  ]
}

