{
  "timeline": [
    {
      "headline": "First Use of RTG",
      "text": "The first use of a radioisotope thermoelectric generator (RTG) was in 1961. It was used to power a satellite, marking the beginning of RTG applications in space exploration.",
      "date": "1961"
    },
    {
      "headline": "Transit 4A Satellite Launch",
      "text": "On June 29, 1961, the Transit 4A satellite was launched, becoming the first spacecraft to be powered by a radioisotope thermoelectric generator.",
      "date": "1961-06-29"
    },
    {
      "headline": "Apollo Lunar Surface Experiments Package",
      "text": "In 1969, RTGs were used in the Apollo Lunar Surface Experiments Package (ALSEP) deployed by Apollo 12 astronauts on the Moon, providing power for scientific instruments.",
      "date": "1969"
    },
    {
      "headline": "Pioneer 10 Launch",
      "text": "Pioneer 10, launched on March 2, 1972, was the first spacecraft to travel through the asteroid belt and make a flyby of Jupiter. It was powered by an RTG.",
      "date": "1972-03-02"
    },
    {
      "headline": "Voyager Program",
      "text": "The Voyager spacecraft, launched in 1977, used RTGs to power their instruments. These spacecraft have provided invaluable data about the outer planets and are still sending data from beyond the solar system.",
      "date": "1977"
    },
    {
      "headline": "Galileo Spacecraft Launch",
      "text": "Launched on October 18, 1989, the Galileo spacecraft was powered by RTGs and studied Jupiter and its moons, providing detailed data about the planet's atmosphere and magnetosphere.",
      "date": "1989-10-18"
    },
    {
      "headline": "Cassini-Huygens Mission",
      "text": "The Cassini-Huygens mission to Saturn, launched on October 15, 1997, used RTGs to power its instruments, allowing it to send back detailed images and data about Saturn and its rings.",
      "date": "1997-10-15"
    },
    {
      "headline": "Mars Science Laboratory Launch",
      "text": "The Mars Science Laboratory, which includes the Curiosity rover, was launched on November 26, 2011. It uses an RTG to power its systems, enabling it to explore the Martian surface.",
      "date": "2011-11-26"
    },
    {
      "headline": "New Horizons Pluto Flyby",
      "text": "New Horizons, launched on January 19, 2006, and powered by an RTG, conducted a flyby of Pluto on July 14, 2015, providing the first close-up images of the dwarf planet.",
      "date": "2015-07-14"
    }
  ]
}

