      "headline": "Ratification of the Eighteenth Amendment",
      "text": "The Eighteenth Amendment was ratified by the requisite number of states on January 16, 1919. This ratification marked the beginning of the prohibition era in the United States.",
      "date": "1919-01-16"
    },
    {
      "headline": "Enforcement of Prohibition",
      "text": "The Eighteenth Amendment went into effect on January 17, 1920, enforcing the prohibition of the manufacture, sale, and transportation of alcoholic beverages in the United States.",
      "date": "1920-01-17"
    },
    {
      "headline": "Repeal of the Eighteenth Amendment",
      "text": "The Eighteenth Amendment was repealed by the Twenty-first Amendment on December 5, 1933. This repeal ended the prohibition era, making it the only constitutional amendment in American history to be repealed.",
      "date": "1933-12-05"
    }
  ]
}

