    {
      "headline": "Formation of the Cherokee Nation",
      "text": "The Cherokee Nation was formed as a distinct political entity in the 18th century, with its own system of government and laws.",
      "date": "1700"
    },
    {
      "headline": "Treaty of Hopewell",
      "text": "In 1785, the Treaty of Hopewell was signed, establishing boundaries between the United States and the Cherokee Nation.",
      "date": "1785"
    },
    {
      "headline": "Adoption of a Written Constitution",
      "text": "In 1827, the Cherokee Nation adopted a written constitution, establishing a government modeled after the United States with executive, legislative, and judicial branches.",
      "date": "1827"
    },
    {
      "headline": "Trail of Tears",
      "text": "In 1838-1839, the Cherokee Nation was forcibly removed from their ancestral lands in the southeastern United States to Indian Territory (present-day Oklahoma) in an event known as the Trail of Tears.",
      "date": "1838"
    },
    {
      "headline": "Reestablishment in Indian Territory",
      "text": "After the Trail of Tears, the Cherokee Nation reestablished itself in Indian Territory, rebuilding its government and communities.",
      "date": "1839"
    },
    {
      "headline": "Civil War and Division",
      "text": "During the American Civil War (1861-1865), the Cherokee Nation was divided, with factions supporting both the Union and the Confederacy.",
      "date": "1861"
    },
    {
      "headline": "Curtis Act of 1898",
      "text": "The Curtis Act of 1898 effectively dismantled the tribal governments of the Five Civilized Tribes, including the Cherokee Nation, as part of the assimilation policies of the United States.",
      "date": "1898"
    },
    {
      "headline": "Reorganization and Federal Recognition",
      "text": "In 1975, the Cherokee Nation adopted a new constitution and was federally recognized, allowing it to reestablish its government and sovereignty.",
      "date": "1975"
    },
    {
      "headline": "Cherokee Nation v. Nash",
      "text": "In 2017, the Cherokee Nation reached a settlement in the case of Cherokee Nation v. Nash, which affirmed the rights of Cherokee Freedmen descendants to citizenship in the Cherokee Nation.",
      "date": "2017"
    }
  ]
}

