      "headline": "Beginning of the Great Game",
      "text": "The Great Game is considered to have begun in 1830 when Britain established a new trade route to Bukhara, aiming to counter Russian influence in Central Asia.",
      "date": "1830"
    },
    {
      "headline": "First Anglo-Afghan War",
      "text": "The First Anglo-Afghan War took place from 1839 to 1842, as Britain sought to establish a friendly regime in Afghanistan to counter Russian influence.",
      "date": "1839"
    },
    {
      "headline": "Treaty of Gandamak",
      "text": "In 1879, the Treaty of Gandamak was signed, marking the end of the Second Anglo-Afghan War and establishing British control over Afghan foreign affairs.",
      "date": "1879"
    },
    {
      "headline": "Panjdeh Incident",
      "text": "The Panjdeh Incident occurred in 1885 when Russian forces seized the oasis of Panjdeh from Afghan forces, nearly leading to war with Britain.",
      "date": "1885"
    },
    {
      "headline": "Anglo-Russian Convention",
      "text": "In 1907, the Anglo-Russian Convention was signed, effectively ending the Great Game by delineating spheres of influence in Persia, Afghanistan, and Tibet.",
      "date": "1907"
    }
  ]
}

