      "headline": "Launch of Bora Backpack",
      "text": "In 1994, Arc'teryx launched the Bora Backpack, which featured the same thermolamination technology used in their harnesses.",
      "date": "1994"
    },
    {
      "headline": "Partnership with W.L. Gore & Associates",
      "text": "In 1995, Arc'teryx partnered with W.L. Gore & Associates to incorporate Gore-Tex fabric into their products, leading to the development of waterproof and breathable outerwear.",
      "date": "1995"
    },
    {
      "headline": "Release of the Alpha SV Jacket",
      "text": "In 1998, Arc'teryx released the Alpha SV Jacket, a highly durable and weather-resistant jacket that became one of their flagship products.",
      "date": "1998"
    },
    {
      "headline": "Acquisition by Salomon Group",
      "text": "In 2001, Arc'teryx was acquired by the Salomon Group, a French company known for its outdoor sports equipment.",
      "date": "2001"
    },
    {
      "headline": "Ownership by Amer Sports",
      "text": "In 2005, Amer Sports, a Finnish sporting goods company, acquired the Salomon Group, and thus Arc'teryx became part of Amer Sports' portfolio.",
      "date": "2005"
    },
    {
      "headline": "Expansion into Urban Apparel",
      "text": "In the 2010s, Arc'teryx expanded its product line to include urban apparel, maintaining its focus on high-performance and technical design.",
      "date": "2010"
    },
    {
      "headline": "Acquisition by Anta Sports",
      "text": "In 2019, Anta Sports, a Chinese sportswear company, acquired Amer Sports, including Arc'teryx, as part of a consortium deal.",
      "date": "2019"
    }
  ]
}

