      "headline": "Outbreak of World War I",
      "text": "World War I began in July 1914, setting the stage for the systematic targeting of the Christian Ottoman Greek population by the Ottoman Empire.",
      "date": "1914-07"
    },
    {
      "headline": "Start of the Greek Genocide",
      "text": "The Greek genocide began during World War I, around 1914, as part of the Ottoman Empire's policy against its Christian minorities, including the Greeks.",
      "date": "1914"
    },
    {
      "headline": "Massacres and Deportations",
      "text": "From 1914 to 1922, the Ottoman government carried out massacres, forced deportations, and death marches against the Greek population, leading to the deaths of several hundred thousand people.",
      "date": "1914-1922"
    },
    {
      "headline": "Turkish War of Independence",
      "text": "The Turkish War of Independence, from 1919 to 1923, saw continued violence against the Greek population, exacerbating the genocide.",
      "date": "1919-1923"
    },
    {
      "headline": "End of the Greek Genocide",
      "text": "The genocide effectively ended in 1922 with the conclusion of the Greco-Turkish War and the establishment of the Republic of Turkey, leading to the mass exodus of Greeks from Anatolia.",
      "date": "1922"
    },
    {
      "headline": "Population Exchange between Greece and Turkey",
      "text": "In 1923, the Treaty of Lausanne formalized a population exchange between Greece and Turkey, leading to the forced migration of remaining Greek populations from Turkey.",
      "date": "1923"
    }
  ]
}

