      "headline": "Start of the South African Border War",
      "text": "The South African Border War began on 26 August 1966, marking the start of a conflict between the South African Defence Force (SADF) and the People's Liberation Army of Namibia (PLAN), the armed wing of SWAPO.",
      "date": "1966-08-26"
    },
    {
      "headline": "Operation Savannah",
      "text": "In October 1975, South Africa launched Operation Savannah, a military intervention in the Angolan Civil War, which was closely linked to the South African Border War.",
      "date": "1975-10"
    },
    {
      "headline": "Battle of Cassinga",
      "text": "On 4 May 1978, the SADF launched an airborne assault on a SWAPO base at Cassinga in Angola, known as the Battle of Cassinga.",
      "date": "1978-05-04"
    },
    {
      "headline": "Operation Protea",
      "text": "In August 1981, the SADF conducted Operation Protea, one of the largest operations of the war, targeting SWAPO bases in southern Angola.",
      "date": "1981-08"
    },
    {
      "headline": "Operation Askari",
      "text": "From December 1983 to January 1984, the SADF carried out Operation Askari, aimed at disrupting SWAPO's logistics and command structures in Angola.",
      "date": "1983-12"
    },
    {
      "headline": "Battle of Cuito Cuanavale",
      "text": "The Battle of Cuito Cuanavale, one of the largest battles in Africa since World War II, took place from 1987 to 1988, involving SADF, Angolan, Cuban, and SWAPO forces.",
      "date": "1987"
    },
    {
      "headline": "Tripartite Accord",
      "text": "On 22 December 1988, the Tripartite Accord was signed by Angola, Cuba, and South Africa, leading to the withdrawal of foreign troops from Angola and paving the way for Namibian independence.",
      "date": "1988-12-22"
    },
    {
      "headline": "End of the South African Border War",
      "text": "The South African Border War officially ended on 21 March 1990, when Namibia gained independence from South African rule.",
      "date": "1990-03-21"
    }
  ]
}

