    {
      "headline": "Preclassic Period Begins",
      "text": "The Preclassic period of Maya civilization begins around 2000 BCE, marking the start of agricultural communities and the development of early Maya culture.",
      "date": "-2000"
    },
    {
      "headline": "Rise of Maya Cities",
      "text": "By 750 BCE, the Maya had established large cities such as Nakbé, which featured monumental architecture and complex societies.",
      "date": "-0750"
    },
    {
      "headline": "Classic Period Begins",
      "text": "The Classic period of Maya civilization begins around 250 CE, characterized by the rise of city-states, monumental architecture, and the development of writing and calendar systems.",
      "date": "0250"
    },
    {
      "headline": "Peak of Maya Civilization",
      "text": "Between 250 and 900 CE, the Maya civilization reached its peak, with significant achievements in art, architecture, mathematics, and astronomy.",
      "date": "0250"
    },
    {
      "headline": "Collapse of Southern Lowland Cities",
      "text": "Around 900 CE, many of the major cities in the southern lowlands were abandoned, marking the end of the Classic period.",
      "date": "0900"
    },
    {
      "headline": "Postclassic Period Begins",
      "text": "The Postclassic period begins around 950 CE, with the rise of new centers such as Chichen Itza and Mayapan in the northern Yucatán Peninsula.",
      "date": "0950"
    },
    {
      "headline": "Spanish Conquest",
      "text": "The Spanish conquest of the Maya began in the early 16th century, with significant battles and the eventual subjugation of the Maya peoples by the Spanish.",
      "date": "1520"
    },
    {
      "headline": "Caste War of Yucatán",
      "text": "The Caste War of Yucatán was a long-running war that began in 1847 between the Maya people and the European-descended population in the Yucatán Peninsula.",
      "date": "1847"
    },
    {
      "headline": "Modern Maya Population",
      "text": "Today, the Maya people continue to inhabit regions of southern Mexico, Guatemala, Belize, and parts of Honduras and El Salvador, maintaining cultural traditions and languages.",
      "date": "2023"
    }
  ]
}

