  "timeline": [
    {
      "headline": "Introduction of the Ship of the Line",
      "text": "The ship of the line was introduced in the early 17th century as a type of naval warship designed for the line of battle tactic. This tactic involved ships forming two columns to maximize their broadside cannon fire.",
      "date": "1600"
    },
    {
      "headline": "Development of the Line of Battle Tactic",
      "text": "By the mid-17th century, the line of battle tactic became the dominant naval warfare strategy. This tactic required ships to be heavily armed and capable of sustaining prolonged cannon fire.",
      "date": "1650"
    },
    {
      "headline": "Peak of Ship of the Line Construction",
      "text": "During the 18th century, the ship of the line reached its peak in terms of construction and use. Nations like Britain, France, and Spain built large fleets of these powerful warships.",
      "date": "1700"
    },
    {
      "headline": "Battle of Trafalgar",
      "text": "On October 21, 1805, the Battle of Trafalgar took place, where the British Royal Navy, under Admiral Nelson, defeated the combined fleets of France and Spain. This battle demonstrated the effectiveness of the ship of the line in naval warfare.",
      "date": "1805-10-21"
    },
    {
      "headline": "Decline of the Ship of the Line",
      "text": "By the mid-19th century, the ship of the line began to decline in favor of steam-powered ironclad warships, which offered greater speed and protection.",
      "date": "1850"
    },
    {
      "headline": "End of the Ship of the Line Era",
      "text": "The era of the ship of the line effectively ended with the transition to steam-powered ironclads, marking a significant shift in naval warfare technology.",
      "date": "1860"
    }
  ]
}

