    {
      "headline": "Start of Ukraine–NATO Relations",
      "text": "Relations between Ukraine and NATO started in 1991 following Ukraine's independence after the dissolution of the Soviet Union.",
      "date": "1991"
    },
    {
      "headline": "Partnership for Peace Program",
      "text": "In 1994, Ukraine joined NATO's Partnership for Peace program, which aimed to build trust between NATO and other states in Europe and the former Soviet Union.",
      "date": "1994"
    },
    {
      "headline": "Charter on a Distinctive Partnership",
      "text": "On July 9, 1997, Ukraine and NATO signed the Charter on a Distinctive Partnership, establishing the NATO-Ukraine Commission to further develop cooperation.",
      "date": "1997-07-09"
    },
    {
      "headline": "Declaration of Intent to Join NATO",
      "text": "In 2002, Ukraine declared its intention to eventually join NATO, marking a significant step in its foreign policy.",
      "date": "2002"
    },
    {
      "headline": "Intensified Dialogue",
      "text": "In 2005, Ukraine and NATO launched an Intensified Dialogue on membership issues, including reforms required for potential membership.",
      "date": "2005"
    },
    {
      "headline": "Bucharest Summit",
      "text": "During the 2008 Bucharest Summit, NATO declared that Ukraine would eventually become a member of NATO, although no specific timeline was set.",
      "date": "2008"
    },
    {
      "headline": "Russian Annexation of Crimea",
      "text": "In 2014, following Russia's annexation of Crimea, Ukraine's pursuit of NATO membership intensified as part of its security strategy.",
      "date": "2014"
    },
    {
      "headline": "Ukraine's Constitutional Amendment",
      "text": "In February 2019, Ukraine amended its constitution to enshrine its strategic course towards full membership in the European Union and NATO.",
      "date": "2019-02"
    },
    {
      "headline": "NATO Enhanced Opportunities Partner",
      "text": "In June 2020, NATO recognized Ukraine as an Enhanced Opportunities Partner, which provides Ukraine with enhanced access to NATO programs and exercises.",
      "date": "2020-06"
    }
  ]
}

