{
  "timeline": [
    {
      "headline": "Emergence of Slavic Paganism",
      "text": "Slavic paganism began to emerge as the Slavic peoples formed distinct cultural and religious identities. This process likely started around the early centuries CE, as the Slavs settled in Eastern Europe.",
      "date": "0001"
    },
    {
      "headline": "First Historical Mentions",
      "text": "The first historical mentions of the Slavs and their religious practices appear in Byzantine and other historical records around the 6th century CE.",
      "date": "0500"
    },
    {
      "headline": "Slavic Expansion",
      "text": "During the 6th and 7th centuries, the Slavic tribes expanded into the Balkans, Central Europe, and Eastern Europe, spreading their pagan beliefs and practices.",
      "date": "0600"
    },
    {
      "headline": "Christianization of the Slavs Begins",
      "text": "The process of Christianization of the Slavs began in the 8th century, with the first significant conversions occurring in the Western Slavic regions.",
      "date": "0700"
    },
    {
      "headline": "Christianization of the Polabian Slavs",
      "text": "The Polabian Slavs, located in present-day Germany, began to be Christianized in the 9th century, although resistance to conversion persisted.",
      "date": "0800"
    },
    {
      "headline": "Christianization of the Kievan Rus'",
      "text": "The Christianization of Kievan Rus' was a major event in the 10th century, marked by the baptism of Prince Vladimir the Great in 988, who then ordered the Christianization of his people.",
      "date": "0988"
    },
    {
      "headline": "Christianization of the Poles",
      "text": "The Christianization of Poland began in 966 with the baptism of Mieszko I, the first ruler of the Polish state.",
      "date": "0966"
    },
    {
      "headline": "Christianization of the Czech Lands",
      "text": "The Czech lands, including Bohemia and Moravia, were Christianized in the 9th and 10th centuries, with significant influence from the Byzantine and Frankish empires.",
      "date": "0900"
    },
    {
      "headline": "Decline of Slavic Paganism",
      "text": "By the 13th century, most Slavic regions had been Christianized, leading to the decline of Slavic paganism as an organized religion, although some pagan practices and beliefs persisted in folklore and traditions.",
      "date": "1200"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Baker–Fancher Wagon Train Begins Journey",
      "text": "In April 1857, the Baker–Fancher wagon train, consisting mostly of families from Arkansas, began their journey to California. They traveled along the Old Spanish Trail, which passed through the Utah Territory.",
      "date": "1857-04"
    },
    {
      "headline": "Arrival in Utah Territory",
      "text": "By late summer 1857, the Baker–Fancher wagon train arrived in the Utah Territory. Tensions were high due to the Utah War, a conflict between Mormon settlers and the United States government.",
      "date": "1857-08"
    },
    {
      "headline": "Siege of the Wagon Train",
      "text": "On September 7, 1857, the Baker–Fancher wagon train was attacked by a group of Mormon settlers and Southern Paiute Native Americans. The emigrants were besieged for several days.",
      "date": "1857-09-07"
    },
    {
      "headline": "Massacre at Mountain Meadows",
      "text": "On September 11, 1857, the siege culminated in the massacre of at least 120 members of the Baker–Fancher wagon train. The attack was carried out by Mormon settlers and their Native American allies.",
      "date": "1857-09-11"
    },
    {
      "headline": "Aftermath and Investigation",
      "text": "Following the massacre, the incident was initially covered up by local Mormon leaders. It wasn't until 1859 that a federal investigation began, leading to increased scrutiny and eventual trials.",
      "date": "1859"
    },
    {
      "headline": "John D. Lee's Trial and Execution",
      "text": "John D. Lee, a leader in the massacre, was tried and convicted for his role. He was executed by firing squad on March 23, 1877, at the site of the massacre.",
      "date": "1877-03-23"
    }
  ]
}

