{
  "timeline": [
    {
      "headline": "Birth of Jesus",
      "text": "Jesus is believed to have been born between 6 and 4 BCE, based on historical and astronomical data, as well as the Gospel accounts.",
      "date": "-0006"
    },
    {
      "headline": "Visit of the Magi",
      "text": "According to the Gospel of Matthew, the Magi visited Jesus after his birth. This event is traditionally celebrated on Epiphany, January 6.",
      "date": "-0004-01-06"
    },
    {
      "headline": "Flight to Egypt",
      "text": "Joseph, Mary, and Jesus fled to Egypt to escape King Herod's massacre of the infants, as described in the Gospel of Matthew.",
      "date": "-0004"
    },
    {
      "headline": "Return to Nazareth",
      "text": "After the death of King Herod, Jesus's family returned from Egypt and settled in Nazareth, as described in the Gospel of Matthew.",
      "date": "-0004"
    },
    {
      "headline": "Jesus in the Temple",
      "text": "At the age of 12, Jesus was found in the Temple in Jerusalem, discussing with the teachers, as described in the Gospel of Luke.",
      "date": "0006"
    },
    {
      "headline": "Baptism by John the Baptist",
      "text": "Jesus was baptized by John the Baptist in the Jordan River, marking the beginning of his public ministry. This event is estimated to have occurred around 27-29 CE.",
      "date": "0028"
    },
    {
      "headline": "Temptation in the Desert",
      "text": "Following his baptism, Jesus spent 40 days in the desert, where he was tempted by Satan, as described in the Synoptic Gospels.",
      "date": "0028"
    },
    {
      "headline": "Calling of the First Disciples",
      "text": "Jesus began calling his first disciples, including Peter, Andrew, James, and John, as described in the Gospels.",
      "date": "0028"
    },
    {
      "headline": "Sermon on the Mount",
      "text": "Jesus delivered the Sermon on the Mount, which includes the Beatitudes, as recorded in the Gospel of Matthew.",
      "date": "0029"
    },
    {
      "headline": "Transfiguration",
      "text": "Jesus was transfigured on a mountain in the presence of Peter, James, and John, as described in the Synoptic Gospels.",
      "date": "0029"
    },
    {
      "headline": "Triumphal Entry into Jerusalem",
      "text": "Jesus entered Jerusalem riding a donkey, an event celebrated as Palm Sunday, marking the beginning of the Passion Week.",
      "date": "0030-04-02"
    },
    {
      "headline": "Last Supper",
      "text": "Jesus shared the Last Supper with his disciples, instituting the Eucharist, on the night before his crucifixion.",
      "date": "0030-04-06"
    },
    {
      "headline": "Crucifixion",
      "text": "Jesus was crucified under the Roman governor Pontius Pilate. This event is traditionally dated to Friday, April 7, 30 CE.",
      "date": "0030-04-07"
    },
    {
      "headline": "Resurrection",
      "text": "According to Christian belief, Jesus rose from the dead on the third day after his crucifixion, celebrated as Easter Sunday.",
      "date": "0030-04-09"
    },
    {
      "headline": "Ascension",
      "text": "Jesus ascended into heaven 40 days after his resurrection, as described in the Acts of the Apostles.",
      "date": "0030-05-18"
    }
  ]
}

