{
  "timeline": [
    {
      "headline": "Origin of Chondrichthyes",
      "text": "Chondrichthyes, or cartilaginous fish, first appeared in the fossil record during the late Silurian period, approximately 420 million years ago.",
      "date": "-0420"
    },
    {
      "headline": "Diversification in the Devonian",
      "text": "During the Devonian period, around 419 to 359 million years ago, Chondrichthyes underwent significant diversification, leading to the emergence of various forms including early sharks and rays.",
      "date": "-0419"
    },
    {
      "headline": "Evolution of Modern Sharks",
      "text": "By the Carboniferous period, approximately 359 to 299 million years ago, modern shark forms began to evolve, showcasing more advanced features and adaptations.",
      "date": "-0359"
    },
    {
      "headline": "Survival through Mass Extinctions",
      "text": "Chondrichthyes survived several mass extinction events, including the Permian-Triassic extinction around 252 million years ago, which wiped out a significant portion of marine life.",
      "date": "-0252"
    },
    {
      "headline": "Rise of Rays and Skates",
      "text": "During the Jurassic period, approximately 201 to 145 million years ago, rays and skates began to diversify and occupy various ecological niches in marine environments.",
      "date": "-0201"
    },
    {
      "headline": "Cretaceous-Paleogene Extinction",
      "text": "Chondrichthyes, including many shark species, survived the Cretaceous-Paleogene extinction event around 66 million years ago, which led to the extinction of the dinosaurs.",
      "date": "-0066"
    },
    {
      "headline": "Modern Diversity",
      "text": "Today, Chondrichthyes are represented by over 1,000 species of sharks, rays, and chimeras, showcasing a wide range of adaptations and occupying diverse marine habitats.",
      "date": "2023"
    }
  ]
}

