    {
      "headline": "Beginning of the Viking Age",
      "text": "The Viking Age is traditionally marked as beginning in 793 AD with the raid on the Lindisfarne monastery in England by Norsemen. This event signaled the start of Norse expansion and raiding across Europe.",
      "date": "0793"
    },
    {
      "headline": "Norse Settlement in Iceland",
      "text": "Around 874 AD, Norse settlers began to colonize Iceland. This marked the beginning of significant Norse settlement outside of Scandinavia.",
      "date": "0874"
    },
    {
      "headline": "Discovery of Greenland",
      "text": "In 982 AD, Erik the Red, a Norse explorer, discovered Greenland. This led to the establishment of Norse settlements on the island.",
      "date": "0982"
    },
    {
      "headline": "Leif Erikson's Voyage to North America",
      "text": "Around the year 1000 AD, Leif Erikson, a Norse explorer, is believed to have reached the shores of North America, specifically an area he called Vinland, which is thought to be part of modern-day Newfoundland, Canada.",
      "date": "1000"
    },
    {
      "headline": "End of the Viking Age",
      "text": "The Viking Age is generally considered to have ended in 1066 AD with the defeat of the Norwegian King Harald Hardrada at the Battle of Stamford Bridge in England.",
      "date": "1066"
    }
  ]
}

