    {
      "headline": "Design and Development",
      "text": "The Heinkel He 111 was designed by Siegfried and Walter Günter at Heinkel Flugzeugwerke in 1934. It was initially presented as a civil airliner due to restrictions on Germany after World War I, but it was intended to serve as a bomber for the Luftwaffe.",
      "date": "1934"
    },
    {
      "headline": "First Flight",
      "text": "The Heinkel He 111 took its first flight on February 24, 1935. This marked the beginning of its development into one of the most recognizable bombers of World War II.",
      "date": "1935-02-24"
    },
    {
      "headline": "Introduction into Service",
      "text": "The Heinkel He 111 was introduced into service with the Luftwaffe in 1936. It quickly became a key component of Germany's air force.",
      "date": "1936"
    },
    {
      "headline": "Spanish Civil War Deployment",
      "text": "The He 111 saw its first combat during the Spanish Civil War, where it was used by the Condor Legion in support of Francisco Franco's Nationalist forces. This deployment provided valuable combat experience and testing for the aircraft.",
      "date": "1937"
    },
    {
      "headline": "World War II Service",
      "text": "The Heinkel He 111 was extensively used during World War II, participating in major campaigns such as the Battle of Britain and the Blitz. It served as the Luftwaffe's primary medium bomber throughout the war.",
      "date": "1939"
    },
    {
      "headline": "Production Ends",
      "text": "Production of the Heinkel He 111 ended in 1944, as newer bomber designs began to replace it. However, it continued to serve in various roles until the end of the war.",
      "date": "1944"
    },
    {
      "headline": "Post-War Use",
      "text": "After World War II, some He 111s were used by other countries, including Spain, where they were produced under license as the CASA 2.111 until the 1950s.",
      "date": "1945"
    }
  ]
}

