{
  "timeline": [
    {
      "headline": "Establishment of Lydia",
      "text": "Lydia was established as a kingdom in the Iron Age, located in the western part of Asia Minor, in what is now modern-day Turkey. Its capital was Sardis.",
      "date": "-1200"
    },
    {
      "headline": "Reign of King Gyges",
      "text": "King Gyges, the founder of the Mermnad dynasty, began his reign around 687 BCE. He is credited with establishing Lydia as a powerful kingdom.",
      "date": "-0687"
    },
    {
      "headline": "Reign of King Alyattes",
      "text": "King Alyattes ruled Lydia from approximately 610 BCE to 560 BCE. He expanded the kingdom's territory and strengthened its economy.",
      "date": "-0610"
    },
    {
      "headline": "Reign of King Croesus",
      "text": "King Croesus, known for his immense wealth, ruled Lydia from around 595 BCE until his defeat by the Persians in 546 BCE.",
      "date": "-0595"
    },
    {
      "headline": "Conquest by the Achaemenid Empire",
      "text": "In 546 BCE, Lydia was conquered by the Persian king Cyrus the Great, becoming a province of the Achaemenid Empire.",
      "date": "-0546"
    },
    {
      "headline": "Lydia under Persian Rule",
      "text": "After its conquest, Lydia remained an important province within the Achaemenid Empire, contributing to its economy and culture.",
      "date": "-0546"
    },
    {
      "headline": "Alexander the Great's Conquest",
      "text": "In 334 BCE, Alexander the Great conquered Lydia during his campaign against the Persian Empire, incorporating it into his expanding empire.",
      "date": "-0334"
    },
    {
      "headline": "Lydia under the Roman Empire",
      "text": "Following the division of Alexander's empire, Lydia eventually became part of the Roman Empire, continuing to be a significant region in Asia Minor.",
      "date": "-00133"
    }
  ]
}

{
