    },
    {
      "headline": "Rasmussen's Father's Suspicions",
      "text": "Rasmussen's father believed that LAPD officer Stephanie Ilene Lazarus, who was formerly in a relationship with Ruetten, was a prime suspect in the murder.",
      "date": "1986"
    },
    {
      "headline": "Case Reopened",
      "text": "In 2009, the case was reopened and DNA evidence led to the arrest of Stephanie Lazarus.",
      "date": "2009"
    },
    {
      "headline": "Stephanie Lazarus Convicted",
      "text": "In March 2012, Stephanie Lazarus was convicted of the murder of Sherri Rasmussen.",
      "date": "2012-03"
    },
    {
      "headline": "Stephanie Lazarus Sentenced",
      "text": "In May 2012, Stephanie Lazarus was sentenced to 27 years to life in prison for the murder of Sherri Rasmussen.",
      "date": "2012-05"
    }
  ]
}

