{
  "timeline": [
    {
      "headline": "Origin of the Mandate of Heaven",
      "text": "The Mandate of Heaven was first used to support the rule of the Zhou Dynasty, which began around 1046 BCE. The Zhou leaders claimed that they had been granted the Mandate of Heaven to overthrow the Shang Dynasty, which they argued had become corrupt and tyrannical.",
      "date": "-1046"
    },
    {
      "headline": "Zhou Dynasty Establishment",
      "text": "In 1046 BCE, the Zhou Dynasty was established after the defeat of the Shang Dynasty. The Zhou rulers used the Mandate of Heaven to justify their rule and maintain legitimacy.",
      "date": "-1046"
    },
    {
      "headline": "Use During the Warring States Period",
      "text": "During the Warring States period (475–221 BCE), the concept of the Mandate of Heaven was used by various states to justify their claims to power as they vied for control over China.",
      "date": "-0475"
    },
    {
      "headline": "Qin Dynasty and the Mandate",
      "text": "In 221 BCE, the Qin Dynasty unified China and claimed the Mandate of Heaven. The Qin Dynasty's harsh rule led to its downfall, which was interpreted as a loss of the Mandate.",
      "date": "-0221"
    },
    {
      "headline": "Han Dynasty and the Mandate",
      "text": "The Han Dynasty, which began in 206 BCE, also claimed the Mandate of Heaven. The Han rulers emphasized Confucian ideals and used the Mandate to legitimize their rule.",
      "date": "-0206"
    },
    {
      "headline": "Mandate of Heaven in Later Dynasties",
      "text": "Throughout Chinese history, subsequent dynasties such as the Tang, Song, Yuan, Ming, and Qing used the Mandate of Heaven to justify their rule. Each dynasty claimed that the previous one had lost the Mandate due to corruption or failure to govern effectively.",
      "date": "0618"
    },
    {
      "headline": "End of the Imperial System",
      "text": "The concept of the Mandate of Heaven effectively ended with the fall of the Qing Dynasty in 1912, when the last emperor of China abdicated, marking the end of the imperial system.",
      "date": "1912"
    }
  ]
}

