{
  "timeline": [
    {
      "headline": "Foundation of Thebes",
      "text": "Thebes, known to the ancient Egyptians as Waset, was founded as a city along the Nile River. Its exact founding date is unknown, but it became prominent during the Old Kingdom period.",
      "date": "-02680"
    },
    {
      "headline": "Thebes as Capital of Egypt",
      "text": "During the Middle Kingdom (circa 2055–1650 BCE), Thebes became the capital of Egypt. It was a period of great prosperity and architectural development.",
      "date": "-02055"
    },
    {
      "headline": "Thebes in the New Kingdom",
      "text": "Thebes reached its height of power and influence during the New Kingdom (circa 1550–1070 BCE), serving as the religious and political capital of Egypt.",
      "date": "-01550"
    },
    {
      "headline": "Construction of Karnak Temple",
      "text": "The Karnak Temple complex, one of the largest religious buildings ever constructed, was developed over many centuries, starting in the Middle Kingdom and continuing through the New Kingdom.",
      "date": "-02000"
    },
    {
      "headline": "Construction of Luxor Temple",
      "text": "The Luxor Temple was constructed around 1400 BCE, dedicated to the Theban Triad of Amun, Mut, and Khonsu.",
      "date": "-01400"
    },
    {
      "headline": "Theban Revolt Against Hyksos",
      "text": "Around 1550 BCE, Theban rulers led a revolt against the Hyksos, foreign rulers who controlled Lower Egypt, eventually leading to the reunification of Egypt.",
      "date": "-01550"
    },
    {
      "headline": "Thebes Decline",
      "text": "After the New Kingdom, Thebes began to decline in political significance, although it remained a major religious center.",
      "date": "-01070"
    },
    {
      "headline": "Assyrian Sack of Thebes",
      "text": "In 663 BCE, Thebes was sacked by the Assyrian king Ashurbanipal, marking a significant decline in its power and influence.",
      "date": "-0663"
    },
    {
      "headline": "UNESCO World Heritage Site",
      "text": "In 1979, the ruins of ancient Thebes, including the temples of Karnak and Luxor, were designated as a UNESCO World Heritage Site.",
      "date": "1979"
    }
  ]
}

