{
  "timeline": [
    {
      "headline": "Alejandro Jodorowsky Begins Work on Dune",
      "text": "In the mid-1970s, Alejandro Jodorowsky began his ambitious project to adapt Frank Herbert's science fiction novel Dune into a film. He assembled a team of artists and designers, including H.R. Giger, Jean 'Moebius' Giraud, and Chris Foss, to create the visual concept for the movie.",
      "date": "1974"
    },
    {
      "headline": "Pre-Production and Development",
      "text": "Throughout the mid-1970s, Jodorowsky worked on pre-production for Dune, creating a comprehensive storyboard and script. He envisioned a film that would be 10 to 14 hours long and cast notable figures such as Salvador Dalí, Orson Welles, and Mick Jagger.",
      "date": "1975"
    },
    {
      "headline": "Funding Challenges",
      "text": "Despite the creative progress, Jodorowsky faced significant challenges in securing the necessary funding to produce the film. The ambitious scope and length of the project made it difficult to find financial backers.",
      "date": "1976"
    },
    {
      "headline": "Project Abandonment",
      "text": "By the late 1970s, Jodorowsky's Dune project was ultimately abandoned due to insurmountable financial and logistical challenges. The rights to the novel eventually lapsed, and the project was never realized.",
      "date": "1977"
    },
    {
      "headline": "Release of Jodorowsky's Dune Documentary",
      "text": "On May 21, 2013, the documentary film Jodorowsky's Dune, directed by Frank Pavich, premiered at the Cannes Film Festival. The documentary explores Jodorowsky's ambitious attempt to adapt Dune and the impact it had on the science fiction genre.",
      "date": "2013-05-21"
    }
  ]
}

