{
  "timeline": [
    {
      "headline": "Construction of Bletchley Park",
      "text": "The mansion at Bletchley Park was constructed during the years following 1883 for the financier and politician Herbert Leon. It was built in the Victorian Gothic, Tudor, and Dutch Baroque styles.",
      "date": "1883"
    },
    {
      "headline": "Purchase by the British Government",
      "text": "In 1938, the British government purchased Bletchley Park to establish a code-breaking center in anticipation of World War II.",
      "date": "1938"
    },
    {
      "headline": "Establishment of Government Code and Cypher School",
      "text": "In 1939, Bletchley Park became the principal site of the Government Code and Cypher School, where Allied codebreakers worked to decipher Axis communications.",
      "date": "1939"
    },
    {
      "headline": "Breaking of the Enigma Code",
      "text": "In 1941, codebreakers at Bletchley Park, including Alan Turing, successfully broke the German Enigma code, significantly aiding the Allied war effort.",
      "date": "1941"
    },
    {
      "headline": "Development of Colossus",
      "text": "In 1944, the world's first programmable digital electronic computer, Colossus, was developed at Bletchley Park to help break the Lorenz-encrypted (Tunny) messages.",
      "date": "1944"
    },
    {
      "headline": "End of World War II and Closure of Codebreaking Operations",
      "text": "In 1945, with the end of World War II, codebreaking operations at Bletchley Park were wound down.",
      "date": "1945"
    },
    {
      "headline": "Bletchley Park Trust Formation",
      "text": "In 1991, the Bletchley Park Trust was formed to preserve the site and its history.",
      "date": "1991"
    },
    {
      "headline": "Opening as a Museum",
      "text": "In 1993, Bletchley Park was opened to the public as a museum dedicated to its role in World War II codebreaking.",
      "date": "1993"
    }
  ]
}

