    {
      "headline": "Publication of Parkinson's Law",
      "text": "In 1955, C. Northcote Parkinson published an essay in The Economist introducing Parkinson's Law, which states that 'work expands so as to fill the time available for its completion.'",
      "date": "1955"
    },
    {
      "headline": "Expansion of Parkinson's Law",
      "text": "Parkinson's Law was expanded to include the observation that the number of workers within public administration tends to grow, regardless of the amount of work to be done. This was attributed to officials wanting subordinates, not rivals, and making work for each other.",
      "date": "1955"
    },
    {
      "headline": "Publication of Parkinson's Law: The Pursuit of Progress",
      "text": "In 1958, C. Northcote Parkinson published a book titled 'Parkinson's Law: The Pursuit of Progress,' which further elaborated on the concepts introduced in his 1955 essay.",
      "date": "1958"
    }
  ]
}

