{
  "timeline": [
    {
      "headline": "Birth of Dorothy Eady",
      "text": "Dorothy Louise Eady was born on January 16, 1904, in London, England.",
      "date": "1904-01-16"
    },
    {
      "headline": "Accident and First Experience",
      "text": "At the age of three, Dorothy Eady fell down a flight of stairs and was pronounced dead by a doctor. She later revived, and this incident marked the beginning of her lifelong belief in reincarnation and her connection to ancient Egypt.",
      "date": "1907"
    },
    {
      "headline": "First Visit to the British Museum",
      "text": "At the age of four, Dorothy visited the British Museum and became fascinated with the Egyptian galleries, claiming she recognized her 'home' in the exhibits.",
      "date": "1908"
    },
    {
      "headline": "Move to Egypt",
      "text": "In 1933, Dorothy Eady moved to Egypt after marrying an Egyptian man, Eman Abdel Meguid, whom she met in London.",
      "date": "1933"
    },
    {
      "headline": "Birth of Son",
      "text": "Dorothy Eady gave birth to her son, Sety, in 1935, which led to her being known as Omm Sety, meaning 'Mother of Sety'.",
      "date": "1935"
    },
    {
      "headline": "Divorce and Move to Abydos",
      "text": "Dorothy Eady divorced her husband in 1936 and later moved to Abydos, where she began working as a draughtswoman for the Department of Egyptian Antiquities.",
      "date": "1936"
    },
    {
      "headline": "Work at Abydos Temple",
      "text": "Dorothy Eady became the caretaker of the Abydos Temple of Seti I, where she conducted extensive research and contributed significantly to the understanding of the temple's history.",
      "date": "1956"
    },
    {
      "headline": "Death of Dorothy Eady",
      "text": "Dorothy Eady passed away on April 21, 1981, in Abydos, Egypt, leaving behind a legacy of contributions to Egyptology and a fascinating story of reincarnation.",
      "date": "1981-04-21"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Invention of Writing",
      "text": "The earliest known writing systems were developed in the ancient Near East around the end of the 4th millennium BCE. The Sumerians of Mesopotamia created cuneiform script, which is one of the earliest forms of writing.",
      "date": "-03500"
    },
    {
      "headline": "Development of Egyptian Hieroglyphs",
      "text": "Egyptian hieroglyphs were developed around 3200 BCE and were used for religious texts, monumental inscriptions, and administrative documents.",
      "date": "-03200"
    },
    {
      "headline": "Chinese Writing System",
      "text": "The earliest confirmed evidence of the Chinese writing system dates back to the Shang dynasty, around 1200 BCE, with oracle bone script used for divination.",
      "date": "-01200"
    },
    {
      "headline": "Phoenician Alphabet",
      "text": "The Phoenician alphabet, developed around 1050 BCE, is one of the first alphabets and is the ancestor of most modern alphabets, including Greek and Latin.",
      "date": "-01050"
    },
    {
      "headline": "Greek Alphabet",
      "text": "The Greek alphabet was developed around 800 BCE and was the first to include vowels, which made it more versatile than previous writing systems.",
      "date": "-00800"
    },
    {
      "headline": "Latin Alphabet",
      "text": "The Latin alphabet, derived from the Etruscan and Greek alphabets, was developed around 700 BCE and became the basis for the writing systems of many modern languages.",
      "date": "-00700"
    },
    {
      "headline": "Development of Paper",
      "text": "Paper was invented in China around 105 CE by Cai Lun, which revolutionized the way writing was recorded and disseminated.",
      "date": "0105"
    },
    {
      "headline": "Invention of the Printing Press",
      "text": "Johannes Gutenberg invented the movable-type printing press around 1440, which greatly facilitated the spread of written knowledge.",
      "date": "1440"
    },
    {
      "headline": "Development of Typewriters",
      "text": "The first practical typewriter was invented in 1868 by Christopher Latham Sholes, which standardized the QWERTY keyboard layout.",
      "date": "1868"
    },
    {
      "headline": "Digital Word Processing",
      "text": "The development of digital word processing began in the 1960s and 1970s, with the introduction of computers and software that allowed for electronic text creation and editing.",
      "date": "1960"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Establishment of the National Security Council",
      "text": "The United States National Security Council (NSC) was established by the National Security Act of 1947, signed into law by President Harry S. Truman. The act was a major restructuring of the United States government's military and intelligence agencies following World War II.",
      "date": "1947"
    },
    {
      "headline": "First Meeting of the NSC",
      "text": "The first meeting of the National Security Council was held on September 26, 1947. This meeting marked the beginning of the NSC's role in advising the President on national security and foreign policy matters.",
      "date": "1947-09-26"
    },
    {
      "headline": "Reorganization under President Eisenhower",
      "text": "In 1953, President Dwight D. Eisenhower reorganized the NSC to make it a more effective advisory body. He established the position of National Security Advisor and created a more structured process for policy development and decision-making.",
      "date": "1953"
    },
    {
      "headline": "Role during the Cuban Missile Crisis",
      "text": "During the Cuban Missile Crisis in October 1962, the NSC played a crucial role in advising President John F. Kennedy on the United States' response to the Soviet Union's deployment of nuclear missiles in Cuba.",
      "date": "1962-10"
    },
    {
      "headline": "Expansion under President Nixon",
      "text": "President Richard Nixon expanded the role of the NSC in the late 1960s and early 1970s, using it as a central hub for foreign policy decision-making and intelligence coordination.",
      "date": "1969"
    },
    {
      "headline": "Reforms under President Carter",
      "text": "In 1977, President Jimmy Carter implemented reforms to streamline the NSC's operations, emphasizing human rights and arms control in its agenda.",
      "date": "1977"
    },
    {
      "headline": "End of the Cold War",
      "text": "The NSC was instrumental in advising President George H. W. Bush during the end of the Cold War, particularly in managing the United States' response to the dissolution of the Soviet Union in 1991.",
      "date": "1991"
    },
    {
      "headline": "Post-9/11 Reorganization",
      "text": "Following the September 11, 2001 terrorist attacks, the NSC's role was expanded to include a greater focus on counterterrorism and homeland security. The Homeland Security Council was also established to coordinate domestic security efforts.",
      "date": "2001"
    },
    {
      "headline": "Reorganization under President Obama",
      "text": "In 2009, President Barack Obama merged the Homeland Security Council with the NSC to create a more integrated approach to national security and foreign policy.",
      "date": "2009"
    }
  ]
}

