{
  "timeline": [
    {
      "headline": "Initial Migration Out of Africa",
      "text": "Approximately 2 million years ago, Homo erectus began the first known migration out of Africa. This marked the beginning of early human migrations.",
      "date": "-2000000"
    },
    {
      "headline": "Homo Erectus in Asia",
      "text": "By around 1.8 million years ago, Homo erectus had reached Asia, spreading across the continent and establishing populations in various regions.",
      "date": "-1800000"
    },
    {
      "headline": "Homo Heidelbergensis Emergence",
      "text": "Around 500,000 years ago, Homo heidelbergensis emerged. This species is considered a likely ancestor of both Denisovans and Neanderthals, as well as modern humans.",
      "date": "-0500000"
    },
    {
      "headline": "Neanderthals in Europe",
      "text": "Neanderthals, descendants of Homo heidelbergensis, began to inhabit Europe around 400,000 years ago, adapting to the colder climates of the region.",
      "date": "-0400000"
    },
    {
      "headline": "Denisovans in Asia",
      "text": "Denisovans, another group descended from Homo heidelbergensis, were present in Asia around 200,000 years ago, contributing to the genetic makeup of modern humans in the region.",
      "date": "-0200000"
    },
    {
      "headline": "Anatomically Modern Humans Emerge",
      "text": "Anatomically modern humans (Homo sapiens) first appeared in Africa approximately 300,000 years ago, marking a significant development in human evolution.",
      "date": "-0300000"
    },
    {
      "headline": "Out of Africa Migration of Homo Sapiens",
      "text": "Around 70,000 years ago, Homo sapiens began migrating out of Africa, spreading across Asia, Europe, and eventually to other continents.",
      "date": "-0070000"
    },
    {
      "headline": "Homo Sapiens in Australia",
      "text": "By about 65,000 years ago, Homo sapiens had reached Australia, likely using primitive boats to cross the sea.",
      "date": "-0065000"
    },
    {
      "headline": "Homo Sapiens in Europe",
      "text": "Homo sapiens arrived in Europe around 45,000 years ago, where they eventually replaced the Neanderthal populations.",
      "date": "-0045000"
    },
    {
      "headline": "Homo Sapiens in the Americas",
      "text": "The first humans are believed to have arrived in the Americas around 15,000 years ago, likely crossing a land bridge from Siberia to Alaska.",
      "date": "-0015000"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Formation of the Cyclone",
      "text": "The 1970 Bhola cyclone formed over the central Bay of Bengal on November 8, 1970.",
      "date": "1970-11-08"
    },
    {
      "headline": "Cyclone Intensification",
      "text": "The cyclone intensified as it moved northward, reaching its peak intensity on November 11, 1970.",
      "date": "1970-11-11"
    },
    {
      "headline": "Landfall in East Pakistan",
      "text": "The cyclone made landfall on the coast of East Pakistan (now Bangladesh) on November 12, 1970, with winds of up to 115 mph (185 km/h).",
      "date": "1970-11-12"
    },
    {
      "headline": "Devastation in the Ganges Delta",
      "text": "The storm surge caused by the cyclone flooded much of the low-lying islands of the Ganges Delta, leading to the deaths of at least 300,000 people, with some estimates as high as 500,000.",
      "date": "1970-11-12"
    },
    {
      "headline": "Impact on West Bengal, India",
      "text": "The cyclone also affected India's West Bengal, causing significant damage and loss of life.",
      "date": "1970-11-12"
    },
    {
      "headline": "Aftermath and Relief Efforts",
      "text": "In the aftermath of the cyclone, relief efforts were launched, but were criticized for being inadequate and slow, leading to political unrest in East Pakistan.",
      "date": "1970-11"
    },
    {
      "headline": "Political Consequences",
      "text": "The inadequate response to the disaster contributed to political tensions in East Pakistan, which eventually led to the Bangladesh Liberation War and the independence of Bangladesh in 1971.",
      "date": "1971"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "End of World War I",
      "text": "On November 11, 1918, the Armistice of Compiègne was signed, ending World War I. This event marked the cessation of hostilities between the Allies and Germany.",
      "date": "1918-11-11"
    },
    {
      "headline": "German Revolution",
      "text": "The German Revolution of 1918–1919 led to the abdication of Kaiser Wilhelm II and the end of the German Empire. It resulted in the establishment of the Weimar Republic.",
      "date": "1918-1919"
    },
    {
      "headline": "Emergence of the Stab-in-the-back Myth",
      "text": "After the end of World War I, the stab-in-the-back myth emerged in Germany. It claimed that the German Army was betrayed by civilians on the home front, particularly Jews and socialists, rather than defeated on the battlefield.",
      "date": "1918"
    },
    {
      "headline": "Denunciation of the 'November Criminals'",
      "text": "The myth labeled the German politicians who signed the Armistice as the 'November criminals,' accusing them of betraying the nation.",
      "date": "1918"
    },
    {
