{
  "timeline": [
    {
      "headline": "Establishment of Athenian Democracy",
      "text": "Athenian democracy developed around the 6th century BC in the Greek city-state of Athens. It was a system that focused on supporting liberty, equality, and security.",
      "date": "-0600"
    },
    {
      "headline": "Reforms of Solon",
      "text": "In 594 BC, Solon, an Athenian statesman, enacted a series of political and economic reforms that laid the foundation for Athenian democracy. These reforms included the cancellation of debts and the liberation of debt slaves.",
      "date": "-0594"
    },
    {
      "headline": "Reforms of Cleisthenes",
      "text": "In 508/507 BC, Cleisthenes introduced further reforms that reorganized the political structure of Athens, establishing the basis for a more direct form of democracy. He created new tribes and a council of 500 to increase citizen participation.",
      "date": "-0508"
    },
    {
      "headline": "The Age of Pericles",
      "text": "During the mid-5th century BC, under the leadership of Pericles, Athenian democracy reached its height. Pericles expanded the involvement of citizens in government and initiated the construction of the Parthenon.",
      "date": "-0450"
    },
    {
      "headline": "The Peloponnesian War",
      "text": "From 431 to 404 BC, Athens was involved in the Peloponnesian War against Sparta. The war led to significant political and social changes in Athens, including challenges to its democratic system.",
      "date": "-0431"
    },
    {
      "headline": "The Oligarchic Coup of 411 BC",
      "text": "In 411 BC, a group of oligarchs temporarily overthrew the democratic government of Athens, establishing the short-lived oligarchy known as the Four Hundred.",
      "date": "-0411"
    },
    {
      "headline": "Restoration of Democracy",
      "text": "In 410 BC, democracy was restored in Athens after the fall of the oligarchic government of the Four Hundred.",
      "date": "-0410"
    },
    {
      "headline": "The Thirty Tyrants",
      "text": "In 404 BC, following Athens' defeat in the Peloponnesian War, the city was ruled by the Thirty Tyrants, an oligarchic regime that lasted for about a year before democracy was restored.",
      "date": "-0404"
    },
    {
      "headline": "Final Restoration of Democracy",
      "text": "In 403 BC, democracy was finally restored in Athens after the overthrow of the Thirty Tyrants, marking the end of oligarchic rule.",
      "date": "-0403"
    },
    {
      "headline": "Decline of Athenian Democracy",
      "text": "By the late 4th century BC, Athenian democracy began to decline due to internal strife and external pressures, including the rise of Macedonian power under Philip II and Alexander the Great.",
      "date": "-0330"
    }
  ]
}

