    {
      "headline": "World Health Organization's List of Essential Medicines",
      "text": "Sodium thiopental was included in the World Health Organization's List of Essential Medicines, highlighting its importance in medical practice.",
      "date": "1977"
    },
    {
      "headline": "Use in Lethal Injections",
      "text": "Sodium thiopental became the first of three drugs administered during most lethal injections in the United States.",
      "date": "1982"
    },
    {
      "headline": "Hospira Stops Manufacturing",
      "text": "In 2011, the US division of Hospira stopped manufacturing sodium thiopental after objecting to its use in lethal injections.",
      "date": "2011"
    },
    {
      "headline": "European Union Export Ban",
      "text": "The European Union banned the export of sodium thiopental for use in lethal injections, further limiting its availability for this purpose.",
      "date": "2011"
    }
  ]
}

