    {
      "headline": "Discovery of Valproic Acid",
      "text": "Valproic acid, the active ingredient in valproate medications, was first synthesized in 1882 by Beverly S. Burton as an analogue of valeric acid, which is found naturally in the plant Valeriana officinalis.",
      "date": "1882"
    },
    {
      "headline": "Anticonvulsant Properties Discovered",
      "text": "In 1962, Pierre Eymard discovered the anticonvulsant properties of valproic acid while using it as a solvent for other compounds being tested for anti-seizure activity.",
      "date": "1962"
    },
    {
      "headline": "Introduction to Market",
      "text": "Valproic acid was first marketed in France in 1967 as an anti-seizure medication under the brand name Depakine.",
      "date": "1967"
    },
    {
      "headline": "FDA Approval in the United States",
      "text": "The U.S. Food and Drug Administration (FDA) approved valproic acid for use in the United States in 1978.",
      "date": "1978"
    },
    {
      "headline": "Approval for Bipolar Disorder",
      "text": "Valproate was approved for the treatment of bipolar disorder in the United States in 1995.",
      "date": "1995"
    },
    {
      "headline": "Approval for Migraine Prevention",
      "text": "In 1996, valproate was approved by the FDA for the prevention of migraine headaches.",
      "date": "1996"
    },
