{
  "timeline": [
    {
      "headline": "First Human Settlement",
      "text": "Matera's history of continuous occupation dates back to the Palaeolithic era, making it one of the oldest continuously inhabited cities in the world.",
      "date": "-10000"
    },
    {
      "headline": "Neolithic Period",
      "text": "During the Neolithic period, Matera saw the development of its first rock-cut settlements, which laid the foundation for its unique urban structure.",
      "date": "-06000"
    },
    {
      "headline": "Roman Era",
      "text": "Matera became part of the Roman Empire, during which time it was known as Matheola, and saw the construction of infrastructure typical of Roman towns.",
      "date": "-00300"
    },
    {
      "headline": "Lombard Rule",
      "text": "In the 7th century, Matera came under the control of the Lombards, who integrated it into the Duchy of Benevento.",
      "date": "0600"
    },
    {
      "headline": "Norman Conquest",
      "text": "In the 11th century, Matera was conquered by the Normans, who fortified the city and established it as a strategic stronghold.",
      "date": "1060"
    },
    {
      "headline": "Sassi di Matera Development",
      "text": "By the late Middle Ages, the Sassi di Matera, the city's famous rock-cut dwellings, had developed into a complex urban environment.",
      "date": "1400"
    },
    {
      "headline": "Kingdom of Naples",
      "text": "Matera became part of the Kingdom of Naples in the 15th century, experiencing economic and cultural growth.",
      "date": "1442"
    },
    {
      "headline": "Italian Unification",
      "text": "Matera became part of the newly unified Kingdom of Italy in 1861, following the unification process led by figures like Giuseppe Garibaldi.",
      "date": "1861"
    },
    {
      "headline": "World War II and Post-War Period",
      "text": "During World War II, Matera was the first Italian city to rise against German occupation in 1943. Post-war, the Sassi were declared a national disgrace due to poor living conditions.",
      "date": "1943"
    },
    {
      "headline": "Sassi Evacuation and Restoration",
      "text": "In the 1950s, the Italian government evacuated the Sassi due to unsanitary conditions, leading to restoration efforts in the late 20th century.",
      "date": "1952"
    },
    {
      "headline": "UNESCO World Heritage Site",
      "text": "In 1993, the Sassi di Matera were designated a UNESCO World Heritage Site, recognizing their historical and cultural significance.",
      "date": "1993"
    },
    {
      "headline": "European Capital of Culture",
      "text": "Matera was named a European Capital of Culture for 2019, highlighting its rich history and cultural heritage.",
      "date": "2019"
    }
  ]
}

