{
  "timeline": [
    {
      "headline": "Birth of Ibn Taymiyya",
      "text": "Ibn Taymiyya was born on January 22, 1263, in Harran, which is now in modern-day Turkey.",
      "date": "1263-01-22"
    },
    {
      "headline": "Migration to Damascus",
      "text": "In 1269, due to the Mongol invasions, Ibn Taymiyya's family moved from Harran to Damascus, where he would spend much of his life.",
      "date": "1269"
    },
    {
      "headline": "Completion of Education",
      "text": "By 1282, Ibn Taymiyya had completed his education in Islamic jurisprudence, theology, and philosophy, becoming a prominent scholar in Damascus.",
      "date": "1282"
    },
    {
      "headline": "First Imprisonment",
      "text": "In 1293, Ibn Taymiyya was imprisoned for the first time due to his controversial religious views and criticisms of certain Islamic practices.",
      "date": "1293"
    },
    {
      "headline": "Diplomatic Mission to Ghazan Khan",
      "text": "In 1303, Ibn Taymiyya participated in a diplomatic mission to the Ilkhanid ruler Ghazan Khan, during the Battle of Marj al-Saffar, which ended the Mongol invasions of the Levant.",
      "date": "1303"
    },
    {
      "headline": "Second Imprisonment",
      "text": "In 1306, Ibn Taymiyya was imprisoned again due to his outspoken views against certain Sufi practices and his criticism of saint veneration.",
      "date": "1306"
    },
    {
      "headline": "Final Imprisonment",
      "text": "Ibn Taymiyya was imprisoned for the last time in 1326 in the Citadel of Damascus, where he continued to write until his death.",
      "date": "1326"
    },
    {
      "headline": "Death of Ibn Taymiyya",
      "text": "Ibn Taymiyya died on September 26, 1328, in the Citadel of Damascus, where he had been imprisoned.",
      "date": "1328-09-26"
    }
  ]
}

