{
  "timeline": [
    {
      "headline": "Homo antecessor",
      "text": "Homo antecessor lived approximately between 1.2 million and 770,000 years ago. They are considered one of the earliest known archaic human species, with fossils found in the Atapuerca Mountains in Spain.",
      "date": "-1200000"
    },
    {
      "headline": "Homo heidelbergensis",
      "text": "Homo heidelbergensis existed around 600,000 to 200,000 years ago. They are believed to be the common ancestor of both Neanderthals and modern humans, with fossils discovered in Europe, Africa, and possibly Asia.",
      "date": "-0600000"
    },
    {
      "headline": "Homo bodoensis",
      "text": "Homo bodoensis lived approximately between 600,000 and 300,000 years ago. This species is known from fossils found in Africa and is considered a direct ancestor of modern humans.",
      "date": "-0600000"
    },
    {
      "headline": "Homo rhodesiensis",
      "text": "Homo rhodesiensis lived approximately between 300,000 and 125,000 years ago. Fossils attributed to this species have been found in Africa, and they are considered closely related to Homo heidelbergensis.",
      "date": "-0300000"
    },
    {
      "headline": "Neanderthals",
      "text": "Neanderthals, or Homo neanderthalensis, lived approximately between 400,000 and 40,000 years ago. They inhabited Europe and parts of western Asia and are known for their robust build and adaptation to cold climates.",
      "date": "-0400000"
    },
    {
      "headline": "Denisovans",
      "text": "Denisovans are an extinct species or subspecies of archaic humans that lived in Asia. They are known primarily from genetic evidence and a few fossil remains, dating from around 160,000 to 30,000 years ago.",
      "date": "-0160000"
    },
    {
      "headline": "Jebel Irhoud Fossils",
      "text": "The Jebel Irhoud fossils, discovered in Morocco, are among the earliest known remains of modern humans, dating back to approximately 300,000 years ago.",
      "date": "-0300000"
    },
    {
      "headline": "Florisbad Skull",
      "text": "The Florisbad Skull, found in South Africa, is an early modern human fossil dated to around 259,000 years ago.",
      "date": "-0259000"
    },
    {
      "headline": "Omo-Kibish I",
      "text": "Omo-Kibish I, discovered in southern Ethiopia, is one of the oldest known anatomically modern human fossils, dating to approximately 195,000 years ago.",
      "date": "-0195000"
    },
    {
      "headline": "Apidima Cave Fossils",
      "text": "The Apidima Cave fossils in Southern Greece include a skull that has been dated to around 210,000 years ago, representing one of the earliest known Homo sapiens in Europe.",
      "date": "-0210000"
    }
  ]
}

