      "headline": "Foundation of the Ottoman Dynasty",
      "text": "The Ottoman dynasty was founded by Osman I, who established the dynasty's rule in northwestern Anatolia around the district of Bilecik, Söğüt. This marked the beginning of the Ottoman Empire, traditionally dated to 1299.",
      "date": "1299"
    },
    {
      "headline": "Osman I's Reign",
      "text": "Osman I, the founder of the Ottoman dynasty, ruled from approximately 1299 until his death in 1323 or 1324. He is credited with laying the foundations of the Ottoman Empire.",
      "date": "1323"
    },
    {
      "headline": "Reign of Orhan",
      "text": "Orhan, the son of Osman I, succeeded his father and ruled from 1323 or 1324 until 1362. He expanded the empire's territories into the Balkans.",
      "date": "1324"
    },
    {
      "headline": "Conquest of Constantinople",
      "text": "Under Sultan Mehmed II, the Ottomans conquered Constantinople on May 29, 1453, marking the end of the Byzantine Empire and establishing the city as the new capital of the Ottoman Empire.",
      "date": "1453-05-29"
    },
    {
      "headline": "Suleiman the Magnificent's Reign",
      "text": "Suleiman the Magnificent ruled from 1520 to 1566, during which the Ottoman Empire reached its peak in terms of territorial expansion, economic strength, and cultural achievements.",
      "date": "1520"
    },
    {
      "headline": "Dissolution of the Ottoman Empire",
      "text": "The Ottoman Empire officially ended on November 1, 1922, when the Sultanate was abolished by the Grand National Assembly of Turkey, marking the end of the Ottoman dynasty's rule.",
      "date": "1922-11-01"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Edwin Hubble's Discovery",
      "text": "In 1929, Edwin Hubble published his observations that galaxies are moving away from Earth at speeds proportional to their distance. This discovery was based on the redshift measurements of galaxies.",
      "date": "1929"
    },
    {
      "headline": "Formulation of Hubble's Law",
      "text": "Hubble's observations led to the formulation of Hubble's Law, which states that the velocity of a galaxy moving away from us is proportional to its distance from us. This was a groundbreaking discovery in the field of cosmology.",
      "date": "1929"
    },
    {
      "headline": "Georges Lemaître's Contribution",
      "text": "In 1927, two years before Hubble's publication, Belgian astronomer Georges Lemaître had already derived the relationship between the distance of galaxies and their recessional velocity, which was later recognized as part of Hubble's Law.",
      "date": "1927"
    },
    {
      "headline": "Recognition of Lemaître's Work",
      "text": "In 2018, the International Astronomical Union voted to recommend that the law be known as the Hubble–Lemaître law, acknowledging Lemaître's earlier work.",
      "date": "2018"
    }
  ]
}

