{
  "timeline": [
    {
      "headline": "First College Basketball Game",
      "text": "The first recorded college basketball game was played on January 18, 1896, between the University of Iowa and the University of Chicago. The game was played in Iowa City, Iowa, and the University of Chicago won 15-12.",
      "date": "1896-01-18"
    },
    {
      "headline": "Formation of NCAA",
      "text": "The National Collegiate Athletic Association (NCAA) was founded on March 31, 1906, to regulate college athletics and ensure fair play.",
      "date": "1906-03-31"
    },
    {
      "headline": "First NCAA Men's Basketball Tournament",
      "text": "The first NCAA Men's Basketball Tournament was held in 1939. The University of Oregon defeated Ohio State University 46-33 to win the inaugural championship.",
      "date": "1939"
    },
    {
      "headline": "Introduction of the Shot Clock",
      "text": "The NCAA introduced the shot clock in men's basketball in 1985 to increase the pace of the game. Initially set at 45 seconds, it was later reduced to 35 seconds in 1993 and then to 30 seconds in 2015.",
      "date": "1985"
    },
    {
      "headline": "First NCAA Women's Basketball Tournament",
      "text": "The first NCAA Women's Basketball Tournament was held in 1982. Louisiana Tech University won the championship by defeating Cheyney University 76-62.",
      "date": "1982"
    },
    {
      "headline": "Three-Point Line Introduced",
      "text": "The NCAA introduced the three-point line in men's basketball for the 1986-87 season, adding a new strategic element to the game.",
      "date": "1986"
    },
    {
      "headline": "NCAA Division I Men's Basketball Tournament Expansion",
      "text": "The NCAA Division I Men's Basketball Tournament expanded to 64 teams in 1985, allowing more teams to compete in the national championship.",
      "date": "1985"
    },
    {
      "headline": "NCAA Division I Women's Basketball Tournament Expansion",
      "text": "The NCAA Division I Women's Basketball Tournament expanded to 64 teams in 1994, mirroring the men's tournament format.",
      "date": "1994"
    }
  ]
}

