    {
      "headline": "Construction of Al-Masjid al-Nabawi",
      "text": "The original mosque was built by the Islamic prophet Muhammad in 622 CE in Medina. It was a simple structure at the time.",
      "date": "0622"
    },
    {
      "headline": "Death of Prophet Muhammad",
      "text": "Prophet Muhammad passed away on June 8, 632 CE, and was buried in the chamber of his wife Aisha, which later became part of the mosque.",
      "date": "0632-06-08"
    },
    {
      "headline": "Burial of Abu Bakr",
      "text": "Abu Bakr, the first Rashidun Caliph, died in 634 CE and was buried next to Prophet Muhammad in the chamber.",
      "date": "0634"
    },
    {
      "headline": "Burial of Umar",
      "text": "Umar, the second Rashidun Caliph, was assassinated in 644 CE and was buried alongside Prophet Muhammad and Abu Bakr.",
      "date": "0644"
    },
    {
      "headline": "First Dome Construction",
      "text": "The first dome over the tomb was constructed in 1279 CE during the reign of Mamluk Sultan Al-Mansur Qalawun.",
      "date": "1279"
    },
    {
      "headline": "Reconstruction and Green Painting",
      "text": "The dome was rebuilt and painted green in 1837 CE during the reign of Ottoman Sultan Mahmud II, giving it the name 'Green Dome'.",
      "date": "1837"
    },
    {
      "headline": "Modern Renovations",
      "text": "The mosque, including the Green Dome, has undergone several renovations and expansions in the 20th and 21st centuries to accommodate the growing number of pilgrims.",
      "date": "1900-2000"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Foundation of the House of Oldenburg",
      "text": "The House of Oldenburg was founded in the early 12th century by Count Elimar I of Oldenburg, who ruled from 1101 to 1108.",
      "date": "1101"
    },
    {
      "headline": "Ascension to the Danish Throne",
      "text": "In 1448, Christian I of the House of Oldenburg became King of Denmark, marking the beginning of the Oldenburg dynasty's rule in Denmark.",
      "date": "1448"
    },
    {
      "headline": "Union of Denmark and Norway",
      "text": "In 1450, Christian I also became King of Norway, uniting the two kingdoms under the Oldenburg dynasty.",
      "date": "1450"
    },
    {
      "headline": "Acquisition of the Swedish Throne",
      "text": "In 1457, Christian I was elected King of Sweden, although the union was short-lived and ended in 1464.",
      "date": "1457"
    },
    {
      "headline": "Establishment of the Duchy of Schleswig and Holstein",
      "text": "In 1460, Christian I became Duke of Schleswig and Holstein, further expanding the influence of the House of Oldenburg.",
      "date": "1460"
    },
    {
      "headline": "Reign of Frederick I of Denmark and Norway",
      "text": "Frederick I, a member of the House of Oldenburg, reigned as King of Denmark and Norway from 1523 to 1533.",
      "date": "1523"
    },
    {
      "headline": "Reign of Christian IV of Denmark and Norway",
      "text": "Christian IV, one of the most famous kings of the House of Oldenburg, reigned from 1588 to 1648 and was known for his efforts in strengthening the Danish state.",
      "date": "1588"
    },
    {
      "headline": "Glücksburg Branch Ascends to the Greek Throne",
      "text": "In 1863, Prince William of Denmark, of the Glücksburg branch of the House of Oldenburg, became King George I of Greece.",
      "date": "1863"
    },
    {
      "headline": "Glücksburg Branch Ascends to the Norwegian Throne",
      "text": "In 1905, Prince Carl of Denmark, of the Glücksburg branch, became King Haakon VII of Norway.",
      "date": "1905"
    },
    {
      "headline": "Glücksburg Branch Ascends to the British Throne",
      "text": "In 2022, King Charles III, a member of the Glücksburg branch of the House of Oldenburg, ascended to the British throne.",
      "date": "2022"
    }
  ]
}

