{
  "timeline": [
    {
      "headline": "Founding of Schweppes",
      "text": "Schweppes was founded in 1783 by Johann Jacob Schweppe in the Republic of Geneva. It was one of the earliest forms of a soft drink, originally being regular soda water.",
      "date": "1783"
    },
    {
      "headline": "Introduction of Carbonated Water",
      "text": "In 1783, Johann Jacob Schweppe developed a process to manufacture carbonated mineral water, which became the basis for the Schweppes brand.",
      "date": "1783"
    },
    {
      "headline": "Relocation to London",
      "text": "In 1792, Johann Jacob Schweppe moved to London to further develop and market his carbonated water.",
      "date": "1792"
    },
    {
      "headline": "Royal Warrant",
      "text": "In 1836, Schweppes was granted a Royal Warrant, marking its recognition and endorsement by the British royal family.",
      "date": "1836"
    },
    {
      "headline": "Introduction of Tonic Water",
      "text": "In 1870, Schweppes introduced tonic water, which became popular as a mixer for gin.",
      "date": "1870"
    },
    {
      "headline": "Expansion of Product Line",
      "text": "Throughout the late 19th and early 20th centuries, Schweppes expanded its product line to include various types of lemonade and ginger ales.",
      "date": "1900"
    },
    {
      "headline": "Acquisition by Cadbury",
      "text": "In 1969, Schweppes merged with Cadbury to form Cadbury Schweppes, expanding its reach and product offerings.",
      "date": "1969"
    },
    {
      "headline": "Separation from Cadbury",
      "text": "In 2008, Cadbury Schweppes separated its beverage and confectionery businesses, leading to the creation of Dr Pepper Snapple Group, which took over the beverage operations.",
      "date": "2008"
    },
    {
      "headline": "Acquisition by Keurig Dr Pepper",
      "text": "In 2018, Dr Pepper Snapple Group merged with Keurig Green Mountain to form Keurig Dr Pepper, which now manages the Schweppes brand in the United States.",
      "date": "2018"
    }
  ]
}

