{
  "timeline": [
    {
      "headline": "Start of Krita (Satya) Yuga",
      "text": "The Krita Yuga, also known as Satya Yuga, is the first of the four Yugas in a Yuga Cycle. It is considered the age of truth and perfection, lasting for 1,728,000 years.",
      "date": "-4320000"
    },
    {
      "headline": "End of Krita (Satya) Yuga",
      "text": "The Krita Yuga ends after 1,728,000 years, marking the transition to the next Yuga in the cycle.",
      "date": "-2592000"
    },
    {
      "headline": "Start of Treta Yuga",
      "text": "The Treta Yuga is the second Yuga in the cycle, characterized by a decline in virtue compared to the Krita Yuga. It lasts for 1,296,000 years.",
      "date": "-2592000"
    },
    {
      "headline": "End of Treta Yuga",
      "text": "The Treta Yuga ends after 1,296,000 years, leading to the beginning of the Dvapara Yuga.",
      "date": "-1296000"
    },
    {
      "headline": "Start of Dvapara Yuga",
      "text": "The Dvapara Yuga is the third Yuga in the cycle, marked by further decline in virtue and righteousness. It lasts for 864,000 years.",
      "date": "-1296000"
    },
    {
      "headline": "End of Dvapara Yuga",
      "text": "The Dvapara Yuga concludes after 864,000 years, transitioning into the Kali Yuga.",
      "date": "-432000"
    },
    {
      "headline": "Start of Kali Yuga",
      "text": "The Kali Yuga is the fourth and final Yuga in the cycle, known for its moral and spiritual decline. It is the shortest Yuga, lasting for 432,000 years.",
      "date": "-432000"
    },
    {
      "headline": "End of Kali Yuga",
      "text": "The Kali Yuga will end after 432,000 years, completing the Yuga Cycle and leading to the start of a new Krita (Satya) Yuga.",
      "date": "0000"
    }
  ]
}

