    },
    {
      "headline": "Death of Tollund Man",
      "text": "The Tollund Man died during the 5th century BCE. His death is believed to have been a ritual sacrifice, as he was found with a noose around his neck.",
      "date": "-0400"
    },
    {
      "headline": "Discovery of Tollund Man",
      "text": "On May 6, 1950, the Tollund Man was discovered in a peat bog near Silkeborg on the Jutland peninsula in Denmark. His body was so well preserved that he was initially mistaken for a recent murder victim.",
      "date": "1950-05-06"
    },
    {
      "headline": "Comparison with Elling Woman",
      "text": "Twelve years before the discovery of the Tollund Man, another bog body, known as the Elling Woman, was found in the same bog. This discovery provided context and comparison for the Tollund Man's preservation and circumstances of death.",
      "date": "1938"
    }
  ]
}

