    {
      "headline": "Early Christian Nontrinitarianism",
      "text": "Nontrinitarian beliefs can be traced back to the early Christian era, with groups such as the Ebionites and Arians rejecting the doctrine of the Trinity. Arius, a priest in Alexandria, was a notable early proponent of nontrinitarianism in the early 4th century.",
      "date": "0300"
    },
    {
      "headline": "Council of Nicaea",
      "text": "In 325, the First Council of Nicaea was convened by Emperor Constantine to address the Arian controversy. The council resulted in the Nicene Creed, which affirmed the Trinitarian view and condemned Arianism as heretical.",
      "date": "0325"
    },
    {
      "headline": "Reformation and Rise of Antitrinitarianism",
      "text": "During the Protestant Reformation in the 16th century, various groups began to question traditional doctrines, including the Trinity. Figures like Michael Servetus and groups such as the Polish Brethren and Socinians emerged, advocating for nontrinitarian beliefs.",
      "date": "1500"
    },
    {
      "headline": "Execution of Michael Servetus",
      "text": "In 1553, Michael Servetus, a Spanish physician and theologian, was executed in Geneva for his anti-Trinitarian views, marking a significant event in the history of nontrinitarianism.",
      "date": "1553"
    },
    {
      "headline": "Formation of the Unitarian Church",
      "text": "In the late 16th and early 17th centuries, Unitarian churches began to form in Poland and Transylvania, promoting nontrinitarian theology and religious tolerance.",
      "date": "1600"
    },
    {
      "headline": "Establishment of the American Unitarian Association",
      "text": "In 1825, the American Unitarian Association was established in Boston, Massachusetts, marking the formal organization of Unitarianism in the United States.",
      "date": "1825"
    },
    {
      "headline": "Formation of the Jehovah's Witnesses",
      "text": "In the late 19th century, Charles Taze Russell founded the Bible Student movement, which later evolved into the Jehovah's Witnesses, a group known for its nontrinitarian beliefs.",
      "date": "1870"
    },
    {
      "headline": "Unitarian Universalist Association",
      "text": "In 1961, the Unitarian Church merged with the Universalist Church of America to form the Unitarian Universalist Association, continuing the tradition of nontrinitarianism within a broader religious framework.",
      "date": "1961"
    }
  ]
}

