      "date": "-1200"
    },
    {
      "headline": "Victory over the Midianites",
      "text": "Gideon led a small army of 300 men to defeat the Midianites, as recounted in Judges 7. This victory was achieved through a surprise night attack, using trumpets and torches to create confusion among the enemy.",
      "date": "-1200"
    },
