  "timeline": [
    {
      "headline": "Foundation of the Latin Empire",
      "text": "The Latin Empire was established in April 1204 following the capture of Constantinople by the Fourth Crusade. It was intended to replace the Byzantine Empire with a Western-recognized Roman Empire in the east.",
      "date": "1204-04"
    },
    {
      "headline": "Coronation of Baldwin I",
      "text": "Baldwin I was crowned the first Latin Emperor of Constantinople on May 16, 1204. He was a leader of the Fourth Crusade and played a significant role in the establishment of the Latin Empire.",
      "date": "1204-05-16"
    },
    {
      "headline": "Battle of Adrianople",
      "text": "On April 14, 1205, the Latin Empire suffered a major defeat at the Battle of Adrianople against the Bulgarians, which weakened its military strength significantly.",
      "date": "1205-04-14"
    },
    {
      "headline": "Death of Baldwin I",
      "text": "Baldwin I died in captivity in 1205 after being captured by the Bulgarians following the Battle of Adrianople.",
      "date": "1205"
    },
    {
      "headline": "Reign of Henry of Flanders",
      "text": "Henry of Flanders, brother of Baldwin I, became the Latin Emperor in 1206 and ruled until his death in 1216. His reign was marked by efforts to consolidate the empire's territories.",
      "date": "1206"
    },
    {
      "headline": "Death of Henry of Flanders",
      "text": "Henry of Flanders died on June 11, 1216, leading to a succession crisis in the Latin Empire.",
      "date": "1216-06-11"
    },
    {
      "headline": "Reign of Peter II of Courtenay",
      "text": "Peter II of Courtenay was elected as the Latin Emperor in 1217, but he never reached Constantinople as he was captured and died in captivity.",
      "date": "1217"
    },
    {
      "headline": "Reign of Robert of Courtenay",
      "text": "Robert of Courtenay, son of Peter II, became the Latin Emperor in 1221 and ruled until 1228. His reign was marked by internal strife and territorial losses.",
      "date": "1221"
    },
    {
      "headline": "Reign of Baldwin II",
      "text": "Baldwin II became the Latin Emperor in 1228 at a young age. His reign was characterized by attempts to secure financial and military support for the struggling empire.",
      "date": "1228"
    },
    {
      "headline": "Fall of the Latin Empire",
      "text": "The Latin Empire fell on July 25, 1261, when the Byzantine forces recaptured Constantinople, effectively ending the Latin rule.",
      "date": "1261-07-25"
    }
  ]
}

