    {
      "headline": "Start of the Second French Intervention in Mexico",
      "text": "In 1861, the French Empire, under Napoleon III, initiated a military invasion of Mexico, purportedly to collect debts owed by Mexico. This marked the beginning of the Second French Intervention in Mexico.",
      "date": "1861"
    },
    {
      "headline": "Formation of the Tripartite Alliance",
      "text": "In 1861, France, Great Britain, and Spain formed a tripartite alliance to intervene in Mexico, initially to collect debts.",
      "date": "1861"
    },
    {
      "headline": "Withdrawal of British and Spanish Forces",
      "text": "In 1862, both Great Britain and Spain withdrew their forces from Mexico, leaving France to continue the intervention alone.",
      "date": "1862"
    },
    {
      "headline": "Battle of Puebla",
      "text": "On May 5, 1862, Mexican forces achieved a significant victory against the French at the Battle of Puebla, celebrated annually as Cinco de Mayo.",
      "date": "1862-05-05"
    },
    {
      "headline": "Capture of Mexico City",
      "text": "In June 1863, French forces captured Mexico City, leading to the establishment of a French-backed monarchy in Mexico.",
      "date": "1863-06"
    },
    {
      "headline": "Establishment of the Second Mexican Empire",
      "text": "In 1864, Archduke Maximilian of Austria was installed as Emperor of Mexico, establishing the Second Mexican Empire.",
      "date": "1864"
    },
    {
      "headline": "End of the American Civil War",
      "text": "In 1865, the American Civil War ended, allowing the United States to provide material aid to Mexican Republicans fighting against the French-backed regime.",
      "date": "1865"
    },
    {
      "headline": "Withdrawal of French Troops",
      "text": "In 1866, Napoleon III decided to withdraw French military support from Mexico, significantly weakening Maximilian's regime.",
      "date": "1866"
    },
    {
      "headline": "Collapse of the Second Mexican Empire",
      "text": "In 1867, the Second Mexican Empire collapsed as Republican forces regained control of Mexico.",
      "date": "1867"
    },
    {
      "headline": "Execution of Maximilian",
      "text": "On June 19, 1867, Emperor Maximilian and two Mexican generals were executed by firing squad, marking the definitive end of the Second Mexican Empire.",
      "date": "1867-06-19"
    }
  ]
}

