{
  "timeline": [
    {
      "headline": "South Carolina Secedes from the Union",
      "text": "On December 20, 1860, South Carolina became the first state to secede from the United States, setting the stage for the conflict at Fort Sumter.",
      "date": "1860-12-20"
    },
    {
      "headline": "Major Robert Anderson Occupies Fort Sumter",
      "text": "On December 26, 1860, Major Robert Anderson of the United States Army moved his garrison from Fort Moultrie to the more defensible Fort Sumter in Charleston Harbor.",
      "date": "1860-12-26"
    },
    {
      "headline": "South Carolina Demands Surrender of Fort Sumter",
      "text": "In January 1861, South Carolina authorities demanded the surrender of Fort Sumter, which Major Anderson refused.",
      "date": "1861-01"
    },
    {
      "headline": "Star of the West Incident",
      "text": "On January 9, 1861, the civilian ship Star of the West attempted to resupply Fort Sumter but was fired upon by South Carolina forces, forcing it to retreat.",
      "date": "1861-01-09"
    },
    {
      "headline": "Confederate Forces Begin Bombardment",
      "text": "On April 12, 1861, at 4:30 a.m., Confederate forces under General P.G.T. Beauregard opened fire on Fort Sumter, marking the beginning of the Battle of Fort Sumter.",
      "date": "1861-04-12"
    },
    {
      "headline": "Fort Sumter Surrenders",
      "text": "On April 13, 1861, after 34 hours of bombardment, Major Robert Anderson agreed to evacuate Fort Sumter, surrendering it to Confederate forces.",
      "date": "1861-04-13"
    },
    {
      "headline": "Evacuation of Fort Sumter",
      "text": "On April 14, 1861, Major Anderson and his men evacuated Fort Sumter, and the Confederate forces took control of the fort.",
      "date": "1861-04-14"
    },
    {
      "headline": "Lincoln Calls for Troops",
      "text": "On April 15, 1861, President Abraham Lincoln called for 75,000 volunteers to suppress the rebellion, marking the official start of the American Civil War.",
      "date": "1861-04-15"
    }
  ]
