    },
    {
      "headline": "Treaty of Waitangi Signed",
      "text": "On February 6, 1840, the Treaty of Waitangi was signed between representatives of the British Crown and various Māori chiefs, establishing British sovereignty over New Zealand.",
      "date": "1840-02-06"
