    {
      "headline": "New Zealand Becomes a British Colony",
      "text": "In 1841, New Zealand was declared a British colony, separating it from New South Wales and establishing its own colonial government.",
      "date": "1841"
    },
    {
      "headline": "New Zealand Wars",
      "text": "From 1845 to 1872, a series of conflicts known as the New Zealand Wars took place between the colonial government and various Māori groups over land and sovereignty.",
      "date": "1845"
    },
    {
      "headline": "Women's Suffrage Achieved",
      "text": "In 1893, New Zealand became the first self-governing country to grant women the right to vote, a significant milestone in its history.",
      "date": "1893"
    },
    {
      "headline": "Statute of Westminster Adoption",
      "text": "In 1947, New Zealand adopted the Statute of Westminster, gaining full legislative independence from the United Kingdom.",
      "date": "1947"
    },
    {
      "headline": "Waitangi Tribunal Established",
      "text": "In 1975, the Waitangi Tribunal was established to address grievances related to the Treaty of Waitangi, providing a legal framework for Māori claims.",
      "date": "1975"
    },
    {
      "headline": "Māori Language Act Passed",
      "text": "In 1987, the Māori Language Act was passed, recognizing Māori as an official language of New Zealand and promoting its revitalization.",
      "date": "1987"
