    {
      "headline": "Federal Reserve Act",
      "text": "The Federal Reserve Act of 1913 established the Federal Reserve System and authorized the issuance of Federal Reserve Notes, including large denominations.",
      "date": "1913"
    },
    {
      "headline": "Series of 1918",
      "text": "The Series of 1918 included the issuance of $500, $1,000, $5,000, and $10,000 Federal Reserve Notes.",
      "date": "1918"
    },
    {
      "headline": "Series of 1928",
      "text": "The Series of 1928 introduced smaller-sized currency notes, including large denominations, to standardize the size of U.S. currency.",
      "date": "1928"
    },
    {
      "headline": "Discontinuation of Large Denominations",
      "text": "In 1969, the United States Treasury and the Federal Reserve discontinued the issuance of large denominations greater than $100 due to lack of use.",
      "date": "1969"
    },
    {
      "headline": "Official Withdrawal",
      "text": "In 1969, President Richard Nixon issued an executive order to officially withdraw large denominations from circulation to combat organized crime.",
      "date": "1969"
    }
  ]
}

