{
  "timeline": [
    {
      "headline": "Beginning of the Jōmon Period",
      "text": "The Jōmon period began around 14,000 BCE, marking the time when Japan was inhabited by a diverse hunter-gatherer population. This period is characterized by the development of pottery, which is among the oldest in the world.",
      "date": "-14000"
    },
    {
      "headline": "Development of Jōmon Pottery",
      "text": "Around 10,500 BCE, the Jōmon people began creating pottery decorated with cord-marked patterns. This pottery style is a defining feature of the Jōmon culture and reflects the early development of sedentary lifestyles.",
      "date": "-10500"
    },
    {
      "headline": "Middle Jōmon Period",
      "text": "By approximately 2500 BCE, the Jōmon culture had reached a considerable degree of cultural complexity and sedentism. This period saw the development of more elaborate pottery and the establishment of larger settlements.",
      "date": "-2500"
    },
    {
      "headline": "Late Jōmon Period",
      "text": "The Late Jōmon period, around 1000 BCE, was marked by changes in climate that led to shifts in settlement patterns and subsistence strategies. The Jōmon people adapted to these changes by diversifying their food sources.",
      "date": "-1000"
    },
    {
      "headline": "End of the Jōmon Period",
      "text": "The Jōmon period came to an end around 300 BCE, transitioning into the Yayoi period. This transition was characterized by the introduction of rice agriculture and new technologies from the Asian continent.",
      "date": "-0300"
    },
    {
      "headline": "Discovery of Jōmon Pottery",
      "text": "In 1877, American zoologist and orientalist Edward S. Morse discovered sherds of Jōmon pottery. He translated the term 'straw-rope pattern' into Japanese as 'Jōmon', giving the period its name.",
      "date": "1877"
    }
  ]
}

