{
  "timeline": [
    {
      "headline": "Discovery of the Money Pit",
      "text": "In 1795, a teenager named Daniel McGinnis discovered a depression in the ground on Oak Island, which led to the first excavation of what would become known as the Money Pit.",
      "date": "1795"
    },
    {
      "headline": "Formation of the Onslow Company",
      "text": "In 1804, the Onslow Company was formed to further excavate the Money Pit. They reached a depth of 90 feet and discovered layers of logs and clay.",
      "date": "1804"
    },
    {
      "headline": "Truro Company Excavation",
      "text": "In 1849, the Truro Company conducted an excavation, reaching a depth of 86 feet before the pit flooded. They found coconut fibers and a stone with mysterious inscriptions.",
      "date": "1849"
    },
    {
      "headline": "Oak Island Association",
      "text": "In 1861, the Oak Island Association was formed to continue the search. A tragic accident occurred when a boiler exploded, killing one worker.",
      "date": "1861"
    },
    {
      "headline": "Formation of the Oak Island Treasure Company",
      "text": "In 1893, Frederick Blair formed the Oak Island Treasure Company, which conducted several excavations over the following decades.",
      "date": "1893"
    },
    {
      "headline": "Excavation by Gilbert Hedden",
      "text": "In 1936, Gilbert Hedden, an American businessman, conducted excavations and found evidence of previous diggings and artifacts.",
      "date": "1936"
    },
    {
      "headline": "Restall Family Tragedy",
      "text": "In 1965, Robert Restall and his son, along with two workers, died from gas exposure while working on the island.",
      "date": "1965"
    },
    {
      "headline": "Formation of Triton Alliance",
      "text": "In 1967, the Triton Alliance was formed by a group of investors to continue the search for treasure on Oak Island.",
      "date": "1967"
    },
    {
      "headline": "Discovery of the Stone Triangle",
      "text": "In 1970, a stone triangle was discovered on the island, believed to be a marker related to the treasure.",
      "date": "1970"
    },
    {
      "headline": "The Lagina Brothers' Involvement",
      "text": "In 2006, Rick and Marty Lagina purchased a controlling interest in Oak Island Tours, Inc., and began new explorations.",
      "date": "2006"
    },
    {
      "headline": "The Curse of Oak Island TV Show",
      "text": "In 2014, the History Channel premiered 'The Curse of Oak Island,' a reality TV series documenting the Lagina brothers' efforts to solve the island's mystery.",
      "date": "2014"
    }
  ]
}

