    {
      "headline": "Portuguese Rule",
      "text": "Dadra, Nagar Haveli, Daman, and Diu were part of Portuguese India, with a joint capital at Panjim, Goa.",
      "date": "-1500"
    },
    {
      "headline": "Annexation of Goa",
      "text": "In 1961, the territories of Goa, Daman, and Diu were annexed by India, ending Portuguese rule.",
      "date": "1961"
    },
    {
      "headline": "Free Dadra and Nagar Haveli",
      "text": "Dadra and Nagar Haveli were liberated from Portuguese rule in 1954 and were administered as a de facto state until officially becoming part of India in 1961.",
      "date": "1954"
    },
    {
      "headline": "Union Territory Formation",
      "text": "Goa, Daman, and Diu were administered as a single union territory after the annexation in 1961.",
      "date": "1961"
    },
    {
      "headline": "Goa Statehood",
      "text": "In 1987, Goa was granted statehood after the Konkani language agitation, leaving Daman and Diu as a separate union territory.",
      "date": "1987"
    },
    {
      "headline": "Merger Announcement",
      "text": "In July 2019, the Government of India announced plans to merge Dadra and Nagar Haveli with Daman and Diu into a single union territory.",
      "date": "2019-07"
    },
    {
      "headline": "Legislation Passed",
      "text": "In December 2019, the Parliament of India passed the necessary legislation to merge the territories.",
      "date": "2019-12"
    },
    {
      "headline": "Union Territory of Dadra and Nagar Haveli and Daman and Diu",
      "text": "The merger came into effect on 26 January 2020, creating the new union territory of Dadra and Nagar Haveli and Daman and Diu.",
      "date": "2020-01-26"
    }
  ]
}

