    {
      "headline": "Introduction of the North American Numbering Plan",
      "text": "The North American Numbering Plan (NANP) was introduced in 1947 by AT&T and the Bell System to simplify and facilitate direct dialing of long-distance calls.",
      "date": "1947"
    },
    {
      "headline": "Implementation of Area Codes",
      "text": "In 1947, the NANP introduced the concept of area codes, which allowed for the systematic assignment of telephone numbers across different regions.",
      "date": "1947"
    },
    {
      "headline": "First Direct-Dial Long-Distance Call",
      "text": "On November 10, 1951, the first direct-dial long-distance call was made using the NANP system, from Englewood, New Jersey, to Alameda, California.",
      "date": "1951-11-10"
    },
    {
      "headline": "Expansion to Include Caribbean Countries",
      "text": "Over the years, the NANP expanded to include several Caribbean countries, allowing them to use the same numbering plan as the United States and Canada.",
      "date": "Various years"
    },
    {
      "headline": "Introduction of Area Code Overlays",
      "text": "In the 1990s, area code overlays were introduced to address the exhaustion of available numbers in certain regions, allowing multiple area codes to coexist within the same geographic area.",
      "date": "1990s"
    },
    {
      "headline": "Implementation of 10-Digit Dialing",
      "text": "With the introduction of area code overlays, 10-digit dialing became necessary in many regions to ensure proper call routing.",
      "date": "1990s"
    },
    {
      "headline": "Continued Expansion and Adjustments",
      "text": "The NANP continues to evolve, with new area codes being added and adjustments made to accommodate the growing demand for telephone numbers.",
      "date": "Ongoing"
    }
  ]
}

