    {
      "headline": "Birth of Gojong",
      "text": "Gojong was born on September 8, 1852, in Seoul, Korea. His personal name was Yi Myeongbok.",
      "date": "1852-09-08"
    },
    {
      "headline": "Ascension to the Throne",
      "text": "Gojong ascended to the throne on January 21, 1864, at the age of 12, becoming the 26th king of the Joseon Dynasty.",
      "date": "1864-01-21"
    },
    {
      "headline": "Marriage to Queen Min",
      "text": "Gojong married Queen Min (Empress Myeongseong) on March 20, 1866. She became a significant political figure during his reign.",
      "date": "1866-03-20"
    },
    {
      "headline": "Assassination of Queen Min",
      "text": "Queen Min was assassinated on October 8, 1895, by Japanese agents, which significantly impacted Gojong's reign and Korea's political landscape.",
      "date": "1895-10-08"
    },
    {
      "headline": "Proclamation of the Korean Empire",
      "text": "On October 12, 1897, Gojong declared the establishment of the Korean Empire and became its first emperor, marking the end of the Joseon Dynasty.",
      "date": "1897-10-12"
    },
    {
      "headline": "Forced Abdication",
      "text": "Gojong was forced to abdicate the throne on July 20, 1907, in favor of his son, Sunjong, due to pressure from Japan.",
      "date": "1907-07-20"
    },
    {
      "headline": "Death of Gojong",
      "text": "Gojong died on January 21, 1919, in Deoksugung Palace, Seoul, Korea.",
      "date": "1919-01-21"
    }
  ]
}

