{
  "timeline": [
    {
      "headline": "Launch of Ayushman Bharat Yojana",
      "text": "Ayushman Bharat Yojana, also known as Pradhan Mantri Jan Arogya Yojana (PM-JAY), was launched on September 23, 2018. It is a national public health insurance scheme aimed at providing free access to health insurance coverage for low-income earners in India.",
      "date": "2018-09-23"
    },
    {
      "headline": "Objective of the Scheme",
      "text": "The scheme aims to cover approximately the bottom 50% of the Indian population, providing them with free secondary and tertiary healthcare services. It is designed to provide financial protection to vulnerable families by covering hospitalization expenses.",
      "date": "2018"
    },
    {
      "headline": "Implementation and Coverage",
      "text": "The scheme provides coverage of up to INR 5 lakh per family per year for secondary and tertiary care hospitalization. It covers over 10 crore poor and vulnerable families, translating to approximately 50 crore beneficiaries.",
      "date": "2018"
    },
    {
      "headline": "Expansion and Impact",
      "text": "Since its inception, Ayushman Bharat Yojana has expanded its network of hospitals and healthcare providers, both public and private, to ensure widespread access to healthcare services across the country.",
      "date": "2019"
    },
    {
      "headline": "Digital Health ID Initiative",
      "text": "In 2020, the government announced the creation of a digital health ID for every Indian citizen as part of the Ayushman Bharat Digital Mission, aiming to streamline healthcare services and improve access to medical records.",
      "date": "2020"
    }
  ]
}

