{
  "timeline": [
    {
      "headline": "Stubby Joins the 102nd Infantry Regiment",
      "text": "Stubby, a stray dog, was found by Private J. Robert Conroy on the grounds of Yale University in 1917, where the 102nd Infantry Regiment was training. Conroy adopted Stubby, and he became the unofficial mascot of the regiment.",
      "date": "1917"
    },
    {
      "headline": "Stubby Travels to France",
      "text": "In 1917, Stubby was smuggled aboard the USS Minnesota by Private Conroy and traveled to France with the 102nd Infantry Regiment to serve in World War I.",
      "date": "1917"
    },
    {
      "headline": "Stubby Participates in First Combat",
      "text": "Stubby saw his first combat in February 1918 during the German Spring Offensive. He served on the Western Front for 18 months, participating in 17 battles and four major offensives.",
      "date": "1918-02"
    },
    {
      "headline": "Stubby Saves Regiment from Mustard Gas Attack",
      "text": "Stubby saved his regiment from a surprise mustard gas attack by alerting the soldiers with his barking, allowing them to put on their gas masks in time. This incident occurred during his service on the Western Front.",
      "date": "1918"
    },
    {
      "headline": "Stubby Captures a German Soldier",
      "text": "Stubby allegedly caught a German soldier by the seat of his pants and held him until American soldiers arrived, earning him further fame. This event took place during his time on the Western Front.",
      "date": "1918"
    },
    {
      "headline": "Stubby Returns to the United States",
      "text": "After the end of World War I, Stubby returned to the United States with Private Conroy in 1919. He was celebrated as a hero and participated in many parades and events.",
      "date": "1919"
    },
    {
      "headline": "Stubby Becomes a Georgetown University Mascot",
      "text": "Stubby became the mascot for the Georgetown Hoyas after Conroy enrolled in Georgetown University Law Center. He continued to be a popular figure on campus.",
      "date": "1921"
    },
    {
      "headline": "Death of Sergeant Stubby",
      "text": "Stubby passed away in 1926. He was remembered as a hero and his remains were preserved and are displayed at the Smithsonian Institution.",
      "date": "1926"
    }
  ]
}

