    {
      "headline": "Beginning of the Old Kingdom",
      "text": "The Old Kingdom of Egypt began around 2700 BCE, marking the start of the Third Dynasty. This period is characterized by the establishment of a centralized government and the construction of monumental architecture.",
      "date": "-2700"
    },
    {
      "headline": "Reign of King Djoser",
      "text": "King Djoser ruled during the Third Dynasty, around 2670 BCE. He is best known for commissioning the Step Pyramid at Saqqara, designed by his architect Imhotep.",
      "date": "-2670"
    },
    {
      "headline": "Reign of King Sneferu",
      "text": "King Sneferu, the first ruler of the Fourth Dynasty, reigned around 2613-2589 BCE. He is credited with building three pyramids, including the Bent Pyramid and the Red Pyramid, marking advancements in pyramid construction.",
      "date": "-2613"
    },
    {
      "headline": "Construction of the Great Pyramid of Giza",
      "text": "The Great Pyramid of Giza was constructed during the reign of King Khufu, around 2580-2560 BCE. It is the largest of the pyramids at Giza and one of the Seven Wonders of the Ancient World.",
      "date": "-2580"
    },
    {
      "headline": "Reign of King Khafre",
      "text": "King Khafre, who ruled around 2558-2532 BCE, is known for building the second pyramid at Giza and possibly the Great Sphinx.",
      "date": "-2558"
    },
    {
      "headline": "Reign of King Menkaure",
      "text": "King Menkaure ruled around 2532-2503 BCE and is known for constructing the third and smallest pyramid at Giza.",
      "date": "-2532"
    },
    {
      "headline": "End of the Old Kingdom",
      "text": "The Old Kingdom period ended around 2200 BCE, transitioning into the First Intermediate Period. This decline was marked by political fragmentation and a decrease in centralized power.",
      "date": "-2200"
    }
  ]
}

