      "date": "2021-11-24"
    },
    {
      "headline": "DART Impact with Dimorphos",
      "text": "On 26 September 2022 at 23:14 UTC, the DART spacecraft successfully collided with Dimorphos, a minor-planet moon of the asteroid Didymos, about 11 million kilometers from Earth. The collision shortened Dimorphos' orbit by 32 minutes.",
      "date": "2022-09-26"
    },
    {
      "headline": "DART Mission Success",
      "text": "The DART mission was deemed a success as it exceeded the pre-defined success threshold of shortening Dimorphos' orbit by 73 seconds. The success was attributed to the momentum transfer associated with the recoil of the ejected debris.",
      "date": "2022-09-26"
    }
  ]
}

