{
  "timeline": [
    {
      "headline": "Jussie Smollett Reports Hate Crime",
      "text": "On January 29, 2019, Jussie Smollett reported to the Chicago Police Department that he had been the victim of a hate crime. He claimed that two men attacked him, shouting racial and homophobic slurs, pouring bleach on him, and placing a noose around his neck.",
      "date": "2019-01-29"
    },
    {
      "headline": "Investigation Reveals Staged Attack",
      "text": "As the investigation progressed, evidence emerged suggesting that Smollett had staged the attack with the help of two Nigerian-American brothers, Abimbola and Olabinjo Osundairo, who had worked as extras on the television drama Empire.",
      "date": "2019-02"
    },
    {
      "headline": "Brothers Testify Against Smollett",
      "text": "The Osundairo brothers testified that Smollett had planned the fake hate crime and directed them to carry out the staged attack near a surveillance camera for publicity.",
      "date": "2019-02"
    },
    {
      "headline": "Jussie Smollett Charged",
      "text": "On February 20, 2019, Jussie Smollett was charged with filing a false police report and disorderly conduct for allegedly staging the attack.",
      "date": "2019-02-20"
    },
    {
      "headline": "Charges Dropped",
      "text": "On March 26, 2019, all charges against Smollett were dropped by the Cook County State's Attorney's Office, a decision that sparked controversy and led to further legal proceedings.",
      "date": "2019-03-26"
    },
    {
      "headline": "Special Prosecutor Appointed",
      "text": "In August 2019, a special prosecutor was appointed to review the handling of the case and the decision to drop charges against Smollett.",
      "date": "2019-08"
    },
    {
      "headline": "Smollett Indicted Again",
      "text": "On February 11, 2020, Jussie Smollett was indicted again on six counts of disorderly conduct related to the false report of the hate crime.",
      "date": "2020-02-11"
    },
    {
      "headline": "Trial and Conviction",
      "text": "In December 2021, Jussie Smollett was found guilty on five of six counts of disorderly conduct for filing a false police report.",
      "date": "2021-12"
    },
    {
      "headline": "Sentencing",
      "text": "On March 10, 2022, Jussie Smollett was sentenced to 150 days in county jail, 30 months of probation, and ordered to pay restitution and fines.",
      "date": "2022-03-10"
    }
  ]
}

