{
  "timeline": [
    {
      "headline": "Formation of the SDLP",
      "text": "The Social Democratic and Labour Party (SDLP) was founded in August 1970. It was established by a group of politicians who were committed to a peaceful resolution to the conflict in Northern Ireland and advocated for Irish nationalism and social democracy.",
      "date": "1970-08"
    },
    {
      "headline": "First Leader of the SDLP",
      "text": "Gerry Fitt became the first leader of the SDLP in 1970, serving until 1979. Under his leadership, the party sought to represent the interests of the nationalist community in Northern Ireland.",
      "date": "1970"
    },
    {
      "headline": "Sunningdale Agreement",
      "text": "In 1973, the SDLP participated in negotiations that led to the Sunningdale Agreement, which aimed to establish a power-sharing executive and a cross-border Council of Ireland. The agreement ultimately failed due to opposition from unionists.",
      "date": "1973"
    },
    {
      "headline": "John Hume's Leadership",
      "text": "John Hume became the leader of the SDLP in 1979. He played a significant role in the Northern Ireland peace process, advocating for dialogue and cooperation between different communities.",
      "date": "1979"
    },
    {
      "headline": "Anglo-Irish Agreement",
      "text": "The SDLP supported the Anglo-Irish Agreement signed in 1985, which gave the Irish government an advisory role in Northern Ireland's affairs and aimed to foster cooperation between the British and Irish governments.",
      "date": "1985"
    },
    {
      "headline": "Good Friday Agreement",
      "text": "The SDLP was a key participant in the negotiations leading to the Good Friday Agreement in 1998, which established a devolved government for Northern Ireland and set the framework for peace and reconciliation.",
      "date": "1998"
    },
    {
      "headline": "Decline in Electoral Support",
      "text": "In the 2000s, the SDLP experienced a decline in electoral support, losing ground to Sinn Féin, which became the dominant nationalist party in Northern Ireland.",
      "date": "2000"
    },
    {
      "headline": "Colum Eastwood's Leadership",
      "text": "Colum Eastwood became the leader of the SDLP in 2015, focusing on revitalizing the party and addressing contemporary political challenges in Northern Ireland.",
      "date": "2015"
    }
  ]
}

