      "date": "2008-04-29"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Foundation of the Durrani Empire",
      "text": "In 1747, Ahmad Shah Durrani founded the Durrani Empire after being elected as the king by a council of tribal chiefs. This marked the beginning of the Afghan Empire.",
      "date": "1747"
    },
    {
      "headline": "Conquest of Delhi",
      "text": "In 1757, Ahmad Shah Durrani captured Delhi, the capital of the Mughal Empire, during his fourth invasion of India. This expanded the influence of the Durrani Empire into northern India.",
      "date": "1757"
    },
    {
      "headline": "Battle of Panipat",
      "text": "On January 14, 1761, Ahmad Shah Durrani defeated the Maratha Empire in the Third Battle of Panipat, which was one of the largest and bloodiest fought in the 18th century.",
      "date": "1761-01-14"
    },
    {
      "headline": "Death of Ahmad Shah Durrani",
      "text": "Ahmad Shah Durrani died in 1772, leading to a period of instability and succession disputes within the empire.",
      "date": "1772"
    },
    {
      "headline": "Reign of Timur Shah Durrani",
      "text": "Timur Shah Durrani, the son of Ahmad Shah, ruled the Durrani Empire from 1772 until his death in 1793. His reign was marked by internal strife and challenges to his authority.",
      "date": "1772"
    },
    {
      "headline": "Decline of the Durrani Empire",
      "text": "Following the death of Timur Shah in 1793, the Durrani Empire began to decline due to internal conflicts and external pressures, leading to its fragmentation.",
      "date": "1793"
    },
    {
      "headline": "End of the Durrani Empire",
      "text": "The Durrani Empire effectively came to an end in 1823 when the Barakzai dynasty took control, marking the transition to the Emirate of Afghanistan.",
      "date": "1823"
    }
  ]
}

