  "timeline": [
    {
      "headline": "Bauhaus School Founded",
      "text": "The Bauhaus School, founded by Walter Gropius in Weimar, Germany, in 1919, played a significant role in the development of modern architecture by promoting functional design and the integration of art, craft, and technology.",
      "date": "1919"
    },
    {
      "headline": "Le Corbusier's 'Five Points of Architecture'",
      "text": "In 1927, Le Corbusier published his 'Five Points of Architecture', which became a manifesto for modernist architecture, emphasizing pilotis, flat roofs, open floor plans, horizontal windows, and free facades.",
      "date": "1927"
    },
    {
      "headline": "International Style Exhibition",
      "text": "The International Style exhibition at the Museum of Modern Art in New York City in 1932, curated by Philip Johnson and Henry-Russell Hitchcock, helped define and popularize modern architecture in the United States.",
      "date": "1932"
    },
    {
      "headline": "Villa Savoye Completed",
      "text": "Designed by Le Corbusier and completed in 1931, the Villa Savoye in Poissy, France, is a prime example of modernist architecture, embodying Le Corbusier's 'Five Points of Architecture'.",
      "date": "1931"
    },
    {
      "headline": "Fallingwater Completed",
      "text": "Frank Lloyd Wright's Fallingwater, completed in 1939 in Pennsylvania, USA, is a landmark of modern architecture, known for its integration with the natural landscape and innovative cantilevered design.",
      "date": "1939"
    },
    {
      "headline": "Seagram Building Completed",
      "text": "The Seagram Building in New York City, designed by Ludwig Mies van der Rohe and Philip Johnson and completed in 1958, is a quintessential example of the International Style in modern architecture.",
      "date": "1958"
    },
    {
      "headline": "Sydney Opera House Completed",
      "text": "The Sydney Opera House, designed by Jørn Utzon and completed in 1973, is a masterpiece of modern architecture, known for its distinctive sail-like shells and innovative engineering.",
      "date": "1973"
    },
    {
      "headline": "Postmodern Architecture Emerges",
      "text": "In the late 1970s, postmodern architecture began to emerge as a reaction against the perceived austerity and lack of variety in modern architecture, marking a shift in architectural styles.",
      "date": "1970-1979"
    }
  ]
}

