{
  "timeline": [
    {
      "headline": "Outbreak of the Peasants' Revolt",
      "text": "The Peasants' Revolt began in May 1381, triggered by socio-economic and political tensions, including the aftermath of the Black Death, high taxes from the Hundred Years' War, and local leadership instability.",
      "date": "1381-05"
    },
    {
      "headline": "Storming of London",
      "text": "On June 13, 1381, the rebels entered London. They were initially welcomed by the city's populace, and they proceeded to attack symbols of royal authority, including the Savoy Palace.",
      "date": "1381-06-13"
    },
    {
      "headline": "Meeting at Mile End",
      "text": "On June 14, 1381, King Richard II met with the rebels at Mile End, where he agreed to their demands, including the abolition of serfdom and the reduction of taxes.",
      "date": "1381-06-14"
    },
    {
      "headline": "Death of Simon Sudbury",
      "text": "On June 14, 1381, Archbishop Simon Sudbury, who was also the Lord Chancellor, was captured by the rebels and executed at the Tower of London.",
      "date": "1381-06-14"
    },
    {
      "headline": "Meeting at Smithfield and Death of Wat Tyler",
      "text": "On June 15, 1381, a second meeting took place at Smithfield between King Richard II and the rebel leader Wat Tyler. During the meeting, Tyler was killed by the king's men, leading to the collapse of the revolt.",
      "date": "1381-06-15"
    },
    {
      "headline": "Suppression of the Revolt",
      "text": "Following the death of Wat Tyler, the revolt was quickly suppressed by the royal forces. By the end of June 1381, most of the rebel leaders had been captured and executed.",
      "date": "1381-06"
    },
    {
      "headline": "Repeal of Concessions",
      "text": "After the suppression of the revolt, King Richard II revoked all the concessions he had made to the rebels, including the abolition of serfdom.",
      "date": "1381"
    }
  ]
}

