      "date": "-0055"
    },
    {
      "headline": "Construction of Dover Castle",
      "text": "Dover Castle, located near the White Cliffs, was constructed in the 11th century by William the Conqueror to protect the coast from invasion.",
      "date": "1066"
    },
    {
      "headline": "World War II Significance",
      "text": "During World War II, the White Cliffs of Dover became a symbol of hope and resilience for the British people. The cliffs were heavily fortified to defend against potential German invasion.",
      "date": "1939"
    },
