{
  "timeline": [
    {
      "headline": "Democritus and Atomism",
      "text": "Around 460 BCE, Democritus, a Greek philosopher, developed the theory of atomism, which posited that everything is composed of small, indivisible particles called atoms. This early form of materialism suggested that the universe is composed entirely of matter.",
      "date": "-0460"
    },
    {
      "headline": "Epicurus and Materialism",
      "text": "In 341 BCE, Epicurus was born. He later developed a philosophy that included materialism, emphasizing that pleasure and pain are the measures of what is good and evil, and that the gods do not interfere with human lives.",
      "date": "-0341"
    },
    {
      "headline": "Lucretius and 'De Rerum Natura'",
      "text": "Around 99 BCE, Lucretius, a Roman poet and philosopher, was born. He wrote 'De Rerum Natura' (On the Nature of Things), which expounded Epicurean philosophy and materialism, explaining the world in terms of atoms and void.",
      "date": "-0099"
    },
    {
      "headline": "Thomas Hobbes and Materialism",
      "text": "In 1651, Thomas Hobbes published 'Leviathan', where he argued that everything in the universe, including human thought and consciousness, could be explained in terms of physical matter and motion.",
      "date": "1651"
    },
    {
      "headline": "Pierre Gassendi's Revival of Atomism",
      "text": "In the mid-17th century, Pierre Gassendi revived Epicurean atomism, integrating it with Christian theology and influencing the development of modern scientific materialism.",
      "date": "1650"
    },
    {
      "headline": "Julien Offray de La Mettrie's 'Man a Machine'",
      "text": "In 1748, Julien Offray de La Mettrie published 'L'Homme Machine' (Man a Machine), arguing that human beings are complex machines and that mental processes are purely physical phenomena.",
      "date": "1748"
    },
    {
      "headline": "Karl Marx and Historical Materialism",
      "text": "In the mid-19th century, Karl Marx developed historical materialism, a theory that posits that material conditions and economic factors are the primary influences on societal development and change.",
      "date": "1850"
    },
    {
      "headline": "Dialectical Materialism",
      "text": "In the late 19th and early 20th centuries, dialectical materialism emerged as a philosophical framework for understanding the material basis of reality, influenced by Marx and Engels, and later adopted by Soviet Marxism.",
      "date": "1900"
    }
  ]
}

