    {
      "headline": "Emergence of Sephardi Jews",
      "text": "Sephardi Jews emerged as a distinct group in the Iberian Peninsula, particularly in Spain and Portugal, during the Middle Ages. They developed unique cultural and religious practices.",
      "date": "1100"
    },
    {
      "headline": "Expulsion from Spain",
      "text": "In 1492, the Alhambra Decree ordered the expulsion of practicing Jews from the Kingdoms of Castile and Aragon, leading to the dispersion of Sephardi Jews across the Mediterranean, North Africa, and the Ottoman Empire.",
      "date": "1492"
    },
    {
      "headline": "Formation of Mizrahi Jews",
      "text": "Mizrahi Jews, also known as Oriental Jews, formed as a distinct group in the Middle East and North Africa. They trace their origins to local Jewish communities in these regions that predate the Arab conquest.",
      "date": "1600"
    },
    {
      "headline": "Development of Ethiopian Jews",
      "text": "Ethiopian Jews, also known as Beta Israel, developed as a distinct community in Ethiopia. They have a unique religious tradition that diverged from mainstream Judaism over centuries of isolation.",
      "date": "1700"
    },
    {
      "headline": "Recognition of Beta Israel",
      "text": "In 1975, the Israeli government officially recognized the Beta Israel community as Jews, paving the way for their immigration to Israel.",
      "date": "1975"
    },
    {
      "headline": "Operation Moses",
      "text": "Operation Moses was a covert evacuation of Ethiopian Jews from Sudan during a famine in 1984. Thousands of Ethiopian Jews were airlifted to Israel.",
      "date": "1984"
    },
    {
      "headline": "Operation Solomon",
      "text": "Operation Solomon was a covert Israeli military operation in 1991 that airlifted over 14,000 Ethiopian Jews to Israel in 36 hours.",
      "date": "1991"
    }
  ]
}

