{
  "timeline": [
    {
      "headline": "Founding of IATA",
      "text": "The International Air Transport Association (IATA) was founded in Havana, Cuba, in April 1945. It was established to promote cooperation among the world's airlines and to ensure safe, reliable, and economical air services.",
      "date": "1945-04"
    },
    {
      "headline": "First IATA Traffic Conference",
      "text": "In 1947, IATA held its first Traffic Conference in Rio de Janeiro, Brazil. This conference was significant as it established the first international standards for airline tariffs and fares.",
      "date": "1947"
    },
    {
      "headline": "Introduction of IATA Billing and Settlement Plan",
      "text": "In 1971, IATA introduced the Billing and Settlement Plan (BSP), a system designed to simplify the selling, reporting, and remitting procedures of IATA Accredited Passenger Sales Agents, as well as improve financial control and cash flow for airlines.",
      "date": "1971"
    },
    {
      "headline": "IATA's Role in Deregulation",
      "text": "During the late 1970s and 1980s, IATA played a role in the deregulation of the airline industry, particularly in the United States and Europe, which led to increased competition and lower fares.",
      "date": "1980"
    },
    {
      "headline": "Launch of IATA Operational Safety Audit (IOSA)",
      "text": "In 2003, IATA launched the IATA Operational Safety Audit (IOSA), a program designed to assess the operational management and control systems of airlines. IOSA has become a global standard for airline safety management.",
      "date": "2003"
    },
    {
      "headline": "Introduction of the New Distribution Capability (NDC)",
      "text": "In 2012, IATA introduced the New Distribution Capability (NDC), a travel industry-supported program launched for the development and market adoption of a new, XML-based data transmission standard that enhances the capability of communications between airlines and travel agents.",
      "date": "2012"
    },
    {
      "headline": "IATA's Response to COVID-19 Pandemic",
      "text": "In 2020, IATA played a crucial role in coordinating the global airline industry's response to the COVID-19 pandemic, advocating for government support and implementing health and safety measures to ensure the safe resumption of air travel.",
      "date": "2020"
    }
  ]
}

