{
  "timeline": [
    {
      "headline": "Discovery by Yves-Joseph de Kerguelen-Trémarec",
      "text": "The Kerguelen Islands were discovered by the French navigator Yves-Joseph de Kerguelen-Trémarec on February 12, 1772. He initially believed he had found a new continent.",
      "date": "1772-02-12"
    },
    {
      "headline": "Second Expedition by Kerguelen",
      "text": "Yves-Joseph de Kerguelen-Trémarec returned to the islands on a second expedition in December 1773, which confirmed the islands were not part of a continent.",
      "date": "1773-12"
    },
    {
      "headline": "British Exploration",
      "text": "In 1776, Captain James Cook visited the Kerguelen Islands during his third voyage, further mapping the area and confirming its isolation.",
      "date": "1776"
    },
    {
      "headline": "French Annexation",
      "text": "The Kerguelen Islands were formally annexed by France in 1893, becoming part of the French colonial empire.",
      "date": "1893"
    },
    {
      "headline": "Establishment of Permanent Base",
      "text": "In 1950, France established a permanent scientific base, Port-aux-Français, on the Kerguelen Islands, which serves as the main settlement.",
      "date": "1950"
    },
    {
      "headline": "Inclusion in French Southern and Antarctic Lands",
      "text": "In 1955, the Kerguelen Islands became part of the French Southern and Antarctic Lands, a French overseas territory.",
      "date": "1955"
    }
  ]
}

