    {
      "headline": "Introduction of CAP Theorem",
      "text": "In 2000, Eric Brewer introduced the CAP theorem at the Symposium on Principles of Distributed Computing (PODC). The theorem states that a distributed data store can only provide two out of the following three guarantees: Consistency, Availability, and Partition Tolerance.",
      "date": "2000"
    },
    {
      "headline": "Formal Proof of CAP Theorem",
      "text": "In 2002, Seth Gilbert and Nancy Lynch provided a formal proof of the CAP theorem, which solidified its place in distributed systems theory.",
      "date": "2002"
    }
  ]
}

