{
  "timeline": [
    {
      "headline": "Founding of Netscape",
      "text": "Netscape Communications Corporation was founded as Mosaic Communications Corporation by Marc Andreessen and Jim Clark in April 1994.",
      "date": "1994-04"
    },
    {
      "headline": "Release of Netscape Navigator 1.0",
      "text": "Netscape released its first web browser, Netscape Navigator 1.0, on December 15, 1994.",
      "date": "1994-12-15"
    },
    {
      "headline": "Netscape Navigator's Market Dominance",
      "text": "By the mid-1990s, Netscape Navigator became the dominant web browser with more than 90% market share.",
      "date": "1995"
    },
    {
      "headline": "Creation of JavaScript",
      "text": "Brendan Eich, an early Netscape employee, created the JavaScript programming language in September 1995, which became the most widely used language for client-side scripting of web pages.",
      "date": "1995-09"
    },
    {
      "headline": "Development of SSL",
      "text": "Netscape developed the Secure Sockets Layer (SSL) protocol in 1995 to secure online communications.",
      "date": "1995"
    },
    {
      "headline": "Netscape's Initial Public Offering",
      "text": "Netscape went public on August 9, 1995, in a highly successful initial public offering (IPO) that marked the start of the dot-com boom.",
      "date": "1995-08-09"
    },
    {
      "headline": "Creation of HTTP Cookies",
      "text": "Lou Montulli, a founding engineer of Netscape, created HTTP cookies in 1994, which became a standard mechanism for storing user data on web browsers.",
      "date": "1994"
    },
    {
      "headline": "The Browser Wars",
      "text": "Netscape faced intense competition from Microsoft's Internet Explorer starting in the late 1990s, leading to a significant decline in its market share.",
      "date": "1996"
    },
    {
      "headline": "Acquisition by AOL",
      "text": "Netscape was acquired by AOL on November 24, 1998, for $4.2 billion.",
      "date": "1998-11-24"
    },
    {
      "headline": "End of Netscape Navigator",
      "text": "Netscape Navigator's market share fell to less than one percent by 2006, marking the end of its relevance in the browser market.",
      "date": "2006"
    }
  ]
}

