{
  "timeline": [
    {
      "headline": "Introduction of Ocean Liners",
      "text": "The concept of ocean liners began in the early 19th century with the advent of steam-powered ships that could reliably cross oceans. These ships were designed to carry passengers, cargo, and mail across seas and oceans.",
      "date": "1800"
    },
    {
      "headline": "First Steam-Powered Ocean Liner",
      "text": "The SS Great Western, launched in 1837, was one of the first steam-powered ocean liners. It was designed by Isambard Kingdom Brunel and marked the beginning of the era of steam-powered transatlantic travel.",
      "date": "1837"
    },
    {
      "headline": "Launch of RMS Titanic",
      "text": "The RMS Titanic, one of the most famous ocean liners, was launched on May 31, 1911. It was the largest ship afloat at the time and was considered unsinkable.",
      "date": "1911-05-31"
    },
    {
      "headline": "Sinking of RMS Titanic",
      "text": "On April 15, 1912, the RMS Titanic sank after hitting an iceberg during its maiden voyage from Southampton to New York City, resulting in the deaths of over 1,500 passengers and crew.",
      "date": "1912-04-15"
    },
    {
      "headline": "Launch of RMS Queen Mary",
      "text": "The RMS Queen Mary was launched on September 26, 1934. It became one of the most famous ocean liners, known for its speed and luxury.",
      "date": "1934-09-26"
    },
    {
      "headline": "Introduction of Queen Mary 2",
      "text": "The Queen Mary 2, the only ocean liner still in service today, was launched on March 21, 2003. It was built by Chantiers de l'Atlantique in Saint-Nazaire, France, for the Cunard Line.",
      "date": "2003-03-21"
    }
  ]
}

