{
  "timeline": [
    {
      "headline": "Founding of the Communist International",
      "text": "The Communist International, also known as the Comintern, was founded in March 1919. It was established in Moscow with the aim of advocating world communism and was led by the Communist Party of the Soviet Union.",
      "date": "1919-03"
    },
    {
      "headline": "Second Congress of the Comintern",
      "text": "The Second Congress of the Communist International took place from July 19 to August 7, 1920. This congress established the 21 Conditions for membership, which were designed to ensure that only parties committed to revolutionary Marxism could join.",
      "date": "1920-07-19"
    },
    {
      "headline": "Third Congress of the Comintern",
      "text": "The Third Congress was held from June 22 to July 12, 1921. It focused on the need for Communist parties to gain mass support and emphasized the importance of working within trade unions.",
      "date": "1921-06-22"
    },
    {
      "headline": "Fourth Congress of the Comintern",
      "text": "The Fourth Congress took place from November 5 to December 5, 1922. It addressed the issue of united fronts, encouraging Communist parties to collaborate with other leftist groups to combat fascism and reactionary forces.",
      "date": "1922-11-05"
    },
    {
      "headline": "Fifth Congress of the Comintern",
      "text": "Held from June 17 to July 8, 1924, the Fifth Congress focused on the internal consolidation of Communist parties and the fight against social democracy, which was seen as a rival to communism.",
      "date": "1924-06-17"
    },
    {
      "headline": "Sixth Congress of the Comintern",
      "text": "The Sixth Congress occurred from July 17 to September 1, 1928. It marked a shift towards a more aggressive stance against social democracy, labeling it as 'social fascism' and emphasizing the need for a proletarian revolution.",
      "date": "1928-07-17"
    },
    {
      "headline": "Seventh Congress of the Comintern",
      "text": "The Seventh Congress, held from July 25 to August 20, 1935, marked a significant change in strategy. It advocated for the formation of Popular Fronts, alliances with non-communist parties to combat fascism.",
      "date": "1935-07-25"
    },
    {
      "headline": "Dissolution of the Communist International",
      "text": "The Communist International was officially dissolved on May 15, 1943. This decision was influenced by the need to improve relations between the Soviet Union and its World War II allies, particularly the United States and the United Kingdom.",
      "date": "1943-05-15"
    }
  ]
}

