{
  "timeline": [
    {
      "headline": "Beginning of the Stolen Generations",
      "text": "The practice of removing Aboriginal and Torres Strait Islander children from their families began in the early 20th century. The removals were conducted under various state and federal policies, with the aim of assimilating these children into white society. This practice started around 1905.",
      "date": "1905"
    },
    {
      "headline": "Aborigines Act 1905",
      "text": "The Aborigines Act 1905 was enacted in Western Australia, giving the Chief Protector of Aborigines legal guardianship of all Aboriginal children to the age of 16. This act was one of the first legal frameworks that facilitated the removal of Aboriginal children from their families.",
      "date": "1905"
    },
    {
      "headline": "Aborigines Protection Act 1909",
      "text": "The Aborigines Protection Act 1909 was passed in New South Wales, allowing for the removal of Aboriginal children from their families without parental consent. This act further institutionalized the practice of child removal.",
      "date": "1909"
    },
    {
      "headline": "Establishment of the Northern Territory Aboriginals Ordinance 1911",
      "text": "The Northern Territory Aboriginals Ordinance 1911 was established, giving the Chief Protector control over Aboriginal people and their property, including the power to remove children from their families.",
      "date": "1911"
    },
    {
      "headline": "Bringing Them Home Report",
      "text": "The Bringing Them Home report was tabled in the Australian Parliament on May 26, 1997. It was the result of a national inquiry into the separation of Aboriginal and Torres Strait Islander children from their families. The report documented the experiences of the Stolen Generations and made recommendations for reparations.",
      "date": "1997-05-26"
    },
    {
      "headline": "National Sorry Day",
      "text": "The first National Sorry Day was held on May 26, 1998, to commemorate the anniversary of the Bringing Them Home report and to acknowledge the impact of the Stolen Generations.",
      "date": "1998-05-26"
    },
    {
      "headline": "Australian Government Apology",
      "text": "On February 13, 2008, then-Prime Minister Kevin Rudd formally apologized to the Stolen Generations on behalf of the Australian government. This apology was a significant moment in acknowledging the wrongs done to Aboriginal and Torres Strait Islander peoples.",
      "date": "2008-02-13"
    }
  ]
}

