{
  "timeline": [
    {
      "headline": "Establishment of the Civilian Conservation Corps",
      "text": "The Civilian Conservation Corps (CCC) was established as part of President Franklin D. Roosevelt's New Deal to provide jobs for young men and to aid families struggling during the Great Depression. The program was officially created on March 31, 1933.",
      "date": "1933-03-31"
    },
    {
      "headline": "First CCC Camp Opens",
      "text": "The first CCC camp, Camp Roosevelt, was established in the George Washington National Forest in Virginia. This marked the beginning of the CCC's operations, which would eventually expand across the United States. The camp opened on April 17, 1933.",
      "date": "1933-04-17"
    },
    {
      "headline": "Expansion of Age Range",
      "text": "The CCC expanded its age range to include young men aged 17 to 28, allowing more individuals to participate in the program. This change occurred in 1935.",
      "date": "1935"
    },
    {
      "headline": "Introduction of She-She-She Camps",
      "text": "In 1936, a smaller counterpart program for unemployed women, known as the She-She-She Camps, was introduced. This initiative was championed by Eleanor Roosevelt to provide similar opportunities for women.",
      "date": "1936"
    },
    {
      "headline": "Peak Enrollment",
      "text": "The CCC reached its peak enrollment in August 1935, with over 500,000 young men participating in the program across the United States.",
      "date": "1935-08"
    },
    {
      "headline": "Closure of the Civilian Conservation Corps",
      "text": "The Civilian Conservation Corps was officially disbanded on June 30, 1942, as the United States entered World War II and the focus shifted to wartime production and military service.",
      "date": "1942-06-30"
    }
  ]
}

