{
  "timeline": [
    {
      "headline": "Siddhartha Gautama Attains Enlightenment",
      "text": "Circa 500 BCE, Siddhartha Gautama, who would become known as the Buddha, attained enlightenment under the Bodhi Tree in Bodh Gaya, Bihar, India.",
      "date": "-0500"
    },
    {
      "headline": "Ashoka's Pilgrimage and Veneration",
      "text": "In the 3rd century BCE, Emperor Ashoka visited the Bodhi Tree and is said to have built a temple around it, marking the site as a place of pilgrimage.",
      "date": "-0250"
    },
    {
      "headline": "Destruction by Tissarakkha",
      "text": "Around 230 BCE, Tissarakkha, the queen of Emperor Ashoka, allegedly destroyed the Bodhi Tree out of jealousy.",
      "date": "-0230"
    },
    {
      "headline": "Replanting by Ashoka",
      "text": "Following its destruction, Emperor Ashoka is said to have replanted the Bodhi Tree using a sapling from the original tree.",
      "date": "-0220"
    },
    {
      "headline": "Propagation to Sri Lanka",
      "text": "In the 3rd century BCE, a sapling from the Bodhi Tree was taken to Sri Lanka by Sanghamitta, the daughter of Ashoka, where it was planted in Anuradhapura. This tree is known as the Jaya Sri Maha Bodhi.",
      "date": "-0237"
    },
    {
      "headline": "Destruction by King Shashanka",
      "text": "In the 7th century CE, King Shashanka of Gauda is said to have destroyed the Bodhi Tree.",
      "date": "0600"
    },
    {
      "headline": "Restoration by Pala Kings",
      "text": "In the 7th century CE, the Pala kings restored the Bodhi Tree, ensuring its continued veneration.",
      "date": "0650"
    },
    {
      "headline": "Current Bodhi Tree Planted",
      "text": "The current Bodhi Tree at Bodh Gaya is believed to be a direct descendant of the original tree, planted in the late 19th century.",
      "date": "1881"
    }
  ]
}

