{
  "timeline": [
    {
      "headline": "Birth of Muhammad of Ghor",
      "text": "Mu'izz al-Din Muhammad ibn Sam, known as Muhammad of Ghor, was born in the Ghor region of present-day central Afghanistan. The exact date of his birth is not recorded, but it is estimated to be around the mid-12th century.",
      "date": "1150"
    },
    {
      "headline": "Ascension to Power",
      "text": "In 1173, Muhammad of Ghor ascended to power alongside his elder brother Ghiyath al-Din Muhammad, ruling in a dyarchy. Muhammad focused on expanding Ghurid rule eastwards.",
      "date": "1173"
    },
    {
      "headline": "Conquest of Ghazni",
      "text": "Muhammad of Ghor captured the city of Ghazni in 1173, marking the beginning of his eastern expansion.",
      "date": "1173"
    },
    {
      "headline": "Battle of Tarain",
      "text": "In 1191, Muhammad of Ghor faced a significant defeat at the First Battle of Tarain against the Rajput confederacy led by Prithviraj Chauhan.",
      "date": "1191"
    },
    {
      "headline": "Victory at the Second Battle of Tarain",
      "text": "Muhammad of Ghor achieved a decisive victory at the Second Battle of Tarain in 1192, which paved the way for Muslim rule in northern India.",
