{
  "timeline": [
    {
      "headline": "Origins of Galician Language",
      "text": "The Galician language originated from the Latin spoken by the Romanized Celtic and Iberian peoples of the region during the Roman Empire. It evolved from Vulgar Latin, which was introduced to the Iberian Peninsula by Roman soldiers, settlers, and merchants.",
      "date": "-0500"
    },
    {
      "headline": "Medieval Galician-Portuguese",
      "text": "During the Middle Ages, Galician and Portuguese were dialects of a single language known as Galician-Portuguese. This language was used in the northwest of the Iberian Peninsula and was the language of the lyric poetry of the troubadours.",
      "date": "1200"
    },
    {
      "headline": "Separation of Galician and Portuguese",
      "text": "By the 15th century, Galician and Portuguese began to diverge into two distinct languages due to political and cultural separation. The Kingdom of Galicia was integrated into the Crown of Castile, which led to the increasing influence of Castilian (Spanish) on Galician.",
      "date": "1400"
    },
    {
      "headline": "Rexurdimento (Galician Renaissance)",
      "text": "The 19th century saw a revival of Galician culture and language known as the Rexurdimento. This period was marked by a renewed interest in Galician literature and the promotion of Galician as a language of culture and identity.",
      "date": "1800"
    },
    {
      "headline": "Official Status in Galicia",
      "text": "In 1981, Galician was granted co-official status alongside Spanish in the autonomous community of Galicia, following the Spanish Constitution of 1978 which recognized the linguistic diversity of Spain.",
      "date": "1981"
    },
    {
      "headline": "Standardization of Galician",
      "text": "The 1980s and 1990s saw efforts to standardize the Galician language, resulting in the establishment of the Instituto da Lingua Galega and the Real Academia Galega, which work to promote and regulate the language.",
      "date": "1990"
    }
  ]
}

