{
  "timeline": [
    {
      "headline": "Thomas Young's Double-Slit Experiment",
      "text": "In 1801, Thomas Young conducted the double-slit experiment, demonstrating that light exhibits wave-like interference patterns, supporting the wave theory of light.",
      "date": "1801"
    },
    {
      "headline": "James Clerk Maxwell's Electromagnetic Theory",
      "text": "In 1865, James Clerk Maxwell published his theory of electromagnetism, which described light as electromagnetic waves, further supporting the wave nature of light.",
      "date": "1865"
    },
    {
      "headline": "Discovery of the Photoelectric Effect",
      "text": "In 1887, Heinrich Hertz discovered the photoelectric effect, where light striking a material causes the emission of electrons, suggesting a particle-like nature of light.",
      "date": "1887"
    },
    {
      "headline": "Albert Einstein's Explanation of the Photoelectric Effect",
      "text": "In 1905, Albert Einstein proposed that light consists of quanta (later called photons) to explain the photoelectric effect, providing evidence for the particle nature of light.",
      "date": "1905"
    },
    {
      "headline": "Louis de Broglie's Hypothesis",
      "text": "In 1924, Louis de Broglie proposed that particles such as electrons also exhibit wave-like properties, introducing the concept of matter waves.",
      "date": "1924"
    },
    {
      "headline": "Davisson-Germer Experiment",
      "text": "In 1927, the Davisson-Germer experiment confirmed de Broglie's hypothesis by demonstrating electron diffraction, showing that electrons exhibit wave-like behavior.",
      "date": "1927"
    },
    {
      "headline": "Niels Bohr's Complementarity Principle",
      "text": "In 1928, Niels Bohr introduced the principle of complementarity, stating that objects have both particle and wave properties, which are complementary and cannot be observed simultaneously.",
      "date": "1928"
    }
  ]
}

