    },
    {
      "headline": "Landfall in Louisiana",
      "text": "On August 29, 2021, Ida made landfall near Port Fourchon, Louisiana, with maximum sustained winds of 150 mph, devastating the town of Grand Isle.",
      "date": "2021-08-29"
    },
    {
      "headline": "Ida Weakens Over Land",
      "text": "Ida weakened steadily over land, becoming a tropical depression on August 30, 2021, as it turned northeastward.",
      "date": "2021-08-30"
    },
    {
      "headline": "Transition to Post-Tropical Cyclone",
      "text": "On September 1, 2021, Ida transitioned into a post-tropical cyclone as it accelerated through the Northeastern United States, causing catastrophic flooding.",
      "date": "2021-09-01"
    },
    {
      "headline": "Remnants Move into the Atlantic",
      "text": "Ida's remnants moved out into the Atlantic on September 2, 2021.",
      "date": "2021-09-02"
    },
