    },
    {
      "headline": "Expansion During the Pacific War",
      "text": "As the Pacific War progressed, the Greater East Asia Co-Prosperity Sphere expanded to include territories in Southeast Asia and parts of India. This expansion was part of Japan's military strategy during World War II.",
      "date": "1941"
    },
    {
      "headline": "Greater East Asia Conference",
      "text": "On November 5-6, 1943, the Greater East Asia Conference was held in Tokyo. It was attended by leaders from Japan, Manchukuo, China, Thailand, Burma, the Philippines, and the Provisional Government of Free India.",
      "date": "1943-11-05"
    },
    {
      "headline": "Dissolution",
      "text": "The Greater East Asia Co-Prosperity Sphere effectively dissolved with Japan's defeat in World War II in 1945. The concept was abandoned as Allied forces occupied Japan and its territories.",
      "date": "1945"
    }
  ]
