{
  "timeline": [
    {
      "headline": "Ancient Origins",
      "text": "The earliest known references to tracheotomy date back to ancient Egypt and India, where it was described in medical texts. The procedure was likely performed in rudimentary forms as early as 3600 BCE.",
      "date": "-3600"
    },
    {
      "headline": "First Documented Tracheotomy",
      "text": "The first documented tracheotomy was performed by the Greek physician Asclepiades of Bithynia in the 2nd century BCE. He is credited with performing the procedure to relieve airway obstruction.",
      "date": "-0200"
    },
    {
      "headline": "Middle Ages Developments",
      "text": "During the Middle Ages, tracheotomy was rarely performed due to the high risk of infection and lack of surgical knowledge, but some physicians like Avicenna mentioned it in their medical writings.",
      "date": "1000"
    },
    {
      "headline": "Renaissance Advancements",
      "text": "In the Renaissance period, medical knowledge expanded, and tracheotomy was revisited by physicians such as Andreas Vesalius, who performed the procedure on animals and described it in his works in the 16th century.",
      "date": "1543"
    },
    {
      "headline": "19th Century Standardization",
      "text": "By the 19th century, tracheotomy became more standardized and safer due to advancements in surgical techniques and antiseptic methods. It was increasingly used to treat diphtheria and other airway obstructions.",
      "date": "1800"
    },
    {
      "headline": "Modern Tracheotomy",
      "text": "In the 20th century, tracheotomy became a common procedure in hospitals worldwide, with improvements in tracheostomy tubes and post-operative care making it safer and more effective.",
      "date": "1900"
    }
  ]
}

