{
  "timeline": [
    {
      "headline": "Ancient Origins",
      "text": "The Grand Trunk Road has its origins in antiquity, dating back to at least 500 BCE. It was a major trade route connecting Central Asia to the Indian subcontinent.",
      "date": "-0500"
    },
    {
      "headline": "Mauryan Empire Expansion",
      "text": "During the Mauryan Empire (322–185 BCE), the road was expanded and improved under the rule of Emperor Chandragupta Maurya and his successors, facilitating trade and communication across the empire.",
      "date": "-0322"
    },
    {
      "headline": "Sher Shah Suri's Renovation",
      "text": "In the 16th century, Sher Shah Suri, the founder of the Suri Empire in North India, renovated and extended the road from the Indus River to Sonargaon in Bengal, making it a vital artery for trade and military movement. This renovation took place around 1540-1545.",
      "date": "1540"
    },
    {
      "headline": "British Colonial Era Enhancements",
      "text": "During the British colonial period in the 19th century, the Grand Trunk Road was further developed and modernized. The British extended the road, improved its surface, and built bridges, making it a key route for the movement of goods and troops.",
      "date": "1800"
    },
    {
      "headline": "Post-Independence Developments",
      "text": "After the independence of India and Pakistan in 1947, the Grand Trunk Road continued to serve as a major highway in both countries, with further improvements and expansions made to accommodate increasing traffic.",
      "date": "1947"
    },
    {
      "headline": "Modern Day Significance",
      "text": "Today, the Grand Trunk Road remains one of the longest and oldest roads in Asia, stretching approximately 3,655 km from Teknaf, Bangladesh to Kabul, Afghanistan, and serving as a vital link for trade and travel across the region.",
      "date": "2023"
    }
  ]
}

