{
  "timeline": [
    {
      "headline": "The Great Alaskan Earthquake Occurs",
      "text": "The 1964 Alaskan earthquake, also known as the Great Alaskan earthquake and Good Friday earthquake, occurred at 5:36 PM AKST on Good Friday, March 27, 1964. It was a megathrust earthquake with a moment magnitude of 9.2, making it the most powerful earthquake recorded in North American history.",
      "date": "1964-03-27"
    },
    {
      "headline": "Impact of the Earthquake",
      "text": "The earthquake caused significant ground fissures, collapsing structures, and tsunamis across south-central Alaska. The resulting destruction led to about 131 deaths.",
      "date": "1964-03-27"
    },
    {
      "headline": "Tsunami Aftermath",
      "text": "The earthquake generated tsunamis that affected not only Alaska but also the west coast of the United States and other areas around the Pacific Ocean. These tsunamis caused additional damage and loss of life.",
      "date": "1964-03-27"
    },
    {
      "headline": "Economic and Structural Damage",
      "text": "The earthquake caused an estimated $311 million in property damage, equivalent to approximately $2.3 billion in 2021 dollars. The destruction included homes, businesses, and infrastructure.",
      "date": "1964-03-27"
    },
    {
      "headline": "Geological Impact",
      "text": "The earthquake caused significant geological changes, including land uplift and subsidence. Some areas were raised by as much as 30 feet, while others sank by several feet.",
      "date": "1964-03-27"
    },
    {
      "headline": "Response and Recovery Efforts",
      "text": "In the aftermath of the earthquake, extensive recovery and rebuilding efforts were undertaken. Federal and state agencies, along with local communities, worked together to provide relief and rebuild affected areas.",
      "date": "1964-03-28"
    }
  ]
}

