{
  "timeline": [
    {
      "headline": "Formulation of Goldbach's Conjecture",
      "text": "Goldbach's conjecture was first proposed by the Prussian mathematician Christian Goldbach in a letter to Leonhard Euler on June 7, 1742. In this letter, Goldbach proposed that every integer greater than 2 can be expressed as the sum of three primes, which Euler reformulated to the modern version: every even integer greater than 2 is the sum of two primes.",
      "date": "1742-06-07"
    },
    {
      "headline": "Euler's Reformulation",
      "text": "Leonhard Euler reformulated Goldbach's original conjecture into the version known today: every even integer greater than 2 can be expressed as the sum of two prime numbers. This reformulation was communicated in his correspondence with Goldbach.",
      "date": "1742"
    },
    {
      "headline": "Verification for Small Numbers",
      "text": "Over the years, mathematicians have verified Goldbach's conjecture for small even numbers using computational methods. By the 20th century, the conjecture had been verified for even numbers up to 4 × 10^18.",
      "date": "20th century"
    },
    {
      "headline": "Vinogradov's Theorem",
      "text": "In 1937, Russian mathematician Ivan Vinogradov proved that every sufficiently large odd integer can be expressed as the sum of three primes. This result indirectly supports the conjecture for large even numbers.",
      "date": "1937"
    },
    {
      "headline": "Chen's Theorem",
      "text": "In 1973, Chinese mathematician Chen Jingrun proved that every sufficiently large even number can be expressed as the sum of a prime and a semiprime (a product of two primes). This result is known as Chen's theorem.",
      "date": "1973"
    },
    {
      "headline": "Verification for Larger Numbers",
      "text": "By 2013, Goldbach's conjecture had been verified for even numbers up to 4 × 10^18 using advanced computational techniques.",
      "date": "2013"
    }
  ]
}

