{
  "timeline": [
    {
      "headline": "Coining of the Term 'Nostalgia'",
      "text": "In the late 17th century, the term 'nostalgia' was coined by Johannes Hofer, a Swiss medical student, to describe the anxieties displayed by Swiss mercenaries fighting away from home. The term is derived from the Greek words νόστος (nóstos), meaning 'homecoming', and ἄλγος (álgos), meaning 'pain'.",
      "date": "1688"
    },
    {
      "headline": "Nostalgia as a Medical Condition",
      "text": "During the early modern period, nostalgia was described as a medical condition, often considered a form of melancholy. It was believed to affect individuals who were away from their homeland for extended periods.",
      "date": "1700"
    },
    {
      "headline": "Nostalgia in Romanticism",
      "text": "In the 19th century, nostalgia became an important trope in Romanticism. It was associated with a longing for the past and an idealization of earlier times, reflecting the Romantic emphasis on emotion and individualism.",
      "date": "1800"
    }
  ]
}

