{
  "timeline": [
    {
      "headline": "Accession to India",
      "text": "On October 26, 1947, the Maharaja of Jammu and Kashmir signed the Instrument of Accession to India, following an invasion by tribal militias and Pakistani forces.",
      "date": "1947-10-26"
    },
    {
      "headline": "First War and Ceasefire",
      "text": "The first Indo-Pakistani War over Kashmir ended with a UN-mediated ceasefire on January 1, 1949, establishing the Line of Control.",
      "date": "1949-01-01"
    },
    {
      "headline": "Adoption of Article 370",
      "text": "In 1950, Article 370 was included in the Indian Constitution, granting special autonomy to Jammu and Kashmir.",
      "date": "1950"
    },
    {
      "headline": "Jammu and Kashmir Constituent Assembly",
      "text": "The Constituent Assembly of Jammu and Kashmir was convened on October 31, 1951, to draft the state's constitution.",
      "date": "1951-10-31"
    },
    {
      "headline": "Jammu and Kashmir Constitution Adopted",
      "text": "On January 26, 1957, the Constitution of Jammu and Kashmir came into effect, formalizing its special status within India.",
      "date": "1957-01-26"
    },
    {
      "headline": "Indo-Pakistani War of 1965",
      "text": "The second Indo-Pakistani War over Kashmir occurred in 1965, resulting in a stalemate and a subsequent ceasefire agreement.",
      "date": "1965"
    },
    {
      "headline": "Indo-Pakistani War of 1971",
      "text": "The third Indo-Pakistani War in 1971 led to the creation of Bangladesh and further tensions over Kashmir.",
      "date": "1971"
    },
    {
      "headline": "Simla Agreement",
      "text": "On July 2, 1972, India and Pakistan signed the Simla Agreement, reaffirming the Line of Control and committing to peaceful resolution of disputes.",
      "date": "1972-07-02"
    },
    {
      "headline": "Insurgency in Kashmir",
      "text": "An armed insurgency began in Jammu and Kashmir in 1989, leading to decades of conflict and unrest in the region.",
      "date": "1989"
    },
    {
      "headline": "Kargil War",
      "text": "The Kargil War between India and Pakistan took place from May to July 1999, resulting in India regaining control of the territory.",
      "date": "1999"
    },
    {
      "headline": "Revocation of Article 370",
      "text": "On August 5, 2019, the Government of India abrogated Article 370, revoking the special status of Jammu and Kashmir and reorganizing it into two Union Territories.",
      "date": "2019-08-05"
    }
  ]
}

