{
  "timeline": [
    {
      "headline": "Maccabean Revolt Begins",
      "text": "In 167 BCE, the Maccabean Revolt began as a Jewish rebellion against the Seleucid Empire and the Hellenistic influence on Jewish life.",
      "date": "-0167"
    },
    {
      "headline": "Mattathias's Leadership",
      "text": "Mattathias, a Jewish priest, initiated the revolt by refusing to worship Greek gods and killing a Hellenistic Jew who stepped forward to do so. This act sparked the uprising in 167 BCE.",
      "date": "-0167"
    },
    {
      "headline": "Judah Maccabee's Leadership",
      "text": "After Mattathias's death in 166 BCE, his son Judah Maccabee took over the leadership of the revolt, leading the Jewish forces to several victories.",
      "date": "-0166"
    },
    {
      "headline": "Rededication of the Second Temple",
      "text": "In 164 BCE, the Maccabees successfully recaptured Jerusalem and rededicated the Second Temple, an event commemorated by the Jewish festival of Hanukkah.",
      "date": "-0164"
    },
    {
      "headline": "Treaty with Rome",
      "text": "In 161 BCE, Judah Maccabee established a treaty with the Roman Republic, seeking support against the Seleucid Empire.",
      "date": "-0161"
    },
    {
      "headline": "Death of Judah Maccabee",
      "text": "Judah Maccabee was killed in battle against the Seleucid forces in 160 BCE, marking a significant moment in the Maccabean Revolt.",
      "date": "-0160"
    },
    {
      "headline": "Jonathan Apphus's Leadership",
      "text": "Jonathan Apphus, another son of Mattathias, took over leadership after Judah's death and continued the struggle for Jewish independence.",
      "date": "-0159"
    },
    {
      "headline": "Simon Thassi's Leadership",
      "text": "In 142 BCE, Simon Thassi, brother of Judah and Jonathan, became the leader of the Maccabees and secured political independence for Judea.",
      "date": "-0142"
    },
    {
      "headline": "Establishment of the Hasmonean Dynasty",
      "text": "In 140 BCE, Simon Thassi was recognized as both the high priest and ruler of Judea, marking the official establishment of the Hasmonean dynasty.",
      "date": "-0140"
    },
    {
      "headline": "Full Independence of Judea",
      "text": "In 104 BCE, Judea became a fully independent kingdom under the Hasmonean dynasty, free from Seleucid control.",
      "date": "-0104"
    },
    {
      "headline": "Roman Conquest of Judea",
      "text": "In 63 BCE, the Roman Republic conquered Judea, ending the Hasmonean dynasty's independence.",
      "date": "-0063"
    },
    {
      "headline": "End of the Hasmonean Dynasty",
      "text": "The Hasmonean dynasty officially ended in 37 BCE when Herod the Great, supported by Rome, became the ruler of Judea.",
      "date": "-0037"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Establishment of Tsinghua University",
      "text": "Tsinghua University was established in 1911 as Tsinghua College in Beijing, China. It was initially a preparatory school for students who would be sent by the government to study in the United States.",
      "date": "1911"
    },
    {
      "headline": "Transition to University",
      "text": "In 1925, Tsinghua College was renamed Tsinghua School and then became Tsinghua University in 1928, marking its transition to a full-fledged university.",
      "date": "1928"
    },
    {
      "headline": "Relocation during the Second Sino-Japanese War",
      "text": "During the Second Sino-Japanese War, Tsinghua University was relocated to Kunming and became part of the National Southwestern Associated University along with Peking University and Nankai University.",
      "date": "1937"
    },
    {
      "headline": "Return to Beijing",
      "text": "After the end of the Second Sino-Japanese War, Tsinghua University returned to its original campus in Beijing in 1946.",
      "date": "1946"
    },
    {
      "headline": "Inclusion in Project 211",
      "text": "Tsinghua University was included in Project 211, a project initiated by the Chinese government in 1995 to strengthen about 100 institutions of higher education and key disciplinary areas as a national priority.",
      "date": "1995"
    },
    {
      "headline": "Inclusion in Project 985",
      "text": "In 1998, Tsinghua University was included in Project 985, a project to promote the development and reputation of the Chinese higher education system by founding world-class universities in the 21st century.",
      "date": "1998"
    },
    {
      "headline": "Double First-Class Initiative",
      "text": "Tsinghua University was selected as a Double First-Class university in 2017, a Chinese government initiative to cultivate an elite group of Chinese universities and individual university departments into world-class institutions by the end of 2050.",
      "date": "2017"
    }
  ]
}

