{
  "timeline": [
    {
      "headline": "First Recorded Claims",
      "text": "The first recorded claims in the South China Sea date back to ancient times, with various Chinese dynasties asserting control over the region. The Han Dynasty (206 BCE – 220 CE) is often cited as the earliest period of Chinese exploration and control.",
      "date": "-0206"
    },
    {
      "headline": "French Colonial Claims",
      "text": "In the late 19th century, France, as the colonial power in Vietnam, began to assert claims over parts of the South China Sea, including the Paracel and Spratly Islands.",
      "date": "1880"
    },
    {
      "headline": "Japanese Occupation",
      "text": "During World War II, Japan occupied several islands in the South China Sea, including the Paracel and Spratly Islands, from 1939 to 1945.",
      "date": "1939"
    },
    {
      "headline": "Post-War Claims",
      "text": "After World War II, China and Vietnam both laid claims to the Paracel and Spratly Islands. The Republic of China (Taiwan) and the People's Republic of China both claimed sovereignty over the islands.",
      "date": "1945"
    },
    {
      "headline": "United Nations Convention on the Law of the Sea (UNCLOS)",
      "text": "The United Nations Convention on the Law of the Sea (UNCLOS) was adopted in 1982, providing a legal framework for maritime boundaries and territorial waters, which impacted claims in the South China Sea.",
      "date": "1982"
    },
    {
      "headline": "China's Nine-Dash Line",
      "text": "In 2009, China submitted a map to the United Nations featuring the 'nine-dash line,' which outlines China's claims to the majority of the South China Sea.",
      "date": "2009"
    },
    {
      "headline": "Philippines v. China Arbitration",
      "text": "In 2013, the Philippines initiated arbitration proceedings against China under UNCLOS. The tribunal ruled in favor of the Philippines in 2016, stating that China's claims to historic rights within the nine-dash line had no legal basis.",
      "date": "2013"
    },
    {
      "headline": "Tribunal Ruling",
      "text": "On July 12, 2016, the Permanent Court of Arbitration in The Hague ruled that China has no legal basis to claim historic rights to resources within the sea areas falling within the 'nine-dash line.'",
      "date": "2016-07-12"
    }
  ]
}

