{
  "timeline": [
    {
      "headline": "Beginning of the Cambrian Explosion",
      "text": "The Cambrian explosion began approximately 538.8 million years ago. This period marked a sudden radiation of complex life forms and the appearance of practically all major animal phyla in the fossil record.",
      "date": "-0538.8"
    },
    {
      "headline": "Diversification of Metazoan Phyla",
      "text": "During the Cambrian explosion, there was a significant divergence of most modern metazoan phyla. This diversification was a key feature of the Cambrian period.",
      "date": "-0538.8"
    },
    {
      "headline": "Major Diversification of Other Organisms",
      "text": "In addition to the diversification of animal phyla, the Cambrian explosion was accompanied by major diversification in other groups of organisms, contributing to the complexity of life forms.",
      "date": "-0538.8"
    },
    {
      "headline": "End of the Cambrian Explosion",
      "text": "The Cambrian explosion lasted for about 13 to 25 million years, concluding around 513.8 to 525.8 million years ago. This period resulted in the establishment of most of the major animal groups that exist today.",
      "date": "-0513.8"
    }
  ]
}

