{
  "timeline": [
    {
      "headline": "Founding of Creative Commons",
      "text": "Creative Commons was founded in 2001 by Lawrence Lessig, Hal Abelson, and Eric Eldred with support from the Center for the Public Domain. The organization was established to provide free licenses and tools that allow creators to make their work available to the public under terms that they choose.",
      "date": "2001"
    },
    {
      "headline": "Release of First Creative Commons Licenses",
      "text": "On December 16, 2002, Creative Commons released its first set of copyright licenses. These licenses allowed creators to communicate which rights they reserved and which rights they waived for the benefit of recipients or other creators.",
      "date": "2002-12-16"
    },
    {
      "headline": "Launch of Creative Commons International",
      "text": "In 2003, Creative Commons launched its internationalization project to adapt the licenses to various legal jurisdictions around the world. This was a significant step in making the licenses applicable globally.",
      "date": "2003"
    },
    {
      "headline": "Creative Commons Version 2.0",
      "text": "In May 2004, Creative Commons released version 2.0 of its licenses. This version included improvements based on feedback from users and legal experts.",
      "date": "2004-05"
    },
    {
      "headline": "Creative Commons Version 3.0",
      "text": "In March 2007, Creative Commons released version 3.0 of its licenses. This version included further refinements and was designed to be more internationally applicable.",
      "date": "2007-03"
    },
    {
      "headline": "Creative Commons Version 4.0",
      "text": "On November 25, 2013, Creative Commons released version 4.0 of its licenses. This version aimed to be more user-friendly and internationally robust, addressing issues such as database rights and moral rights.",
      "date": "2013-11-25"
    },
    {
      "headline": "Creative Commons Global Network",
      "text": "In 2017, Creative Commons launched the Creative Commons Global Network, a community of advocates, activists, and practitioners working to promote the use of open licenses and the sharing of creative works.",
      "date": "2017"
    }
  ]
}

