{
  "timeline": [
    {
      "headline": "Emergence of Zaibatsu",
      "text": "The term 'zaibatsu' refers to industrial and financial conglomerates in Japan that began to emerge during the Meiji period, starting in 1868. These conglomerates played a significant role in the Japanese economy.",
      "date": "1868"
    },
    {
      "headline": "Expansion Post Russo-Japanese War",
      "text": "Following the Russo-Japanese War (1904-1905), the zaibatsu expanded significantly in number and influence, as Japan sought to strengthen its industrial and economic capabilities.",
      "date": "1905"
    },
    {
      "headline": "Growth During World War I",
      "text": "During World War I (1914-1918), the zaibatsu grew further as Japan's economy benefited from supplying goods to the Allies, leading to increased industrial production and economic power.",
      "date": "1918"
    },
    {
      "headline": "Interwar Period Expansion",
      "text": "In the interwar period, the zaibatsu continued to expand as Japan pursued aggressive economic and military policies in East Asia and the Pacific Rim.",
      "date": "1930"
    },
    {
      "headline": "World War II Influence",
      "text": "During World War II (1939-1945), the zaibatsu were instrumental in supporting Japan's war efforts through their industrial and financial resources.",
      "date": "1945"
    },
    {
      "headline": "Dissolution by Allied Forces",
      "text": "After World War II, the Allied occupation forces dissolved the zaibatsu to democratize the Japanese economy and reduce the concentration of economic power.",
      "date": "1945"
    },
    {
      "headline": "Transition to Keiretsu",
      "text": "Following their dissolution, the zaibatsu were succeeded by keiretsu, a new form of corporate grouping that maintained some of the zaibatsu's characteristics but with less centralized control.",
      "date": "1950"
    }
  ]
}

