      "headline": "Birth of Giovanni Maria Mastai-Ferretti",
      "text": "Giovanni Maria Mastai-Ferretti, who would become Pope Pius IX, was born on May 13, 1792, in Senigallia, Papal States.",
      "date": "1792-05-13"
    },
    {
      "headline": "Ordination as Priest",
      "text": "Giovanni Maria Mastai-Ferretti was ordained as a priest on April 10, 1819.",
      "date": "1819-04-10"
    },
    {
      "headline": "Consecration as Bishop",
      "text": "He was consecrated as the Bishop of Spoleto on June 3, 1827.",
      "date": "1827-06-03"
    },
    {
      "headline": "Appointment as Archbishop of Imola",
      "text": "Mastai-Ferretti was appointed as the Archbishop of Imola on December 17, 1832.",
      "date": "1832-12-17"
    },
    {
      "headline": "Creation as Cardinal",
      "text": "He was created a cardinal by Pope Gregory XVI on December 14, 1840.",
      "date": "1840-12-14"
    },
    {
      "headline": "Election as Pope",
      "text": "Giovanni Maria Mastai-Ferretti was elected as Pope Pius IX on June 16, 1846.",
      "date": "1846-06-16"
    },
    {
      "headline": "Proclamation of the Immaculate Conception",
      "text": "Pope Pius IX proclaimed the dogma of the Immaculate Conception on December 8, 1854.",
      "date": "1854-12-08"
    },
    {
      "headline": "Convocation of the First Vatican Council",
      "text": "Pope Pius IX convoked the First Vatican Council on December 8, 1869.",
      "date": "1869-12-08"
    },
    {
      "headline": "Loss of the Papal States",
      "text": "The Papal States were annexed by the Kingdom of Italy on September 20, 1870, leading to Pope Pius IX declaring himself a 'prisoner in the Vatican'.",
      "date": "1870-09-20"
    },
    {
      "headline": "Death of Pope Pius IX",
      "text": "Pope Pius IX died on February 7, 1878, in Vatican City.",
      "date": "1878-02-07"
    }
  ]
}

