{
  "timeline": [
    {
      "headline": "First Partition of Poland",
      "text": "The First Partition of Poland took place on August 5, 1772. The Habsburg monarchy, the Kingdom of Prussia, and the Russian Empire agreed to divide parts of the Polish–Lithuanian Commonwealth among themselves, significantly reducing its territory.",
      "date": "1772-08-05"
    },
    {
      "headline": "Second Partition of Poland",
      "text": "The Second Partition of Poland occurred on January 23, 1793. Russia and Prussia further divided and annexed large portions of the Polish–Lithuanian Commonwealth, leaving it with only one-third of its original size.",
      "date": "1793-01-23"
    },
    {
      "headline": "Third Partition of Poland",
      "text": "The Third Partition of Poland was finalized on October 24, 1795. This partition resulted in the complete dissolution of the Polish–Lithuanian Commonwealth. The remaining territories were divided among the Habsburg monarchy, the Kingdom of Prussia, and the Russian Empire, erasing Poland as a sovereign state.",
      "date": "1795-10-24"
    },
    {
      "headline": "End of Polish Sovereignty",
      "text": "Following the Third Partition in 1795, Poland ceased to exist as an independent nation. The territories were absorbed by the partitioning powers, and Poland would not regain sovereignty until 1918.",
      "date": "1795"
    }
  ]
}

