{
  "timeline": [
    {
      "headline": "Outbreak of the Third Servile War",
      "text": "In 073 BCE, the Third Servile War began when a group of around 70 gladiators, led by Spartacus, Crixus, and Oenomaus, escaped from a gladiatorial training school in Capua.",
      "date": "-0073"
    },
    {
      "headline": "Initial Successes of the Slave Army",
      "text": "Throughout 073 BCE, the escaped gladiators attracted a large number of slaves to their cause, defeating several Roman forces sent to suppress them.",
      "date": "-0073"
    },
    {
      "headline": "Spartacus Defeats Roman Forces",
      "text": "In 072 BCE, Spartacus and his followers defeated the Roman consular armies of Gellius Publicola and Lentulus, further alarming the Roman Senate.",
      "date": "-0072"
    },
    {
      "headline": "Spartacus Moves North",
      "text": "In 072 BCE, Spartacus led his forces northward, possibly intending to cross the Alps and disperse his followers back to their homelands.",
      "date": "-0072"
    },
    {
      "headline": "Roman Response Intensifies",
      "text": "In 071 BCE, the Roman Senate granted Marcus Licinius Crassus command of eight legions to decisively end the rebellion.",
      "date": "-0071"
    },
    {
      "headline": "Battle of the Silarus River",
      "text": "In 071 BCE, Spartacus's forces were decisively defeated by Crassus's legions in the Battle of the Silarus River, leading to the end of the rebellion.",
      "date": "-0071"
    },
    {
      "headline": "Crucifixion of the Rebels",
      "text": "In 071 BCE, following the defeat, approximately 6,000 captured slaves were crucified along the Appian Way from Capua to Rome as a warning to other potential rebels.",
      "date": "-0071"
    }
  ]
}

