{
  "timeline": [
    {
      "headline": "Origin of Triage",
      "text": "The concept of triage originated during the Napoleonic Wars, when French military surgeon Baron Dominique Jean Larrey implemented a system to prioritize the treatment of wounded soldiers based on the severity of their injuries and the likelihood of survival. This system was developed in the early 19th century.",
      "date": "1800"
    },
    {
      "headline": "World War I and Triage",
      "text": "During World War I, the concept of triage was further developed and formalized. Medical personnel used triage to manage the large number of casualties, prioritizing treatment based on urgency and the potential for recovery. This period marked a significant evolution in the practice of triage.",
      "date": "1914"
    },
    {
      "headline": "World War II and Advances in Triage",
      "text": "World War II saw further advancements in triage, with the implementation of more structured systems to manage battlefield casualties. The use of triage expanded beyond military applications to civilian emergency medicine.",
      "date": "1939"
    },
    {
      "headline": "Modern Triage Systems",
      "text": "In the latter half of the 20th century, triage systems became more sophisticated and were integrated into emergency medical services worldwide. These systems are now used in hospitals, disaster response, and emergency medical services to efficiently allocate resources and prioritize patient care.",
      "date": "1950"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "First Periodic Table by Dmitri Mendeleev",
      "text": "In 1869, Dmitri Mendeleev published the first periodic table. He arranged the 63 known elements into a table based on atomic mass, which revealed that elements with similar properties occurred at regular intervals.",
      "date": "1869"
    },
    {
      "headline": "Mendeleev's Periodic Law",
      "text": "In 1871, Mendeleev revised his periodic table and formulated the periodic law, which states that the properties of elements are a periodic function of their atomic masses.",
      "date": "1871"
    },
    {
      "headline": "Discovery of Noble Gases",
      "text": "In the late 1890s, the noble gases were discovered, leading to the addition of a new group to the periodic table.",
      "date": "1890"
    },
    {
      "headline": "Henry Moseley's Atomic Number",
      "text": "In 1913, Henry Moseley determined that the atomic number, not atomic mass, is the basis for the organization of the periodic table, leading to the modern definition of the periodic law.",
      "date": "1913"
    },
    {
      "headline": "Glenn T. Seaborg's Actinide Concept",
      "text": "In 1945, Glenn T. Seaborg proposed the actinide concept, which led to the current layout of the periodic table with the actinide series placed below the lanthanide series.",
      "date": "1945"
    },
    {
      "headline": "International Union of Pure and Applied Chemistry (IUPAC) Standardization",
      "text": "In 1985, IUPAC standardized the periodic table, resolving discrepancies in element names and symbols.",
      "date": "1985"
    },
    {
      "headline": "Inclusion of New Elements",
      "text": "In 2016, the periodic table was updated to include four new elements: nihonium (Nh), moscovium (Mc), tennessine (Ts), and oganesson (Og), completing the seventh period.",
      "date": "2016"
    }
  ]
}

