{
  "timeline": [
    {
      "headline": "Discovery of Enzymes",
      "text": "In 1833, Anselme Payen discovered the first enzyme, diastase, marking the beginning of biochemistry as a distinct scientific discipline.",
      "date": "1833"
    },
    {
      "headline": "Synthesis of Urea",
      "text": "In 1828, Friedrich Wöhler synthesized urea from inorganic compounds, challenging the belief that organic compounds could only be produced by living organisms.",
      "date": "1828"
    },
    {
      "headline": "Discovery of DNA Structure",
      "text": "In 1953, James Watson and Francis Crick discovered the double helix structure of DNA, a pivotal moment in biochemistry and molecular biology.",
      "date": "1953"
    },
    {
      "headline": "Development of the Central Dogma",
      "text": "In 1958, Francis Crick proposed the central dogma of molecular biology, describing the flow of genetic information from DNA to RNA to protein.",
      "date": "1958"
    },
    {
      "headline": "Discovery of the Krebs Cycle",
      "text": "In 1937, Hans Krebs discovered the citric acid cycle (Krebs cycle), a key metabolic pathway that unifies carbohydrate, fat, and protein metabolism.",
      "date": "1937"
    },
    {
      "headline": "Discovery of the Structure of Proteins",
      "text": "In 1958, John Kendrew and Max Perutz determined the structure of myoglobin and hemoglobin, respectively, using X-ray crystallography.",
      "date": "1958"
    },
    {
      "headline": "Discovery of Enzyme Catalysis",
      "text": "In 1897, Eduard Buchner demonstrated that fermentation could occur outside living cells, proving that enzymes can catalyze chemical reactions.",
      "date": "1897"
    },
    {
      "headline": "Discovery of the Genetic Code",
      "text": "In the early 1960s, Marshall Nirenberg and others deciphered the genetic code, determining how sequences of nucleotides in DNA and RNA correspond to amino acids in proteins.",
      "date": "1960"
    },
    {
      "headline": "Development of Recombinant DNA Technology",
      "text": "In the 1970s, scientists developed recombinant DNA technology, allowing for the manipulation of genetic material and the creation of genetically modified organisms.",
      "date": "1970"
    },
    {
      "headline": "Completion of the Human Genome Project",
      "text": "In 2003, the Human Genome Project was completed, mapping the entire human genome and providing a comprehensive understanding of human genetics.",
      "date": "2003"
    }
  ]
}

