{
  "timeline": [
    {
      "headline": "Proposal of the Younger Dryas Impact Hypothesis",
      "text": "The Younger Dryas impact hypothesis was first proposed in 2007. It suggests that the onset of the Younger Dryas cooling period, around 12,900 years ago, was caused by a cosmic impact event.",
      "date": "2007"
    },
    {
      "headline": "Initial Publication and Reception",
      "text": "The hypothesis was initially published in 2007 and received significant attention. However, it was met with skepticism from the scientific community due to a lack of reproducible evidence.",
      "date": "2007"
    },
    {
      "headline": "Criticism and Rejection by Experts",
      "text": "Over the years following its proposal, the Younger Dryas impact hypothesis was widely rejected by experts in relevant fields. Critics compared it to cold fusion due to the lack of reproducibility and evidence.",
      "date": "2007-2010"
    },
    {
      "headline": "Influence of Creationism",
      "text": "The hypothesis has been noted to have influences from creationism, which further contributed to its controversial status among scientists.",
      "date": "2007-2010"
    },
    {
      "headline": "Alternative Explanation for Younger Dryas",
      "text": "The widely accepted explanation for the Younger Dryas cooling period is a significant reduction or shutdown of the North Atlantic Conveyor, caused by a sudden influx of freshwater from Lake Agassiz and deglaciation in North America.",
      "date": "2007-2010"
    }
  ]
}

