      "headline": "Formation of Shinsengumi",
      "text": "The Shinsengumi was formed in 1863 as a special police force to protect the Tokugawa shogunate representatives in Kyoto. It was composed of commoners and low-ranking samurai.",
      "date": "1863"
    },
    {
      "headline": "Ikedaya Incident",
      "text": "On July 8, 1864, the Shinsengumi gained fame for their role in the Ikedaya Incident, where they thwarted a plot by anti-shogunate forces to set fire to Kyoto and assassinate key officials.",
      "date": "1864-07-08"
    },
    {
      "headline": "August 18 Coup",
      "text": "The Shinsengumi played a significant role in the August 18 Coup of 1864, which resulted in the expulsion of the Chōshū clan from the imperial court.",
      "date": "1864-08-18"
    },
    {
      "headline": "Battle of Toba-Fushimi",
      "text": "In January 1868, the Shinsengumi fought in the Battle of Toba-Fushimi, part of the Boshin War, which marked the beginning of the end for the Tokugawa shogunate.",
      "date": "1868-01"
    },
    {
      "headline": "Battle of Kōshū-Katsunuma",
      "text": "On March 29, 1868, the Shinsengumi participated in the Battle of Kōshū-Katsunuma, suffering a defeat against the imperial forces.",
      "date": "1868-03-29"
    },
    {
      "headline": "Battle of Aizu",
      "text": "The Shinsengumi fought in the Battle of Aizu in October 1868, one of the last major battles of the Boshin War.",
      "date": "1868-10"
    },
    {
      "headline": "Disbandment of Shinsengumi",
      "text": "The Shinsengumi was officially disbanded in 1869 following the defeat of the Tokugawa shogunate and the establishment of the Meiji government.",
      "date": "1869"
    }
  ]
}

