    {
      "headline": "Beginning of Second-wave Feminism",
      "text": "Second-wave feminism began in the early 1960s, building on the feminist gains of the late 19th and early 20th centuries. It aimed to increase women's equality throughout the Western world.",
      "date": "1960"
    },
    {
      "headline": "Publication of 'The Feminine Mystique'",
      "text": "In 1963, Betty Friedan published 'The Feminine Mystique', which is often credited with sparking the beginning of second-wave feminism in the United States.",
      "date": "1963"
    },
    {
      "headline": "Formation of the National Organization for Women (NOW)",
      "text": "In 1966, the National Organization for Women (NOW) was founded in the United States to advocate for women's rights and equality.",
      "date": "1966"
    },
    {
      "headline": "Introduction of the Equal Pay Act",
      "text": "The Equal Pay Act was introduced in the United States in 1963, aiming to abolish wage disparity based on sex.",
      "date": "1963"
    },
    {
      "headline": "Publication of 'Sexual Politics'",
      "text": "In 1970, Kate Millett published 'Sexual Politics', a seminal work in feminist literature that critiqued the patriarchy and its influence on society.",
      "date": "1970"
    },
    {
      "headline": "Roe v. Wade Decision",
      "text": "In 1973, the United States Supreme Court issued the Roe v. Wade decision, which legalized abortion nationwide and was a significant victory for women's reproductive rights.",
      "date": "1973"
    },
    {
      "headline": "International Women's Year",
      "text": "The United Nations declared 1975 as International Women's Year, highlighting global issues related to gender equality and women's rights.",
      "date": "1975"
    },
    {
      "headline": "The Feminist Sex Wars",
      "text": "In the early 1980s, the feminist movement experienced internal conflicts known as the feminist sex wars, which revolved around issues of sexuality, pornography, and sexual expression.",
      "date": "1980"
    },
    {
      "headline": "End of Second-wave Feminism",
      "text": "Second-wave feminism began to decline in the early 1980s, eventually being replaced by third-wave feminism in the early 1990s.",
      "date": "1980"
    }
  ]
}

