      "text": "The construction of the Tuileries Palace began on May 22, 1564, under the orders of Queen Catherine de' Medici.",
      "date": "1564-05-22"
    },
    {
      "headline": "Completion of Initial Construction",
      "text": "The initial construction of the Tuileries Palace was completed in 1572, although it underwent several expansions and renovations in subsequent years.",
      "date": "1572"
    },
    {
      "headline": "Expansion under Henry IV",
      "text": "In the early 17th century, King Henry IV expanded the Tuileries Palace, connecting it to the Louvre Palace with the Grande Galerie.",
      "date": "1600"
    },
    {
      "headline": "Louis XIV Moves to Versailles",
      "text": "In 1682, King Louis XIV moved his court to the Palace of Versailles, reducing the significance of the Tuileries Palace as a royal residence.",
      "date": "1682"
    },
    {
      "headline": "Residence of Napoleon Bonaparte",
      "text": "Napoleon Bonaparte made the Tuileries Palace his official residence after becoming Emperor in 1804.",
      "date": "1804"
    },
    {
      "headline": "Restoration of the Monarchy",
      "text": "After the fall of Napoleon, the Tuileries Palace became the residence of the restored Bourbon monarchy in 1814.",
      "date": "1814"
    },
    {
      "headline": "Residence of Louis-Philippe",
      "text": "Louis-Philippe, the last King of France, resided in the Tuileries Palace during his reign from 1830 to 1848.",
      "date": "1830"
    },
    {
      "headline": "Residence of Napoleon III",
      "text": "Napoleon III used the Tuileries Palace as his residence during the Second Empire from 1852 until the fall of his regime in 1870.",
      "date": "1852"
    },
    {
      "headline": "Destruction by the Paris Commune",
      "text": "The Tuileries Palace was set on fire and largely destroyed by the Paris Commune on May 23, 1871.",
      "date": "1871-05-23"
    },
    {
      "headline": "Demolition of the Ruins",
      "text": "The remaining ruins of the Tuileries Palace were demolished in 1883, marking the end of its existence.",
      "date": "1883"
    }
  ]
}

