{
  "timeline": [
    {
      "headline": "Origin of Nixtamalization",
      "text": "The process of nixtamalization is believed to have originated in Mesoamerica around 1500 BCE. This ancient technique involved soaking and cooking maize in an alkaline solution, which improved the nutritional value and flavor of the grain.",
      "date": "-1500"
    },
    {
      "headline": "Spread of Nixtamalization in Mesoamerica",
      "text": "By 1200 BCE, nixtamalization had become a widespread practice among various Mesoamerican cultures, including the Olmecs, Mayans, and Aztecs. This process was essential for the preparation of staple foods such as tortillas and tamales.",
      "date": "-1200"
    },
    {
      "headline": "Introduction to the Spanish",
      "text": "In the 16th century, Spanish colonizers encountered the process of nixtamalization in the Americas. They documented the technique and its benefits, although it was not widely adopted in Europe at the time.",
      "date": "1500"
    },
    {
      "headline": "Scientific Understanding of Nixtamalization",
      "text": "In the 20th century, scientists began to understand the nutritional benefits of nixtamalization, particularly its role in increasing the bioavailability of niacin and preventing pellagra, a disease caused by niacin deficiency.",
      "date": "1900"
    },
    {
      "headline": "Modern Applications of Nixtamalization",
      "text": "Today, nixtamalization is used not only in traditional food preparation but also in industrial processes to produce masa harina, a key ingredient in many Latin American dishes. The process continues to be an important cultural and nutritional practice.",
      "date": "2000"
    }
  ]
}

