{
  "timeline": [
    {
      "headline": "Ancient Birth Control Methods",
      "text": "Various ancient civilizations, including the Egyptians, Greeks, and Romans, used a variety of methods to prevent pregnancy, such as herbal concoctions and barrier methods. These methods date back to ancient times, with some records indicating use as early as 1850 BCE.",
      "date": "-1850"
    },
    {
      "headline": "Publication of 'Ars Amatoria'",
      "text": "In 2 CE, the Roman poet Ovid wrote 'Ars Amatoria', which included advice on contraception, indicating the awareness and use of birth control methods in Roman society.",
      "date": "0002"
    },
    {
      "headline": "Contraceptive Methods in the Middle Ages",
      "text": "During the Middle Ages, various contraceptive methods were used, including coitus interruptus and herbal remedies. However, these methods were often discouraged by religious authorities.",
      "date": "1000"
    },
    {
      "headline": "Development of the Condom",
      "text": "The condom was developed in the 16th century, initially made from linen and later from animal intestines. It was one of the first widely used barrier methods of contraception.",
      "date": "1500"
    },
    {
      "headline": "Invention of the Rubber Condom",
      "text": "In 1855, the first rubber condom was produced following the invention of vulcanized rubber by Charles Goodyear in 1839.",
      "date": "1855"
    },
    {
      "headline": "Margaret Sanger Opens First Birth Control Clinic",
      "text": "In 1916, Margaret Sanger opened the first birth control clinic in the United States in Brooklyn, New York, marking a significant moment in the birth control movement.",
      "date": "1916"
    },
    {
      "headline": "Development of the Birth Control Pill",
      "text": "In 1960, the first oral contraceptive pill, Enovid, was approved by the FDA in the United States, revolutionizing birth control methods.",
      "date": "1960"
    },
    {
      "headline": "Griswold v. Connecticut",
      "text": "In 1965, the U.S. Supreme Court ruled in Griswold v. Connecticut that married couples have the right to use birth control, establishing a legal precedent for privacy in reproductive matters.",
      "date": "1965"
    },
    {
      "headline": "Eisenstadt v. Baird",
      "text": "In 1972, the U.S. Supreme Court extended the right to use birth control to unmarried couples in the Eisenstadt v. Baird decision.",
      "date": "1972"
    },
    {
      "headline": "Introduction of Long-Acting Reversible Contraceptives",
      "text": "In the late 20th century, long-acting reversible contraceptives (LARCs) such as IUDs and implants became more widely available, offering new options for birth control.",
      "date": "1990"
    }
  ]
}

