    {
      "headline": "Planning and Preparation",
      "text": "In the early 1960s, the United States planned a series of high-altitude nuclear tests as part of Operation Fishbowl, which was a subset of Operation Dominic. These tests were intended to study the effects of nuclear explosions in space.",
      "date": "1960"
    },
    {
      "headline": "Operation Fishbowl Initiation",
      "text": "Operation Fishbowl was initiated as part of the larger Operation Dominic series of nuclear tests. The goal was to understand the impact of nuclear detonations in the upper atmosphere and outer space.",
      "date": "1962"
    },
    {
      "headline": "Starfish Prime Launch",
      "text": "On July 9, 1962, Starfish Prime was launched from Johnston Atoll. The test involved a Thor rocket carrying a W49 thermonuclear warhead.",
      "date": "1962-07-09"
    },
    {
      "headline": "Detonation of Starfish Prime",
      "text": "The nuclear device detonated at an altitude of 400 kilometers (250 miles) above the Pacific Ocean. The explosion had a yield of 1.4 megatons.",
      "date": "1962-07-09"
    },
    {
      "headline": "Effects of the Explosion",
      "text": "The explosion created an artificial aurora visible over a wide area, including Hawaii, and caused electromagnetic pulse (EMP) effects that disrupted electrical systems and communications over a large area.",
      "date": "1962-07-09"
    },
    {
      "headline": "Scientific Observations",
      "text": "Starfish Prime provided valuable data on the effects of nuclear explosions in space, including the creation of artificial radiation belts and the impact on satellites.",
      "date": "1962"
    },
    {
      "headline": "Impact on Space Policy",
      "text": "The test highlighted the potential dangers of nuclear explosions in space, contributing to the development of the Partial Test Ban Treaty of 1963, which prohibited nuclear tests in the atmosphere, outer space, and underwater.",
      "date": "1963"
    }
  ]
}

