    {
      "headline": "Construction Initiated",
      "text": "Construction of the Chesapeake Bay Bridge was initiated in the late 1940s under the leadership of William Preston Lane Jr., the 52nd Governor of Maryland, after decades of political indecision and public controversy.",
      "date": "1940"
    },
    {
      "headline": "Original Span Opened",
      "text": "The original span of the Chesapeake Bay Bridge was opened in 1952. At the time, it was the world's longest continuous over-water steel structure, measuring 4 miles (6.4 km) in length.",
      "date": "1952"
    },
    {
      "headline": "Parallel Span Added",
      "text": "A parallel span was added to the Chesapeake Bay Bridge in 1973 to accommodate increased traffic and improve transportation between Maryland's Eastern and Western Shores.",
      "date": "1973"
    }
  ]
}

