{
  "timeline": [
    {
      "headline": "Neolithic Period",
      "text": "The history of agriculture in India dates back to the Neolithic period, which began around 7000 BCE. During this time, early farming communities began to cultivate crops and domesticate animals.",
      "date": "-7000"
    },
    {
      "headline": "Indus Valley Civilization",
      "text": "Around 3300 BCE, the Indus Valley Civilization developed advanced agricultural practices, including irrigation and crop rotation, contributing to their prosperity.",
      "date": "-3300"
    },
    {
      "headline": "Vedic Period",
      "text": "During the Vedic period (1500 BCE - 500 BCE), agriculture was the mainstay of the economy, with references to plowing, irrigation, and various crops in Vedic texts.",
      "date": "-1500"
    },
    {
      "headline": "Maurya Empire",
      "text": "Under the Maurya Empire (322 BCE - 185 BCE), agriculture was highly organized with state control over land and resources, as documented in the Arthashastra.",
      "date": "-0322"
    },
    {
      "headline": "Gupta Empire",
      "text": "The Gupta Empire (c. 320 CE - 550 CE) saw advancements in agricultural techniques and the expansion of cultivated land, contributing to economic prosperity.",
      "date": "0320"
    },
    {
      "headline": "Medieval Period",
      "text": "During the medieval period, new crops such as sugarcane and cotton were introduced, and agricultural practices continued to evolve with the influence of Islamic and European traders.",
      "date": "1000"
    },
    {
      "headline": "British Colonial Period",
      "text": "The British colonial period (1757 - 1947) saw significant changes in Indian agriculture, including the introduction of cash crops like tea, coffee, and indigo, and the establishment of plantations.",
      "date": "1757"
    },
    {
      "headline": "Green Revolution",
      "text": "In the 1960s, the Green Revolution transformed Indian agriculture through the introduction of high-yielding varieties of seeds, increased use of fertilizers, and improved irrigation techniques.",
      "date": "1960"
    },
    {
      "headline": "Economic Survey 2020-21",
      "text": "According to the Indian economic survey 2020-21, agriculture employed more than 50% of the Indian workforce and contributed 20.2% to the country's GDP.",
      "date": "2021"
    }
  ]
}

