{
  "timeline": [
    {
      "headline": "Sandy Hook Elementary School Shooting",
      "text": "On December 14, 2012, Adam Lanza fatally shot his mother before murdering 20 students and six staff members at Sandy Hook Elementary School in Newtown, Connecticut, and later committed suicide.",
      "date": "2012-12-14"
    },
    {
      "headline": "Emergence of Conspiracy Theories",
      "text": "In the immediate aftermath of the shooting, various conspiracy theories began to emerge, claiming that the massacre was a hoax or orchestrated by the U.S. government to promote gun control.",
      "date": "2012-12"
    },
    {
      "headline": "Alex Jones Promotes Conspiracy Theories",
      "text": "Alex Jones, a prominent conspiracy theorist, began promoting theories that the Sandy Hook shooting was staged, contributing significantly to the spread of misinformation.",
      "date": "2013"
    },
    {
      "headline": "Lawsuits Against Conspiracy Theorists",
      "text": "Families of the victims began filing lawsuits against conspiracy theorists, including Alex Jones, for defamation and emotional distress caused by false claims about the shooting.",
      "date": "2018"
    },
    {
      "headline": "Alex Jones Found Liable",
      "text": "In 2021, Alex Jones was found liable in several defamation lawsuits filed by the families of Sandy Hook victims due to his false claims about the shooting.",
      "date": "2021"
    },
    {
      "headline": "Alex Jones Ordered to Pay Damages",
      "text": "In 2022, Alex Jones was ordered to pay nearly $1 billion in damages to the families of the Sandy Hook victims for spreading false conspiracy theories about the shooting.",
      "date": "2022"
    }
  ]
}

