    },
    {
      "headline": "NBA Rookie of the Year",
      "text": "Brogdon won the NBA Rookie of the Year Award for the 2016–17 season, becoming the first second-round pick to win the award since 1965.",
      "date": "2017"
    },
    {
      "headline": "50–40–90 Season Achievement",
      "text": "In 2019, Brogdon became the eighth player in NBA history to achieve a 50–40–90 season, a mark of shooting efficiency.",
      "date": "2019"
    },
    {
      "headline": "Trade to Indiana Pacers",
      "text": "In the 2019 off-season, Malcolm Brogdon was traded to the Indiana Pacers.",
      "date": "2019"
    },
    {
      "headline": "Trade to Boston Celtics",
      "text": "Malcolm Brogdon was traded to the Boston Celtics in 2022.",
      "date": "2022"
    },
    {
      "headline": "NBA Sixth Man of the Year",
      "text": "Brogdon won the NBA Sixth Man of the Year award in 2023 while playing for the Boston Celtics.",
      "date": "2023"
    }
