{
  "timeline": [
    {
      "headline": "Founding of Al-Azhar Mosque",
      "text": "The Al-Azhar Mosque was founded in 970 CE by the Fatimid Caliph Al-Mu'izz li-Din Allah as a center for Islamic learning.",
      "date": "0970"
    },
    {
      "headline": "Establishment of Al-Azhar University",
      "text": "Al-Azhar University was established in 988 CE as a center for Islamic learning, making it one of the oldest universities in the world.",
      "date": "0988"
    },
    {
      "headline": "Expansion of Curriculum",
      "text": "During the 12th century, the curriculum at Al-Azhar was expanded to include a wide range of Islamic sciences, including jurisprudence, theology, and Arabic grammar.",
      "date": "1100"
    },
    {
      "headline": "Ottoman Influence",
      "text": "In the 16th century, under Ottoman rule, Al-Azhar gained prominence as a center for Sunni Islamic scholarship.",
      "date": "1500"
    },
    {
      "headline": "Modern Reforms",
      "text": "In the 19th century, Al-Azhar underwent significant reforms to modernize its curriculum and administration, including the introduction of secular subjects.",
      "date": "1800"
    },
    {
      "headline": "Nationalization of Al-Azhar",
      "text": "In 1961, Al-Azhar University was nationalized and restructured to include faculties of medicine, engineering, and agriculture, alongside traditional Islamic studies.",
      "date": "1961"
    },
    {
      "headline": "Expansion of Educational Network",
      "text": "By 1996, Al-Azhar University oversaw a national network of schools with approximately two million students and over 4,000 teaching institutes affiliated with the university.",
      "date": "1996"
    }
  ]
}

