{
  "timeline": [
    {
      "headline": "Girolamo Fracastoro Proposes Contagion Theory",
      "text": "In 1546, Girolamo Fracastoro proposed that epidemic diseases are caused by transferable seed-like entities, which he called 'seminaria'. This was an early precursor to the germ theory of disease.",
      "date": "1546"
    },
    {
      "headline": "Antonie van Leeuwenhoek Observes Microorganisms",
      "text": "In 1676, Antonie van Leeuwenhoek used a microscope to observe microorganisms, which he referred to as 'animalcules'. This was one of the first observations of bacteria and other microorganisms.",
      "date": "1676"
    },
    {
      "headline": "Agostino Bassi Demonstrates Fungal Infection",
      "text": "In 1835, Agostino Bassi showed that a silkworm disease was caused by a fungal infection, providing evidence that microorganisms could cause disease.",
      "date": "1835"
    },
    {
      "headline": "Ignaz Semmelweis Advocates Handwashing",
      "text": "In 1847, Ignaz Semmelweis demonstrated that handwashing with chlorinated lime solutions reduced the incidence of puerperal fever in obstetrical clinics, suggesting that disease could be spread by contaminated hands.",
      "date": "1847"
    },
    {
      "headline": "John Snow Investigates Cholera Outbreak",
      "text": "In 1854, John Snow conducted a study of a cholera outbreak in London, tracing the source to a contaminated water pump. This was an important step in understanding the transmission of infectious diseases.",
      "date": "1854"
    },
    {
      "headline": "Louis Pasteur Develops Germ Theory",
      "text": "In the 1860s, Louis Pasteur conducted experiments that supported the germ theory of disease, demonstrating that microorganisms were responsible for fermentation and spoilage.",
      "date": "1860"
    },
    {
      "headline": "Joseph Lister Introduces Antiseptic Surgery",
      "text": "In 1867, Joseph Lister published his work on antiseptic surgery, using carbolic acid to sterilize surgical instruments and clean wounds, significantly reducing surgical infections.",
      "date": "1867"
    },
    {
      "headline": "Robert Koch Identifies Anthrax Bacillus",
      "text": "In 1876, Robert Koch identified the bacterium Bacillus anthracis as the cause of anthrax, providing strong evidence for the germ theory of disease.",
      "date": "1876"
    },
    {
      "headline": "Koch's Postulates Formulated",
      "text": "In 1890, Robert Koch formulated his postulates, a series of criteria designed to establish a causative relationship between a microbe and a disease.",
      "date": "1890"
    }
  ]
}

