{
  "timeline": [
    {
      "headline": "Old Frisian Period",
      "text": "The Old Frisian period is generally considered to have lasted from around 1150 to 1550. During this time, the Frisian language was used in legal documents and literature.",
      "date": "1150"
    },
    {
      "headline": "Middle Frisian Period",
      "text": "The Middle Frisian period lasted from 1550 to 1800. This period saw a decline in the use of Frisian as a written language, largely due to the influence of Dutch.",
      "date": "1550"
    },
    {
      "headline": "Modern Frisian Period",
      "text": "The Modern Frisian period began around 1800 and continues to the present day. Efforts to revive and standardize the Frisian languages have been ongoing, with Frisian being recognized as an official language in Friesland, Netherlands.",
      "date": "1800"
    },
    {
      "headline": "Recognition of Frisian as an Official Language",
      "text": "In 1956, Frisian was recognized as an official language in the province of Friesland, Netherlands, which marked a significant step in the preservation and promotion of the language.",
      "date": "1956"
    },
    {
      "headline": "European Charter for Regional or Minority Languages",
      "text": "In 1996, the Frisian language was recognized under the European Charter for Regional or Minority Languages, which aims to protect and promote historical regional and minority languages in Europe.",
      "date": "1996"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Early Use of Stop Motion",
      "text": "The first known use of stop motion animation was in the late 19th century. The technique was used in the 1898 short film 'The Humpty Dumpty Circus' by J. Stuart Blackton and Albert E. Smith.",
      "date": "1898"
    },
    {
      "headline": "Development of Stop Motion Techniques",
      "text": "In 1902, the film 'Fun in a Bakery Shop' showcased early stop motion techniques, using clay to create animated sequences.",
      "date": "1902"
    },
    {
      "headline": "Pioneering Stop Motion Film",
      "text": "In 1907, the film 'The Haunted Hotel' by J. Stuart Blackton became a pioneering work in stop motion animation, gaining significant popularity.",
      "date": "1907"
    },
    {
      "headline": "Introduction of Clay Animation",
      "text": "In 1916, the film 'Modeling Extraordinary' by Helena Smith Dayton was one of the first to use clay animation, a subset of stop motion.",
      "date": "1916"
    },
    {
      "headline": "King Kong and Stop Motion",
      "text": "The 1933 film 'King Kong' featured groundbreaking stop motion animation by Willis O'Brien, which became a landmark in the use of the technique for special effects.",
      "date": "1933"
    },
    {
      "headline": "Ray Harryhausen's Influence",
      "text": "Ray Harryhausen, a prominent figure in stop motion animation, began his career in the 1940s and became known for his work on films like 'Jason and the Argonauts' (1963).",
      "date": "1940"
    },
    {
      "headline": "Advent of Claymation",
      "text": "In the 1970s, the term 'claymation' was coined by Will Vinton, who popularized the use of clay in stop motion animation with films like 'Closed Mondays' (1974).",
      "date": "1974"
    },
    {
      "headline": "Stop Motion in Music Videos",
      "text": "The 1980s saw the use of stop motion in music videos, notably in Peter Gabriel's 'Sledgehammer' (1986), which became famous for its innovative animation techniques.",
      "date": "1986"
    },
    {
      "headline": "Revival of Stop Motion in Feature Films",
      "text": "The 1990s and 2000s saw a revival of stop motion in feature films, with notable works like 'The Nightmare Before Christmas' (1993) and 'Coraline' (2009).",
      "date": "1993"
    },
    {
      "headline": "Modern Stop Motion Achievements",
      "text": "In the 2010s, stop motion continued to thrive with films like 'Kubo and the Two Strings' (2016), showcasing advanced techniques and storytelling.",
      "date": "2016"
    }
  ]
}

