{
  "timeline": [
    {
      "headline": "Formation of 3. Liga",
      "text": "The 3. Liga was formed as a new third tier in the German football league system, positioned between the 2. Bundesliga and the Regionalliga. This was part of a restructuring of the league system by the German Football Association (DFB).",
      "date": "2008"
    },
