{
  "timeline": [
    {
      "headline": "Genghis Khan Unites the Mongol Tribes",
      "text": "In 1206, Genghis Khan united the Mongol tribes and was proclaimed the leader of the Mongols, marking the beginning of the Mongol Empire.",
      "date": "1206"
    },
    {
      "headline": "Conquest of the Western Xia",
      "text": "Between 1209 and 1210, Genghis Khan launched a successful campaign against the Western Xia, a Tangut state in northwestern China.",
      "date": "1209"
    },
    {
      "headline": "Invasion of the Khwarazmian Empire",
      "text": "In 1219, Genghis Khan launched an invasion of the Khwarazmian Empire, which covered parts of present-day Iran, Turkmenistan, Uzbekistan, and Kazakhstan.",
      "date": "1219"
    },
    {
      "headline": "Conquest of the Khwarazmian Empire",
      "text": "By 1221, the Mongols had successfully conquered the Khwarazmian Empire, completing one of their most significant early conquests.",
      "date": "1221"
    },
    {
      "headline": "Mongol Invasion of the Caucasus and Eastern Europe",
      "text": "In 1223, the Mongols defeated a coalition of Russian princes at the Battle of the Kalka River, marking the beginning of Mongol incursions into Eastern Europe.",
      "date": "1223"
    },
    {
      "headline": "Death of Genghis Khan",
      "text": "Genghis Khan died in 1227 during a campaign against the Western Xia. His death marked a significant transition in Mongol leadership.",
      "date": "1227"
    },
    {
      "headline": "Ogedei Khan's Reign",
      "text": "Ogedei Khan, Genghis Khan's third son, was elected as the Great Khan in 1229, continuing the expansion of the Mongol Empire.",
      "date": "1229"
    },
    {
      "headline": "Mongol Invasion of the Jin Dynasty",
      "text": "In 1234, the Mongols completed their conquest of the Jin Dynasty in northern China, further expanding their empire.",
      "date": "1234"
    },
    {
      "headline": "Mongol Invasion of Europe",
      "text": "In 1236, the Mongols began their invasion of Europe, starting with the Volga Bulgars and Kievan Rus'.",
      "date": "1236"
    },
    {
      "headline": "Battle of Legnica",
      "text": "In 1241, the Mongols defeated a European coalition at the Battle of Legnica in Poland, demonstrating their military prowess in Europe.",
      "date": "1241"
    },
    {
      "headline": "Battle of Mohi",
      "text": "Also in 1241, the Mongols defeated the Kingdom of Hungary at the Battle of Mohi, furthering their European campaign.",
      "date": "1241"
    },
    {
      "headline": "Death of Ogedei Khan",
      "text": "Ogedei Khan died in 1241, leading to a temporary halt in Mongol expansion as the empire focused on succession.",
      "date": "1241"
    },
    {
      "headline": "Mongol Invasion of the Song Dynasty",
      "text": "In 1259, the Mongols began their invasion of the Song Dynasty in southern China, which would eventually lead to the unification of China under Mongol rule.",
      "date": "1259"
    },
    {
      "headline": "Kublai Khan Becomes Great Khan",
      "text": "In 1260, Kublai Khan was declared the Great Khan, and he continued the expansion of the Mongol Empire, particularly in China.",
      "date": "1260"
    },
    {
      "headline": "Fall of the Song Dynasty",
      "text": "In 1279, the Mongols completed their conquest of the Song Dynasty, establishing the Yuan Dynasty in China under Kublai Khan.",
      "date": "1279"
    },
    {
      "headline": "End of the Mongol Empire",
      "text": "By 1368, the Mongol Empire had fragmented and lost control over China, marking the end of the Yuan Dynasty and the Mongol Empire's dominance.",
      "date": "1368"
    }
  ]
}

