{
  "timeline": [
    {
      "headline": "Beginning of the Vedic Period",
      "text": "The Vedic period is generally dated from approximately 1500 BCE to 500 BCE. This era marks the composition of the Vedas, the oldest sacred texts of the Vedic religion.",
      "date": "-1500"
    },
    {
      "headline": "Composition of the Rigveda",
      "text": "The Rigveda, the oldest of the Vedas, was composed around 1500 BCE to 1200 BCE. It consists of hymns dedicated to various deities and is a central text of the Vedic religion.",
      "date": "-1500"
    },
    {
      "headline": "Composition of the Samaveda",
      "text": "The Samaveda, which is primarily a collection of melodies and chants, was composed around 1200 BCE to 1000 BCE. It is used in Vedic rituals and ceremonies.",
      "date": "-1200"
    },
    {
      "headline": "Composition of the Yajurveda",
      "text": "The Yajurveda, containing prose mantras for rituals, was composed around 1200 BCE to 1000 BCE. It provides instructions for the performance of sacrificial rituals.",
      "date": "-1200"
    },
    {
      "headline": "Composition of the Atharvaveda",
      "text": "The Atharvaveda, composed around 1000 BCE, includes hymns, spells, and incantations, reflecting the more personal and domestic aspects of Vedic religion.",
      "date": "-1000"
    },
    {
      "headline": "Development of the Brahmanas",
      "text": "The Brahmanas, prose texts that explain the hymns in the Vedas and detail the rituals, were composed around 900 BCE to 700 BCE.",
      "date": "-0900"
    },
    {
      "headline": "Composition of the Aranyakas and Upanishads",
      "text": "The Aranyakas and Upanishads, philosophical texts that explore the spiritual ideas of the Vedic religion, were composed around 800 BCE to 500 BCE.",
      "date": "-0800"
    },
    {
      "headline": "End of the Vedic Period",
      "text": "The Vedic period is considered to have ended around 500 BCE, transitioning into the period of the Upanishads and the development of classical Hinduism.",
      "date": "-0500"
    }
  ]
}

