    {
      "headline": "First Inhabitants",
      "text": "The first known inhabitants of Saba were the Ciboney people, who were later replaced by the Arawak and Carib peoples. The exact dates of these settlements are not precisely known, but they occurred before European contact.",
      "date": "-1000"
    },
    {
      "headline": "Christopher Columbus Sighting",
      "text": "Christopher Columbus is believed to have sighted Saba on November 13, 1493, during his second voyage to the New World, although he did not land on the island.",
      "date": "1493-11-13"
    },
    {
      "headline": "First European Settlement Attempt",
      "text": "In 1632, a group of shipwrecked Englishmen landed on Saba and attempted to establish a settlement, but they were soon driven off by the indigenous Caribs.",
      "date": "1632"
    },
    {
      "headline": "Dutch Colonization",
      "text": "The Dutch claimed Saba in 1640, and it became part of the Dutch West India Company’s territory. The island was used primarily for agriculture and as a base for privateering.",
      "date": "1640"
    },
    {
      "headline": "Pirate Haven",
      "text": "During the 17th and 18th centuries, Saba was known as a haven for pirates, who used the island’s rugged terrain to hide from authorities.",
      "date": "1700"
    },
    {
      "headline": "British Occupation",
      "text": "The British occupied Saba several times during the 18th century, including a notable period from 1781 to 1784, during the Fourth Anglo-Dutch War.",
      "date": "1781"
    },
    {
      "headline": "Return to Dutch Control",
      "text": "Saba was returned to Dutch control in 1816 after the Napoleonic Wars, as part of the Treaty of Paris.",
      "date": "1816"
    },
    {
      "headline": "Establishment of the Saba Lace Industry",
      "text": "In the late 19th century, the Saba lace industry was established, becoming an important economic activity for the island.",
      "date": "1870"
    },
    {
      "headline": "Construction of The Road",
      "text": "The construction of 'The Road', a major engineering feat on Saba, began in 1938 and was completed in 1958, connecting the island's settlements and improving transportation.",
      "date": "1938"
    },
    {
      "headline": "Saba Becomes a Special Municipality",
      "text": "On October 10, 2010, Saba became a special municipality of the Netherlands, following the dissolution of the Netherlands Antilles.",
      "date": "2010-10-10"
    }
  ]
}

