{
  "timeline": [
    {
      "headline": "Origins of Bloodletting",
      "text": "Bloodletting is believed to have originated in ancient Egypt around 3000 BCE, where it was used to balance the humours in the body.",
      "date": "-3000"
    },
    {
      "headline": "Hippocratic Influence",
      "text": "Around 400 BCE, Hippocrates, the Greek physician, incorporated bloodletting into the humoral theory of medicine, which posited that health depended on the balance of four bodily fluids.",
      "date": "-0400"
    },
    {
      "headline": "Galen's Advocacy",
      "text": "In the 2nd century CE, Galen, a prominent Greek physician in the Roman Empire, popularized bloodletting as a treatment for various ailments, solidifying its place in Western medicine.",
      "date": "0150"
    },
    {
      "headline": "Medieval Practice",
      "text": "During the Middle Ages, bloodletting became a common medical practice in Europe, often performed by barber-surgeons.",
      "date": "1100"
    },
    {
      "headline": "Renaissance and Continued Use",
      "text": "In the Renaissance period, bloodletting continued to be widely practiced, with physicians like Andreas Vesalius and Ambroise Paré discussing its use.",
      "date": "1500"
    },
    {
      "headline": "19th Century Criticism",
      "text": "In the early 19th century, medical studies began to show the harmful effects of bloodletting, leading to growing criticism of the practice.",
      "date": "1800"
    },
    {
      "headline": "Decline of Bloodletting",
      "text": "By the late 19th century, bloodletting had largely fallen out of favor in modern medicine, except for a few specific conditions like hemochromatosis and polycythemia.",
      "date": "1890"
    }
  ]
}

