{
  "timeline": [
    {
      "headline": "Early Settlement",
      "text": "The presence of Jews in Yemen dates back to antiquity, with some traditions suggesting that Jews settled in Yemen during the time of King Solomon, around the 10th century BCE.",
      "date": "-1000"
    },
    {
      "headline": "Himyarite Kingdom Conversion",
      "text": "In the 4th century CE, the Himyarite Kingdom, which ruled over Yemen, converted to Judaism.",
      "date": "0300"
    },
    {
      "headline": "Islamic Conquest",
      "text": "In the 7th century, Yemen was conquered by Muslim armies, and the Jewish community came under Islamic rule.",
      "date": "0630"
    },
    {
      "headline": "Maimonides' Letter",
      "text": "In 1173, Maimonides wrote a famous letter to the Jews of Yemen, offering them support and guidance during a time of persecution.",
      "date": "1173"
    },
    {
      "headline": "Ottoman Rule",
      "text": "In the 16th century, Yemen came under Ottoman rule, which lasted intermittently until the early 20th century, affecting the Jewish community's status and conditions.",
      "date": "1500"
    },
    {
      "headline": "Dhimmi Status",
      "text": "Throughout the centuries under Islamic rule, Yemenite Jews lived as dhimmis, a protected but second-class status, which imposed certain restrictions and taxes.",
      "date": "1800"
    },
    {
      "headline": "Operation Magic Carpet",
      "text": "Between June 1949 and September 1950, the majority of Yemenite Jews were airlifted to Israel in Operation Magic Carpet, also known as Operation On Wings of Eagles.",
      "date": "1949-06"
    },
    {
      "headline": "Final Emigration",
      "text": "By 2024, only one Jew, Levi Marhabi, remains in Yemen, marking the near-complete emigration of Yemenite Jews from their historical homeland.",
      "date": "2024"
    }
  ]
}

