{
  "timeline": [
    {
      "headline": "Foundation of Ancient Corinth",
      "text": "Ancient Corinth was founded in the Neolithic period, around 6500 BCE, and became a significant city-state in ancient Greece.",
      "date": "-6500"
    },
    {
      "headline": "Rise of Corinth as a Major City-State",
      "text": "By the 8th century BCE, Corinth had become one of the major city-states of ancient Greece, known for its wealth and strategic location.",
      "date": "-0800"
    },
    {
      "headline": "Rule of the Bacchiadae",
      "text": "From around 747 BCE, the Bacchiadae, a powerful aristocratic family, ruled Corinth, establishing an oligarchic government.",
      "date": "-0747"
    },
    {
      "headline": "Cypselus Overthrows the Bacchiadae",
      "text": "In 657 BCE, Cypselus overthrew the Bacchiadae and established a tyranny, marking the beginning of the Cypselid dynasty.",
      "date": "-0657"
    },
    {
      "headline": "Periander's Rule",
      "text": "Periander, son of Cypselus, ruled Corinth from 627 BCE to 585 BCE, and under his rule, Corinth reached the height of its power and prosperity.",
      "date": "-0627"
    },
    {
      "headline": "Corinth Joins the Peloponnesian League",
      "text": "In the 6th century BCE, Corinth became a member of the Peloponnesian League, aligning itself with Sparta.",
      "date": "-0600"
    },
    {
      "headline": "Corinthian War",
      "text": "From 395 to 387 BCE, Corinth was involved in the Corinthian War against Sparta, alongside Athens, Thebes, and Argos.",
      "date": "-0395"
    },
    {
      "headline": "Destruction by the Romans",
      "text": "In 146 BCE, Corinth was destroyed by the Roman general Lucius Mummius, marking the end of the ancient city-state.",
      "date": "-0146"
    },
    {
      "headline": "Reestablishment by Julius Caesar",
      "text": "In 44 BCE, Julius Caesar refounded Corinth as a Roman colony, leading to its revival and prosperity under Roman rule.",
      "date": "-0044"
    }
  ]
}

