    {
      "headline": "Development of Mk 12 SPR",
      "text": "The Mk 12 Special Purpose Rifle was developed as a designated marksman rifle for the United States Special Operations Forces. Initially, it was designed as an add-on upper receiver assembly, known as the Special Purpose Receiver.",
      "date": "1990s"
    },
    {
      "headline": "Transition to Stand-Alone Weapon",
      "text": "The nomenclature changed from Special Purpose Receiver to Special Purpose Rifle as the Mk 12 became a stand-alone weapons system.",
      "date": "2000s"
    },
    {
      "headline": "Service with United States Special Operations Forces",
      "text": "The Mk 12 SPR was in service with United States Special Operations Forces in the designated marksman role.",
      "date": "2000s-2017"
    },
    {
      "headline": "Retirement from Service",
      "text": "The Mk 12 Special Purpose Rifle was retired from service in 2017.",
      "date": "2017"
    }
  ]
}

{
