{
  "timeline": [
    {
      "headline": "Formation of Jodeci",
      "text": "Jodeci was formed in 1988 in Charlotte, North Carolina. The group began as a duo of DeVanté Swing and JoJo, but later each added their brothers, Mr. Dalvin and K-Ci.",
      "date": "1988"
    },
    {
      "headline": "Signing with Uptown Records",
      "text": "In 1990, Jodeci signed with Uptown Records, marking the beginning of their professional music career.",
      "date": "1990"
    },
    {
      "headline": "Release of Debut Album 'Forever My Lady'",
      "text": "Jodeci released their debut album 'Forever My Lady' in 1991. The album brought them mainstream success with three straight Billboard R&B No. 1 hit singles: the album's titular track, 'Stay', and 'Come and Talk to Me'.",
      "date": "1991"
    },
    {
      "headline": "Release of Second Album 'Diary of a Mad Band'",
      "text": "In 1993, Jodeci released their second album, 'Diary of a Mad Band', which continued their success in the R&B genre.",
      "date": "1993"
    },
    {
      "headline": "Release of Third Album 'The Show, the After Party, the Hotel'",
      "text": "Jodeci released their third album, 'The Show, the After Party, the Hotel', in 1995, further solidifying their place in the R&B music scene.",
      "date": "1995"
    },
    {
      "headline": "Hiatus and Solo Projects",
      "text": "Following their third album, Jodeci went on a hiatus, during which members pursued solo projects and collaborations.",
      "date": "1996"
    },
    {
      "headline": "Reunion and Release of 'The Past, the Present, the Future'",
      "text": "Jodeci reunited and released their fourth studio album, 'The Past, the Present, the Future', in 2015, marking their return to the music industry after nearly two decades.",
      "date": "2015"
    }
  ]
}

