      "headline": "World War II Production",
      "text": "During World War II, the revolver was produced as the Smith & Wesson Victory Model, used extensively by Allied forces.",
      "date": "1940"
    },
    {
      "headline": "Post-War Production Resumption",
      "text": "After World War II, production of the revolver resumed under its civilian name, the Smith & Wesson Model 10.",
      "date": "1945"
    },
    {
      "headline": "Most-Produced Handgun of the 20th Century",
      "text": "By the end of the 20th century, the Smith & Wesson Model 10 had become the most-produced handgun of the century, with over 6,000,000 units manufactured.",
      "date": "2000"
    }
  ]
