{
  "timeline": [
    {
      "headline": "Establishment of Georgia Tech",
      "text": "The Georgia Institute of Technology was established on October 13, 1885, as part of Reconstruction plans to build an industrial economy in the post-Civil War Southern United States.",
      "date": "1885-10-13"
    },
    {
      "headline": "Opening of Georgia Tech",
      "text": "Georgia Tech opened its doors to students on October 8, 1888, with two buildings. The school initially offered only a degree in mechanical engineering.",
      "date": "1888-10-08"
    },
    {
      "headline": "First Graduating Class",
      "text": "In 1890, Georgia Tech graduated its first class of students, consisting of two graduates.",
      "date": "1890"
    },
    {
      "headline": "Expansion of Academic Programs",
      "text": "By 1901, Georgia Tech had expanded its academic offerings to include electrical, civil, and chemical engineering.",
      "date": "1901"
    },
    {
      "headline": "Establishment of the Evening School of Commerce",
      "text": "In 1912, Georgia Tech established the Evening School of Commerce, which later became Georgia State University.",
      "date": "1912"
    },
    {
      "headline": "Georgia Tech's First Female Students",
      "text": "In 1952, Georgia Tech admitted its first female students to regular classes.",
      "date": "1952"
    },
    {
      "headline": "Desegregation of Georgia Tech",
      "text": "In 1961, Georgia Tech became the first university in the Deep South to desegregate without a court order, admitting three African American students.",
      "date": "1961"
    },
    {
      "headline": "Establishment of Georgia Tech Savannah",
      "text": "In 1999, Georgia Tech established a satellite campus in Savannah, Georgia, to expand its educational reach.",
      "date": "1999"
    },
    {
      "headline": "Opening of Georgia Tech Lorraine",
      "text": "Georgia Tech Lorraine, a satellite campus in Metz, France, was established in 1990 to provide international education opportunities.",
      "date": "1990"
    }
  ]
}

