{
  "timeline": [
    {
      "headline": "Creation of HP Sauce",
      "text": "HP Sauce was created by Frederick Gibson Garton, a grocer from Nottingham, England, in the late 19th century. The exact year is not specified, but it was during this period that the sauce first appeared on British dinner tables.",
      "date": "1890"
    },
    {
      "headline": "Trademark Registration",
      "text": "Frederick Gibson Garton registered the name HP Sauce in 1895. The name was inspired by the Houses of Parliament in London.",
      "date": "1895"
    },
    {
      "headline": "Sale to Edwin Samson Moore",
      "text": "In 1903, Frederick Gibson Garton sold the recipe and brand to Edwin Samson Moore, the owner of the Midland Vinegar Company, due to financial difficulties.",
      "date": "1903"
    },
    {
      "headline": "Production in Aston, Birmingham",
      "text": "HP Sauce began production at the Midland Vinegar Company's factory in Aston, Birmingham, in the early 20th century.",
      "date": "1903"
    },
    {
