      "headline": "Birth of Duleep Singh",
      "text": "Duleep Singh was born on 1838-09-06 in Lahore, Punjab, which was then part of the Sikh Empire.",
      "date": "1838-09-06"
    },
    {
      "headline": "Ascension to the Throne",
      "text": "Duleep Singh became the Maharaja of the Sikh Empire on 1843-09-18, following the death of his father, Maharaja Ranjit Singh, and the subsequent political turmoil.",
      "date": "1843-09-18"
    },
    {
      "headline": "Treaty of Lahore",
      "text": "On 1846-03-09, the Treaty of Lahore was signed, marking the end of the First Anglo-Sikh War and leading to significant territorial concessions by the Sikh Empire.",
      "date": "1846-03-09"
    },
    {
      "headline": "Annexation of the Sikh Empire",
      "text": "The Sikh Empire was annexed by the British East India Company on 1849-03-29, following the Second Anglo-Sikh War, and Duleep Singh was deposed.",
      "date": "1849-03-29"
    },
    {
      "headline": "Relocation to England",
      "text": "In 1854, Duleep Singh was relocated to England, where he was received by Queen Victoria and became a favorite of the British royal family.",
      "date": "1854"
    },
    {
      "headline": "Conversion to Christianity",
      "text": "Duleep Singh converted to Christianity on 1853-03-08, a decision that was influenced by his guardians and the British government.",
      "date": "1853-03-08"
    },
    {
      "headline": "Marriage to Bamba Müller",
      "text": "Duleep Singh married Bamba Müller on 1864-06-07 in Alexandria, Egypt. Bamba was of German and Ethiopian descent.",
      "date": "1864-06-07"
    },
    {
      "headline": "Return to India Attempt",
      "text": "In 1886, Duleep Singh attempted to return to India to reclaim his heritage and title, but was stopped by the British government.",
      "date": "1886"
    },
    {
      "headline": "Death of Duleep Singh",
      "text": "Duleep Singh died on 1893-10-22 in Paris, France, after spending his final years in relative obscurity and financial difficulty.",
      "date": "1893-10-22"
    }
  ]
}

