    {
      "headline": "First Settlement",
      "text": "The area of present-day Podgorica has been inhabited since the Illyrian and Roman periods. The earliest known settlement was established by the Illyrians.",
      "date": "-0020"
    },
    {
      "headline": "Roman Period",
      "text": "During the Roman period, the settlement was known as Birziminium and was an important stop on the trade routes.",
      "date": "0000"
    },
    {
      "headline": "Medieval Period",
      "text": "In the early Middle Ages, the town was known as Ribnica. It was first mentioned in 1326 in a charter of the Serbian King Stefan Dečanski.",
      "date": "1326"
    },
    {
      "headline": "Ottoman Rule",
      "text": "Podgorica came under Ottoman rule in 1474, marking a significant change in its cultural and political landscape.",
      "date": "1474"
    },
    {
      "headline": "Liberation from Ottoman Rule",
      "text": "Podgorica was liberated from Ottoman rule in 1878 following the Congress of Berlin, which recognized Montenegro's independence.",
      "date": "1878"
    },
    {
      "headline": "World War I",
      "text": "During World War I, Podgorica was occupied by Austro-Hungarian forces from 1916 to 1918.",
      "date": "1916"
    },
    {
      "headline": "Podgorica Assembly",
      "text": "In 1918, the Podgorica Assembly voted for the unification of Montenegro with the Kingdom of Serbia, leading to the creation of the Kingdom of Serbs, Croats, and Slovenes.",
      "date": "1918"
    },
    {
      "headline": "World War II",
      "text": "Podgorica was heavily bombed during World War II, leading to significant destruction in the city.",
      "date": "1944"
    },
    {
      "headline": "Renaming to Titograd",
      "text": "In 1946, Podgorica was renamed Titograd in honor of Josip Broz Tito, the leader of Yugoslavia.",
      "date": "1946"
    },
    {
      "headline": "Return to Podgorica",
      "text": "Following the breakup of Yugoslavia, the city was renamed back to Podgorica in 1992.",
      "date": "1992"
    },
    {
      "headline": "Capital of Montenegro",
      "text": "In 2006, following Montenegro's declaration of independence, Podgorica became the capital of the newly independent country.",
      "date": "2006"
    }
  ]
}

