    {
      "headline": "Damnatio Memoriae in Ancient Egypt",
      "text": "The practice of damnatio memoriae can be traced back to the Egyptian New Kingdom period. Notable examples include the erasure of Pharaoh Hatshepsut's name and images after her death, as well as the removal of Akhenaten's legacy following his reign.",
      "date": "-1500"
    },
    {
      "headline": "Damnatio Memoriae in Ancient Rome",
      "text": "In Ancient Rome, damnatio memoriae was a common practice used to condemn emperors and other public figures who fell out of favor. Their names were removed from inscriptions, statues were defaced, and their memory was officially condemned.",
      "date": "-0049"
    },
    {
      "headline": "Damnatio Memoriae of Emperor Domitian",
      "text": "After the assassination of Roman Emperor Domitian in 96 AD, the Senate passed a damnatio memoriae against him. His statues were destroyed, and his name was erased from public monuments.",
      "date": "0096"
    },
    {
      "headline": "Damnatio Memoriae of Geta",
      "text": "Following the murder of Roman Emperor Geta in 211 AD by his brother Caracalla, a damnatio memoriae was declared. Geta's images were removed, and his name was erased from inscriptions.",
      "date": "0211"
    },
    {
      "headline": "Modern Usage of Damnatio Memoriae",
      "text": "The term 'damnatio memoriae' is used in modern contexts to describe similar practices of erasing individuals from history, whether through censorship, destruction of records, or other means.",
      "date": "2000"
    }
  ]
}

