{
  "timeline": [
    {
      "headline": "First Known Ransomware Attack",
      "text": "In 1989, the first known ransomware attack, known as the AIDS Trojan or PC Cyborg, was created by Joseph Popp. It was distributed via floppy disks and demanded a ransom of $189.",
      "date": "1989"
    },
    {
      "headline": "Introduction of Modern Ransomware",
      "text": "In 2005, modern ransomware began to emerge with the use of stronger encryption methods, making it more difficult for victims to recover their files without paying the ransom.",
      "date": "2005"
    },
    {
      "headline": "Rise of CryptoLocker",
      "text": "In 2013, CryptoLocker was released, marking a significant evolution in ransomware. It used strong encryption and demanded payment in Bitcoin, making it harder to trace.",
      "date": "2013"
    },
    {
      "headline": "WannaCry Ransomware Attack",
      "text": "On May 12, 2017, the WannaCry ransomware attack affected hundreds of thousands of computers across 150 countries, exploiting a vulnerability in Windows systems.",
      "date": "2017-05-12"
    },
    {
      "headline": "NotPetya Ransomware Attack",
      "text": "In June 2017, the NotPetya ransomware attack spread globally, initially targeting Ukraine. It caused widespread damage and was later identified as a wiper rather than true ransomware.",
      "date": "2017-06"
    },
    {
      "headline": "Ryuk Ransomware Emergence",
      "text": "In 2018, Ryuk ransomware emerged, targeting large organizations and demanding high ransoms. It became known for its targeted attacks and significant financial impact.",
      "date": "2018"
    },
    {
      "headline": "Colonial Pipeline Ransomware Attack",
      "text": "In May 2021, the Colonial Pipeline, a major fuel pipeline in the United States, was hit by a ransomware attack, leading to fuel shortages and highlighting vulnerabilities in critical infrastructure.",
      "date": "2021-05"
    },
    {
      "headline": "Kaseya VSA Ransomware Attack",
      "text": "On July 2, 2021, a ransomware attack on Kaseya VSA affected thousands of businesses worldwide, demonstrating the risks associated with supply chain attacks.",
      "date": "2021-07-02"
    }
  ]
}

