    {
      "headline": "Foundation of Malacca Sultanate",
      "text": "The Malacca Sultanate was founded by Parameswara, a Srivijayan prince, around the year 1400.",
      "date": "1400"
    },
    {
      "headline": "Conversion to Islam",
      "text": "In 1414, Parameswara converted to Islam and took the title Sultan Iskandar Shah, marking the beginning of the Islamic influence in the region.",
      "date": "1414"
    },
    {
      "headline": "Malacca as a Major Trading Port",
      "text": "By the mid-15th century, Malacca had become a major trading port in Southeast Asia, attracting traders from across Asia and the Middle East.",
      "date": "1450"
    },
    {
      "headline": "Portuguese Conquest",
      "text": "In 1511, the Portuguese, led by Afonso de Albuquerque, captured Malacca, marking the beginning of European colonial influence in the region.",
      "date": "1511"
    },
    {
      "headline": "Dutch Capture Malacca",
      "text": "The Dutch East India Company captured Malacca from the Portuguese in 1641, establishing Dutch control over the region.",
      "date": "1641"
    },
    {
      "headline": "British Occupation",
      "text": "In 1795, during the Napoleonic Wars, the British occupied Malacca to prevent it from falling into French hands.",
      "date": "1795"
    },
    {
      "headline": "Anglo-Dutch Treaty",
      "text": "The Anglo-Dutch Treaty of 1824 resulted in Malacca being ceded to the British in exchange for Bencoolen (Bengkulu) in Sumatra.",
      "date": "1824"
    },
    {
      "headline": "Formation of the Straits Settlements",
      "text": "In 1826, Malacca became part of the Straits Settlements, a group of British territories in Southeast Asia.",
      "date": "1826"
    },
    {
      "headline": "Japanese Occupation",
      "text": "During World War II, Malacca was occupied by Japanese forces from 1942 to 1945.",
      "date": "1942"
    },
    {
      "headline": "Malacca Joins the Federation of Malaya",
      "text": "In 1948, Malacca became part of the Federation of Malaya, which gained independence from British rule in 1957.",
      "date": "1948"
    },
    {
      "headline": "Independence of Malaya",
      "text": "Malacca, as part of the Federation of Malaya, gained independence from British colonial rule on 31 August 1957.",
      "date": "1957-08-31"
    },
    {
      "headline": "Formation of Malaysia",
      "text": "On 16 September 1963, Malacca became part of Malaysia, following the merger of the Federation of Malaya with North Borneo, Sarawak, and Singapore.",
      "date": "1963-09-16"
    },
    {
      "headline": "UNESCO World Heritage Site",
