{
  "timeline": [
    {
      "headline": "Emergence of Arctodus Genus",
      "text": "The genus Arctodus first appeared during the Pleistocene epoch, which began approximately 2.58 million years ago. This genus includes the short-faced bears that inhabited North America.",
      "date": "-002580000"
    },
    {
      "headline": "Arctodus pristinus in Early Pleistocene",
      "text": "Arctodus pristinus, the lesser short-faced bear, was largely restricted to the Early Pleistocene of the eastern United States. This species is one of the earliest known members of the Arctodus genus.",
      "date": "-002580000"
    },
    {
      "headline": "Evolution of Arctodus simus",
      "text": "Arctodus simus, the giant short-faced bear, evolved from Arctodus pristinus. It is known for being one of the largest terrestrial mammalian carnivores.",
      "date": "-001000000"
    },
    {
      "headline": "Middle Pleistocene Overlap",
      "text": "During the Middle Pleistocene, both Arctodus pristinus and Arctodus simus likely overlapped in their habitats. This period saw both species coexisting in North America.",
      "date": "-000781000"
    },
    {
      "headline": "Late Pleistocene Range of Arctodus simus",
      "text": "Arctodus simus had a broader range during the Late Pleistocene, with fossil finds in the United States, Mexico, and Canada. It is considered one of the best-known members of North America's extinct Ice Age megafauna.",
      "date": "-000126000"
    },
    {
      "headline": "Extinction of Arctodus",
      "text": "The Arctodus genus, including both A. simus and A. pristinus, became extinct by the end of the Pleistocene epoch, approximately 11,000 years ago.",
      "date": "-000011000"
    }
  ]
}

