    {
      "headline": "Foundation of Lhasa",
      "text": "Lhasa was founded as a religious and administrative center in the 7th century by Songtsen Gampo, the 33rd king of the Yarlung Dynasty, who unified Tibet and established the Tibetan Empire.",
      "date": "-0640"
    },
    {
      "headline": "Construction of Jokhang Temple",
      "text": "In 647, the Jokhang Temple, one of the most sacred and important temples in Tibet, was constructed by Songtsen Gampo to house the Buddhist statues brought by his wives.",
      "date": "0647"
    },
    {
      "headline": "Construction of Potala Palace",
      "text": "The Potala Palace was originally constructed in 637 by Songtsen Gampo and later expanded in the 17th century by the 5th Dalai Lama, becoming the winter palace of the Dalai Lamas.",
      "date": "0637"
    },
    {
      "headline": "Lhasa becomes the capital of Tibet",
      "text": "In the 17th century, under the rule of the 5th Dalai Lama, Lhasa was established as the capital of Tibet, solidifying its status as the political and religious center.",
      "date": "1642"
    },
    {
      "headline": "Invasion by the Qing Dynasty",
      "text": "In 1720, the Qing Dynasty invaded Tibet and established a protectorate over the region, influencing the governance of Lhasa.",
      "date": "1720"
    },
    {
      "headline": "British Expedition to Tibet",
      "text": "In 1904, a British expedition led by Colonel Francis Younghusband entered Lhasa, resulting in the signing of the Treaty of Lhasa.",
      "date": "1904"
    },
    {
      "headline": "Chinese Control Established",
      "text": "In 1951, following the Chinese invasion of Tibet, the Seventeen Point Agreement was signed, establishing Chinese control over Tibet, including Lhasa.",
      "date": "1951"
    },
    {
      "headline": "Lhasa Uprising",
      "text": "In March 1959, the Lhasa Uprising occurred as Tibetans revolted against Chinese rule, leading to the flight of the 14th Dalai Lama to India.",
      "date": "1959-03"
    },
    {
      "headline": "Lhasa becomes a city",
      "text": "In 1960, Lhasa was officially designated as a city within the Tibet Autonomous Region of China.",
      "date": "1960"
    },
    {
      "headline": "Lhasa Railway Completion",
      "text": "In 2006, the Qinghai-Tibet Railway was completed, connecting Lhasa to the rest of China and significantly impacting its economy and accessibility.",
      "date": "2006"
    }
  ]
}

