  "timeline": [
    {
      "headline": "Cato the Elder's Birth",
      "text": "Cato the Elder, a Roman statesman known for his conservatism and opposition to Hellenization, was born in 234 BCE.",
      "date": "-0234"
    },
    {
      "headline": "Cato the Elder's Political Career",
      "text": "Cato the Elder began his political career, serving in various roles including quaestor, aedile, praetor, and consul. He was known for his staunch traditionalism and advocacy for Roman values.",
      "date": "-0195"
    },
    {
      "headline": "Cato the Elder's Censorship",
      "text": "In 184 BCE, Cato the Elder was elected as censor, a position he used to promote moral legislation and traditional Roman values.",
      "date": "-0184"
    },
    {
      "headline": "Cato the Elder's Advocacy for Carthage's Destruction",
      "text": "During the period leading up to the Third Punic War (149-146 BCE), Cato the Elder famously ended his speeches with the phrase 'Carthago delenda est' ('Carthage must be destroyed'), advocating for the complete destruction of Carthage.",
      "date": "-0150"
    },
    {
      "headline": "Third Punic War",
      "text": "The Third Punic War took place from 149 BCE to 146 BCE, resulting in the destruction of Carthage and the end of the Carthaginian Empire.",
      "date": "-0149"
    },
    {
      "headline": "Death of Cato the Elder",
      "text": "Cato the Elder died in 149 BCE, the same year the Third Punic War began, not living to see the destruction of Carthage.",
      "date": "-0149"
    }
  ]
}

