    {
      "headline": "Elected to the U.S. House of Representatives",
      "text": "John Marshall was elected to the U.S. House of Representatives from Virginia, serving from March 4, 1799, to June 7, 1800.",
      "date": "1799-03-04"
    },
    {
      "headline": "Appointed U.S. Secretary of State",
      "text": "Marshall was appointed as the U.S. Secretary of State by President John Adams, serving from June 6, 1800, to March 4, 1801.",
      "date": "1800-06-06"
    },
    {
      "headline": "Appointed Chief Justice of the United States",
      "text": "John Marshall was appointed as the Chief Justice of the United States by President John Adams, taking office on February 4, 1801.",
      "date": "1801-02-04"
    },
    {
      "headline": "Marbury v. Madison Decision",
      "text": "On February 24, 1803, the Supreme Court under Chief Justice John Marshall issued its decision in Marbury v. Madison, establishing the principle of judicial review.",
      "date": "1803-02-24"
    },
    {
      "headline": "McCulloch v. Maryland Decision",
      "text": "In 1819, the Supreme Court under Marshall decided McCulloch v. Maryland, affirming the federal government's implied powers over the states.",
      "date": "1819"
    },
    {
      "headline": "Gibbons v. Ogden Decision",
      "text": "In 1824, the Supreme Court under Marshall decided Gibbons v. Ogden, reinforcing the federal government's power to regulate interstate commerce.",
      "date": "1824"
    },
    {
      "headline": "Death of John Marshall",
