      "headline": "First Known Basilica",
      "text": "The first known basilica was the Basilica Porcia, built in Rome by Cato the Elder in 184 BCE. It served as a place for legal matters and business transactions.",
      "date": "-0184"
    },
    {
      "headline": "Construction of the Basilica Aemilia",
      "text": "The Basilica Aemilia was constructed in the Roman Forum in 179 BCE. It was one of the most important basilicas in ancient Rome, used for business and legal proceedings.",
      "date": "-0179"
    },
    {
      "headline": "Basilica Sempronia Built",
      "text": "The Basilica Sempronia was built in 169 BCE by Tiberius Sempronius Gracchus. It was located in the Roman Forum and replaced some older structures.",
      "date": "-0169"
    },
    {
      "headline": "Basilica Opimia Constructed",
      "text": "The Basilica Opimia was constructed in 121 BCE by the consul Lucius Opimius. It was located near the Temple of Concord in the Roman Forum.",
      "date": "-0121"
    },
    {
      "headline": "Basilica Julia Initiated",
      "text": "Julius Caesar began the construction of the Basilica Julia in the Roman Forum in 54 BCE. It was intended to replace the Basilica Sempronia.",
      "date": "-0054"
    },
    {
      "headline": "Completion of Basilica Julia",
      "text": "The Basilica Julia was completed by Augustus in 12 BCE after being damaged by fire and undergoing reconstruction.",
      "date": "-0012"
    },
    {
      "headline": "Basilica Ulpia Constructed",
      "text": "The Basilica Ulpia was constructed under Emperor Trajan as part of his forum in Rome, completed around 112 CE. It was one of the largest and most magnificent basilicas in Rome.",
      "date": "0112"
    },
    {
      "headline": "Christian Adaptation of Basilicas",
      "text": "In the 4th century CE, Roman basilicas began to be adapted for Christian worship, influencing the design of early Christian churches.",
      "date": "0300"
    }
  ]
}

