      "headline": "Birth of Jean Sibelius",
      "text": "Jean Sibelius was born on December 8, 1865, in Hämeenlinna, Grand Duchy of Finland, which was part of the Russian Empire at the time.",
      "date": "1865-12-08"
    },
    {
      "headline": "Sibelius's Early Education",
      "text": "In 1885, Sibelius enrolled at the Helsinki Music Institute (now the Sibelius Academy) where he studied music theory and composition.",
      "date": "1885"
    },
    {
      "headline": "Studies in Berlin",
      "text": "Sibelius studied in Berlin from 1889 to 1890, where he was influenced by the works of Richard Wagner.",
      "date": "1889"
    },
    {
      "headline": "Studies in Vienna",
      "text": "In 1890, Sibelius continued his studies in Vienna, where he was exposed to the music of Anton Bruckner and Johannes Brahms.",
      "date": "1890"
    },
    {
      "headline": "Premiere of Kullervo Symphony",
      "text": "The premiere of Sibelius's Kullervo Symphony took place on April 28, 1892, in Helsinki, marking his breakthrough as a composer.",
      "date": "1892-04-28"
    },
    {
      "headline": "Marriage to Aino Järnefelt",
      "text": "Jean Sibelius married Aino Järnefelt on June 10, 1892.",
      "date": "1892-06-10"
    },
    {
      "headline": "Finlandia Composed",
      "text": "Sibelius composed Finlandia in 1899, a piece that became a symbol of Finnish nationalism.",
      "date": "1899"
    },
    {
      "headline": "First Symphony",
      "text": "Sibelius's Symphony No. 1 premiered on April 26, 1899, in Helsinki.",
      "date": "1899-04-26"
    },
    {
      "headline": "Second Symphony",
      "text": "The Second Symphony, often seen as a statement of Finnish nationalism, premiered on March 8, 1902.",
      "date": "1902-03-08"
    },
    {
      "headline": "Move to Ainola",
      "text": "In 1904, Sibelius and his family moved to Ainola, a home built for them in Järvenpää, where he lived for the rest of his life.",
      "date": "1904"
    },
    {
      "headline": "Third Symphony",
      "text": "Sibelius's Symphony No. 3 premiered on September 25, 1907.",
      "date": "1907-09-25"
    },
    {
      "headline": "Fourth Symphony",
      "text": "The Fourth Symphony premiered on April 3, 1911, and marked a departure from his earlier style.",
      "date": "1911-04-03"
    },
    {
      "headline": "Fifth Symphony",
      "text": "Sibelius's Symphony No. 5 premiered on December 8, 1915, his 50th birthday.",
      "date": "1915-12-08"
    },
    {
      "headline": "Sixth Symphony",
      "text": "The Sixth Symphony premiered on February 19, 1923.",
      "date": "1923-02-19"
    },
    {
      "headline": "Seventh Symphony",
      "text": "Sibelius's Symphony No. 7 premiered on March 24, 1924.",
      "date": "1924-03-24"
    },
    {
      "headline": "The Silence of Järvenpää",
      "text": "After 1926, Sibelius entered a period of silence, during which he composed little and did not publish any new major works.",
      "date": "1926"
    },
    {
      "headline": "Death of Jean Sibelius",
      "text": "Jean Sibelius died on September 20, 1957, at his home in Ainola, Järvenpää, Finland.",
      "date": "1957-09-20"
    }
  ]
}

