{
  "timeline": [
    {
      "headline": "Establishment of Bengal Presidency",
      "text": "The Bengal Presidency was established in 1765 following the Battle of Buxar, where the British East India Company gained control over the region of Bengal, Bihar, and Orissa.",
      "date": "1765"
    },
    {
      "headline": "Regulating Act of 1773",
      "text": "The Regulating Act of 1773 was passed by the British Parliament to address the administration of the East India Company, leading to the appointment of Warren Hastings as the first Governor-General of Bengal.",
      "date": "1773"
    },
    {
      "headline": "Pitt's India Act",
      "text": "In 1784, Pitt's India Act was enacted, which established a dual system of control by the British government and the East India Company, further solidifying the administrative structure of the Bengal Presidency.",
      "date": "1784"
    },
    {
      "headline": "Charter Act of 1833",
      "text": "The Charter Act of 1833 was passed, which centralized the administration of British India and made the Governor-General of Bengal the Governor-General of India, with Calcutta as the capital.",
      "date": "1833"
    },
    {
      "headline": "Partition of Bengal",
      "text": "In 1905, the British government partitioned Bengal into two separate provinces, East Bengal and West Bengal, to improve administrative efficiency. This decision was met with strong opposition and protests.",
      "date": "1905"
    },
    {
      "headline": "Reversal of Bengal Partition",
      "text": "The partition of Bengal was reversed in 1911 due to widespread protests and political pressure, and the region was reunited.",
      "date": "1911"
    },
    {
      "headline": "Transfer of Capital to Delhi",
      "text": "In 1911, the capital of British India was transferred from Calcutta to Delhi, marking the end of Calcutta's status as the capital.",
      "date": "1911"
    },
    {
      "headline": "Formation of Bengal Province",
      "text": "Following the Government of India Act 1935, the Bengal Presidency was reorganized into the Bengal Province, which continued until the partition of India in 1947.",
      "date": "1935"
    },
    {
      "headline": "Partition of India",
      "text": "In 1947, the Indian Independence Act led to the partition of India, resulting in the division of Bengal into West Bengal (India) and East Bengal (Pakistan, later Bangladesh).",
      "date": "1947"
    }
  ]
}

