{
  "timeline": [
    {
      "headline": "Beginning of the Second Opium War",
      "text": "The Second Opium War began in October 1856 when Chinese officials boarded the British-registered ship Arrow, arresting its crew and lowering the British flag.",
      "date": "1856-10"
    },
    {
      "headline": "British and French Alliance",
      "text": "In 1857, the United Kingdom formed an alliance with France to jointly pursue military action against the Qing dynasty.",
      "date": "1857"
    },
    {
      "headline": "Capture of Canton",
      "text": "On December 29, 1857, British and French forces captured the city of Canton (Guangzhou), a major trading port in southern China.",
      "date": "1857-12-29"
    },
    {
      "headline": "Treaty of Tientsin",
      "text": "In June 1858, the Treaty of Tientsin was signed, temporarily halting hostilities and granting Western powers new trade rights and territorial concessions.",
      "date": "1858-06"
    },
    {
      "headline": "Renewal of Hostilities",
      "text": "Hostilities resumed in 1859 when the Qing government refused to ratify the Treaty of Tientsin, leading to further military engagements.",
      "date": "1859"
    },
    {
      "headline": "Battle of Taku Forts",
      "text": "On June 25, 1859, British and French forces attempted to capture the Taku Forts near Tianjin but were repelled by Qing forces.",
      "date": "1859-06-25"
    },
    {
      "headline": "Capture of Beijing",
      "text": "In October 1860, British and French forces captured Beijing, leading to the looting and burning of the Old Summer Palace.",
      "date": "1860-10"
    },
    {
      "headline": "Convention of Peking",
      "text": "The Convention of Peking was signed on October 24, 1860, officially ending the Second Opium War and granting further concessions to the British and French.",
      "date": "1860-10-24"
    }
  ]
}

