{
  "timeline": [
    {
      "headline": "First Recorded Blood Transfusion",
      "text": "In 1665, the first recorded blood transfusion was performed by Richard Lower, who transfused blood between dogs.",
      "date": "1665"
    },
    {
      "headline": "First Human Blood Transfusion",
      "text": "In 1667, Jean-Baptiste Denis, a French physician, performed the first human blood transfusion, transfusing sheep blood into a human.",
      "date": "1667"
    },
    {
      "headline": "Discovery of Blood Groups",
      "text": "In 1901, Karl Landsteiner discovered the first three human blood groups, which later became known as A, B, and O. This discovery made blood transfusions safer and more effective.",
      "date": "1901"
    },
    {
      "headline": "Development of Citrate Glucose Solution",
      "text": "In 1914, Albert Hustin and Luis Agote independently discovered that adding sodium citrate to blood prevented it from clotting, allowing for the storage of blood and the development of blood banks.",
      "date": "1914"
    },
    {
      "headline": "First Blood Bank Established",
      "text": "In 1936, the first blood bank was established in Chicago at Cook County Hospital by Dr. Bernard Fantus.",
      "date": "1936"
    },
    {
      "headline": "Introduction of Rh Factor",
      "text": "In 1940, Karl Landsteiner and Alexander S. Wiener discovered the Rh factor, further improving the safety of blood transfusions.",
      "date": "1940"
    },
    {
      "headline": "Development of Component Therapy",
      "text": "In the 1960s, the practice of component therapy began, allowing for the transfusion of specific blood components such as red blood cells, plasma, and platelets.",
      "date": "1960"
    },
    {
      "headline": "Introduction of Leukoreduction",
      "text": "In the 1990s, leukoreduction became a standard practice in many countries, reducing the number of white blood cells in blood products to decrease the risk of complications.",
      "date": "1990"
    }
  ]
}

