{
  "timeline": [
    {
      "headline": "Francesco Maria Grimaldi Coins the Term 'Diffraction'",
      "text": "In 1660, Italian scientist Francesco Maria Grimaldi coined the term 'diffraction' and was the first to record accurate observations of the phenomenon. He described how light waves bend around obstacles and spread out after passing through small apertures.",
      "date": "1660"
    },
    {
      "headline": "Thomas Young's Double-Slit Experiment",
      "text": "In 1801, Thomas Young conducted his famous double-slit experiment, demonstrating that light behaves as a wave and providing evidence for the wave theory of light through the observation of interference patterns.",
      "date": "1801"
    },
    {
      "headline": "Augustin-Jean Fresnel Develops Wave Theory",
      "text": "In the early 19th century, Augustin-Jean Fresnel developed a comprehensive wave theory of light, explaining diffraction and interference phenomena. His work laid the foundation for understanding light as a wave.",
      "date": "1815"
    },
    {
      "headline": "Fraunhofer Diffraction",
      "text": "Joseph von Fraunhofer, in the early 19th century, studied diffraction patterns and developed the theory of Fraunhofer diffraction, which applies to the far-field region where wavefronts are essentially parallel.",
      "date": "1821"
    },
    {
      "headline": "Discovery of X-ray Diffraction",
      "text": "In 1912, Max von Laue discovered X-ray diffraction, demonstrating that crystals could diffract X-rays. This discovery provided a powerful tool for determining the atomic structure of crystals.",
      "date": "1912"
    },
    {
      "headline": "Bragg's Law Formulated",
      "text": "In 1913, William Lawrence Bragg formulated Bragg's Law, which relates the angles at which X-rays are diffracted by the atomic planes in a crystal. This law is fundamental to the field of X-ray crystallography.",
      "date": "1913"
    }
  ]
}

