    {
      "headline": "Establishment of Stone Mountain Village",
      "text": "The village of Stone Mountain was established in 1839, serving as a small community near the mountain.",
      "date": "1839"
    },
    {
      "headline": "Civil War Significance",
      "text": "During the American Civil War, Stone Mountain was used as a signal point by the Confederate Army. The mountain's strategic location made it an important site during the war.",
      "date": "1861-1865"
    },
    {
      "headline": "Stone Mountain Granite Quarrying",
      "text": "In the late 19th century, Stone Mountain became a significant site for granite quarrying, which contributed to the local economy.",
      "date": "1880"
    },
    {
      "headline": "Inception of Confederate Memorial Carving",
      "text": "In 1915, the idea for a Confederate memorial carving on Stone Mountain was conceived by the United Daughters of the Confederacy.",
      "date": "1915"
    },
    {
      "headline": "Start of Carving by Gutzon Borglum",
      "text": "In 1923, sculptor Gutzon Borglum began work on the Confederate memorial carving on Stone Mountain.",
      "date": "1923"
    },
    {
      "headline": "Carving Abandoned and Restarted",
      "text": "The carving was abandoned in 1925 due to funding issues and disagreements. It was restarted in 1964 under the direction of Walker Hancock.",
      "date": "1964"
    },
    {
      "headline": "Completion of Confederate Memorial Carving",
      "text": "The Confederate memorial carving on Stone Mountain was completed in 1972, depicting Jefferson Davis, Robert E. Lee, and Stonewall Jackson.",
      "date": "1972"
    },
    {
      "headline": "Establishment of Stone Mountain Park",
      "text": "Stone Mountain Park was established in 1965, encompassing the mountain and surrounding areas as a public park.",
      "date": "1965"
    }
  ]
}

