{
  "timeline": [
    {
      "headline": "Incorporation of Whitewater Development Corporation",
      "text": "The Whitewater Development Corporation was incorporated in 1979 with the purpose of developing vacation properties on land along the White River near Flippin, Arkansas.",
      "date": "1979"
    },
    {
      "headline": "Clintons and McDougals Purchase Land",
      "text": "In 1978, Bill and Hillary Clinton, along with Jim and Susan McDougal, purchased 230 acres of land in the Ozark Mountains, intending to build vacation homes.",
      "date": "1978"
    },
    {
      "headline": "Jim McDougal Acquires Madison Guaranty Savings and Loan",
      "text": "In 1982, Jim McDougal acquired Madison Guaranty Savings and Loan, which later became central to the Whitewater controversy.",
      "date": "1982"
    },
    {
      "headline": "Madison Guaranty Fails",
      "text": "In 1989, Madison Guaranty Savings and Loan failed, costing taxpayers $73 million. This failure was a key element in the Whitewater investigation.",
      "date": "1989"
    },
    {
      "headline": "Federal Investigation Begins",
      "text": "In 1992, during Bill Clinton's presidential campaign, questions about the Whitewater investments arose, leading to a federal investigation.",
      "date": "1992"
    },
    {
      "headline": "Appointment of Special Prosecutor",
      "text": "In January 1994, Robert B. Fiske was appointed as the special prosecutor to investigate the Whitewater controversy.",
      "date": "1994-01"
    },
    {
      "headline": "Kenneth Starr Appointed as Independent Counsel",
      "text": "In August 1994, Kenneth Starr was appointed as the independent counsel to continue the investigation into the Whitewater controversy.",
      "date": "1994-08"
    },
    {
      "headline": "Susan McDougal Imprisoned for Contempt",
      "text": "In September 1996, Susan McDougal was jailed for contempt of court for refusing to answer questions related to the Whitewater investigation.",
      "date": "1996-09"
    },
    {
      "headline": "Final Report Issued",
      "text": "In September 2000, Kenneth Starr's successor, Robert Ray, issued the final report on the Whitewater investigation, stating there was insufficient evidence to charge the Clintons with any criminal wrongdoing.",
      "date": "2000-09"
    }
  ]
}

