    {
      "headline": "Udaipur Becomes Capital of Mewar",
      "text": "After its founding in 1559, Udaipur served as the capital of the kingdom of Mewar. The city became a significant center for the Rajput culture and politics.",
      "date": "1559"
    },
    {
      "headline": "Mewar Becomes a British Princely State",
      "text": "In 1818, the kingdom of Mewar, with Udaipur as its capital, became a princely state under British rule. This marked a significant political change for the region.",
      "date": "1818"
    },
    {
      "headline": "Integration into Independent India",
      "text": "In 1947, following India's independence from British rule, the Mewar province, including Udaipur, became part of the newly formed state of Rajasthan.",
      "date": "1947"
    }
  ]
}

