    {
      "headline": "Creation of the Position",
      "text": "The position of General Secretary of the Communist Party of the Soviet Union was created on April 3, 1922. It was initially a technical role responsible for administrative tasks within the party.",
      "date": "1922-04-03"
    },
    {
      "headline": "Joseph Stalin Becomes General Secretary",
      "text": "Joseph Stalin was appointed as the General Secretary of the Communist Party on April 3, 1922. Over time, he consolidated power and transformed the role into the most powerful position in the Soviet Union.",
      "date": "1922-04-03"
    },
    {
      "headline": "Stalin's Consolidation of Power",
      "text": "Throughout the 1920s, Joseph Stalin used his position as General Secretary to consolidate power, outmaneuvering political rivals and becoming the de facto leader of the Soviet Union by the late 1920s.",
      "date": "1920s"
    },
    {
      "headline": "Nikita Khrushchev's Leadership",
      "text": "Nikita Khrushchev served as the General Secretary from September 14, 1953, following Stalin's death, until October 14, 1964. He initiated de-Stalinization and various reforms during his tenure.",
      "date": "1953-09-14"
    },
    {
      "headline": "Leonid Brezhnev's Era",
      "text": "Leonid Brezhnev became General Secretary on October 14, 1964, and led the Soviet Union until his death on November 10, 1982. His tenure was marked by a period of stagnation and the Cold War.",
      "date": "1964-10-14"
    },
    {
      "headline": "Mikhail Gorbachev's Reforms",
      "text": "Mikhail Gorbachev was appointed General Secretary on March 11, 1985. He introduced significant reforms such as glasnost and perestroika, which eventually led to the dissolution of the Soviet Union.",
      "date": "1985-03-11"
    },
    {
      "headline": "Dissolution of the Soviet Union",
      "text": "The position of General Secretary effectively ended with the dissolution of the Soviet Union on December 26, 1991, marking the end of the Communist Party's rule.",
      "date": "1991-12-26"
    }
  ]
}

