{
  "timeline": [
    {
      "headline": "Establishment of the Residential School System",
      "text": "The Canadian Indian residential school system was established in the 19th century as a network of boarding schools for Indigenous peoples. The system was funded by the Canadian government's Department of Indian Affairs and administered by various Christian churches.",
      "date": "1800"
    },
    {
      "headline": "First Residential Schools Open",
      "text": "The first residential schools began operating in the 1840s. These schools were created to isolate Indigenous children from the influence of their own culture and religion in order to assimilate them into the dominant Euro-Canadian culture.",
      "date": "1840"
    },
    {
      "headline": "Gradual Expansion of the System",
      "text": "Throughout the late 19th and early 20th centuries, the residential school system expanded across Canada. By the 1930s, about 30 percent of Indigenous children were attending residential schools.",
      "date": "1930"
    },
    {
      "headline": "Peak Enrollment",
      "text": "By the 1930s, the residential school system had reached its peak enrollment, with approximately 30 percent of Indigenous children attending these schools.",
      "date": "1930"
    },
    {
      "headline": "Decline and Closure of Schools",
      "text": "The number of residential schools began to decline in the mid-20th century, with many schools closing in the 1960s and 1970s as public awareness and criticism of the system grew.",
      "date": "1960"
    },
    {
      "headline": "Last Residential School Closes",
      "text": "The last federally operated residential school, Gordon's Indian Residential School in Punnichy, Saskatchewan, closed in 1996.",
      "date": "1996"
    },
    {
