{
  "timeline": [
    {
      "headline": "Neronian Persecution",
      "text": "The first localized persecution of Christians occurred under Emperor Nero in Rome, following the Great Fire of Rome in 64 AD. Christians were blamed for the fire and subjected to severe punishments.",
      "date": "0064"
    },
    {
      "headline": "Persecutions under Marcus Aurelius",
      "text": "During the reign of Marcus Aurelius (161-180 AD), a number of mostly localized persecutions of Christians occurred. These were not empire-wide but were significant in certain regions.",
      "date": "0161"
    },
    {
      "headline": "Decian Persecution",
      "text": "In 250 AD, Emperor Decius initiated a particularly extensive persecution of Christians, requiring all citizens to perform a sacrifice to the Roman gods and obtain a certificate proving they had done so.",
      "date": "0250"
    },
    {
      "headline": "Persecution under Trebonianus Gallus",
      "text": "Following Decius, Emperor Trebonianus Gallus continued the persecution of Christians, maintaining the pressure on Christians to conform to Roman religious practices.",
      "date": "0251"
    },
    {
      "headline": "Persecution under Valerian",
      "text": "Emperor Valerian intensified the persecution of Christians beginning in 257 AD, targeting Christian clergy and confiscating church property.",
      "date": "0257"
    },
    {
      "headline": "Capture of Valerian and End of Persecution",
      "text": "The persecution under Valerian ceased with his capture by the Sasanian Empire's Shapur I at the Battle of Edessa in 260 AD. His successor, Gallienus, halted the persecutions.",
      "date": "0260"
    }
  ]
}

