      "date": "0813"
    },
    {
      "headline": "Translation Movement",
      "text": "The House of Wisdom became a key center for the Translation Movement, where scholars translated significant works from Greek, Persian, and Indian texts into Arabic, significantly contributing to the Islamic Golden Age.",
      "date": "0813"
    },
    {
      "headline": "Destruction of the House of Wisdom",
      "text": "The House of Wisdom was destroyed during the Siege of Baghdad in 1258 by the Mongol Empire, marking the end of its contributions to the Islamic Golden Age.",
      "date": "1258"
    }
  ]
}

