    },
    {
      "headline": "Fez under the Wattasid dynasty",
      "text": "In the 15th century, Fez came under the control of the Wattasid dynasty, continuing its role as a cultural and religious center.",
      "date": "1400"
    },
    {
      "headline": "Fez under the Saadi dynasty",
      "text": "In the 16th century, the Saadi dynasty took control of Fez, which remained an important city despite losing its status as the capital.",
      "date": "1500"
    },
    {
      "headline": "Fez under the Alaouite dynasty",
      "text": "In the 17th century, the Alaouite dynasty took control of Fez, which continued to be a significant cultural and religious center.",
      "date": "1600"
    },
    {
      "headline": "French Protectorate established",
      "text": "In 1912, the Treaty of Fez established the French Protectorate in Morocco, impacting the city's development.",
      "date": "1912"
