{
  "timeline": [
    {
      "headline": "Unification of Upper and Lower Egypt",
      "text": "Around 3100 BCE, King Narmer (also known as Menes) unified Upper and Lower Egypt, marking the beginning of the First Dynasty and the Early Dynastic Period.",
      "date": "-3100"
    },
    {
      "headline": "Construction of the Great Pyramid of Giza",
      "text": "The Great Pyramid of Giza was constructed during the reign of Pharaoh Khufu around 2580–2560 BCE. It is one of the Seven Wonders of the Ancient World.",
      "date": "-2580"
    },
    {
      "headline": "Middle Kingdom Period",
      "text": "The Middle Kingdom of Egypt, considered a high point in Egyptian culture and power, began around 2050 BCE and lasted until around 1710 BCE.",
      "date": "-2050"
    },
    {
      "headline": "Hyksos Invasion",
      "text": "Around 1650 BCE, the Hyksos, a foreign Semitic people, invaded and ruled parts of Egypt, marking the Second Intermediate Period.",
      "date": "-1650"
    },
    {
      "headline": "New Kingdom Period",
      "text": "The New Kingdom, known for its wealth, power, and expansion, began around 1550 BCE and lasted until 1070 BCE. This era included famous pharaohs like Hatshepsut, Akhenaten, and Tutankhamun.",
      "date": "-1550"
    },
    {
      "headline": "Reign of Ramses II",
      "text": "Ramses II, also known as Ramses the Great, reigned from 1279 BCE to 1213 BCE. He is known for his military leadership and monumental building projects.",
      "date": "-1279"
    },
    {
      "headline": "Third Intermediate Period",
      "text": "The Third Intermediate Period began around 1070 BCE and lasted until 664 BCE, characterized by political fragmentation and decline in centralized power.",
      "date": "-1070"
    },
    {
      "headline": "Late Period of Egypt",
      "text": "The Late Period of Egypt began in 664 BCE and lasted until the conquest by Alexander the Great in 332 BCE. It was marked by foreign invasions and internal strife.",
      "date": "-0664"
    },
    {
      "headline": "Conquest by Alexander the Great",
      "text": "In 332 BCE, Alexander the Great conquered Egypt, marking the beginning of the Hellenistic Period and the establishment of the Ptolemaic Kingdom.",
      "date": "-0332"
    },
    {
      "headline": "Roman Conquest of Egypt",
      "text": "In 30 BCE, Egypt became a province of the Roman Empire following the defeat of Cleopatra VII and Mark Antony by Octavian (later Augustus Caesar).",
      "date": "-0030"
    },
    {
      "headline": "Arab Conquest of Egypt",
      "text": "In 641 CE, Egypt was conquered by the Arab Muslim forces led by Amr ibn al-As, marking the beginning of Islamic rule in Egypt.",
      "date": "0641"
    },
    {
      "headline": "Ottoman Rule",
      "text": "In 1517, Egypt became part of the Ottoman Empire, and it remained under Ottoman control until the early 19th century.",
      "date": "1517"
    },
    {
      "headline": "British Occupation",
      "text": "In 1882, Britain occupied Egypt, and although it remained nominally part of the Ottoman Empire, it was effectively under British control until 1952.",
      "date": "1882"
    },
    {
      "headline": "Egyptian Revolution of 1952",
      "text": "The Egyptian Revolution of 1952, led by the Free Officers Movement, resulted in the overthrow of King Farouk and the establishment of a republic.",
      "date": "1952"
    }
  ]
}

