    {
      "headline": "Move to Dresden",
      "text": "In 1798, Friedrich moved to Dresden, which became his primary residence and where he became associated with the Romantic movement.",
      "date": "1798"
    },
    {
      "headline": "Exhibition at the Berlin Academy",
      "text": "In 1805, Friedrich exhibited his work at the Berlin Academy, gaining recognition for his unique approach to landscape painting.",
      "date": "1805"
    },
    {
      "headline": "Creation of 'The Monk by the Sea'",
      "text": "In 1808-1810, Friedrich painted 'The Monk by the Sea', one of his most famous works, which was exhibited in Berlin in 1810.",
      "date": "1810"
    },
    {
      "headline": "Marriage to Caroline Bommer",
      "text": "On January 21, 1818, Friedrich married Caroline Bommer, the daughter of a dyer from Dresden.",
      "date": "1818-01-21"
    },
    {
      "headline": "Creation of 'Wanderer above the Sea of Fog'",
      "text": "In 1818, Friedrich completed 'Wanderer above the Sea of Fog', which became one of his most iconic paintings.",
      "date": "1818"
    },
    {
      "headline": "Decline in Popularity",
      "text": "By the late 1820s, Friedrich's work began to fall out of favor as the art world shifted towards Realism and away from Romanticism.",
      "date": "1820"
    },
    {
      "headline": "Suffered a Stroke",
      "text": "In 1835, Friedrich suffered a stroke that left him partially paralyzed and unable to paint with his previous skill.",
      "date": "1835"
    },
    {
      "headline": "Death of Caspar David Friedrich",
      "text": "Caspar David Friedrich died on May 7, 1840, in Dresden, Kingdom of Saxony (now Germany).",
