{
  "timeline": [
    {
      "headline": "Colonial America Alcohol Consumption",
      "text": "In colonial America, there were generally no minimum purchase ages for alcohol, and consumption by young teenagers was common, even in taverns.",
      "date": "-01700"
    },
    {
      "headline": "Post-Revolutionary America Changes",
      "text": "After the American Revolution, the freedom to purchase alcohol gradually reduced due to religious sentiments and a growing recognition in the medical community about the dangers of alcohol.",
      "date": "1800"
    },
    {
      "headline": "Prohibition Era",
      "text": "During the Prohibition era (1920-1933), the sale of alcohol was banned nationwide, effectively setting the minimum purchase age at 21 when Prohibition ended.",
      "date": "1920"
    },
    {
      "headline": "Repeal of Prohibition",
      "text": "In 1933, the 21st Amendment repealed Prohibition, and states were allowed to set their own minimum purchase ages for alcohol.",
      "date": "1933"
    },
    {
      "headline": "Minimum Drinking Age Act",
      "text": "In 1984, the National Minimum Drinking Age Act was passed, which required states to raise the minimum purchase age to 21 or face a reduction in highway funds.",
      "date": "1984"
    }
  ]
}

