    {
      "headline": "Camp David Accords",
      "text": "In 1978, the Camp David Accords were signed between Egypt and Israel, which included discussions on plans for 'Palestinian autonomy'. However, no Palestinian representatives were included in these discussions.",
      "date": "1978"
    },
    {
      "headline": "Madrid Conference",
      "text": "The Madrid Conference of 1991 was a peace conference held in Madrid, Spain, aimed at reviving the Israeli-Palestinian peace process through negotiations involving Israel, Palestine, and neighboring Arab countries.",
      "date": "1991"
    },
    {
      "headline": "Oslo Accords",
      "text": "The Oslo Accords were a series of agreements between Israel and the Palestine Liberation Organization (PLO) signed in 1993, which aimed to achieve a peace treaty based on United Nations Security Council Resolutions 242 and 338 and to fulfill the 'right of the Palestinian people to self-determination'.",
      "date": "1993"
    },
    {
      "headline": "Camp David 2000 Summit",
      "text": "In July 2000, the Camp David 2000 Summit was held, where U.S. President Bill Clinton hosted Israeli Prime Minister Ehud Barak and Palestinian Authority Chairman Yasser Arafat to negotiate a final status agreement. The summit ended without an agreement.",
      "date": "2000-07"
    },
    {
      "headline": "Taba Summit",
      "text": "In January 2001, the Taba Summit was held in Taba, Egypt, as a continuation of the peace negotiations. Although significant progress was made, no final agreement was reached.",
      "date": "2001-01"
    },
    {
      "headline": "Roadmap for Peace",
      "text": "In 2003, the 'Roadmap for Peace' was proposed by the Quartet on the Middle East (the United States, the European Union, Russia, and the United Nations) as a plan to resolve the Israeli-Palestinian conflict.",
      "date": "2003"
    },
    {
      "headline": "Annapolis Conference",
      "text": "In November 2007, the Annapolis Conference was held in Annapolis, Maryland, USA, with the aim of restarting the peace process and implementing the two-state solution.",
      "date": "2007-11"
    },
    {
      "headline": "Direct Negotiations",
      "text": "In September 2010, direct negotiations between Israel and the Palestinian Authority were resumed in Washington, D.C., but were suspended shortly after due to disagreements over Israeli settlement construction.",
      "date": "2010-09"
    }
  ]
}

