    {
      "headline": "Marriage to Shiva",
      "text": "Sati married Shiva, the ascetic god of destruction and transformation. Despite her father's disapproval, Sati chose Shiva as her husband, symbolizing the union of divine feminine and masculine energies.",
      "date": "-"
    },
    {
      "headline": "Daksha's Yajna",
      "text": "Daksha organized a grand yajna (sacrificial ritual) but deliberately did not invite Shiva and Sati. Sati, feeling humiliated by her father's actions, attended the yajna uninvited.",
      "date": "-"
    },
    {
      "headline": "Sati's Self-Immolation",
      "text": "During the yajna, Sati was insulted by her father Daksha. Unable to bear the disrespect towards her husband Shiva, Sati immolated herself in the sacrificial fire, leading to her death.",
      "date": "-"
    },
    {
      "headline": "Reincarnation as Parvati",
      "text": "After her death, Sati was reincarnated as Parvati, the daughter of the mountain king Himavan and queen Mena. Parvati later married Shiva, continuing the divine relationship.",
      "date": "-"
    }
  ]
}

