    },
    {
      "headline": "Publication of Bell's Theorem",
      "text": "In 1964, John Stewart Bell published a paper titled 'On the Einstein Podolsky Rosen Paradox,' which introduced what is now known as Bell's theorem. This theorem demonstrated that no physical theory of local hidden variables can ever reproduce all of the predictions of quantum mechanics.",
      "date": "1964"
    },
    {
      "headline": "Aspect's Experiment",
      "text": "In 1982, Alain Aspect and his team conducted experiments that provided strong evidence supporting the predictions of quantum mechanics over local hidden-variable theories, thus supporting Bell's theorem.",
      "date": "1982"
    },
    {
      "headline": "John Stewart Bell's Death",
      "text": "John Stewart Bell passed away on October 1, 1990, in Geneva, Switzerland.",
      "date": "1990-10-01"
    }
  ]
}

