{
  "timeline": [
    {
      "headline": "Colonial Era Sodomy Laws",
      "text": "In the 17th century, the American colonies inherited sodomy laws from English common law. These laws criminalized a variety of sexual acts deemed unnatural or immoral.",
      "date": "1600"
    },
    {
      "headline": "First Sodomy Law in the United States",
      "text": "The first sodomy law in the United States was enacted in the Virginia Colony in 1610, which imposed the death penalty for sodomy.",
      "date": "1610"
    },
    {
      "headline": "Sodomy Laws in Early American States",
      "text": "By the late 18th century, most states had adopted sodomy laws, often carrying severe penalties, including death or imprisonment.",
      "date": "1790"
    },
    {
      "headline": "Model Penal Code Influence",
      "text": "In 1962, the American Law Institute's Model Penal Code recommended decriminalizing consensual sodomy, influencing some states to reform their laws.",
      "date": "1962"
    },
    {
      "headline": "Illinois Repeals Sodomy Law",
      "text": "Illinois became the first state to repeal its sodomy law in 1962, following the recommendations of the Model Penal Code.",
      "date": "1962"
    },
    {
      "headline": "Bowers v. Hardwick",
      "text": "In 1986, the U.S. Supreme Court upheld the constitutionality of sodomy laws in Bowers v. Hardwick, ruling that there was no constitutional protection for acts of sodomy.",
      "date": "1986"
    },
    {
      "headline": "Lawrence v. Texas",
      "text": "On June 26, 2003, the U.S. Supreme Court overturned Bowers v. Hardwick in Lawrence v. Texas, invalidating sodomy laws in the U.S. and affirming the right to privacy for consensual sexual conduct.",
      "date": "2003-06-26"
    }
  ]
}

