    {
      "headline": "Start of the Sierra Leone Civil War",
      "text": "The Sierra Leone Civil War began on 23 March 1991 when the Revolutionary United Front (RUF), supported by Charles Taylor's National Patriotic Front of Liberia (NPFL), intervened in Sierra Leone to overthrow the government of Joseph Momoh.",
      "date": "1991-03-23"
    },
    {
      "headline": "RUF Advances",
      "text": "Throughout 1991, the RUF advanced into eastern and southern Sierra Leone, capturing towns and committing widespread atrocities against civilians.",
      "date": "1991"
    },
    {
      "headline": "Military Coup",
      "text": "On 29 April 1992, a group of young military officers led by Captain Valentine Strasser overthrew President Joseph Momoh, establishing the National Provisional Ruling Council (NPRC).",
      "date": "1992-04-29"
    },
    {
      "headline": "Peace Talks and Continued Conflict",
      "text": "In 1996, peace talks were initiated, leading to the Abidjan Peace Accord in November 1996, but the conflict continued as the agreement was not fully implemented.",
      "date": "1996-11"
    },
    {
      "headline": "AFRC Coup",
      "text": "On 25 May 1997, the Armed Forces Revolutionary Council (AFRC) led by Major Johnny Paul Koroma overthrew the government, inviting the RUF to join them in ruling the country.",
      "date": "1997-05-25"
    },
    {
      "headline": "ECOMOG Intervention",
      "text": "In February 1998, the Economic Community of West African States Monitoring Group (ECOMOG) intervened, ousting the AFRC/RUF junta and reinstating President Ahmad Tejan Kabbah.",
      "date": "1998-02"
    },
    {
      "headline": "Lomé Peace Accord",
      "text": "On 7 July 1999, the Lomé Peace Accord was signed between the government and the RUF, granting amnesty to combatants and integrating the RUF into the government.",
      "date": "1999-07-07"
    },
    {
      "headline": "UNAMSIL Deployment",
      "text": "In October 1999, the United Nations Mission in Sierra Leone (UNAMSIL) was established to assist with the implementation of the Lomé Peace Accord.",
      "date": "1999-10"
    },
    {
      "headline": "End of the Civil War",
      "text": "The Sierra Leone Civil War officially ended on 18 January 2002, when President Ahmad Tejan Kabbah declared the conflict over.",
      "date": "2002-01-18"
    }
  ]
}

