{
  "timeline": [
    {
      "headline": "Pre-Columbian Era",
      "text": "The Mapuche people inhabited south-central Chile and southwestern Argentina, including parts of Patagonia, long before the arrival of Europeans. They developed a distinct culture with a common social, religious, and economic structure, and spoke the Mapudungun language.",
      "date": "-1500"
    },
    {
      "headline": "Spanish Conquest and Arauco War",
      "text": "Beginning in the 16th century, the Mapuche fiercely resisted Spanish colonization in a series of conflicts known as the Arauco War, which lasted for more than 300 years.",
      "date": "1540"
    },
    {
      "headline": "Battle of Curalaba",
      "text": "On December 23, 1598, the Mapuche achieved a significant victory against the Spanish in the Battle of Curalaba, which led to a major uprising and the destruction of several Spanish settlements.",
      "date": "1598-12-23"
    },
    {
      "headline": "Parliament of Quilín",
      "text": "In 1641, the Spanish Crown recognized Mapuche independence south of the Bío-Bío River through the Parliament of Quilín, establishing a formal peace agreement.",
      "date": "1641"
    },
    {
      "headline": "Occupation of Araucanía",
      "text": "In the late 19th century, the Chilean and Argentine governments began the Occupation of Araucanía and the Conquest of the Desert, respectively, which led to the annexation of Mapuche territories.",
      "date": "1860"
    },
    {
      "headline": "Mapuche Migration",
      "text": "Throughout the 20th century, many Mapuche people migrated from rural areas to urban centers such as Santiago and Buenos Aires in search of economic opportunities.",
      "date": "1900"
    },
    {
      "headline": "Recognition of Indigenous Rights",
      "text": "In the late 20th and early 21st centuries, there has been increased recognition of indigenous rights in Chile and Argentina, with efforts to address historical grievances and improve the socio-economic conditions of the Mapuche people.",
      "date": "1990"
    }
  ]
}

