    {
      "headline": "Confederation and Establishment of Parliament",
      "text": "The Parliament of Canada was established following the confederation of Canada on July 1, 1867, under the Constitution Act, 1867 (formerly the British North America Act, 1867). This act united the provinces of Canada (now Ontario and Quebec), New Brunswick, and Nova Scotia into a single Dominion within the British Empire.",
      "date": "1867-07-01"
    },
    {
      "headline": "First Session of the First Parliament",
      "text": "The first session of the First Parliament of Canada was opened on November 6, 1867, in Ottawa. This marked the beginning of legislative activities in the newly formed Dominion of Canada.",
      "date": "1867-11-06"
    },
    {
      "headline": "Parliament Buildings Fire",
      "text": "On February 3, 1916, a fire destroyed the original Centre Block of the Parliament Buildings in Ottawa. The fire led to the loss of several lives and significant damage to the building.",
      "date": "1916-02-03"
    },
    {
      "headline": "Completion of the New Centre Block",
      "text": "The new Centre Block of the Parliament Buildings, including the Peace Tower, was completed in 1927. This reconstruction followed the destruction caused by the fire in 1916.",
      "date": "1927"
    },
    {
      "headline": "Canada Act 1982",
      "text": "The Canada Act 1982 was passed by the UK Parliament and received royal assent on March 29, 1982. It ended the power of the British Parliament to legislate for Canada, marking a significant step in Canadian sovereignty.",
      "date": "1982-03-29"
    },
    {
      "headline": "Parliament Hill Shooting",
      "text": "On October 22, 2014, a gunman attacked the Canadian Parliament, resulting in the death of Corporal Nathan Cirillo and the gunman himself. This event led to increased security measures on Parliament Hill.",
      "date": "2014-10-22"
    }
  ]
}

