{
  "timeline": [
    {
      "headline": "Formation of the South Lebanon Army",
      "text": "The South Lebanon Army (SLA) was founded by Lebanese military officer Saad Haddad in 1977, amidst the Lebanese Civil War. It was initially formed from the remnants of the Army of Free Lebanon.",
      "date": "1977"
    },
    {
      "headline": "Declaration of the State of Free Lebanon",
      "text": "In 1979, Saad Haddad declared the area under his control as the State of Free Lebanon, an unrecognized entity. The SLA operated as the military force of this entity.",
      "date": "1979"
    },
    {
      "headline": "Israeli Support",
      "text": "Throughout the 1980s, the SLA received significant support from Israel, including funding, weapons, and training, as part of Israel's strategy to combat Palestinian and Lebanese militant groups in southern Lebanon.",
      "date": "1980"
    },
    {
      "headline": "Leadership of Antoine Lahad",
      "text": "After the death of Saad Haddad in 1984, Antoine Lahad took over leadership of the SLA. Under Lahad, the SLA continued to collaborate closely with Israel.",
      "date": "1984"
    },
    {
      "headline": "Operation Accountability",
      "text": "In 1993, the SLA participated in Operation Accountability, a military operation conducted by Israel against Hezbollah and other militant groups in southern Lebanon.",
      "date": "1993"
    },
    {
      "headline": "Operation Grapes of Wrath",
      "text": "In 1996, the SLA was involved in Operation Grapes of Wrath, another Israeli military campaign aimed at Hezbollah in southern Lebanon.",
      "date": "1996"
    },
    {
      "headline": "Withdrawal of Israeli Forces",
      "text": "In May 2000, Israel withdrew its forces from southern Lebanon. This led to the collapse of the SLA, as many of its members fled to Israel or were captured by Hezbollah.",
      "date": "2000-05"
    },
    {
      "headline": "Disbandment of the South Lebanon Army",
      "text": "Following the Israeli withdrawal, the South Lebanon Army was officially disbanded. Many former members faced trials in Lebanon, while others resettled in Israel.",
      "date": "2000"
    }
  ]
}

