{
  "timeline": [
    {
      "headline": "Metis' Role in the Titanomachy",
      "text": "Metis played a crucial role in the Titanomachy, the war between the Titans and the Olympians. She helped Zeus by providing him with an emetic potion to force Cronus to disgorge his siblings, who had been swallowed by Cronus. This event is a significant part of Greek mythology, although the exact date is not specified.",
      "date": "-1600" 	},
    {
      "headline": "Marriage to Zeus",
      "text": "Metis became the first wife of Zeus. This union was significant in Greek mythology as it symbolized the merging of wisdom (Metis) with power (Zeus). The exact date of their marriage is not specified in mythology.",
      "date": "-1600"
    },
    {
      "headline": "Prophecy of Metis' Child",
      "text": "A prophecy foretold that Metis would bear a son who would be mightier than his father, Zeus. To prevent this, Zeus swallowed Metis while she was pregnant, incorporating her wisdom into himself. This event is a key mythological story without a specific date.",
      "date": "-1600"
    },
    {
      "headline": "Birth of Athena",
      "text": "After swallowing Metis, Zeus experienced a severe headache. Hephaestus, or in some versions Prometheus, cleaved Zeus's head open with an axe, and Athena emerged fully grown and armored. This mythological event is significant in the birth of Athena, the goddess of wisdom and war.",
      "date": "-1600"
    }
  ]
}

{
