      "headline": "Discovery of Heard Island",
      "text": "Heard Island was discovered on 25 November 1853 by Captain John Heard aboard the ship Oriental.",
      "date": "1853-11-25"
    },
    {
      "headline": "Discovery of McDonald Islands",
      "text": "The McDonald Islands were discovered in January 1854 by Captain William McDonald aboard the ship Samarang.",
      "date": "1854-01"
    },
    {
      "headline": "Annexation by the United Kingdom",
      "text": "In 1910, the United Kingdom formally annexed Heard Island and the McDonald Islands.",
      "date": "1910"
    },
    {
      "headline": "Transfer to Australia",
      "text": "On 26 December 1947, the United Kingdom transferred the sovereignty of Heard Island and McDonald Islands to Australia.",
      "date": "1947-12-26"
    },
    {
      "headline": "Establishment as a nature reserve",
      "text": "In 1980, the islands were declared a nature reserve by the Australian government to protect their unique ecosystems.",
      "date": "1980"
    },
    {
      "headline": "World Heritage Site designation",
      "text": "In 1997, Heard Island and McDonald Islands were designated as a UNESCO World Heritage Site for their outstanding natural values.",
      "date": "1997"
    }
  ]
}

{
