{
  "timeline": [
    {
      "headline": "Charles I becomes King of Spain",
      "text": "In 1516, Charles I ascended to the Spanish throne, marking the beginning of Habsburg rule in Spain. He was the grandson of Ferdinand II of Aragon and Isabella I of Castile.",
      "date": "1516"
    },
    {
      "headline": "Charles I becomes Holy Roman Emperor",
      "text": "In 1519, Charles I was elected Holy Roman Emperor, becoming Charles V. This expanded his influence significantly across Europe.",
      "date": "1519"
    },
    {
      "headline": "Battle of Pavia",
      "text": "On February 24, 1525, the Spanish forces under Charles V defeated the French army at the Battle of Pavia, capturing King Francis I of France.",
      "date": "1525-02-24"
    },
    {
      "headline": "Treaty of Madrid",
      "text": "In 1526, the Treaty of Madrid was signed, in which Francis I of France was forced to cede Burgundy to Charles V, although it was later repudiated by Francis.",
      "date": "1526"
    },
    {
      "headline": "Sack of Rome",
      "text": "On May 6, 1527, troops of Charles V sacked Rome, marking a critical point in the conflict between the Holy Roman Empire and the Papacy.",
      "date": "1527-05-06"
    },
    {
      "headline": "Peace of Augsburg",
      "text": "In 1555, the Peace of Augsburg was signed, allowing for the coexistence of Catholicism and Lutheranism in Germany, a significant event during Charles V's reign.",
      "date": "1555"
    },
    {
      "headline": "Abdication of Charles V",
      "text": "In 1556, Charles V abdicated his titles, dividing his empire between his brother Ferdinand I, who became Holy Roman Emperor, and his son Philip II, who became King of Spain.",
      "date": "1556"
    },
    {
      "headline": "Philip II becomes King of Spain",
      "text": "Philip II ascended to the Spanish throne in 1556, inheriting a vast empire that included territories in Europe, the Americas, and Asia.",
      "date": "1556"
    },
    {
      "headline": "Battle of Lepanto",
      "text": "On October 7, 1571, the Holy League, led by Spain, defeated the Ottoman fleet at the Battle of Lepanto, marking a significant naval victory.",
      "date": "1571-10-07"
    },
    {
      "headline": "Annexation of Portugal",
      "text": "In 1580, Philip II successfully claimed the Portuguese throne, uniting the Iberian Peninsula under Spanish rule.",
      "date": "1580"
    },
    {
      "headline": "Spanish Armada",
      "text": "In 1588, the Spanish Armada, a large fleet sent by Philip II to invade England, was defeated by the English navy.",
      "date": "1588"
    },
    {
      "headline": "Philip III becomes King of Spain",
      "text": "Philip III ascended to the Spanish throne in 1598, following the death of his father, Philip II.",
      "date": "1598"
    },
    {
      "headline": "Twelve Years' Truce",
      "text": "In 1609, the Twelve Years' Truce was signed between Spain and the Dutch Republic, temporarily halting the Eighty Years' War.",
      "date": "1609"
    },
    {
      "headline": "Philip IV becomes King of Spain",
      "text": "Philip IV ascended to the Spanish throne in 1621, succeeding his father, Philip III.",
      "date": "1621"
    },
    {
      "headline": "Thirty Years' War",
      "text": "Spain was heavily involved in the Thirty Years' War (1618-1648), a series of conflicts across Europe that had significant political and religious implications.",
      "date": "1618"
    },
    {
      "headline": "Peace of Westphalia",
      "text": "In 1648, the Peace of Westphalia was signed, ending the Thirty Years' War and marking the decline of Spanish dominance in Europe.",
      "date": "1648"
    },
    {
      "headline": "Charles II becomes King of Spain",
      "text": "Charles II ascended to the Spanish throne in 1665, following the death of his father, Philip IV.",
      "date": "1665"
    },
    {
      "headline": "Death of Charles II",
      "text": "Charles II died on November 1, 1700, ending the Habsburg dynasty in Spain and leading to the War of Spanish Succession.",
