    }
  ]
}

{
  "timeline": [
    {
      "headline": "Establishment of the First Central Bank",
      "text": "The first central bank, the Riksbank, was established in Sweden in 1668. It was created to stabilize the currency and provide loans to the government.",
      "date": "1668"
    },
    {
      "headline": "Creation of the Bank of England",
      "text": "The Bank of England was founded in 1694. It was established to act as the government's banker and debt-manager and later became the model for modern central banks.",
      "date": "1694"
    },
    {
      "headline": "Establishment of the Federal Reserve System",
      "text": "The Federal Reserve System, the central bank of the United States, was created in 1913 to provide the country with a safer, more flexible, and more stable monetary and financial system.",
      "date": "1913"
    },
    {
      "headline": "Bretton Woods Conference",
      "text": "In 1944, the Bretton Woods Conference established the International Monetary Fund (IMF) and the World Bank, which play significant roles in global monetary policy and financial stability.",
      "date": "1944"
    },
    {
      "headline": "Introduction of the Euro and the European Central Bank",
      "text": "The European Central Bank (ECB) was established in 1998 to manage the euro and implement EU monetary policy. The euro was introduced as a currency in 1999.",
      "date": "1998"
    },
    {
      "headline": "Global Financial Crisis and Central Bank Response",
      "text": "During the global financial crisis of 2007-2008, central banks worldwide, including the Federal Reserve and the ECB, took unprecedented measures to stabilize financial systems and economies.",
      "date": "2007"
    },
    {
      "headline": "COVID-19 Pandemic Economic Response",
      "text": "In response to the economic impact of the COVID-19 pandemic in 2020, central banks globally implemented significant monetary policy measures, including interest rate cuts and quantitative easing, to support economies.",
      "date": "2020"
    }
  ]
}

