{
  "timeline": [
    {
      "headline": "Birth of John Dee",
      "text": "John Dee was born on July 13, 1527, in Tower Ward, London, England.",
      "date": "1527-07-13"
    },
    {
      "headline": "Education at Cambridge",
      "text": "In 1542, John Dee entered St John's College, Cambridge, where he studied mathematics, astronomy, and other sciences.",
      "date": "1542"
    },
    {
      "headline": "Graduation from Cambridge",
      "text": "John Dee graduated with a Bachelor of Arts degree in 1545 from St John's College, Cambridge.",
      "date": "1545"
    },
    {
      "headline": "Master of Arts Degree",
      "text": "Dee was awarded a Master of Arts degree in 1548 from Trinity College, Cambridge.",
      "date": "1548"
    },
    {
      "headline": "Travels to the Continent",
      "text": "Between 1548 and 1551, Dee traveled to the Continent, studying in Louvain and Brussels, and lecturing in Paris.",
      "date": "1548"
    },
    {
      "headline": "Return to England",
      "text": "In 1551, John Dee returned to England and was appointed as a tutor to the children of the Duke of Northumberland.",
      "date": "1551"
    },
    {
      "headline": "Imprisonment",
      "text": "In 1555, Dee was imprisoned on charges of treason and sorcery but was released after being cleared of the charges.",
      "date": "1555"
    },
    {
      "headline": "Advisor to Queen Elizabeth I",
      "text": "In 1558, Dee became an advisor to Queen Elizabeth I, serving as her court astronomer and astrologer.",
      "date": "1558"
    },
    {
      "headline": "Publication of 'Monas Hieroglyphica'",
      "text": "In 1564, Dee published 'Monas Hieroglyphica', a work on symbolic language and alchemy.",
      "date": "1564"
    },
    {
      "headline": "Voyage to the Continent",
      "text": "In 1571, Dee traveled to the Continent again, visiting the court of Emperor Maximilian II.",
      "date": "1571"
    },
    {
      "headline": "Meeting with Edward Kelley",
      "text": "In 1582, Dee began working with Edward Kelley, a medium, to communicate with angels.",
      "date": "1582"
    },
    {
      "headline": "Travels in Europe",
      "text": "Between 1583 and 1589, Dee traveled across Europe with Kelley, engaging in alchemical and spiritual experiments.",
      "date": "1583"
    },
    {
      "headline": "Return to England",
      "text": "Dee returned to England in 1589 after his travels in Europe.",
      "date": "1589"
    },
    {
      "headline": "Warden of Christ's College, Manchester",
      "text": "In 1595, Dee was appointed Warden of Christ's College, Manchester.",
      "date": "1595"
    },
    {
      "headline": "Death of John Dee",
      "text": "John Dee died in December 1608 or early 1609 in Mortlake, Surrey, England.",
      "date": "1609"
    }
  ]
}

