{
  "timeline": [
    {
      "headline": "Early Settlement",
      "text": "The history of Mexico begins with the early settlement over 13,000 years ago by nomadic peoples.",
      "date": "-11000"
    },
    {
      "headline": "Rise of Mesoamerican Civilizations",
      "text": "Central and southern Mexico, known as Mesoamerica, saw the rise of complex civilizations such as the Olmec, Maya, and Zapotec, which developed glyphic writing systems to record political histories and conquests.",
      "date": "-1500"
    },
    {
      "headline": "Olmec Civilization",
      "text": "The Olmec civilization, considered the 'mother culture' of Mesoamerica, flourished in the Gulf Coast region of Mexico.",
      "date": "-1200"
    },
    {
      "headline": "Teotihuacan Flourishes",
      "text": "The city of Teotihuacan, one of the largest cities in the ancient world, flourished in the Valley of Mexico.",
      "date": "0001"
    },
    {
      "headline": "Classic Maya Period",
      "text": "The Classic Period of the Maya civilization, known for its monumental architecture and advanced writing system, began.",
      "date": "0250"
    },
    {
      "headline": "Toltec Empire",
      "text": "The Toltec Empire rose to prominence in central Mexico, influencing later cultures such as the Aztecs.",
      "date": "0900"
    },
    {
      "headline": "Aztec Empire Established",
      "text": "The Aztec Empire was established in the Valley of Mexico, with Tenochtitlan as its capital.",
      "date": "1325"
    },
    {
      "headline": "Spanish Conquest of the Aztec Empire",
      "text": "The Spanish, led by Hernán Cortés, conquered the Aztec Empire, marking the beginning of Spanish rule in Mexico.",
      "date": "1521"
    },
    {
      "headline": "Establishment of New Spain",
      "text": "Following the conquest, the Spanish established the colony of New Spain, bringing Spanish rule, Christianity, and European influences to the region.",
      "date": "1535"
    },
    {
      "headline": "Mexican War of Independence",
      "text": "The Mexican War of Independence began, leading to the end of Spanish rule in Mexico.",
      "date": "1810"
    },
    {
      "headline": "Independence of Mexico",
      "text": "Mexico achieved independence from Spain, marking the end of colonial rule.",
      "date": "1821"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Treaty of Saint-Clair-sur-Epte",
      "text": "In 911, the Treaty of Saint-Clair-sur-Epte was signed between King Charles III of West Francia and the Viking leader Rollo. This treaty granted Rollo land in what would become Normandy in exchange for his protection against other Viking raids.",
      "date": "0911"
    },
    {
      "headline": "Establishment of the Duchy of Normandy",
      "text": "Following the Treaty of Saint-Clair-sur-Epte in 911, the Duchy of Normandy was established. Rollo became the first ruler of Normandy, marking the beginning of Norman control over the region.",
      "date": "0911"
    },
    {
      "headline": "Expansion under Rollo",
      "text": "Rollo expanded the territory of Normandy beyond the initial grant, consolidating his power and establishing a strong Norman presence in the region during his rule from 911 to 927.",
      "date": "0911-0927"
    },
    {
      "headline": "Rollo's Death",
      "text": "Rollo, the first Duke of Normandy, died around 928, leaving the duchy to his descendants.",
      "date": "0928"
    },
    {
      "headline": "William the Conqueror's Birth",
      "text": "William the Conqueror, one of the most famous Dukes of Normandy, was born in 1028. He would later become King of England after the Norman Conquest.",
      "date": "1028"
    },
    {
      "headline": "Norman Conquest of England",
      "text": "In 1066, Duke William II of Normandy, known as William the Conqueror, led the Norman Conquest of England, culminating in his victory at the Battle of Hastings and his coronation as King of England.",
      "date": "1066"
    },
    {
      "headline": "Integration into the Angevin Empire",
      "text": "In 1144, the Duchy of Normandy was integrated into the Angevin Empire under the rule of Geoffrey Plantagenet, Count of Anjou, following his conquest of the region.",
      "date": "1144"
    },
    {
      "headline": "Loss of Normandy to France",
      "text": "In 1204, King Philip II of France conquered Normandy, ending its status as a separate duchy and integrating it into the Kingdom of France.",
      "date": "1204"
    }
  ]
}

